const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [roleWarning, setRoleWarning] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRepairing, setIsRepairing] = useState(false);
  const { login, refreshProfile } = useAuth();
  const navigate = useNavigate();

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setError('');
    setRoleWarning(false);
    setIsSubmitting(true);

    try {
      const result = await login(email.trim(), password);

      if (result.user) {
        // DETECT WRONG ROLE FOR ADMIN
        const isMasterEmail = email.toLowerCase() === 'masteradmin@ssk.com';
        if (isMasterEmail && result.user.role !== Role.MasterAdmin) {
            setRoleWarning(true);
            setError(`Your account exists but is currently assigned the '${result.user.role}' role instead of 'MasterAdmin'.`);
            setIsSubmitting(false);
            return;
        }

        redirectToDashboard(result.user.role);
      } else {
          setError(result.error || 'Login failed. Please verify your credentials.');
      }
    } catch (err: any) {
      setError(err.message || 'An unexpected error occurred during login.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const redirectToDashboard = (role: Role) => {
    switch (role) {
      case Role.MasterAdmin: navigate('/admin'); break;
      case Role.Organisation: navigate('/organisation'); break;
      case Role.Volunteer: navigate('/volunteer'); break;
      default: navigate('/');
    }
  };

  const handleAutoRepair = async () => {
    setIsRepairing(true);
    try {
        const { data: { session } } = await supabase.auth.getSession();
        if (!session?.user) {
            setError("No active session. Please log in first.");
            return;
        }

        // Attempt direct update (requires RLS to be permissive or disabled for testing)
        const { error: updateError } = await supabase
            .from('profiles')
            .update({ role: 'MasterAdmin', name: 'Master Admin' })
            .eq('id', session.user.id);

        if (updateError) {
            setError(`Auto-repair failed: ${updateError.message}. You must run the SQL manually in Supabase.`);
        } else {
            // Success! Refresh the local user state
            await refreshProfile();
            redirectToDashboard(Role.MasterAdmin);
        }
    } catch (err: any) {
        setError("An error occurred during auto-repair.");
    } finally {
        setIsRepairing(false);
    }
  };

  return (
    <div className="min-h-screen bg-black flex flex-col">
        <Header />
        <div className="flex-grow flex flex-col items-center justify-center p-4">
            <Card className="w-full max-w-md">
