                <p className="text-gray-500 text-center text-sm mb-8">Enter your credentials to manage SSK People</p>

                <form onSubmit={handleLogin} className="space-y-4">
                    <Input 
                        label="Email Address"
                        id="email"
                        name="email"
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="Masteradmin@ssk.com"
                        required
                    />
                    <Input 
                        label="Password"
                        id="password"
                        name="password"
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="Ssk1919@"
                        required
                    />

                    {error && (
                        <div className={`p-4 rounded-md border ${roleWarning ? 'bg-orange-900/10 border-orange-800/30' : 'bg-red-900/10 border-red-800/30'}`}>
                            <div className={`flex items-center gap-2 font-bold mb-1 text-xs uppercase tracking-wider ${roleWarning ? 'text-orange-500' : 'text-red-500'}`}>
                                {roleWarning ? <AlertTriangle size={14} /> : <AlertCircle size={14} />}
                                <span>{roleWarning ? 'Role Mismatch Detected' : 'Login Failed'}</span>
                            </div>
                            <p className={`${roleWarning ? 'text-orange-400' : 'text-red-400'} text-[11px] leading-relaxed`}>{error}</p>
                        </div>
                    )}

                    <Button 
                        type="submit" 
                        disabled={!email || !password || isSubmitting} 
                        className="w-full py-3 shadow-lg shadow-orange-900/20"
                    >
                        {isSubmitting ? 'Verifying Identity...' : 'Sign In'}
                    </Button>
                </form>

                <div className="mt-8 pt-6 border-t border-gray-800 space-y-4">
                    {roleWarning && (
                        <div className="bg-orange-500/10 border border-orange-500/30 p-4 rounded-md animate-pulse">
                             <div className="flex items-center gap-2 text-orange-500 font-bold mb-3 text-[10px] uppercase tracking-[0.2em]">
                                <Wrench size={12} />
                                <span>Profile Repair Utility</span>
                            </div>
                            <p className="text-[10px] text-gray-300 mb-4 leading-tight">We've detected you're the Admin but have the wrong role. Try auto-repairing below or use the SQL script.</p>

                            <Button 
                                onClick={handleAutoRepair} 
                                disabled={isRepairing}
                                className="w-full text-xs py-2 mb-4 bg-orange-700 hover:bg-orange-600 flex items-center justify-center gap-2"
                            >
                                <RefreshCw size={14} className={isRepairing ? 'animate-spin' : ''} />
