const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [roleWarning, setRoleWarning] = useState(false);
  const [profileMissing, setProfileMissing] = useState(false);
  const [authFailed, setAuthFailed] = useState(false);
  const [currentUid, setCurrentUid] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRepairing, setIsRepairing] = useState(false);
  const { login, refreshProfile } = useAuth();
  const { addNotification } = useNotification();
  const navigate = useNavigate();

  useEffect(() => {
      // Cleanup check for existing session
      const checkSession = async () => {
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) {
              setCurrentUid(session.user.id);
          }
      };
      checkSession();
  }, []);

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setError('');
    setRoleWarning(false);
    setProfileMissing(false);
    setAuthFailed(false);
    setIsSubmitting(true);

    try {
      const result = await login(email.trim(), password);

      if (result.user) {
        // Successful login with profile
        const isMasterEmail = email.toLowerCase() === 'masteradmin@ssk.com';
        if (isMasterEmail && result.user.role !== Role.MasterAdmin) {
            setRoleWarning(true);
            setError(`Account identified, but restricted. Current role: '${result.user.role}'. Master Admin level requires 'MasterAdmin' privilege.`);
            setIsSubmitting(false);
            return;
        }
        redirectToDashboard(result.user.role);
      } else {
          // Authentication failed or Profile missing
          if (result.error === "no Profile record found") {
              setProfileMissing(true);
              // We need the UID to offer a fix
              const { data: { session } } = await supabase.auth.getSession();
              if (session?.user) setCurrentUid(session.user.id);
              setError("Identity verified, but Profile record is missing from the database.");
          } else {
              setAuthFailed(true);
              setError(result.error || 'Identity verification failed. Invalid credentials.');
          }
      }
    } catch (err: any) {
      setError(err.message || 'A terminal error occurred during sequence initiation.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const redirectToDashboard = (role: Role) => {
    switch (role) {
      case Role.MasterAdmin: navigate('/admin'); break;
      case Role.Organisation: navigate('/organisation'); break;
      case Role.Volunteer: navigate('/volunteer'); break;
      default: navigate('/');
    }
  };

  const handleAutoRepair = async () => {
    setIsRepairing(true);
    try {
        const { data: { session } } = await supabase.auth.getSession();
        if (!session?.user) {
            setError("Session not established. Re-authenticate first.");
            setIsRepairing(false);
            return;
        }

        const { error: updateError } = await supabase
            .from('profiles')
            .upsert({ 
                id: session.user.id, 
                role: 'MasterAdmin', 
                name: 'Master Admin',
                email: session.user.email 
            });

        if (updateError) {
            setError(`Repair operation failed: ${updateError.message}. Use manual SQL override.`);
        } else {
            addNotification("Access Level: Master Admin GRANTED.", "success");
            await refreshProfile();
            redirectToDashboard(Role.MasterAdmin);
        }
    } catch (err: any) {
        setError("Operation interrupted by system fault.");
    } finally {
        setIsRepairing(false);
    }
  };

  const copySql = () => {
      const uid = currentUid || 'REPLACE_WITH_UID_FROM_DASHBOARD';
