                <div className="flex justify-center mb-4">
                  <div className="p-4 bg-orange-500/10 rounded-full border border-orange-500/20 shadow-[0_0_15px_rgba(249,115,22,0.1)]">
                    <ShieldCheck className="text-orange-500" size={40} />
                  </div>
                </div>

