                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="masteradmin@ssk.com"
                        className="bg-black/50 border-gray-800 text-sm"
                        required
                    />
                    <Input 
                        label="SECURITY KEY (PASSWORD)"
                        id="password"
                        name="password"
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="••••••••"
                        className="bg-black/50 border-gray-800 text-sm"
                        required
                    />

                    {error && (
                        <div className={`p-4 rounded border ${ (roleWarning || profileMissing) ? 'bg-orange-900/10 border-orange-800/40' : 'bg-red-900/10 border-red-800/40'}`}>
                            <div className={`flex items-center gap-2 font-bold mb-2 text-[11px] uppercase tracking-widest ${ (roleWarning || profileMissing) ? 'text-orange-500' : 'text-red-500'}`}>
                                {profileMissing ? <ShieldAlert size={14} /> : (roleWarning ? <AlertTriangle size={14} /> : <AlertCircle size={14} />)}
                                <span>{profileMissing ? 'Profile Not Found' : (roleWarning ? 'Privilege Mismatch' : 'Auth Fault')}</span>
                            </div>
                            <p className={`${ (roleWarning || profileMissing) ? 'text-orange-400' : 'text-red-400'} text-xs leading-relaxed opacity-90`}>{error}</p>
