import React, { useState, useMemo, useEffect } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import { useAuth } from '../../context/AuthContext';
import { Member, MemberStatus } from '../../types';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { User, Building2 } from 'lucide-react';

const VolunteerDashboard: React.FC = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [mySubmissions, setMySubmissions] = useState<Member[]>([]);
    const [loading, setLoading] = useState(true);
    const { addNotification } = useNotification();

    useEffect(() => {
        const fetchSubmissions = async () => {
            if (!user?.id) return;
            setLoading(true);
            const { data, error } = await supabase
                .from('members')
                .select('*')
                .eq('volunteer_id', user.id);

            if (error) {
                console.error("Error fetching submissions:", error);
            } else if (data) {
                setMySubmissions(data);
            }
            setLoading(false);
        };
        fetchSubmissions();
    }, [user]);

    const [filters, setFilters] = useState({
        startDate: '',
        endDate: '',
        phone: '',
        area: '', // Pincode
    });

    const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
    };

    const filteredSubmissions = useMemo(() => {
        return mySubmissions.filter(member => {
            const submissionDate = new Date(member.submission_date);
            const startDate = filters.startDate ? new Date(filters.startDate) : null;
            const endDate = filters.endDate ? new Date(filters.endDate) : null;
            if (endDate) {
                endDate.setHours(23, 59, 59, 999);
            }
            if (startDate && submissionDate < startDate) return false;
            if (endDate && submissionDate > endDate) return false;

            if (filters.phone && !member.mobile.includes(filters.phone)) {
                return false;
            }

            if (filters.area && !member.pincode.includes(filters.area)) {
                return false;
            }

            return true;
        });
    }, [mySubmissions, filters]);

    return (
        <DashboardLayout title="Volunteer Dashboard">
            <div className="space-y-6">
                {/* Identity Header */}
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 p-6 bg-blue-900/10 border border-blue-900/20 rounded-lg">
                    <div className="flex gap-4 items-center">
                         <div className="p-3 bg-blue-500/10 rounded-full border border-blue-500/20 text-blue-400">
                            <User size={32} />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-400/60">Active Field Agent</p>
                            <h2 className="font-cinzel text-2xl text-white">{user?.name}</h2>
                        </div>
                    </div>
                    <div className="flex gap-4 items-center md:border-l border-blue-900/30 md:pl-8">
                         <div className="p-3 bg-white/5 rounded-full border border-white/10 text-gray-500">
                            <Building2 size={32} />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-500">Reporting To</p>
                            <h2 className="font-cinzel text-xl text-white">{user?.organisationName || 'Unknown Entity'}</h2>
                        </div>
                    </div>
                    <Button onClick={() => navigate('/volunteer/new-member')} className="w-full md:w-auto mt-2 md:mt-0">
                        Add New Member
                    </Button>
                </div>

                <Card className="mb-6">
                    <div className="flex flex-wrap gap-4 items-end p-2">
                        <div className="flex-1 min-w-[150px]">
                            <Input label="Start Date" type="date" name="startDate" value={filters.startDate} onChange={handleFilterChange} />
                        </div>
                        <div className="flex-1 min-w-[150px]">
                            <Input label="End Date" type="date" name="endDate" value={filters.endDate} onChange={handleFilterChange} />
                        </div>
                        <div className="flex-1 min-w-[150px]">
                            <Input label="Phone Number" type="text" name="phone" placeholder="Search by phone..." value={filters.phone} onChange={handleFilterChange} />
                        </div>
                        <div className="flex-1 min-w-[150px]">
                            <Input label="Area (Pincode)" type="text" name="area" placeholder="Search by pincode..." value={filters.area} onChange={handleFilterChange} />
                        </div>
                    </div>
                </Card>

                <Card>
                    <div className="overflow-x-auto">
                      <table className="w-full text-left">
                        <thead className="border-b border-gray-700">
                          <tr>
                            <th className="p-2">Name</th>
                            <th className="p-2">Mobile</th>
                            <th className="p-2">Date</th>
                            <th className="p-2">Status</th>
                            <th className="p-2">Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {loading ? (
                              <tr><td colSpan={5} className="text-center p-4">Loading submissions...</td></tr>
                          ) : (
                            <>
                            {filteredSubmissions.map(member => (
                              <tr key={member.id} className="border-b border-gray-800 hover:bg-gray-800 transition-colors">
                                <td className="p-2">{member.name} {member.surname}</td>
                                <td className="p-2">{member.mobile}</td>
                                <td className="p-2">{member.submission_date}</td>
                                <td className={`p-2 font-semibold ${member.status === MemberStatus.Accepted ? 'text-green-400' : 'text-yellow-400'}`}>
                                  {member.status}
                                </td>
                                <td className="p-2">
                                  {member.status === MemberStatus.Pending && (
                                      <Button variant="secondary" size="sm" onClick={() => addNotification(`Editing for ${member.name} is not implemented yet.`, 'info')}>
                                          Edit
                                      </Button>
                                  )}
                                </td>
                              </tr>
                            ))}
                            {filteredSubmissions.length === 0 && (
                                <tr>
                                    <td colSpan={5} className="text-center p-4 text-gray-500">
                                        No submissions match the current filters.
                                    </td>
                                </tr>
                            )}
                            </>
                          )}
                        </tbody>
                      </table>
                    </div>
                </Card>
            </div>
        </DashboardLayout>
    );
};

export default VolunteerDashboard;

import React, { createContext, useState, useContext, ReactNode, useEffect, useCallback } from 'react';
import { User, Role } from '../types';
import { supabase } from '../supabase/client';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<{ user: User | null; error?: string }>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  updatePassword: (newPassword: string) => Promise<{ success: boolean; error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const mapToRole = (roleStr: any): Role => {
    if (!roleStr) return Role.Volunteer;
    const normalized = String(roleStr).toLowerCase().trim();
    if (normalized === 'masteradmin' || normalized === 'superadmin') return Role.MasterAdmin;
    if (normalized === 'organisation' || normalized === 'admin' || normalized === 'org') return Role.Organisation;
    return Role.Volunteer;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      const { data: profile, error } = await supabase
          .from('profiles')
          .select(`
            *,
            organisations (
              name
            )
          `)
          .eq('id', userId)
          .single();

      if (error) {
          console.error('Auth: Profile fetch failed:', error.message);
          return null;
      }

      if (profile) {
          return {
              id: profile.id,
              name: profile.name,
              email: profile.email,
              role: mapToRole(profile.role),
              organisationId: profile.organisation_id,
              organisationName: profile.organisations?.name || null,
              mobile: profile.mobile,
          };
      }
    } catch (e) {
      console.error('Auth: Unexpected fetch error', e);
    }
    return null;
  }, []);

  const refreshProfile = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
          const updatedUser = await fetchProfile(session.user.id);
          setUser(updatedUser);
      }
  };

  const updatePassword = async (newPassword: string): Promise<{ success: boolean; error?: string }> => {
    try {
      const { error } = await supabase.auth.updateUser({
        password: newPassword
      });
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message };
    }
  };

  useEffect(() => {
    let mounted = true;

    const initializeAuth = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && mounted) {
            const mapped = await fetchProfile(session.user.id);
            setUser(mapped);
        }
        if (mounted) setLoading(false);
    };

    initializeAuth();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_OUT') {
            setUser(null);
        } else if (session?.user && (event === 'SIGNED_IN' || event === 'INITIAL_SESSION')) {
            const mapped = await fetchProfile(session.user.id);
            setUser(mapped);
        }
    });

    return () => {
      mounted = false;
      subscription?.unsubscribe();
    };
  }, [fetchProfile]);

  const login = async (email: string, password: string): Promise<{ user: User | null; error?: string }> => {
    try {
        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({ 
            email: email.trim(), 
            password: password 
        });

        if (authError) {
            return { user: null, error: authError.message };
        }

        if (authData.user) {
            const mappedUser = await fetchProfile(authData.user.id);
            if (!mappedUser) {
                return { user: null, error: "no Profile record found" };
            }
            setUser(mappedUser);
            return { user: mappedUser };
        }
        return { user: null, error: "Authentication failed." };
    } catch (err: any) {
        return { user: null, error: err.message || "An unexpected error occurred" };
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshProfile, updatePassword }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { useState, useMemo, useEffect } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import { Shield, Users, UserCheck, Key, RefreshCw, AlertCircle } from 'lucide-react';
import { Organisation, Volunteer, Member, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useAuth } from '../../context/AuthContext';
import { useNotification } from '../../context/NotificationContext';

interface OrgPerformance extends Organisation {
    enrollments: number;
}

const AdminDashboard: React.FC = () => {
    const { updatePassword } = useAuth();
    const { addNotification } = useNotification();
    const [searchTerm, setSearchTerm] = useState('');
    const [organisations, setOrganisations] = useState<Organisation[]>([]);
    const [volunteers, setVolunteers] = useState<Volunteer[]>([]);
    const [members, setMembers] = useState<Member[]>([]);
    const [loading, setLoading] = useState(true);

    // Password Update State
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isUpdatingPassword, setIsUpdatingPassword] = useState(false);

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true);
            const { data: orgsData } = await supabase.from('organisations').select('*');
            const { data: membersData } = await supabase.from('members').select('*');
            const { data: volsData } = await supabase.from('profiles').select('*').eq('role', Role.Volunteer);

            if (orgsData) setOrganisations(orgsData);
            if (membersData) setMembers(membersData);
            if (volsData && membersData) {
                const volunteersWithEnrollments: Volunteer[] = volsData.map(v => ({
                    id: v.id,
                    name: v.name,
                    email: v.email,
                    role: v.role,
                    organisationId: v.organisation_id,
                    mobile: v.mobile,
                    enrollments: membersData.filter(m => m.volunteer_id === v.id).length,
                }));
                setVolunteers(volunteersWithEnrollments);
            }
            setLoading(false);
        };
        fetchData();
    }, []);

    const orgPerformanceData = useMemo<OrgPerformance[]>(() => {
        const orgEnrollments = members.reduce((acc, member) => {
            acc[member.organisation_id] = (acc[member.organisation_id] || 0) + 1;
            return acc;
        }, {} as Record<string, number>);

        return organisations.map(org => ({
            ...org,
            enrollments: orgEnrollments[org.id] || 0,
        })).sort((a, b) => b.enrollments - a.enrollments);
    }, [members, organisations]);

    const volunteerPerformanceData = useMemo<Volunteer[]>(() => {
        return [...volunteers].sort((a, b) => b.enrollments - a.enrollments);
    }, [volunteers]);

    const filteredOrgs = useMemo(() => {
        if (!searchTerm) return orgPerformanceData;
        return orgPerformanceData.filter(org => org.mobile.includes(searchTerm));
    }, [searchTerm, orgPerformanceData]);

    const filteredVolunteers = useMemo(() => {
        if (!searchTerm) return volunteerPerformanceData;
        const matchingOrgIds = organisations.filter(org => org.mobile.includes(searchTerm)).map(org => org.id);
        return volunteerPerformanceData.filter(vol => matchingOrgIds.includes(vol.organisationId));
    }, [searchTerm, volunteerPerformanceData, organisations]);

    const handlePasswordUpdate = async (e: React.FormEvent) => {
        e.preventDefault();
        if (newPassword.length < 6) {
            addNotification("Security key must be at least 6 characters.", "error");
            return;
        }
        if (newPassword !== confirmPassword) {
            addNotification("Security keys do not match.", "error");
            return;
        }

        setIsUpdatingPassword(true);
        const result = await updatePassword(newPassword);

        if (result.success) {
            addNotification("Security key updated successfully.", "success");
            setNewPassword('');
            setConfirmPassword('');
        } else {
