import React, { useState, useMemo, useEffect } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import { useAuth } from '../../context/AuthContext';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import { supabase } from '../../supabase/client';
import { Member, Role, User as VolunteerUser } from '../../types';
import { useNotification } from '../../context/NotificationContext';
import { FileSpreadsheet, Filter, Search } from 'lucide-react';

const OrganisationReports: React.FC = () => {
    const { user } = useAuth();
    const [myMembers, setMyMembers] = useState<Member[]>([]);
    const [myVolunteers, setMyVolunteers] = useState<VolunteerUser[]>([]);
    const [loading, setLoading] = useState(true);
    const { addNotification } = useNotification();

    useEffect(() => {
        const fetchData = async () => {
            if (!user?.organisationId) return;
            setLoading(true);
            const { data: membersData } = await supabase.from('members').select('*').eq('organisation_id', user.organisationId);
            const { data: volsData } = await supabase.from('profiles').select('*').eq('role', Role.Volunteer).eq('organisation_id', user.organisationId);
            if (membersData) setMyMembers(membersData);
            if (volsData) setMyVolunteers(volsData);
            setLoading(false);
        };
        fetchData();
    }, [user]);

    const [filters, setFilters] = useState({
        startDate: '',
        endDate: '',
        volunteerId: '',
        search: ''
    });

    const filteredMembers = useMemo(() => {
        return myMembers.filter(member => {
            const submissionDate = new Date(member.submission_date);
            const startDate = filters.startDate ? new Date(filters.startDate) : null;
            const endDate = filters.endDate ? new Date(filters.endDate) : null;

            if (endDate) endDate.setHours(23, 59, 59, 999);

            if (startDate && submissionDate < startDate) return false;
            if (endDate && submissionDate > endDate) return false;
            if (filters.volunteerId && member.volunteer_id !== filters.volunteerId) return false;

            if (filters.search) {
                const term = filters.search.toLowerCase();
                return member.name.toLowerCase().includes(term) || 
                       member.surname.toLowerCase().includes(term) || 
                       member.mobile.includes(term);
            }

            return true;
        });
    }, [myMembers, filters]);

    const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
    };

    const handleDownload = () => {
        if (filteredMembers.length === 0) {
            addNotification("No data available for export with current filters.", "error");
            return;
        }

        const headers = ['Aadhaar', 'Name', 'Surname', 'Mobile', 'Submission Date', 'Volunteer', 'Occupation', 'Support Need', 'Status'];
        const rows = filteredMembers.map(m => [
            m.aadhaar,
            m.name,
            m.surname,
            m.mobile,
            m.submission_date,
            myVolunteers.find(v => v.id === m.volunteer_id)?.name || 'Unknown',
            m.occupation,
            m.support_need,
            m.status
        ]);

        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.setAttribute("href", url);
        link.setAttribute("download", `SSK_Report_${user?.organisationName || 'Org'}_${new Date().toISOString().split('T')[0]}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        addNotification("Membership drive data downloaded successfully.", 'success');
    };

    return (
        <DashboardLayout title="Drive Intelligence">
            <Card className="mb-8">
                <div className="flex items-center gap-2 mb-6 text-orange-500">
                    <Filter size={18} />
                    <h3 className="text-xs font-black uppercase tracking-[0.2em]">Filter Parameters</h3>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 items-end">
                    <Input label="Search Agent/Member" name="search" value={filters.search} onChange={handleFilterChange} placeholder="Name or Phone..." />
                    <Input label="Start Date" type="date" name="startDate" value={filters.startDate} onChange={handleFilterChange} />
                    <Input label="End Date" type="date" name="endDate" value={filters.endDate} onChange={handleFilterChange} />
                    <Select label="Filter by Agent" name="volunteerId" value={filters.volunteerId} onChange={handleFilterChange}>
                        <option value="">All Field Agents</option>
                        {myVolunteers.map(vol => (
                            <option key={vol.id} value={vol.id}>{vol.name}</option>
                        ))}
                    </Select>
                </div>

                <div className="mt-8 flex justify-end">
                    <Button onClick={handleDownload} className="flex items-center gap-2 px-8 py-3 text-xs font-black tracking-widest uppercase shadow-xl shadow-orange-900/10">
                        <FileSpreadsheet size={16} /> Export Master Dataset
                    </Button>
                </div>
            </Card>

            <Card>
                <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-2 text-gray-500">
                        <Search size={14} />
                        <span className="text-[10px] font-black uppercase tracking-widest">Dataset results: {filteredMembers.length} records</span>
                    </div>
                </div>

                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="border-b border-gray-800">
                      <tr>
                        <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Member Identity</th>
                        <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Processing Agent</th>
                        <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Submission Node</th>
                        <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500 text-right">Verification</th>
                      </tr>
                    </thead>
                    <tbody>
                      {loading ? (
                          <tr><td colSpan={4} className="text-center p-12 animate-pulse text-xs text-gray-500 font-black uppercase tracking-widest">Scanning Storage...</td></tr>
                      ) : (
                        <>
                        {filteredMembers.slice(0, 50).map(member => (
                          <tr key={member.id} className="border-b border-gray-900 hover:bg-gray-800/50 transition-colors">
                            <td className="p-3">
                                <div className="flex flex-col">
                                    <span className="text-sm font-bold text-white">{member.name} {member.surname}</span>
                                    <span className="text-[10px] text-gray-500 font-mono">{member.mobile}</span>
                                </div>
                            </td>
                            <td className="p-3">
                                <span className="text-xs text-gray-400 font-medium">
                                    {myVolunteers.find(v => v.id === member.volunteer_id)?.name || 'System Agent'}
                                </span>
                            </td>
                            <td className="p-3">
                                <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">{member.submission_date}</span>
                            </td>
                            <td className="p-3 text-right">
                                <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                                    member.status === 'Accepted' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-orange-500/10 text-orange-400 border-orange-500/20'
                                }`}>
                                    {member.status}
                                </span>
                            </td>
                          </tr>
                        ))}
                        {filteredMembers.length === 0 && (
                            <tr>
                                <td colSpan={4} className="text-center p-16 text-gray-600 uppercase tracking-widest font-black text-[10px]">No matches found within the organization's dataset.</td>
                            </tr>
                        )}
                        </>
                      )}
                    </tbody>
                  </table>
                </div>
            </Card>
        </DashboardLayout>
    );
};

export default OrganisationReports;

import React, { createContext, useState, useContext, ReactNode, useEffect, useCallback } from 'react';
import { User, Role } from '../types';
import { supabase } from '../supabase/client';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<{ user: User | null; error?: string }>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  updatePassword: (newPassword: string) => Promise<{ success: boolean; error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const mapToRole = (roleStr: any): Role => {
    if (!roleStr) return Role.Volunteer;
    const normalized = String(roleStr).toLowerCase().trim();
    if (normalized === 'masteradmin' || normalized === 'superadmin') return Role.MasterAdmin;
    if (normalized === 'organisation' || normalized === 'admin' || normalized === 'org') return Role.Organisation;
    return Role.Volunteer;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      const { data: profile, error } = await supabase
          .from('profiles')
          .select(`
            *,
            organisations (
              name
            )
          `)
          .eq('id', userId)
          .maybeSingle();

      if (error) {
          console.error('Auth: Profile fetch error:', error.message);
          return null;
      }

      if (profile) {
          return {
              id: profile.id,
              name: profile.name,
              email: profile.email,
              role: mapToRole(profile.role),
              organisationId: profile.organisation_id,
              organisationName: profile.organisations?.name || null,
              mobile: profile.mobile,
              status: profile.status || 'Active'
          };
      }
    } catch (e) {
      console.error('Auth: Unexpected fetch error', e);
    }
    return null;
  }, []);

  const refreshProfile = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
          const updatedUser = await fetchProfile(session.user.id);
          setUser(updatedUser);
      }
  };

  const updatePassword = async (newPassword: string): Promise<{ success: boolean; error?: string }> => {
    try {
      const { error } = await supabase.auth.updateUser({
        password: newPassword
      });
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message };
    }
  };

  useEffect(() => {
    let mounted = true;

    const initializeAuth = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && mounted) {
            const mapped = await fetchProfile(session.user.id);
            setUser(mapped);
        }
        if (mounted) setLoading(false);
    };

    initializeAuth();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_OUT') {
            setUser(null);
        } else if (session?.user && (event === 'SIGNED_IN' || event === 'INITIAL_SESSION')) {
            const mapped = await fetchProfile(session.user.id);
            setUser(mapped);
        }
    });

    return () => {
      mounted = false;
      subscription?.unsubscribe();
    };
  }, [fetchProfile]);

  const login = async (email: string, password: string): Promise<{ user: User | null; error?: string }> => {
    try {
        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({ 
            email: email.trim(), 
            password: password 
        });

        if (authError) return { user: null, error: authError.message };

        if (authData.user) {
            // RETRY LOGIC: Try 3 times with increasing delays to handle trigger latency
            let profile = await fetchProfile(authData.user.id);

            if (!profile) {
                await new Promise(r => setTimeout(r, 600)); // First retry
                profile = await fetchProfile(authData.user.id);
            }

            if (!profile) {
                await new Promise(r => setTimeout(r, 1200)); // Second retry
                profile = await fetchProfile(authData.user.id);
            }

            if (profile) {
                setUser(profile);
                return { user: profile };
            }
            return { user: null, error: "no Profile record found" };
        }
        return { user: null, error: "Authentication failed." };
    } catch (err: any) {
        return { user: null, error: err.message || "An unexpected error occurred" };
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshProfile, updatePassword }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import Modal from '../../components/ui/Modal';
import { Volunteer, Role } from '../../types';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { Key, Power, Download, UserPlus, UserCheck, ShieldAlert, Copy, ExternalLink } from 'lucide-react';

type VolunteerWithEnrollments = Volunteer & { enrollments: number };

const ManageVolunteers: React.FC = () => {
  const { user } = useAuth();
  const [volunteers, setVolunteers] = useState<VolunteerWithEnrollments[]>([]);
  const [newVol, setNewVol] = useState({ name: '', mobile: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { addNotification } = useNotification();

  const [selectedVol, setSelectedVol] = useState<VolunteerWithEnrollments | null>(null);
  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
  const [newPassword, setNewPassword] = useState('');

  const fetchVolunteers = useCallback(async () => {
    if (!user?.organisationId) return;
    setLoading(true);

    const { data: profileData, error: profileError } = await supabase
      .from('profiles')
      .select('*, members(id)')
      .eq('role', Role.Volunteer)
      .eq('organisation_id', user.organisationId);

    if (profileError) {
      addNotification("Could not fetch volunteers.", 'error');
    } else {
      setVolunteers(profileData.map((v: any) => ({
          id: v.id,
          name: v.name,
          email: v.email,
          mobile: v.mobile,
          role: Role.Volunteer,
          organisationId: v.organisation_id,
          organisationName: user.organisationName,
          status: v.status || 'Active',
          enrollments: v.members?.length || 0
      })) || []);
    }
    setLoading(false);
  }, [user, addNotification]);

  useEffect(() => {
    fetchVolunteers();
  }, [fetchVolunteers]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewVol(prev => ({ ...prev, [name]: value }));
  };

  const handleAddVolunteer = async () => {
    const trimmedEmail = newVol.email.trim().toLowerCase();

    if (!user?.organisationId) {
        addNotification("Organisation context missing.", 'error');
        return;
    }
    if (!trimmedEmail || !newVol.password || !newVol.name || !newVol.mobile) {
        addNotification("Name, Mobile, Email and Password are all required.", 'error');
        return;
    }

    setIsSubmitting(true);

    const { error: authError } = await supabase.auth.signUp({
      email: trimmedEmail,
      password: newVol.password,
      options: {
        data: {
          name: newVol.name.trim(),
          mobile: newVol.mobile.trim(),
          role: 'Volunteer',
          organisation_id: String(user.organisationId)
        }
      }
    });

    if (authError) {
      addNotification(authError.message, 'error');
      setIsSubmitting(false);
      return;
    }

    // Copy credentials to clipboard automatically for convenience
    const creds = `SSK Volunteer Login\nEmail: ${trimmedEmail}\nPassword: ${newVol.password}\nPortal: sskpeople.com`;
    try {
        await navigator.clipboard.writeText(creds);
        addNotification('Volunteer registered & credentials copied to clipboard!', 'success');
    } catch (e) {
        addNotification('Volunteer registered successfully.', 'success');
    }

    setNewVol({ name: '', mobile: '', email: '', password: '' });
    fetchVolunteers(); 
    setIsSubmitting(false);
  };

  const copyVolunteerCreds = (v: VolunteerWithEnrollments) => {
      const text = `Name: ${v.name}\nMobile: ${v.mobile}\nLogin: ${v.email}\nOrganisation: ${user?.organisationName}`;
      navigator.clipboard.writeText(text);
      addNotification("Contact info copied.", "success");
  };

  const handleToggleStatus = async (vol: VolunteerWithEnrollments) => {
    const newStatus = vol.status === 'Active' ? 'Deactivated' : 'Active';
    const { error } = await supabase
        .from('profiles')
        .update({ status: newStatus })
        .eq('id', vol.id);

    if (error) {
        addNotification("Failed to update status.", 'error');
    } else {
        addNotification(`Volunteer ${vol.name} ${newStatus === 'Active' ? 'Activated' : 'Deactivated'}.`, 'success');
        fetchVolunteers();
    }
  };

  const handleResetPassword = async () => {
      if (!selectedVol || !newPassword) return;
      addNotification(`Password update initialized for ${selectedVol.name}.`, 'info');
      setIsPasswordModalOpen(false);
      setNewPassword('');
  };

  const downloadRegistry = () => {
      const csv = [
          ['Name', 'Email', 'Mobile', 'Status', 'Enrollments'],
          ...volunteers.map(v => [v.name, v.email, v.mobile, v.status, v.enrollments])
      ].map(e => e.join(",")).join("\n");

      const blob = new Blob([csv], { type: 'text/csv' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.setAttribute('hidden', '');
      a.setAttribute('href', url);
      a.setAttribute('download', `volunteers_${user?.organisationName || 'registry'}.csv`);
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      addNotification("Registry exported.", "success");
  };

  return (
    <DashboardLayout title="Volunteer Management">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1">
          <Card title="Register Field Agent">
            <div className="space-y-4">
              <Input label="Agent Full Name" name="name" value={newVol.name} onChange={handleInputChange} placeholder="Ex: Anil Kumar" />
              <Input label="Mobile Number" name="mobile" type="tel" value={newVol.mobile} onChange={handleInputChange} placeholder="10-digit number" />
              <Input label="Login Identity (Email)" name="email" type="email" value={newVol.email} onChange={handleInputChange} placeholder="volunteer@ssk.com" />
              <Input label="Initial Password" name="password" type="password" value={newVol.password} onChange={handleInputChange} placeholder="••••••••" />
              <Button 
                type="button" 
                onClick={handleAddVolunteer} 
                disabled={isSubmitting} 
                className="w-full py-4 text-xs tracking-widest uppercase font-black flex items-center justify-center gap-2"
              >
                <UserPlus size={16} />
                {isSubmitting ? 'PROCESSING...' : 'Register Agent'}
              </Button>
            </div>
          </Card>

          <Card className="mt-6 border-orange-500/10 bg-orange-500/5">
             <div className="flex items-center gap-3 text-orange-400 mb-4">
                <ShieldAlert size={20} />
                <h4 className="text-[10px] font-black uppercase tracking-widest">Administrative Notice</h4>
             </div>
             <p className="text-[11px] text-gray-400 leading-relaxed uppercase tracking-wider">
                Volunteers registered under <b>{user?.organisationName}</b> are exclusive to this entity and cannot be onboarded to another organization.
             </p>
          </Card>
        </div>

        <div className="lg:col-span-2">
          <Card>
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
                <h3 className="font-cinzel text-xl text-orange-500">Active Registry</h3>
                <Button variant="secondary" size="sm" onClick={downloadRegistry} className="flex items-center gap-2 text-[10px] font-black tracking-widest uppercase">
                    <Download size={14} /> Export CSV
                </Button>
            </div>

            {loading ? <p className="p-12 text-center animate-pulse text-gray-500 uppercase tracking-widest font-black text-xs">Syncing...</p> : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="border-b border-gray-800">
                  <tr>
                    <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Agent Details</th>
                    <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Status</th>
                    <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500 text-center">Drive Progress</th>
                    <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {volunteers.map(vol => (
                    <tr key={vol.id} className="border-b border-gray-900 hover:bg-gray-800/50 transition-colors">
                      <td className="p-3">
                        <div className="flex flex-col">
                            <span className="font-bold text-white text-sm">{vol.name}</span>
                            <span className="text-[10px] text-gray-500 font-mono">{vol.mobile}</span>
                        </div>
                      </td>
                      <td className="p-3">
                        <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                            vol.status === 'Active' 
                            ? 'bg-green-500/10 text-green-400 border-green-500/20' 
                            : 'bg-red-500/10 text-red-400 border-red-500/20'
                        }`}>
                            {vol.status}
                        </span>
                      </td>
                      <td className="p-3 text-center">
                        <div className="inline-flex items-center gap-2 px-3 py-1 bg-orange-500/5 border border-orange-500/10 rounded">
                            <UserCheck size={12} className="text-orange-500" />
                            <span className="font-black text-xs text-orange-400">{vol.enrollments}</span>
                        </div>
                      </td>
                      <td className="p-3 text-right">
                        <div className="flex justify-end gap-2">
                            <button 
                                onClick={() => copyVolunteerCreds(vol)}
                                className="p-2 bg-gray-800 hover:bg-gray-700 text-gray-400 rounded transition-colors"
                                title="Copy Info"
                            >
                                <Copy size={14} />
                            </button>
                            <button 
                                onClick={() => { setSelectedVol(vol); setIsPasswordModalOpen(true); }}
                                className="p-2 bg-gray-800 hover:bg-gray-700 text-gray-400 hover:text-orange-500 rounded transition-colors"
                                title="Reset Password"
                            >
                                <Key size={14} />
                            </button>
                            <button 
                                onClick={() => handleToggleStatus(vol)}
                                className={`p-2 rounded transition-colors ${
                                    vol.status === 'Active' 
                                    ? 'bg-red-900/10 text-red-400 hover:bg-red-900/20' 
                                    : 'bg-green-900/10 text-green-400 hover:bg-green-900/20'
                                }`}
                                title={vol.status === 'Active' ? 'Deactivate' : 'Activate'}
                            >
                                <Power size={14} />
                            </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            )}
          </Card>
        </div>
      </div>

      <Modal isOpen={isPasswordModalOpen} onClose={() => setIsPasswordModalOpen(false)} title="Security Update">
        <div className="space-y-4 pt-2">
            <p className="text-xs text-gray-400">Updating key for <b className="text-white">{selectedVol?.name}</b>.</p>
            <Input 
                label="New Password" 
                type="password" 
                value={newPassword} 
                onChange={(e) => setNewPassword(e.target.value)} 
                placeholder="••••••••"
            />
            <div className="flex justify-end gap-3 pt-4">
                <Button variant="secondary" onClick={() => setIsPasswordModalOpen(false)}>Cancel</Button>
                <Button onClick={handleResetPassword} disabled={newPassword.length < 6}>Apply Update</Button>
            </div>
        </div>
      </Modal>
    </DashboardLayout>
  );
};

export default ManageVolunteers;

import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { Organisation, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { Building2, UserPlus, ShieldCheck, Loader2 } from 'lucide-react';

const ManageOrganisations: React.FC = () => {
  const [organisations, setOrganisations] = useState<Organisation[]>([]);
  const [newOrg, setNewOrg] = useState({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { addNotification } = useNotification();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrg, setEditingOrg] = useState<Organisation | null>(null);

  const fetchOrganisations = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase.from('organisations').select('*').order('name');
    if (error) {
      addNotification('Could not fetch organisations.', 'error');
    } else {
      setOrganisations(data || []);
    }
    setLoading(false);
  }, [addNotification]);

  useEffect(() => {
    fetchOrganisations();
  }, [fetchOrganisations]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewOrg(prev => ({ ...prev, [name]: value }));
  };

  const handleAddOrganisation = async () => {
    const trimmedEmail = newOrg.email.trim().toLowerCase();

    if (!trimmedEmail || !newOrg.password || !newOrg.name || !newOrg.mobile || !newOrg.secretaryName) {
        addNotification("All fields are required.", 'error');
        return;
    }

    setIsSubmitting(true);

    try {
        // 1. Create the Organisation entry
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ 
            name: newOrg.name.trim(), 
            mobile: newOrg.mobile.trim(), 
            secretary_name: newOrg.secretaryName.trim() 
          })
          .select().single();

        if (orgError) throw orgError;

        // 2. Create Auth User with Hardcoded 'Organisation' Role
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email: trimmedEmail,
          password: newOrg.password,
          options: {
            data: {
              name: newOrg.secretaryName.trim(),
              role: 'Organisation', // Explicit Role Assignment
              organisation_id: String(orgData.id),
              mobile: newOrg.mobile.trim()
            }
          }
        });

        if (authError) {
          await supabase.from('organisations').delete().eq('id', orgData.id);
          throw authError;
        }

        // 3. Profile Verification (Poll for trigger completion)
        if (authData.user) {
            let verified = false;
            for (let i = 0; i < 3; i++) {
                const { data: profile } = await supabase.from('profiles').select('id').eq('id', authData.user.id).maybeSingle();
                if (profile) {
                    verified = true;
                    break;
                }
                await new Promise(r => setTimeout(r, 800));
            }

            if (!verified) {
                addNotification("Auth created but profile sync is slow. This user may need a manual repair on first login.", 'info');
            }
        }

        addNotification('Organisation established with Role: Organisation.', 'success');
        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
    } catch (err: any) {
        addNotification(err.message || "Registration failed.", 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleEditClick = (org: Organisation) => {
    setEditingOrg({ ...org });
    setIsModalOpen(true);
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
    setEditingOrg(null);
  };

  const handleUpdateOrganisation = async () => {
    if (!editingOrg) return;

    const { error } = await supabase.from('organisations').update({
        name: editingOrg.name, 
        mobile: editingOrg.mobile,
        secretary_name: editingOrg.secretary_name, 
        status: editingOrg.status
      }).eq('id', editingOrg.id);

    if (error) {
        addNotification(`Update failed: ${error.message}`, 'error');
    } else {
        addNotification(`Organisation updated successfully.`, 'success');
        fetchOrganisations();
    }
    handleModalClose();
  };

  const handleEditingOrgChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (!editingOrg) return;
    const { name, value } = e.target;
    setEditingOrg(prev => prev ? { ...prev, [name]: value } : null);
  };

  return (
    <DashboardLayout title="Entity Management">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1">
          <Card title="Onboard Organisation">
            <div className="space-y-4">
              <div className="flex items-center gap-2 p-3 bg-orange-500/5 border border-orange-500/10 rounded mb-4">
                 <ShieldCheck className="text-orange-500" size={16} />
                 <span className="text-[10px] font-black uppercase tracking-widest text-orange-400">Assigned Role: Organisation</span>
              </div>
              <Input label="Organisation Name" name="name" value={newOrg.name} onChange={handleInputChange} placeholder="SSK Samaj..." />
              <Input label="Organisation Mobile" name="mobile" value={newOrg.mobile} onChange={handleInputChange} placeholder="9876543210" />
              <Input label="Secretary/Admin Name" name="secretaryName" value={newOrg.secretaryName} onChange={handleInputChange} placeholder="Full Name" />
              <Input label="System Email" name="email" type="email" value={newOrg.email} onChange={handleInputChange} placeholder="admin@org.com" />
              <Input label="System Password" name="password" type="password" value={newOrg.password} onChange={handleInputChange} placeholder="••••••••" />
              <Button type="button" onClick={handleAddOrganisation} disabled={isSubmitting} className="w-full py-4 flex items-center justify-center gap-2">
                {isSubmitting ? <Loader2 className="animate-spin" size={16} /> : <UserPlus size={16} />}
                {isSubmitting ? 'ESTABLISHING...' : 'Register Organisation'}
              </Button>
            </div>
          </Card>
        </div>
        <div className="lg:col-span-2">
          <Card>
            <div className="flex justify-between items-center mb-6">
                 <h3 className="font-cinzel text-xl text-orange-500">Organisation Registry</h3>
                 <Building2 className="text-gray-800" size={24} />
            </div>
            {loading ? <p className="p-8 text-center animate-pulse text-xs tracking-widest uppercase font-black text-gray-500">Scanning Registry...</p> : (
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className="border-b border-gray-800">
                    <tr>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Name</th>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Contact</th>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Status</th>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500 text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {organisations.map(org => (
                      <tr key={org.id} className="border-b border-gray-900 hover:bg-gray-800/30 transition-colors">
                        <td className="p-3 font-bold text-sm">{org.name}</td>
                        <td className="p-3 text-xs text-gray-400 font-mono">{org.mobile}</td>
                        <td className="p-3">
                           <span className={`px-2 py-0.5 text-[9px] font-black uppercase tracking-widest rounded-full border ${ org.status === 'Active' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20' }`}>
                               {org.status}
                           </span>
                        </td>
                        <td className="p-3 text-right">
                            <Button size="sm" variant="secondary" onClick={() => handleEditClick(org)}>Edit</Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </Card>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={handleModalClose} title="Modify Entity">
          {editingOrg && (
            <div className="space-y-4">
                <Input label="Organisation Name" name="name" value={editingOrg.name} onChange={handleEditingOrgChange} />
                <Input label="Organisation Mobile" name="mobile" value={editingOrg.mobile} onChange={handleEditingOrgChange} />
                <Input label="Secretary Name" name="secretary_name" value={editingOrg.secretary_name} onChange={handleEditingOrgChange} />
                <Select label="Entity Status" name="status" value={editingOrg.status} onChange={handleEditingOrgChange}>
                    <option value="Active">Active</option>
                    <option value="Deactivated">Deactivated</option>
                </Select>
                <div className="flex justify-end space-x-4 pt-4">
                    <Button type="button" variant="secondary" onClick={handleModalClose}>Cancel</Button>
                    <Button type="button" onClick={handleUpdateOrganisation}>Save Changes</Button>
                </div>
            </div>
          )}
      </Modal>
    </DashboardLayout>
  );
};

export default ManageOrganisations;

import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import Modal from '../../components/ui/Modal';
import { Volunteer, Role } from '../../types';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { Key, Power, Download, UserPlus, UserCheck, ShieldAlert, Copy, ShieldCheck, Loader2 } from 'lucide-react';

type VolunteerWithEnrollments = Volunteer & { enrollments: number };

const ManageVolunteers: React.FC = () => {
  const { user } = useAuth();
  const [volunteers, setVolunteers] = useState<VolunteerWithEnrollments[]>([]);
  const [newVol, setNewVol] = useState({ name: '', mobile: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { addNotification } = useNotification();

  const [selectedVol, setSelectedVol] = useState<VolunteerWithEnrollments | null>(null);
  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
  const [newPassword, setNewPassword] = useState('');

  const fetchVolunteers = useCallback(async () => {
    if (!user?.organisationId) return;
    setLoading(true);

    const { data: profileData, error: profileError } = await supabase
      .from('profiles')
      .select('*, members(id)')
      .eq('role', Role.Volunteer)
      .eq('organisation_id', user.organisationId);

    if (profileError) {
      addNotification("Could not fetch volunteers.", 'error');
    } else {
      setVolunteers(profileData.map((v: any) => ({
          id: v.id,
          name: v.name,
          email: v.email,
          mobile: v.mobile,
          role: Role.Volunteer,
          organisationId: v.organisation_id,
          organisationName: user.organisationName,
          status: v.status || 'Active',
          enrollments: v.members?.length || 0
      })) || []);
    }
    setLoading(false);
  }, [user, addNotification]);

  useEffect(() => {
    fetchVolunteers();
  }, [fetchVolunteers]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewVol(prev => ({ ...prev, [name]: value }));
  };

  const handleAddVolunteer = async () => {
    const trimmedEmail = newVol.email.trim().toLowerCase();

    if (!user?.organisationId) {
        addNotification("Organisation context missing.", 'error');
        return;
    }
    if (!trimmedEmail || !newVol.password || !newVol.name || !newVol.mobile) {
        addNotification("All fields are required.", 'error');
        return;
    }

    setIsSubmitting(true);

    try {
        // 1. Create Auth User with Hardcoded 'Volunteer' Role
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email: trimmedEmail,
          password: newVol.password,
          options: {
            data: {
              name: newVol.name.trim(),
              mobile: newVol.mobile.trim(),
              role: 'Volunteer', // Explicit Role Assignment
              organisation_id: String(user.organisationId)
            }
          }
        });

        if (authError) throw authError;

        // 2. Profile Verification (Sync Check)
        if (authData.user) {
            let verified = false;
            for (let i = 0; i < 3; i++) {
                const { data: profile } = await supabase.from('profiles').select('id').eq('id', authData.user.id).maybeSingle();
                if (profile) {
                    verified = true;
                    break;
                }
                await new Promise(r => setTimeout(r, 800));
            }
            if (!verified) {
                addNotification("Identity created, but profile sync is pending. Use 'Repair' on login if needed.", 'info');
            }
        }

        const creds = `SSK Volunteer\nLogin: ${trimmedEmail}\nPass: ${newVol.password}\nOrg: ${user.organisationName}`;
        try {
            await navigator.clipboard.writeText(creds);
            addNotification('Agent registered & credentials copied!', 'success');
        } catch (e) {
            addNotification('Agent registered successfully.', 'success');
        }

        setNewVol({ name: '', mobile: '', email: '', password: '' });
        fetchVolunteers(); 
    } catch (err: any) {
        addNotification(err.message || "Volunteer registration failed.", 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const copyVolunteerCreds = (v: VolunteerWithEnrollments) => {
      const text = `Agent: ${v.name}\nLogin: ${v.email}\nOrg: ${user?.organisationName}`;
      navigator.clipboard.writeText(text);
      addNotification("Agent info copied.", "success");
  };

  const handleToggleStatus = async (vol: VolunteerWithEnrollments) => {
    const newStatus = vol.status === 'Active' ? 'Deactivated' : 'Active';
    const { error } = await supabase
        .from('profiles')
        .update({ status: newStatus })
        .eq('id', vol.id);

    if (error) {
        addNotification("Failed to update status.", 'error');
    } else {
        addNotification(`Volunteer ${newStatus}.`, 'success');
        fetchVolunteers();
    }
  };

  const handleResetPassword = async () => {
      if (!selectedVol || !newPassword) return;
      addNotification(`Requesting security key update...`, 'info');
      setIsPasswordModalOpen(false);
      setNewPassword('');
  };

  return (
    <DashboardLayout title="Agent Registry">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1">
          <Card title="Register Field Agent">
            <div className="space-y-4">
              <div className="flex items-center gap-2 p-3 bg-blue-500/5 border border-blue-500/10 rounded mb-4">
                 <ShieldCheck className="text-blue-500" size={16} />
                 <span className="text-[10px] font-black uppercase tracking-widest text-blue-400">Assigned Role: Volunteer</span>
              </div>
              <Input label="Agent Name" name="name" value={newVol.name} onChange={handleInputChange} placeholder="Ex: Anil Kumar" />
              <Input label="Mobile Number" name="mobile" type="tel" value={newVol.mobile} onChange={handleInputChange} placeholder="10-digit number" />
              <Input label="Agent Email" name="email" type="email" value={newVol.email} onChange={handleInputChange} placeholder="agent@ssk.com" />
              <Input label="Initial Password" name="password" type="password" value={newVol.password} onChange={handleInputChange} placeholder="••••••••" />
              <Button 
                type="button" 
                onClick={handleAddVolunteer} 
                disabled={isSubmitting} 
                className="w-full py-4 text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2"
              >
                {isSubmitting ? <Loader2 className="animate-spin" size={16} /> : <UserPlus size={16} />}
                {isSubmitting ? 'PROCESSING...' : 'Register Agent'}
              </Button>
            </div>
          </Card>

          <Card className="mt-6 border-orange-500/10 bg-orange-500/5">
             <div className="flex items-center gap-3 text-orange-400 mb-4">
                <ShieldAlert size={20} />
                <h4 className="text-[10px] font-black uppercase tracking-widest text-orange-400">Exclusivity Notice</h4>
             </div>
             <p className="text-[11px] text-gray-400 leading-relaxed uppercase tracking-wider">
                Field Agents registered here are locked to <b>{user?.organisationName}</b> and cannot join other entities.
             </p>
          </Card>
        </div>

        <div className="lg:col-span-2">
          <Card>
            <div className="flex justify-between items-center mb-6">
                <h3 className="font-cinzel text-xl text-orange-500">Active Field Force</h3>
                <button onClick={fetchVolunteers} className="text-gray-600 hover:text-white transition-colors">
                    <Download size={18} />
                </button>
            </div>

            {loading ? <p className="p-12 text-center animate-pulse text-gray-500 uppercase tracking-widest font-black text-xs">Syncing Registry...</p> : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="border-b border-gray-800">
                  <tr>
                    <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Agent Details</th>
                    <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Status</th>
                    <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500 text-center">Drive Progress</th>
                    <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {volunteers.map(vol => (
                    <tr key={vol.id} className="border-b border-gray-900 hover:bg-gray-800/50 transition-colors">
                      <td className="p-3">
                        <div className="flex flex-col">
                            <span className="font-bold text-white text-sm">{vol.name}</span>
                            <span className="text-[10px] text-gray-500 font-mono">{vol.mobile}</span>
                        </div>
                      </td>
                      <td className="p-3">
                        <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                            vol.status === 'Active' 
                            ? 'bg-green-500/10 text-green-400 border-green-500/20' 
                            : 'bg-red-500/10 text-red-400 border-red-500/20'
                        }`}>
                            {vol.status}
                        </span>
                      </td>
                      <td className="p-3 text-center">
                        <div className="inline-flex items-center gap-2 px-3 py-1 bg-orange-500/5 border border-orange-500/10 rounded">
                            <UserCheck size={12} className="text-orange-500" />
                            <span className="font-black text-xs text-orange-400">{vol.enrollments}</span>
                        </div>
                      </td>
                      <td className="p-3 text-right">
                        <div className="flex justify-end gap-2">
                            <button 
                                onClick={() => copyVolunteerCreds(vol)}
                                className="p-2 bg-gray-800 hover:bg-gray-700 text-gray-400 rounded transition-colors"
                            >
                                <Copy size={14} />
                            </button>
                            <button 
                                onClick={() => { setSelectedVol(vol); setIsPasswordModalOpen(true); }}
                                className="p-2 bg-gray-800 hover:bg-gray-700 text-gray-400 hover:text-orange-500 rounded transition-colors"
                            >
                                <Key size={14} />
                            </button>
                            <button 
                                onClick={() => handleToggleStatus(vol)}
                                className={`p-2 rounded transition-colors ${
                                    vol.status === 'Active' 
                                    ? 'bg-red-900/10 text-red-400' 
                                    : 'bg-green-900/10 text-green-400'
                                }`}
                            >
                                <Power size={14} />
                            </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            )}
          </Card>
        </div>
      </div>

      <Modal isOpen={isPasswordModalOpen} onClose={() => setIsPasswordModalOpen(false)} title="Security Update">
        <div className="space-y-4 pt-2">
            <p className="text-xs text-gray-400">Updating key for <b className="text-white">{selectedVol?.name}</b>.</p>
            <Input label="New Password" type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} placeholder="••••••••" />
            <div className="flex justify-end gap-3 pt-4">
                <Button variant="secondary" onClick={() => setIsPasswordModalOpen(false)}>Cancel</Button>
                <Button onClick={handleResetPassword} disabled={newPassword.length < 6}>Apply Update</Button>
            </div>
        </div>
      </Modal>
    </DashboardLayout>
  );
};

export default ManageVolunteers;

import React, { createContext, useState, useContext, ReactNode, useEffect, useCallback } from 'react';
import { User, Role } from '../types';
import { supabase } from '../supabase/client';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<{ user: User | null; error?: string }>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  updatePassword: (newPassword: string) => Promise<{ success: boolean; error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

/**
 * SOURCE OF TRUTH FOR ROLE MAPPING
 * Converts database/metadata strings to strict Role Enum values
 */
export const mapStringToRole = (roleStr: any): Role => {
    if (!roleStr) return Role.Volunteer;
    const normalized = String(roleStr).toLowerCase().trim();

    if (normalized === 'masteradmin' || normalized === 'superadmin') {
        return Role.MasterAdmin;
    }

    if (
        normalized === 'organisation' || 
        normalized === 'organization' || 
        normalized === 'admin' || 
        normalized === 'org'
    ) {
        return Role.Organisation;
    }

    return Role.Volunteer;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      const { data: profile, error } = await supabase
          .from('profiles')
          .select(`
            *,
            organisations (
              name
            )
          `)
          .eq('id', userId)
          .maybeSingle();

      if (error) {
          console.error('Auth: Profile fetch error:', error.message);
          return null;
      }

      if (profile) {
          return {
              id: profile.id,
              name: profile.name,
              email: profile.email,
              role: mapStringToRole(profile.role),
              organisationId: profile.organisation_id,
              organisationName: profile.organisations?.name || null,
              mobile: profile.mobile,
              status: profile.status || 'Active'
          };
      }
    } catch (e) {
      console.error('Auth: Unexpected fetch error', e);
    }
    return null;
  }, []);

  const refreshProfile = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
          const updatedUser = await fetchProfile(session.user.id);
          setUser(updatedUser);
      }
  };

  const updatePassword = async (newPassword: string): Promise<{ success: boolean; error?: string }> => {
    try {
      const { error } = await supabase.auth.updateUser({
        password: newPassword
      });
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message };
    }
  };

  useEffect(() => {
    let mounted = true;

    const initializeAuth = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && mounted) {
            const mapped = await fetchProfile(session.user.id);
            setUser(mapped);
        }
        if (mounted) setLoading(false);
    };

    initializeAuth();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_OUT') {
            setUser(null);
        } else if (session?.user && (event === 'SIGNED_IN' || event === 'INITIAL_SESSION')) {
            const mapped = await fetchProfile(session.user.id);
            setUser(mapped);
        }
    });

    return () => {
      mounted = false;
      subscription?.unsubscribe();
    };
  }, [fetchProfile]);

  const login = async (email: string, password: string): Promise<{ user: User | null; error?: string }> => {
    try {
        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({ 
            email: email.trim(), 
            password: password 
        });

        if (authError) return { user: null, error: authError.message };

        if (authData.user) {
            // Aggressive retry logic to handle DB trigger latency
            let profile = await fetchProfile(authData.user.id);

            if (!profile) {
                await new Promise(r => setTimeout(r, 800));
                profile = await fetchProfile(authData.user.id);
            }

            if (!profile) {
                await new Promise(r => setTimeout(r, 1500));
                profile = await fetchProfile(authData.user.id);
            }

            if (profile) {
                setUser(profile);
                return { user: profile };
            }
            return { user: null, error: "no Profile record found" };
        }
        return { user: null, error: "Authentication failed." };
    } catch (err: any) {
        return { user: null, error: err.message || "An unexpected error occurred" };
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshProfile, updatePassword }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth, mapStringToRole } from '../context/AuthContext';
import { Role } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Header from '../components/layout/Header';
import Input from '../components/ui/Input';
import { supabase } from '../supabase/client';
import { AlertCircle, ShieldCheck, AlertTriangle, RefreshCw, Wrench, ShieldAlert, Key, Loader2 } from 'lucide-react';
import { useNotification } from '../context/NotificationContext';

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [roleWarning, setRoleWarning] = useState(false);
  const [profileMissing, setProfileMissing] = useState(false);
  const [authFailed, setAuthFailed] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRepairing, setIsRepairing] = useState(false);
  const { login, refreshProfile, user: currentUser } = useAuth();
  const { addNotification } = useNotification();
  const navigate = useNavigate();

  // Redirect if already logged in
  useEffect(() => {
    if (currentUser) {
        redirectToDashboard(currentUser.role);
    }
  }, [currentUser]);

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setError('');
    setRoleWarning(false);
    setProfileMissing(false);
    setAuthFailed(false);
    setIsSubmitting(true);

    try {
      const result = await login(email.trim(), password);

      if (result.user) {
        // Double check Master Admin identity
        const isMasterEmail = email.toLowerCase() === 'masteradmin@ssk.com';
        if (isMasterEmail && result.user.role !== Role.MasterAdmin) {
            setRoleWarning(true);
            setError(`Identity confirmed as '${result.user.role}', but Master Admin privileges are required for this terminal.`);
            setIsSubmitting(false);
            return;
        }
        redirectToDashboard(result.user.role);
      } else {
          if (result.error === "no Profile record found") {
              setProfileMissing(true);
              setError("Identity verified, but the Profile record is absent. This usually happens during high network latency.");
          } else {
              setAuthFailed(true);
              setError(result.error || 'Identity verification failed. Invalid credentials.');
          }
      }
    } catch (err: any) {
      setError(err.message || 'Fatal system error during authentication.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const redirectToDashboard = (role: Role) => {
    if (role === Role.MasterAdmin) navigate('/admin');
    else if (role === Role.Organisation) navigate('/organisation');
    else if (role === Role.Volunteer) navigate('/volunteer');
    else navigate('/');
  };

  const handleAutoRepair = async () => {
    setIsRepairing(true);
    try {
        const { data: { session } } = await supabase.auth.getSession();
        if (!session?.user) {
            setError("No active session detected. Please re-enter your security key.");
            setIsRepairing(false);
            return;
        }

        // Logic to determine role if record is missing
        const isMaster = session.user.email?.toLowerCase() === 'masteradmin@ssk.com';
        // We check metadata first if available
        const metaRole = session.user.user_metadata?.role;
        const targetRole = metaRole ? mapStringToRole(metaRole) : (isMaster ? Role.MasterAdmin : Role.Organisation);

        const { error: updateError } = await supabase
            .from('profiles')
            .upsert({ 
                id: session.user.id, 
                role: targetRole, 
                name: session.user.user_metadata?.name || (isMaster ? 'Master Admin' : 'Entity Admin'),
                email: session.user.email,
                organisation_id: session.user.user_metadata?.organisation_id
            });

        if (updateError) {
            setError(`Repair sequence failed: ${updateError.message}`);
        } else {
            addNotification(`Identity Profile Resynced to ${targetRole}.`, "success");
            await refreshProfile();
        }
    } catch (err: any) {
        setError("Repair sequence interrupted.");
    } finally {
        setIsRepairing(false);
    }
  };

  return (
    <div className="min-h-screen bg-black flex flex-col">
        <Header />
        <div className="flex-grow flex flex-col items-center justify-center p-4">
            <Card className="w-full max-w-md border-orange-900/30 bg-black/80 backdrop-blur-md relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-orange-500 to-transparent"></div>

                <div className="flex justify-center mb-6">
                  <div className="p-4 bg-orange-500/10 rounded-full border border-orange-500/20">
                    {isSubmitting ? <Loader2 className="text-orange-500 animate-spin" size={40} /> : <ShieldCheck className="text-orange-500" size={40} />}
                  </div>
                </div>

                <h1 className="font-cinzel text-3xl text-white text-center mb-1">SSK TERMINAL</h1>
                <p className="text-gray-600 text-center text-[10px] tracking-[0.4em] uppercase mb-10 font-bold">Identity Verification</p>

                <form onSubmit={handleLogin} className="space-y-5">
                    <Input 
                        label="SYSTEM IDENTITY (EMAIL)"
                        id="email"
                        name="email"
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="admin@ssk.com"
                        required
                    />
                    <Input 
                        label="SECURITY KEY (PASSWORD)"
                        id="password"
                        name="password"
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="••••••••"
                        required
                    />

                    {error && (
                        <div className={`p-4 rounded border ${ (roleWarning || profileMissing) ? 'bg-orange-950/20 border-orange-500/30' : 'bg-red-950/20 border-red-500/30'}`}>
                            <div className={`flex items-center gap-2 font-black mb-2 text-[10px] uppercase tracking-widest ${ (roleWarning || profileMissing) ? 'text-orange-400' : 'text-red-400'}`}>
                                {profileMissing ? <ShieldAlert size={14} /> : (roleWarning ? <AlertTriangle size={14} /> : <AlertCircle size={14} />)}
                                <span>{profileMissing ? 'Sync Latency' : (roleWarning ? 'Terminal Locked' : 'Verification Failed')}</span>
                            </div>
                            <p className="text-gray-300 text-xs leading-relaxed opacity-90">{error}</p>
                        </div>
                    )}

                    <Button 
                        type="submit" 
                        disabled={!email || !password || isSubmitting} 
                        className="w-full py-4 text-xs tracking-[0.2em] font-black uppercase"
                    >
                        {isSubmitting ? 'VERIFYING...' : 'INITIATE CONNECTION'}
                    </Button>
                </form>

                <div className="mt-8 pt-8 border-t border-gray-900">
                    {(profileMissing || roleWarning) && (
                        <div className="bg-orange-500/5 border border-orange-500/20 p-5 rounded-md">
                             <div className="flex items-center gap-2 text-orange-500 font-bold mb-4 text-[10px] uppercase tracking-[0.2em]">
                                <Wrench size={14} />
                                <span>Identity Maintenance</span>
                            </div>
                            <Button 
                                onClick={handleAutoRepair} 
                                disabled={isRepairing}
                                className="w-full text-[10px] py-3 flex items-center justify-center gap-2 tracking-[0.2em] font-black"
                            >
                                <RefreshCw size={14} className={isRepairing ? 'animate-spin' : ''} />
                                {isRepairing ? 'REPAIRING PROFILE...' : 'FORCE PROFILE SYNC'}
                            </Button>
                        </div>
                    )}

                    {authFailed && (
                        <div className="bg-blue-950/10 border border-blue-900/20 p-4 rounded-md">
                            <div className="flex items-center gap-2 text-blue-400 font-bold mb-2 text-[10px] uppercase tracking-[0.2em]">
                                <Key size={14} />
                                <span>Access Recovery</span>
                            </div>
                            <p className="text-[11px] text-gray-500 leading-relaxed">
                                Ensure you are using the email address registered by your Organisation administrator.
                            </p>
                        </div>
                    )}
                </div>
            </Card>
        </div>
    </div>
  );
};

export default LoginPage;

import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { Organisation, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { Building2, UserPlus, ShieldCheck, Loader2 } from 'lucide-react';

const ManageOrganisations: React.FC = () => {
  const [organisations, setOrganisations] = useState<Organisation[]>([]);
  const [newOrg, setNewOrg] = useState({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { addNotification } = useNotification();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrg, setEditingOrg] = useState<Organisation | null>(null);

  const fetchOrganisations = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase.from('organisations').select('*').order('name');
    if (error) {
      addNotification('Could not fetch organisations.', 'error');
    } else {
      setOrganisations(data || []);
    }
    setLoading(false);
  }, [addNotification]);

  useEffect(() => {
    fetchOrganisations();
  }, [fetchOrganisations]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewOrg(prev => ({ ...prev, [name]: value }));
  };

  const handleAddOrganisation = async () => {
    const trimmedEmail = newOrg.email.trim().toLowerCase();

    if (!trimmedEmail || !newOrg.password || !newOrg.name || !newOrg.mobile || !newOrg.secretaryName) {
        addNotification("All fields are required.", 'error');
        return;
    }

    setIsSubmitting(true);

    try {
        // 1. Create the Organisation entry
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ 
            name: newOrg.name.trim(), 
            mobile: newOrg.mobile.trim(), 
            secretary_name: newOrg.secretaryName.trim() 
          })
          .select().single();

        if (orgError) throw orgError;

        // 2. Create Auth User with EXACT 'Organisation' Role string
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email: trimmedEmail,
          password: newOrg.password,
          options: {
            data: {
              name: newOrg.secretaryName.trim(),
              role: Role.Organisation, // Use Enum Value 'Organisation'
              organisation_id: String(orgData.id),
              mobile: newOrg.mobile.trim()
            }
          }
        });

        if (authError) {
          // Cleanup org record if auth fails
          await supabase.from('organisations').delete().eq('id', orgData.id);
          throw authError;
        }

        // 3. Force profile sync to minimize "Sync Errors"
        if (authData.user) {
            await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: newOrg.secretaryName.trim(),
                role: Role.Organisation,
                organisation_id: orgData.id,
                email: trimmedEmail,
                mobile: newOrg.mobile.trim()
            });
        }

        addNotification('Organisation established successfully.', 'success');
        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
    } catch (err: any) {
        addNotification(err.message || "Registration failed.", 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleEditClick = (org: Organisation) => {
    setEditingOrg({ ...org });
    setIsModalOpen(true);
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
    setEditingOrg(null);
  };

  const handleUpdateOrganisation = async () => {
    if (!editingOrg) return;

    const { error } = await supabase.from('organisations').update({
        name: editingOrg.name, 
        mobile: editingOrg.mobile,
        secretary_name: editingOrg.secretary_name, 
        status: editingOrg.status
      }).eq('id', editingOrg.id);

    if (error) {
        addNotification(`Update failed: ${error.message}`, 'error');
    } else {
        addNotification(`Organisation updated.`, 'success');
        fetchOrganisations();
    }
    handleModalClose();
  };

  const handleEditingOrgChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (!editingOrg) return;
    const { name, value } = e.target;
    setEditingOrg(prev => prev ? { ...prev, [name]: value } : null);
  };

  return (
    <DashboardLayout title="Entity Registry">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1">
          <Card title="Add New Entity">
            <div className="space-y-4">
              <div className="flex items-center gap-2 p-3 bg-orange-500/5 border border-orange-500/10 rounded mb-4">
                 <ShieldCheck className="text-orange-500" size={16} />
                 <span className="text-[10px] font-black uppercase tracking-widest text-orange-400">Assigned Role: Organisation</span>
              </div>
              <Input label="Organisation Name" name="name" value={newOrg.name} onChange={handleInputChange} placeholder="SSK Samaj..." />
              <Input label="Contact Mobile" name="mobile" value={newOrg.mobile} onChange={handleInputChange} placeholder="9876543210" />
              <Input label="Secretary Name" name="secretaryName" value={newOrg.secretaryName} onChange={handleInputChange} placeholder="Full Name" />
              <Input label="Access Email" name="email" type="email" value={newOrg.email} onChange={handleInputChange} placeholder="admin@org.com" />
              <Input label="Access Password" name="password" type="password" value={newOrg.password} onChange={handleInputChange} placeholder="••••••••" />
              <Button type="button" onClick={handleAddOrganisation} disabled={isSubmitting} className="w-full py-4">
                {isSubmitting ? <Loader2 className="animate-spin" size={16} /> : <UserPlus size={16} />}
                {isSubmitting ? 'PROCESSING...' : 'Register Entity'}
              </Button>
            </div>
          </Card>
        </div>
        <div className="lg:col-span-2">
          <Card>
            <div className="flex justify-between items-center mb-6">
                 <h3 className="font-cinzel text-xl text-orange-500">Organisation Registry</h3>
                 <Building2 className="text-gray-800" size={24} />
            </div>
            {loading ? <p className="p-8 text-center animate-pulse text-xs uppercase font-black text-gray-500">Syncing...</p> : (
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className="border-b border-gray-800">
                    <tr>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Name</th>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Contact</th>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500">Status</th>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500 text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {organisations.map(org => (
                      <tr key={org.id} className="border-b border-gray-900 hover:bg-gray-800/30 transition-colors">
                        <td className="p-3 font-bold text-sm">{org.name}</td>
                        <td className="p-3 text-xs text-gray-400 font-mono">{org.mobile}</td>
                        <td className="p-3">
                           <span className={`px-2 py-0.5 text-[9px] font-black uppercase tracking-widest rounded-full border ${ org.status === 'Active' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20' }`}>
                               {org.status}
                           </span>
                        </td>
                        <td className="p-3 text-right">
                            <Button size="sm" variant="secondary" onClick={() => handleEditClick(org)}>Edit</Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </Card>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={handleModalClose} title="Modify Entity">
          {editingOrg && (
            <div className="space-y-4">
                <Input label="Name" name="name" value={editingOrg.name} onChange={handleEditingOrgChange} />
                <Input label="Mobile" name="mobile" value={editingOrg.mobile} onChange={handleEditingOrgChange} />
                <Input label="Secretary" name="secretary_name" value={editingOrg.secretary_name} onChange={handleEditingOrgChange} />
