import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { Organisation, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';

const ManageOrganisations: React.FC = () => {
  const [organisations, setOrganisations] = useState<Organisation[]>([]);
  const [newOrg, setNewOrg] = useState({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { addNotification } = useNotification();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrg, setEditingOrg] = useState<Organisation | null>(null);

  const fetchOrganisations = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase.from('organisations').select('*').order('name');
    if (error) {
      console.error('Error fetching organisations:', error);
      addNotification('Could not fetch organisations.', 'error');
    } else {
      setOrganisations(data || []);
    }
    setLoading(false);
  }, [addNotification]);

  useEffect(() => {
    fetchOrganisations();
  }, [fetchOrganisations]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewOrg(prev => ({ ...prev, [name]: value }));
  };

  const handleAddOrganisation = async () => {
    const email = newOrg.email.trim();
    const password = newOrg.password;
    const name = newOrg.name.trim();
    const mobile = newOrg.mobile.trim();
    const secretaryName = newOrg.secretaryName.trim();

    if (!email || !password || !name || !mobile || !secretaryName) {
        addNotification("All fields are required.", 'error');
        return;
    }

    setIsSubmitting(true);

    try {
        // 1. Create the Organisation entry
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ 
            name: name, 
            mobile: mobile, 
            secretary_name: secretaryName 
          })
          .select().single();

        if (orgError) throw orgError;

        // 2. Create Auth User
        // Passing exact Enum 'Organisation' and ensuring ID is not an empty string
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email: email,
          password: password,
          options: {
            data: {
              name: secretaryName,
              role: Role.Organisation, 
              organisation_id: orgData.id,
              mobile: mobile
            }
          }
        });

        if (authError) {
          // Cleanup org record if auth fails to avoid orphaned records
          await supabase.from('organisations').delete().eq('id', orgData.id);
          throw authError;
        }

        // 3. Forced Profile Creation (Defensive check against trigger failures)
        if (authData.user) {
            await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: secretaryName,
                email: email,
                role: Role.Organisation,
                organisation_id: orgData.id,
                mobile: mobile,
                status: 'Active'
            });
        }

        addNotification('Organisation terminal access established.', 'success');
        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
    } catch (err: any) {
        console.error("Organisation Registration Error:", err);
        addNotification(err.message || "Identity creation failed. Please check terminal logs.", 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleEditClick = (org: Organisation) => {
    setEditingOrg({ ...org });
    setIsModalOpen(true);
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
    setEditingOrg(null);
  };

  const handleUpdateOrganisation = async () => {
    if (!editingOrg) return;

    const { error } = await supabase.from('organisations').update({
        name: editingOrg.name, 
        mobile: editingOrg.mobile,
        secretary_name: editingOrg.secretary_name, 
        status: editingOrg.status
      }).eq('id', editingOrg.id);

    if (error) {
        addNotification(`Update failed: ${error.message}`, 'error');
    } else {
        addNotification(`Organisation updated successfully.`, 'success');
        fetchOrganisations();
    }
    handleModalClose();
  };

  const handleEditingOrgChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (!editingOrg) return;
    const { name, value } = e.target;
    setEditingOrg(prev => prev ? { ...prev, [name]: value } : null);
  };

  return (
    <DashboardLayout title="Entity Registry">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1">
          <Card title="Add New Entity">
            <div className="space-y-4">
              <Input label="Organisation Name" name="name" value={newOrg.name} onChange={handleInputChange} placeholder="Ex: SSK Hubli" />
              <Input label="Organisation Mobile" name="mobile" value={newOrg.mobile} onChange={handleInputChange} placeholder="9876543210" />
              <Input label="Secretary/Admin Name" name="secretaryName" value={newOrg.secretaryName} onChange={handleInputChange} placeholder="Full Name" />
              <Input label="System Login Email" name="email" type="email" value={newOrg.email} onChange={handleInputChange} placeholder="admin@org.com" />
              <Input label="Security Key (Password)" name="password" type="password" value={newOrg.password} onChange={handleInputChange} placeholder="••••••••" />
              <Button type="button" onClick={handleAddOrganisation} disabled={isSubmitting} className="w-full py-3">
                {isSubmitting ? 'Synchronizing...' : 'Register Organisation'}
              </Button>
            </div>
          </Card>
        </div>
        <div className="lg:col-span-2">
          <Card title="Active Entities">
            {loading ? <p className="text-center p-10 animate-pulse text-gray-500 uppercase font-black text-xs tracking-widest">Scanning Registry...</p> : (
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className="border-b border-gray-800">
                    <tr>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500 font-black">Entity Name</th>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500 font-black">Contact</th>
                      <th className="p-3 text-[10px] uppercase tracking-widest text-gray-500 font-black">Status</th>
                      <th className="p-3 text-right text-[10px] uppercase tracking-widest text-gray-500 font-black">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {organisations.map(org => (
                      <tr key={org.id} className="border-b border-gray-900 hover:bg-gray-800/30 transition-colors">
                        <td className="p-3 font-bold text-sm">{org.name}</td>
                        <td className="p-3 text-xs text-gray-400 font-mono">{org.mobile}</td>
                        <td className="p-3">
                           <span className={`px-2 py-0.5 text-[10px] font-black uppercase tracking-widest rounded-full border ${ org.status === 'Active' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20' }`}>
                               {org.status}
                           </span>
                        </td>
                        <td className="p-3 text-right">
                            <Button size="sm" variant="secondary" onClick={() => handleEditClick(org)}>Edit</Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </Card>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={handleModalClose} title="Modify Entity Profile">
          {editingOrg && (
            <div className="space-y-4">
                <Input label="Organisation Name" name="name" value={editingOrg.name} onChange={handleEditingOrgChange} />
                <Input label="Organisation Mobile" name="mobile" value={editingOrg.mobile} onChange={handleEditingOrgChange} />
                <Input label="Secretary Name" name="secretary_name" value={editingOrg.secretary_name} onChange={handleEditingOrgChange} />
                <Select label="Entity Status" name="status" value={editingOrg.status} onChange={handleEditingOrgChange}>
                    <option value="Active">Active</option>
                    <option value="Deactivated">Deactivated</option>
                </Select>
                <div className="flex justify-end space-x-4 pt-4">
                    <Button type="button" variant="secondary" onClick={handleModalClose}>Cancel</Button>
                    <Button type="button" onClick={handleUpdateOrganisation}>Commit Changes</Button>
                </div>
            </div>
          )}
      </Modal>
    </DashboardLayout>
  );
};

export default ManageOrganisations;

import React, { useState, useEffect, useCallback } from 'react';
