import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { Organisation, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { ShieldCheck, UserPlus, Building2, Loader2, AlertCircle, Terminal, Copy, CheckCircle2 } from 'lucide-react';

const ManageOrganisations: React.FC = () => {
  const [organisations, setOrganisations] = useState<Organisation[]>([]);
  const [newOrg, setNewOrg] = useState({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSqlFix, setShowSqlFix] = useState(false);

  const { addNotification } = useNotification();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrg, setEditingOrg] = useState<Organisation | null>(null);

  const fetchOrganisations = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase.from('organisations').select('*').order('name');
    if (error) {
      console.error('Error fetching organisations:', error);
      addNotification('Could not fetch organisations.', 'error');
    } else {
      setOrganisations(data || []);
    }
    setLoading(false);
  }, [addNotification]);

  useEffect(() => {
    fetchOrganisations();
  }, [fetchOrganisations]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewOrg(prev => ({ ...prev, [name]: value }));
  };

  const sqlFixCode = `CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, email, name, role, organisation_id, mobile, status)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'name', 'User'),
    (COALESCE(NEW.raw_user_meta_data->>'role', 'Volunteer'))::user_role,
    NULLIF(NEW.raw_user_meta_data->>'organisation_id', '')::uuid,
    NEW.raw_user_meta_data->>'mobile',
    'Active'
  )
  ON CONFLICT (id) DO UPDATE SET
    role = EXCLUDED.role,
    organisation_id = EXCLUDED.organisation_id,
    name = EXCLUDED.name,
    mobile = EXCLUDED.mobile;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;`;

  const copySql = () => {
    navigator.clipboard.writeText(sqlFixCode);
    addNotification("SQL Code copied to clipboard.", "success");
  };

  const handleAddOrganisation = async () => {
    const email = newOrg.email.trim().toLowerCase();
    const password = newOrg.password;
    const name = newOrg.name.trim();
    const mobile = newOrg.mobile.trim();
    const secretaryName = newOrg.secretaryName.trim();

    if (!email || !password || !name || !mobile || !secretaryName) {
        addNotification("All fields are required.", 'error');
        return;
    }

    setIsSubmitting(true);
    setShowSqlFix(false);

    try {
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ name, mobile, secretary_name: secretaryName })
          .select().single();

        if (orgError) throw orgError;

        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              name: secretaryName,
              role: 'Organisation',
              organisation_id: orgData.id, // Explicit UUID from DB
              mobile
            }
          }
        });

        if (authError) {
          await supabase.from('organisations').delete().eq('id', orgData.id);
          throw authError;
        }

        // Defensive Profile Sync
        if (authData.user) {
            await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: secretaryName,
                email,
                role: 'Organisation',
                organisation_id: orgData.id,
                mobile,
                status: 'Active'
            });
        }

        addNotification('Organisation registry successful.', 'success');
        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
    } catch (err: any) {
        console.error("Critical Reg Error:", err);
        const msg = err.message || "";
        if (msg.includes("Database error")) {
            setShowSqlFix(true);
            addNotification("Database Trigger Error detected. Run the SQL fix below.", 'error');
        } else {
            addNotification(msg || "Registration failed.", 'error');
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <DashboardLayout title="Entity Registry">
      <div className="space-y-8">
        {showSqlFix && (
          <div className="bg-red-950/20 border border-red-500/30 rounded-2xl p-6 animate-in fade-in slide-in-from-top-4 duration-500">
             <div className="flex items-start gap-4">
                <div className="p-3 bg-red-500/10 rounded-xl text-red-500">
                    <Terminal size={24} />
                </div>
                <div className="flex-1">
                    <h3 className="text-red-400 font-black uppercase tracking-widest text-xs mb-2">Backend Repair Required</h3>
                    <p className="text-gray-400 text-xs leading-relaxed mb-4">
                        Your Supabase database is failing to process new users because the SQL trigger is missing a type cast for <code className="text-white bg-gray-800 px-1 rounded">organisation_id</code>. Copy the code below and run it in your <b>Supabase SQL Editor</b> to fix this instantly.
                    </p>
                    <div className="relative group">
                        <pre className="bg-black/80 p-4 rounded-xl border border-gray-800 font-mono text-[10px] text-orange-400/80 overflow-x-auto whitespace-pre-wrap max-h-48">
                            {sqlFixCode}
                        </pre>
                        <button 
                            onClick={copySql}
                            className="absolute top-3 right-3 p-2 bg-gray-800 hover:bg-orange-500 text-white rounded-lg transition-all shadow-xl"
                            title="Copy Fix Code"
                        >
                            <Copy size={14} />
                        </button>
                    </div>
                </div>
             </div>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
            <div className="lg:col-span-1">
                <Card title="Register New Entity">
                    <div className="space-y-4">
                    <Input label="Organisation Name" name="name" value={newOrg.name} onChange={handleInputChange} placeholder="SSK Samaj..." />
                    <Input label="Primary Contact Mobile" name="mobile" value={newOrg.mobile} onChange={handleInputChange} placeholder="9876543210" />
                    <Input label="Admin / Secretary Name" name="secretaryName" value={newOrg.secretaryName} onChange={handleInputChange} placeholder="Full Name" />
                    <Input label="System Login Email" name="email" type="email" value={newOrg.email} onChange={handleInputChange} placeholder="admin@entity.com" />
                    <Input label="Access Secret (Password)" name="password" type="password" value={newOrg.password} onChange={handleInputChange} placeholder="••••••••" />
                    <Button type="button" onClick={handleAddOrganisation} disabled={isSubmitting} className="w-full py-4 flex items-center justify-center gap-2">
                        {isSubmitting ? <Loader2 className="animate-spin" size={18} /> : <UserPlus size={18} />}
                        {isSubmitting ? 'SYNCHRONIZING...' : 'Establish Connection'}
                    </Button>
                    </div>
                </Card>
            </div>

            <div className="lg:col-span-2">
                <Card>
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="font-cinzel text-xl text-orange-500">Registry Snapshot</h3>
                        <Building2 className="text-gray-800" size={24} />
                    </div>
                    {loading ? (
                        <div className="p-20 flex justify-center"><Loader2 className="animate-spin text-orange-500" size={32} /></div>
                    ) : (
                        <div className="overflow-x-auto">
                            <table className="w-full text-left">
                            <thead className="border-b border-gray-800">
                                <tr>
                                <th className="p-4 text-[10px] uppercase tracking-widest text-gray-500 font-black">Entity Identity</th>
                                <th className="p-4 text-[10px] uppercase tracking-widest text-gray-500 font-black">Status</th>
                                <th className="p-4 text-right text-[10px] uppercase tracking-widest text-gray-500 font-black">Control</th>
                                </tr>
                            </thead>
                            <tbody>
                                {organisations.map(org => (
                                <tr key={org.id} className="border-b border-gray-900 hover:bg-gray-800/30 transition-colors">
                                    <td className="p-4">
                                        <div className="flex flex-col">
                                            <span className="font-bold text-sm text-white">{org.name}</span>
                                            <span className="text-[10px] text-gray-500 font-mono">{org.mobile}</span>
                                        </div>
                                    </td>
                                    <td className="p-4">
                                    <span className={`px-2 py-0.5 text-[9px] font-black uppercase tracking-widest rounded-full border ${ org.status === 'Active' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20' }`}>
                                        {org.status}
                                    </span>
                                    </td>
                                    <td className="p-4 text-right">
                                        <Button size="sm" variant="secondary" onClick={() => { setEditingOrg(org); setIsModalOpen(true); }} className="text-[10px]">Modify</Button>
                                    </td>
                                </tr>
                                ))}
                            </tbody>
                            </table>
                        </div>
                    )}
                </Card>
            </div>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Modify Entity Profile">
          {editingOrg && (
            <div className="space-y-4">
                <Input label="Organisation Name" name="name" value={editingOrg.name} onChange={(e) => setEditingOrg({...editingOrg, name: e.target.value})} />
                <Input label="Organisation Mobile" name="mobile" value={editingOrg.mobile} onChange={(e) => setEditingOrg({...editingOrg, mobile: e.target.value})} />
                <Select label="Entity Status" name="status" value={editingOrg.status} onChange={(e) => setEditingOrg({...editingOrg, status: e.target.value as any})}>
                    <option value="Active">Active</option>
                    <option value="Deactivated">Deactivated</option>
                </Select>
                <div className="flex justify-end space-x-4 pt-4">
                    <Button type="button" variant="secondary" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                    <Button type="button" onClick={handleUpdateOrganisation}>Commit Changes</Button>
                </div>
            </div>
          )}
      </Modal>
    </DashboardLayout>
  );

  async function handleUpdateOrganisation() {
    if (!editingOrg) return;
    const { error } = await supabase.from('organisations').update({
        name: editingOrg.name, mobile: editingOrg.mobile, status: editingOrg.status
    }).eq('id', editingOrg.id);
    if (!error) {
        addNotification("Organisation updated.", "success");
        fetchOrganisations();
        setIsModalOpen(false);
    }
  }
};

export default ManageOrganisations;

