import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { Organisation, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { ShieldCheck, UserPlus, Building2, Loader2, Database, Terminal, Copy, AlertTriangle, CheckCircle2, ChevronRight, Settings } from 'lucide-react';

const ManageOrganisations: React.FC = () => {
  const [organisations, setOrganisations] = useState<Organisation[]>([]);
  const [newOrg, setNewOrg] = useState({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSqlFix, setShowSqlFix] = useState(false);

  const { addNotification } = useNotification();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrg, setEditingOrg] = useState<Organisation | null>(null);

  const fetchOrganisations = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase.from('organisations').select('*').order('name');
    if (error) {
      console.error('Error fetching organisations:', error);
      addNotification('Could not fetch organisations.', 'error');
    } else {
      setOrganisations(data || []);
    }
    setLoading(false);
  }, [addNotification]);

  useEffect(() => {
    fetchOrganisations();
  }, [fetchOrganisations]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewOrg(prev => ({ ...prev, [name]: value }));
  };

  const sqlFixCode = `-- FINAL REPAIR SCRIPT: FIX DATABASE SYNC ERROR
-- Execute this in your Supabase SQL Editor to fix the 'Database error saving new user'
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
DECLARE
  org_id_txt text;
  org_id_uuid uuid;
BEGIN
  -- Extract organisation_id safely
  org_id_txt := NULLIF(NEW.raw_user_meta_data->>'organisation_id', '');

  -- Attempt UUID conversion
  IF org_id_txt IS NOT NULL THEN
     org_id_uuid := org_id_txt::uuid;
  ELSE
     org_id_uuid := NULL;
  END IF;

  INSERT INTO public.profiles (id, email, name, role, organisation_id, mobile, status)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'name', 'User'),
    (COALESCE(NEW.raw_user_meta_data->>'role', 'Volunteer'))::user_role,
    org_id_uuid, -- Correctly cast UUID
    NEW.raw_user_meta_data->>'mobile',
    'Active'
  )
  ON CONFLICT (id) DO UPDATE SET
    role = EXCLUDED.role,
    organisation_id = EXCLUDED.organisation_id,
    name = EXCLUDED.name,
    mobile = EXCLUDED.mobile;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;`;

  const copySql = () => {
    navigator.clipboard.writeText(sqlFixCode);
    addNotification("Hardened Repair Script copied. Paste in SQL Editor and click RUN.", "success");
  };

  const handleAddOrganisation = async () => {
    const email = newOrg.email.trim().toLowerCase();
    const password = newOrg.password;
    const name = newOrg.name.trim();
    const mobile = newOrg.mobile.trim();
    const secretaryName = newOrg.secretaryName.trim();

    if (!email || !password || !name || !mobile || !secretaryName) {
        addNotification("All fields are mandatory.", 'error');
        return;
    }

    setIsSubmitting(true);
    setShowSqlFix(false);

    try {
        // 1. Create the Organisation entry
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ name, mobile, secretary_name: secretaryName })
          .select().single();

        if (orgError) throw orgError;

        // 2. Create Auth User
        // Note: The 'Database error' happens here because the trigger crashes on insert
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              name: secretaryName,
              role: 'Organisation',
              organisation_id: String(orgData.id), // Ensure it's a string for metadata
              mobile
            }
          }
        });

        if (authError) {
          // Cleanup org record if auth fails
          await supabase.from('organisations').delete().eq('id', orgData.id);
          throw authError;
        }

        // 3. Forced Sync (Safety Net)
        if (authData.user) {
            const { error: profileError } = await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: secretaryName,
                email,
                role: 'Organisation',
                organisation_id: orgData.id,
                mobile,
                status: 'Active'
            });

            if (profileError && profileError.message.includes("uuid")) {
                setShowSqlFix(true);
                throw new Error("System Sync Error: Your database trigger requires a manual UUID repair.");
            }
        }

        addNotification('Organisation terminal successfully authorized.', 'success');
        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
    } catch (err: any) {
        console.error("Master Registration Failure:", err);
        const msg = err.message || "";
        if (msg.includes("Database error saving new user") || msg.includes("uuid") || msg.includes("invalid input syntax")) {
            setShowSqlFix(true);
            addNotification("Sync Error: Critical Database Repair required.", 'error');
        } else {
            addNotification(msg || "Authorization sequence interrupted.", 'error');
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleEditClick = (org: Organisation) => {
    setEditingOrg({ ...org });
    setIsModalOpen(true);
  };

  const handleUpdateOrganisation = async () => {
    if (!editingOrg) return;
    const { error } = await supabase.from('organisations').update({
        name: editingOrg.name, 
        mobile: editingOrg.mobile,
        secretary_name: editingOrg.secretary_name, 
        status: editingOrg.status
    }).eq('id', editingOrg.id);

    if (error) {
        addNotification(`Update failed: ${error.message}`, 'error');
    } else {
        addNotification(`Registry entry updated.`, 'success');
        fetchOrganisations();
        setIsModalOpen(false);
    }
  };

  return (
    <DashboardLayout title="Entity Administration">
      <div className="space-y-12">
        {showSqlFix && (
          <div className="bg-[#050000] border border-red-500/40 rounded-[2.5rem] p-10 animate-in fade-in slide-in-from-top-10 duration-700 shadow-[0_0_80px_-20px_rgba(239,68,68,0.3)]">
             <div className="flex flex-col lg:flex-row items-start gap-10">
                <div className="p-6 bg-red-500/10 rounded-3xl text-red-500 border border-red-500/20 shadow-xl">
                    <Database size={48} strokeWidth={1} className="animate-pulse" />
                </div>
                <div className="flex-1">
                    <div className="flex items-center gap-4 mb-6">
                        <div className="h-3 w-3 rounded-full bg-red-500 animate-ping"></div>
                        <h3 className="font-cinzel text-2xl text-red-400 tracking-[0.1em] uppercase">Critical Sync Repair Required</h3>
                    </div>
                    <p className="text-gray-400 text-base leading-relaxed mb-10 max-w-3xl">
                        The <b className="text-white">"Database error saving new user"</b> is a Postgres conflict in your Supabase trigger. It is attempting to insert a text ID into a UUID column without a cast. 
                        <br/><br/>
                        <span className="text-red-400/80 font-bold uppercase tracking-widest text-xs">Steps to resolve:</span>
                        <br/>
                        1. Copy the script below.
                        <br/>
                        2. Open your <b className="text-white">Supabase Dashboard</b> → <b className="text-white">SQL Editor</b>.
                        <br/>
                        3. Create a <b className="text-white">New Query</b>, paste the script, and click <b className="text-white">RUN</b>.
                    </p>
                    <div className="relative group">
                        <div className="absolute inset-0 bg-red-500/[0.03] blur-[40px] rounded-3xl"></div>
                        <pre className="relative bg-black/95 p-8 rounded-[2rem] border border-gray-800 font-mono text-[11px] text-red-400/90 overflow-x-auto whitespace-pre-wrap max-h-[350px] scrollbar-hide shadow-inner">
                            {sqlFixCode}
                        </pre>
                        <button 
                            onClick={copySql}
                            className="absolute top-8 right-8 p-5 bg-gray-800 hover:bg-red-600 text-white rounded-2xl transition-all shadow-2xl flex items-center gap-3 text-[10px] font-black uppercase tracking-widest border border-white/5 active:scale-95 group-hover:scale-105"
                        >
                            <Copy size={18} />
                            <span>Copy Final Repair Script</span>
                        </button>
                    </div>
                </div>
             </div>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
            <div className="lg:col-span-1">
                <Card title="Authorize New Entity">
                    <div className="space-y-6">
                        <div className="p-5 bg-orange-500/5 border border-orange-500/10 rounded-2xl mb-2 flex items-center gap-4">
                             <ShieldCheck className="text-orange-500" size={28} />
                             <span className="text-[11px] font-black uppercase tracking-[0.3em] text-orange-400/80 leading-tight">Identity Tier:<br/>Organisation Admin</span>
                        </div>
                        <Input label="Organisation Name" name="name" value={newOrg.name} onChange={handleInputChange} placeholder="SSK Samaj Bangalore" />
                        <Input label="Registry Mobile" name="mobile" value={newOrg.mobile} onChange={handleInputChange} placeholder="98XXXXXXXX" />
                        <Input label="Secretary Name" name="secretaryName" value={newOrg.secretaryName} onChange={handleInputChange} placeholder="Full Name" />
                        <Input label="Access Email" name="email" type="email" value={newOrg.email} onChange={handleInputChange} placeholder="admin@entity.com" />
                        <Input label="Security Key" name="password" type="password" value={newOrg.password} onChange={handleInputChange} placeholder="••••••••" />
                        <Button type="button" onClick={handleAddOrganisation} disabled={isSubmitting} className="w-full py-5 flex items-center justify-center gap-3 text-[11px] font-black tracking-[0.3em] uppercase mt-4 shadow-xl">
                            {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <UserPlus size={20} />}
                            {isSubmitting ? 'AUTHORIZING NODE...' : 'Authorize Entity'}
                        </Button>
                    </div>
                </Card>
            </div>

            <div className="lg:col-span-2">
                <Card>
                    <div className="flex justify-between items-center mb-12">
                        <div className="flex items-center gap-4">
                            <div className="p-3 bg-white/5 rounded-2xl text-orange-500">
                                <Building2 size={24} />
                            </div>
                            <h3 className="font-cinzel text-3xl text-white">Authorized Registry</h3>
                        </div>
                        <div className="flex items-center gap-3 px-5 py-2.5 bg-white/5 rounded-full border border-white/5">
                            <div className="h-2 w-2 rounded-full bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]"></div>
                            <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Live Secure Sync</span>
                        </div>
                    </div>
                    {loading ? (
                        <div className="p-40 flex flex-col items-center justify-center gap-8">
                            <div className="w-16 h-16 border-4 border-orange-500/20 border-t-orange-500 rounded-full animate-spin"></div>
                            <span className="text-[11px] font-black uppercase tracking-[0.5em] text-gray-600">Accessing Master Registry...</span>
                        </div>
                    ) : (
                        <div className="overflow-x-auto">
                            <table className="w-full text-left">
                                <thead className="border-b border-gray-800">
                                    <tr>
                                        <th className="p-6 text-[11px] uppercase tracking-[0.4em] text-gray-500 font-black">Identity</th>
                                        <th className="p-6 text-[11px] uppercase tracking-[0.4em] text-gray-500 font-black text-right">Verification</th>
                                        <th className="p-6"></th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {organisations.map(org => (
                                    <tr key={org.id} className="group border-b border-gray-900/50 hover:bg-white/[0.02] transition-all duration-500">
                                        <td className="p-6">
                                            <div className="flex flex-col gap-1">
                                                <span className="font-bold text-lg text-white group-hover:text-orange-500 transition-colors">{org.name}</span>
                                                <div className="flex items-center gap-3 text-[10px] text-gray-600 uppercase tracking-widest">
                                                    <span>{org.secretary_name}</span>
                                                    <span className="h-1 w-1 rounded-full bg-gray-800"></span>
                                                    <span className="font-mono">{org.mobile}</span>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-6 text-right">
                                            <span className={`px-4 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-full border shadow-sm transition-all ${ org.status === 'Active' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20' }`}>
                                                {org.status}
                                            </span>
                                        </td>
                                        <td className="p-6 text-right opacity-0 group-hover:opacity-100 transition-opacity">
                                            <Button size="sm" variant="secondary" onClick={() => handleEditClick(org)} className="text-[10px] font-black uppercase tracking-[0.2em] px-5 py-2.5 rounded-xl">Edit</Button>
