                    <Button type="button" onClick={handleUpdateOrganisation} className="text-[11px] font-black uppercase tracking-widest px-8 shadow-lg shadow-orange-900/20">Commit Changes</Button>
                </div>
            </div>
          )}
      </Modal>
    </DashboardLayout>
  );
};

