  const sqlFixCode = `-- ULTIMATE REPAIR SCRIPT: FIX UUID CRASH & INFINITE RLS RECURSION
-- INSTRUCTIONS: Copy this entire block, go to Supabase SQL Editor, paste, and click RUN.

-- 1. BREAK RECURSION (Role Helper)
-- We use SECURITY DEFINER to bypass RLS within this function, breaking the loop.
CREATE OR REPLACE FUNCTION public.get_my_role()
RETURNS text AS $$
  SELECT role::text FROM public.profiles WHERE id = auth.uid();
$$ LANGUAGE sql SECURITY DEFINER SET search_path = public;

-- 2. HARDENED TRIGGER (Fixes UUID Casting Crash)
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
DECLARE
    parsed_org_id uuid;
    raw_org_id text;
BEGIN
    raw_org_id := NEW.raw_user_meta_data->>'organisation_id';

    -- Pre-validate UUID format with Regex to prevent casting crashes
    IF raw_org_id IS NOT NULL 
       AND raw_org_id ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' 
    THEN
        parsed_org_id := raw_org_id::uuid;
    ELSE
        parsed_org_id := NULL;
    END IF;

    INSERT INTO public.profiles (id, email, name, role, organisation_id, mobile, status)
    VALUES (
        NEW.id,
        NEW.email,
        COALESCE(NEW.raw_user_meta_data->>'name', 'User'),
        (COALESCE(NEW.raw_user_meta_data->>'role', 'Volunteer'))::user_role,
        parsed_org_id,
        NEW.raw_user_meta_data->>'mobile',
        'Active'
    )
    ON CONFLICT (id) DO UPDATE SET
        email = EXCLUDED.email,
        name = EXCLUDED.name,
        role = EXCLUDED.role,
        organisation_id = EXCLUDED.organisation_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 3. RESET POLICIES (Recursion-Free)
DROP POLICY IF EXISTS "Admins have full access" ON public.profiles;
DROP POLICY IF EXISTS "Users can view own profile" ON public.profiles;

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

-- Simple non-recursive policy for self
CREATE POLICY "Users can view own profile" 
ON public.profiles FOR SELECT 
USING (auth.uid() = id);

-- Uses the helper function to check role without triggering RLS recursion
CREATE POLICY "Admins have full access" 
ON public.profiles FOR ALL 
USING (public.get_my_role() = 'MasterAdmin');

-- 4. RE-ATTACH TRIGGER
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();`;

