import React, { createContext, useState, useContext, ReactNode, useEffect, useCallback } from 'react';
import { User, Role } from '../types';
import { supabase } from '../supabase/client';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<{ user: User | null; error?: string }>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  updatePassword: (newPassword: string) => Promise<{ success: boolean; error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

/**
 * SOURCE OF TRUTH FOR ROLE MAPPING
 * Ensures database strings are correctly mapped to our Role Enum
 */
export const mapStringToRole = (roleStr: any): Role => {
    if (!roleStr) return Role.Volunteer;
    const normalized = String(roleStr).toLowerCase().trim();

    // Master Admin Checks
    if (normalized === 'masteradmin' || normalized === 'superadmin' || normalized === 'master_admin') {
        return Role.MasterAdmin;
    }

    // Organisation Checks
    if (
        normalized === 'organisation' || 
        normalized === 'organization' || 
        normalized === 'admin' || 
        normalized === 'org' ||
        normalized === 'organisation_admin' ||
        normalized === 'org_admin'
    ) {
        return Role.Organisation;
    }

    return Role.Volunteer;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      const { data: profile, error } = await supabase
          .from('profiles')
          .select(`
            *,
            organisations (
              name
            )
          `)
          .eq('id', userId)
          .maybeSingle();

      if (error) {
          console.error('Auth: Profile fetch error:', error.message);
          if (error.message.includes('recursion')) {
              // Return the specific error message to be handled by the UI
              throw new Error('infinite recursion detected in policy for relation "profiles"');
          }
          return null;
      }

      if (profile) {
          return {
              id: profile.id,
              name: profile.name,
              email: profile.email,
              role: mapStringToRole(profile.role),
              organisationId: profile.organisation_id,
              organisationName: profile.organisations?.name || null,
              mobile: profile.mobile,
              status: profile.status || 'Active'
          };
      }
    } catch (e: any) {
      console.error('Auth: Unexpected fetch error', e);
      if (e.message?.includes('recursion')) throw e;
    }
    return null;
  }, []);

  const refreshProfile = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
          try {
              const updatedUser = await fetchProfile(session.user.id);
              setUser(updatedUser);
          } catch (e) {
              console.error("Failed to refresh profile due to recursion");
          }
      }
  };

  const updatePassword = async (newPassword: string): Promise<{ success: boolean; error?: string }> => {
    try {
      const { error } = await supabase.auth.updateUser({
        password: newPassword
      });
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message };
    }
  };

  useEffect(() => {
    let mounted = true;

    const initializeAuth = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && mounted) {
            try {
                const mapped = await fetchProfile(session.user.id);
                setUser(mapped);
            } catch (e) {
                console.error("Initialization error: recursion detected.");
            }
        }
        if (mounted) setLoading(false);
    };

    initializeAuth();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_OUT') {
            setUser(null);
        } else if (session?.user && (event === 'SIGNED_IN' || event === 'INITIAL_SESSION')) {
            try {
                const mapped = await fetchProfile(session.user.id);
                setUser(mapped);
            } catch (e) {
                console.error("Auth change error: recursion detected.");
            }
        }
    });

    return () => {
      mounted = false;
      subscription?.unsubscribe();
    };
  }, [fetchProfile]);

  const login = async (email: string, password: string): Promise<{ user: User | null; error?: string }> => {
    try {
        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({ 
            email: email.trim(), 
            password: password 
        });

        if (authError) return { user: null, error: authError.message };

        if (authData.user) {
            try {
                // Retry logic with slight delay for trigger sync
                let profile = await fetchProfile(authData.user.id);

                if (!profile) {
                    await new Promise(r => setTimeout(r, 800));
                    profile = await fetchProfile(authData.user.id);
                }

                if (profile) {
                    setUser(profile);
                    return { user: profile };
                }
                return { user: null, error: "Profile record missing." };
            } catch (e: any) {
                return { user: null, error: e.message };
            }
        }
        return { user: null, error: "Authentication failed." };
    } catch (err: any) {
        return { user: null, error: err.message || "An unexpected error occurred" };
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshProfile, updatePassword }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Role } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Header from '../components/layout/Header';
import Input from '../components/ui/Input';
import { ShieldCheck, AlertCircle, AlertTriangle, Copy, Loader2, Zap, Info } from 'lucide-react';
import { useNotification } from '../context/NotificationContext';

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [roleWarning, setRoleWarning] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showRepair, setShowRepair] = useState(false);

  const { login, user: currentUser } = useAuth();
  const { addNotification } = useNotification();
  const navigate = useNavigate();

  useEffect(() => {
    if (currentUser) {
        const role = currentUser.role;
        if (role === Role.MasterAdmin) navigate('/admin');
        else if (role === Role.Organisation) navigate('/organisation');
        else if (role === Role.Volunteer) navigate('/volunteer');
    }
  }, [currentUser, navigate]);

  const sqlRepairScript = `-- RECURSION REPAIR SCRIPT (Run in Supabase SQL Editor)
-- This breaks the infinite loop in your RLS policies.

CREATE OR REPLACE FUNCTION public.get_my_role()
RETURNS text AS $$
  -- SECURITY DEFINER bypasses RLS to break recursion
  SELECT role::text FROM public.profiles WHERE id = auth.uid();
$$ LANGUAGE sql SECURITY DEFINER SET search_path = public;

-- Reset and re-apply non-recursive policies
DROP POLICY IF EXISTS "Admins have full access" ON public.profiles;
DROP POLICY IF EXISTS "Users can view own profile" ON public.profiles;

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own profile" 
ON public.profiles FOR SELECT 
USING (auth.uid() = id);

CREATE POLICY "Admins have full access" 
ON public.profiles FOR ALL 
USING (public.get_my_role() = 'MasterAdmin');`;

  const copyRepairScript = () => {
    navigator.clipboard.writeText(sqlRepairScript);
    addNotification("Repair script copied. Paste it into your Supabase SQL Editor.", "success");
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setError('');
    setRoleWarning(false);
    setShowRepair(false);
    setIsSubmitting(true);

    try {
      const result = await login(email.trim(), password);

      if (result.user) {
        const isMasterEmail = email.toLowerCase() === 'masteradmin@ssk.com';
        if (isMasterEmail && result.user.role !== Role.MasterAdmin) {
            setRoleWarning(true);
            setError(`Terminal mismatch. Detected role '${result.user.role}', but Master privileges are required.`);
            setIsSubmitting(false);
            return;
        }

        const role = result.user.role;
        if (role === Role.MasterAdmin) navigate('/admin');
        else if (role === Role.Organisation) navigate('/organisation');
        else if (role === Role.Volunteer) navigate('/volunteer');
      } else {
          const errMsg = result.error || 'Identity verification failed.';
          setError(errMsg);
          if (errMsg.toLowerCase().includes('recursion')) {
              setShowRepair(true);
          }
      }
    } catch (err: any) {
      const errMsg = err.message || 'Authentication error.';
      setError(errMsg);
      if (errMsg.toLowerCase().includes('recursion')) {
          setShowRepair(true);
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-black flex flex-col">
        <Header />
        <div className="flex-grow flex flex-col items-center justify-center p-4">
            <div className="w-full max-w-md space-y-6">
                <Card className="border-orange-900/30 bg-black/80 backdrop-blur-md relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-orange-500 to-transparent"></div>

                    <div className="flex justify-center mb-6">
                      <div className="p-4 bg-orange-500/10 rounded-full border border-orange-500/20">
                        {isSubmitting ? <Loader2 className="text-orange-500 animate-spin" size={40} /> : <ShieldCheck className="text-orange-500" size={40} />}
                      </div>
                    </div>

                    <h1 className="font-cinzel text-3xl text-white text-center mb-1 uppercase tracking-tight">Terminal Login</h1>
                    <p className="text-gray-600 text-center text-[10px] tracking-[0.4em] uppercase mb-10 font-bold">Identity Verification Required</p>

                    <form onSubmit={handleLogin} className="space-y-5">
                        <Input 
                            label="SYSTEM EMAIL"
                            id="email"
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="admin@ssk.com"
                            required
                        />
                        <Input 
                            label="SECURITY KEY"
                            id="password"
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="••••••••"
                            required
                        />

                        {error && (
                            <div className={`p-4 rounded border ${roleWarning ? 'bg-orange-950/20 border-orange-500/30' : 'bg-red-950/20 border-red-500/30'}`}>
                                <div className={`flex items-center gap-2 font-black mb-2 text-[10px] uppercase tracking-widest ${roleWarning ? 'text-orange-400' : 'text-red-400'}`}>
                                    {roleWarning ? <AlertTriangle size={14} /> : <AlertCircle size={14} />}
                                    <span>{roleWarning ? 'Terminal Locked' : 'Denied'}</span>
                                </div>
                                <p className="text-gray-300 text-xs leading-relaxed opacity-90">{error}</p>
                            </div>
                        )}

                        <Button 
                            type="submit" 
                            disabled={!email || !password || isSubmitting} 
                            className="w-full py-4 text-xs tracking-[0.2em] font-black uppercase"
                        >
                            {isSubmitting ? 'CONNECTING...' : 'INITIATE CONNECTION'}
                        </Button>
                    </form>
                </Card>

                {showRepair && (
                    <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
                        <Card className="bg-red-950/20 border-red-500/40 p-6">
                            <div className="flex items-start gap-4 mb-6">
                                <div className="p-3 bg-red-500/20 rounded-xl text-red-500 animate-pulse">
                                    <Zap size={24} />
                                </div>
                                <div>
                                    <h3 className="text-red-400 font-cinzel text-xl tracking-wider">Critical Conflict</h3>
                                    <p className="text-xs text-gray-400 mt-1 uppercase tracking-widest font-bold">Infinite Policy Recursion Detected</p>
                                </div>
                            </div>
                            <p className="text-gray-300 text-xs leading-relaxed mb-6">
                                Your database security policies are caught in a loop. You must run the repair script in your Supabase SQL Editor to restore access.
                            </p>
                            <div className="bg-black/80 rounded-lg p-4 font-mono text-[10px] text-red-400/80 mb-6 overflow-hidden max-h-40 relative group">
                                <pre className="overflow-x-auto">{sqlRepairScript}</pre>
                                <div className="absolute inset-0 bg-gradient-to-t from-black to-transparent"></div>
                            </div>
                            <Button 
                                variant="secondary" 
                                onClick={copyRepairScript} 
                                className="w-full py-3 text-[10px] font-black tracking-widest uppercase flex items-center justify-center gap-2 bg-red-900/40 border border-red-500/30 hover:bg-red-900/60"
                            >
                                <Copy size={14} />
                                Copy Repair Script
                            </Button>
                            <div className="mt-4 flex items-center gap-2 text-gray-500 text-[10px] uppercase tracking-widest font-bold">
                                <Info size={12} />
                                <span>Paste & Run in Supabase SQL Editor</span>
                            </div>
                        </Card>
                    </div>
                )}
            </div>
        </div>
    </div>
  );
};

