-- Note: You MUST also create this user manually in the Auth Dashboard first.

INSERT INTO public.profiles (id, name, email, role, status)
SELECT 
    id, 
    'Master Administrator', 
    email, 
    'MasterAdmin', 
    'Active'
FROM auth.users 
