import React, { createContext, useState, useContext, ReactNode, useEffect, useCallback } from 'react';
import { User, Role } from '../types';
import { supabase } from '../supabase/client';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<{ user: User | null; error?: string; code?: string }>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  updatePassword: (newPassword: string) => Promise<{ success: boolean; error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const mapStringToRole = (roleStr: any): Role => {
    if (!roleStr) return Role.Volunteer;
    const normalized = String(roleStr).toLowerCase().trim();
    if (normalized === 'masteradmin' || normalized === 'superadmin' || normalized === 'master_admin') {
        return Role.MasterAdmin;
    }
    if (
        normalized === 'organisation' || 
        normalized === 'organization' || 
        normalized === 'admin' || 
        normalized === 'org' ||
        normalized === 'organisation_admin' ||
        normalized === 'org_admin'
    ) {
        return Role.Organisation;
    }
    return Role.Volunteer;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      const { data: profile, error } = await supabase
          .from('profiles')
          .select(`*, organisations (name)`)
          .eq('id', userId)
          .maybeSingle();

      if (error) {
          if (error.message.includes('recursion')) {
              throw new Error('infinite recursion detected in policy for relation "profiles"');
          }
          console.error('Profile fetch error:', error.message);
          return null;
      }

      if (profile) {
          return {
              id: profile.id,
              name: profile.name,
              email: profile.email,
              role: mapStringToRole(profile.role),
              organisationId: profile.organisation_id,
              organisationName: profile.organisations?.name || null,
              mobile: profile.mobile,
              status: profile.status || 'Active'
          };
      }
    } catch (e: any) {
      if (e.message?.includes('recursion')) throw e;
    }
    return null;
  }, []);

  const refreshProfile = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
          try {
              const updatedUser = await fetchProfile(session.user.id);
              setUser(updatedUser);
          } catch (e) {
              console.error("Refresh recursion error");
          }
      }
  };

  const updatePassword = async (newPassword: string): Promise<{ success: boolean; error?: string }> => {
    try {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message };
    }
  };

  useEffect(() => {
    let mounted = true;
    const initializeAuth = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && mounted) {
            try {
                const mapped = await fetchProfile(session.user.id);
                setUser(mapped);
            } catch (e) {
                console.error("Init recursion error");
            }
        }
        if (mounted) setLoading(false);
    };
    initializeAuth();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_OUT') {
            setUser(null);
        } else if (session?.user && (event === 'SIGNED_IN' || event === 'INITIAL_SESSION')) {
            try {
                const mapped = await fetchProfile(session.user.id);
                setUser(mapped);
            } catch (e) {
                console.error("Auth change recursion error");
            }
        }
    });

    return () => {
      mounted = false;
      subscription?.unsubscribe();
    };
  }, [fetchProfile]);

  const login = async (email: string, password: string): Promise<{ user: User | null; error?: string; code?: string }> => {
    try {
        const cleanEmail = email.trim().toLowerCase();
        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({ 
            email: cleanEmail, 
            password: password 
        });

        if (authError) {
            return { 
                user: null, 
                error: authError.message, 
                code: authError.message.includes('confirm') ? 'EMAIL_NOT_CONFIRMED' : 'AUTH_FAILED' 
            };
        }

        if (authData.user) {
            try {
                // Potential delay in profile creation trigger
                let profile = await fetchProfile(authData.user.id);
                if (!profile) {
                    await new Promise(r => setTimeout(r, 1500));
                    profile = await fetchProfile(authData.user.id);
                }

                if (profile) {
                    setUser(profile);
                    return { user: profile };
                }
                return { 
                    user: null, 
                    error: "Auth succeeded but Profile record is missing in database.", 
                    code: 'MISSING_PROFILE' 
                };
            } catch (e: any) {
                return { user: null, error: e.message, code: 'RECURSION_ERROR' };
            }
        }
        return { user: null, error: "Authentication failed." };
    } catch (err: any) {
        return { user: null, error: err.message || "Unexpected error" };
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshProfile, updatePassword }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { createContext, useState, useContext, ReactNode, useEffect, useCallback } from 'react';
import { User, Role } from '../types';
import { supabase } from '../supabase/client';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<{ user: User | null; error?: string; code?: string }>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  updatePassword: (newPassword: string) => Promise<{ success: boolean; error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const mapStringToRole = (roleStr: any): Role => {
    if (!roleStr) return Role.Volunteer;
    const normalized = String(roleStr).toLowerCase().trim();
    if (normalized === 'masteradmin' || normalized === 'superadmin' || normalized === 'master_admin') {
        return Role.MasterAdmin;
    }
    if (
        normalized === 'organisation' || 
        normalized === 'organization' || 
        normalized === 'admin' || 
        normalized === 'org' ||
        normalized === 'organisation_admin' ||
        normalized === 'org_admin'
    ) {
        return Role.Organisation;
    }
    return Role.Volunteer;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      // Fetch with service-level clarity (handled by supabase client)
      const { data: profile, error } = await supabase
          .from('profiles')
          .select(`*, organisations (name)`)
          .eq('id', userId)
          .maybeSingle();

      if (error) {
          if (error.message.includes('recursion')) {
              throw new Error('RLS_RECURSION_ERROR');
          }
          console.error('Profile fetch error:', error.message);
          return null;
      }

      if (profile) {
          return {
              id: profile.id,
              name: profile.name,
              email: profile.email,
              role: mapStringToRole(profile.role),
              organisationId: profile.organisation_id,
              organisationName: profile.organisations?.name || null,
              mobile: profile.mobile,
              status: profile.status || 'Active'
          };
      }
    } catch (e: any) {
      if (e.message === 'RLS_RECURSION_ERROR') throw e;
    }
    return null;
  }, []);

  const refreshProfile = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
          try {
              const updatedUser = await fetchProfile(session.user.id);
              setUser(updatedUser);
          } catch (e) {
              console.error("Refresh sync error:", e);
          }
      }
  };

  const updatePassword = async (newPassword: string): Promise<{ success: boolean; error?: string }> => {
    try {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message };
    }
  };

  useEffect(() => {
    let mounted = true;
    const initializeAuth = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && mounted) {
            try {
                const mapped = await fetchProfile(session.user.id);
                setUser(mapped);
            } catch (e) {
                console.error("Initialization sync error");
            }
        }
        if (mounted) setLoading(false);
    };
    initializeAuth();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_OUT') {
            setUser(null);
        } else if (session?.user && (event === 'SIGNED_IN' || event === 'INITIAL_SESSION')) {
            try {
                const mapped = await fetchProfile(session.user.id);
                setUser(mapped);
            } catch (e) {
                console.error("Auth change sync error");
            }
        }
    });

    return () => {
      mounted = false;
      subscription?.unsubscribe();
    };
  }, [fetchProfile]);

  const login = async (email: string, password: string): Promise<{ user: User | null; error?: string; code?: string }> => {
    try {
        const cleanEmail = email.trim().toLowerCase();
        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({ 
            email: cleanEmail, 
            password: password 
        });

        if (authError) {
            return { 
                user: null, 
                error: authError.message, 
                code: authError.message.includes('confirm') ? 'EMAIL_NOT_CONFIRMED' : 'AUTH_FAILED' 
            };
        }

        if (authData.user) {
            try {
                // Critical: Account for database trigger latency
                let profile = await fetchProfile(authData.user.id);
                if (!profile) {
                    // One retry after 1.5s delay
                    await new Promise(r => setTimeout(r, 1500));
                    profile = await fetchProfile(authData.user.id);
                }

                if (profile) {
                    setUser(profile);
                    return { user: profile };
                }

                return { 
                    user: null, 
                    error: "Authentication successful, but identity record (Profile) is missing in the database. Run the 'Master Repair SQL' in your dashboard.", 
                    code: 'MISSING_PROFILE' 
                };
            } catch (e: any) {
                if (e.message === 'RLS_RECURSION_ERROR') {
                    return { user: null, error: "Database Security Loop detected. Access blocked.", code: 'RECURSION_ERROR' };
                }
                return { user: null, error: e.message };
            }
        }
        return { user: null, error: "System failed to return identity data." };
    } catch (err: any) {
        return { user: null, error: err.message || "Unexpected authentication terminal error." };
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshProfile, updatePassword }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { Organisation, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { ShieldCheck, UserPlus, Building2, Loader2, Settings, ShieldAlert, Zap, Copy, Info } from 'lucide-react';

const ManageOrganisations: React.FC = () => {
  const [organisations, setOrganisations] = useState<Organisation[]>([]);
  const [newOrg, setNewOrg] = useState({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSqlFix, setShowSqlFix] = useState(false);

  const { addNotification } = useNotification();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrg, setEditingOrg] = useState<Organisation | null>(null);

  const fetchOrganisations = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase.from('organisations').select('*').order('name');
    if (error) {
      if (error.message.includes('recursion')) {
          setShowSqlFix(true);
          addNotification('Security Loop: RLS Recursion detected.', 'error');
      } else {
          addNotification('Master registry access failed.', 'error');
      }
    } else {
      setOrganisations(data || []);
      setShowSqlFix(false);
    }
    setLoading(false);
  }, [addNotification]);

  useEffect(() => {
    fetchOrganisations();
  }, [fetchOrganisations]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewOrg(prev => ({ ...prev, [name]: value }));
  };

  const handleAddOrganisation = async () => {
    const email = newOrg.email.trim().toLowerCase();
    const password = newOrg.password;
    const name = newOrg.name.trim();
    const mobile = newOrg.mobile.trim();
    const secretaryName = newOrg.secretaryName.trim();

    if (!email || !password || !name || !mobile || !secretaryName) {
        addNotification("All identity parameters are mandatory.", 'error');
        return;
    }

    setIsSubmitting(true);

    try {
        // 1. Create Organization Entry
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ name, mobile, secretary_name: secretaryName })
          .select().single();

        if (orgError) throw orgError;

        // 2. Create Auth Node
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              name: secretaryName,
              role: 'Organisation',
              organisation_id: orgData.id,
              mobile
            }
          }
        });

        if (authError) {
          // Cleanup failed entry
          await supabase.from('organisations').delete().eq('id', orgData.id);
          throw authError;
        }

        // 3. Force Profile Injection (Sync Guard)
        if (authData.user) {
            const { error: profileError } = await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: secretaryName,
                email,
                role: 'Organisation',
                organisation_id: orgData.id,
                mobile,
                status: 'Active'
            });

            if (profileError && profileError.message.includes('recursion')) {
                setShowSqlFix(true);
            }
        }

        addNotification('Organization successfully authorized and deployed.', 'success');
        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
    } catch (err: any) {
        console.error("Auth Sequence Failure:", err);
        if (err.message.includes('recursion')) {
            setShowSqlFix(true);
            addNotification("Database blocked by security loop.", 'error');
        } else {
            addNotification(err.message || "Failed to authorize entity.", 'error');
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleEditClick = (org: Organisation) => {
    setEditingOrg({ ...org });
    setIsModalOpen(true);
  };

  const handleUpdateOrganisation = async () => {
    if (!editingOrg) return;
    const { error } = await supabase.from('organisations').update({
        name: editingOrg.name, 
        mobile: editingOrg.mobile,
        secretary_name: editingOrg.secretary_name, 
        status: editingOrg.status
    }).eq('id', editingOrg.id);

    if (error) {
        addNotification(`Update rejected: ${error.message}`, 'error');
    } else {
        addNotification(`Entity parameters updated.`, 'success');
        fetchOrganisations();
        setIsModalOpen(false);
    }
  };

  return (
    <DashboardLayout title="Entity Administration">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        <div className="lg:col-span-1">
          <Card title="Authorize New Entity">
            <div className="space-y-6">
              <Input label="Organisation Name" name="name" value={newOrg.name} onChange={handleInputChange} placeholder="Ex: SSK Bangalore" />
              <Input label="Primary Mobile" name="mobile" value={newOrg.mobile} onChange={handleInputChange} placeholder="91XXXXXXXX" />
              <Input label="Secretary Name" name="secretaryName" value={newOrg.secretaryName} onChange={handleInputChange} />
              <Input label="Access Email" name="email" type="email" value={newOrg.email} onChange={handleInputChange} placeholder="admin@entity.com" />
              <Input label="Security Key" name="password" type="password" value={newOrg.password} onChange={handleInputChange} placeholder="Min 6 characters" />
              <Button type="button" onClick={handleAddOrganisation} disabled={isSubmitting} className="w-full py-5 flex items-center justify-center gap-3 text-[11px] font-black uppercase tracking-widest shadow-xl">
                {isSubmitting ? <Loader2 className="animate-spin" size={18} /> : <UserPlus size={18} />}
                {isSubmitting ? 'AUTHORIZING...' : 'Establish Entity'}
              </Button>
            </div>
          </Card>
        </div>

        <div className="lg:col-span-2">
          <Card title="Active Entity Registry">
            {loading ? (
                <div className="p-40 flex justify-center"><Loader2 className="animate-spin text-orange-500" size={48} /></div>
            ) : (
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="border-b border-gray-800">
                            <tr>
                                <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Entity Identity</th>
                                <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black text-right">Verification</th>
                                <th className="p-6"></th>
                            </tr>
                        </thead>
                        <tbody>
                            {organisations.map(org => (
                            <tr key={org.id} className="group border-b border-gray-900/50 hover:bg-white/[0.02] transition-all">
                                <td className="p-6">
                                    <div className="flex flex-col">
                                        <span className="font-bold text-white text-lg group-hover:text-orange-500 transition-colors">{org.name}</span>
                                        <span className="text-[11px] text-gray-600 uppercase font-mono tracking-tighter">{org.secretary_name} • {org.mobile}</span>
                                    </div>
                                </td>
                                <td className="p-6 text-right">
                                    <span className={`px-4 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-full border ${ org.status === 'Active' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20' }`}>
                                        {org.status}
                                    </span>
                                </td>
                                <td className="p-6 text-right">
                                    <Button size="sm" variant="secondary" onClick={() => handleEditClick(org)} className="opacity-0 group-hover:opacity-100 transition-opacity">Edit</Button>
                                </td>
                            </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
          </Card>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Modify Entity Parameters">
          {editingOrg && (
            <div className="space-y-6">
                <Input label="Organisation Name" name="name" value={editingOrg.name} onChange={(e) => setEditingOrg({...editingOrg, name: e.target.value})} />
                <Input label="Registry Mobile" name="mobile" value={editingOrg.mobile} onChange={(e) => setEditingOrg({...editingOrg, mobile: e.target.value})} />
                <Input label="Secretary Name" name="secretary_name" value={editingOrg.secretary_name} onChange={(e) => setEditingOrg({...editingOrg, secretary_name: e.target.value})} />
                <Select label="Access Status" name="status" value={editingOrg.status} onChange={(e) => setEditingOrg({...editingOrg, status: e.target.value as any})}>
                    <option value="Active">Active / Operational</option>
                    <option value="Deactivated">Locked / Deactivated</option>
                </Select>
                <div className="flex justify-end gap-4 pt-6">
                    <Button type="button" variant="secondary" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                    <Button type="button" onClick={handleUpdateOrganisation}>Commit Changes</Button>
                </div>
            </div>
          )}
      </Modal>
    </DashboardLayout>
  );
};

export default ManageOrganisations;

