import React, { createContext, useState, useContext, ReactNode, useEffect, useCallback } from 'react';
import { User, Role } from '../types';
import { supabase } from '../supabase/client';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<{ user: User | null; error?: string; code?: string }>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  updatePassword: (newPassword: string) => Promise<{ success: boolean; error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const mapStringToRole = (roleStr: any): Role => {
    if (!roleStr) return Role.Volunteer;
    const normalized = String(roleStr).toLowerCase().trim();
    if (normalized === 'masteradmin' || normalized === 'superadmin' || normalized === 'master_admin') {
        return Role.MasterAdmin;
    }
    if (
        normalized === 'organisation' || 
        normalized === 'organization' || 
        normalized === 'admin' || 
        normalized === 'org' ||
        normalized === 'organisation_admin' ||
        normalized === 'org_admin'
    ) {
        return Role.Organisation;
    }
    return Role.Volunteer;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      const { data: profile, error } = await supabase
          .from('profiles')
          .select(`*, organisations (name)`)
          .eq('id', userId)
          .maybeSingle();

      if (error) {
          if (error.message.includes('recursion')) {
              throw new Error('RLS_RECURSION_ERROR');
          }
          console.error('Profile fetch internal error:', error.message);
          return null;
      }

      if (profile) {
          return {
              id: profile.id,
              name: profile.name,
              email: profile.email,
              role: mapStringToRole(profile.role),
              organisationId: profile.organisation_id,
              organisationName: profile.organisations?.name || null,
              mobile: profile.mobile,
              status: (profile.status as any) || 'Active'
          };
      }
    } catch (e: any) {
      if (e.message === 'RLS_RECURSION_ERROR') throw e;
      console.error("fetchProfile caught:", e);
    }
    return null;
  }, []);

  const refreshProfile = useCallback(async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
          try {
              const updatedUser = await fetchProfile(session.user.id);
              setUser(updatedUser);
          } catch (e: any) {
              console.error("Refresh sync error:", e.message);
          }
      }
  }, [fetchProfile]);

  const updatePassword = async (newPassword: string): Promise<{ success: boolean; error?: string }> => {
    try {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message };
    }
  };

  useEffect(() => {
    let mounted = true;

    const initializeAuth = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && mounted) {
            try {
                const mapped = await fetchProfile(session.user.id);
                setUser(mapped);
            } catch (e: any) {
                console.error("Initialization sync error:", e.message);
            }
        }
        if (mounted) setLoading(false);
    };
    initializeAuth();

    const { data: { subscription: authSubscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (!mounted) return;

        if (event === 'SIGNED_OUT') {
            setUser(null);
        } else if (session?.user && (event === 'SIGNED_IN' || event === 'INITIAL_SESSION' || event === 'USER_UPDATED')) {
            try {
                let mapped = await fetchProfile(session.user.id);

                // Retry polling for profiles (up to 3 times) for new users
                let retries = 0;
                while (!mapped && retries < 3) {
                    await new Promise(r => setTimeout(r, 1000 * (retries + 1)));
                    mapped = await fetchProfile(session.user.id);
                    retries++;
                }

                setUser(mapped);
            } catch (e: any) {
                console.error("Auth change sync fault:", e.message || e);
            }
        }
    });

    return () => {
      mounted = false;
      authSubscription?.unsubscribe();
    };
  }, [fetchProfile]);

  // Separate effect for profile realtime sync to avoid loop
  useEffect(() => {
    if (!user?.id) return;

    const channel = supabase
        .channel(`profile-sync-${user.id}`)
        .on(
            'postgres_changes',
            {
                event: '*',
                schema: 'public',
                table: 'profiles',
                filter: `id=eq.${user.id}`
            },
            () => {
                refreshProfile();
            }
        )
        .subscribe();

    return () => {
        supabase.removeChannel(channel);
    };
  }, [user?.id, refreshProfile]);

  const login = async (email: string, password: string): Promise<{ user: User | null; error?: string; code?: string }> => {
    try {
        const cleanEmail = email.trim().toLowerCase();
        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({ 
            email: cleanEmail, 
            password: password 
        });

        if (authError) {
            return { 
                user: null, 
                error: authError.message, 
                code: authError.message.includes('confirm') ? 'EMAIL_NOT_CONFIRMED' : 'AUTH_FAILED' 
            };
        }

        if (authData.user) {
            try {
                let profile = await fetchProfile(authData.user.id);
                if (!profile) {
                    // Quick immediate retry
                    await new Promise(r => setTimeout(r, 2000));
                    profile = await fetchProfile(authData.user.id);
                }

                if (profile) {
                    setUser(profile);
                    return { user: profile };
                }

                return { 
                    user: null, 
                    error: "Identity record is missing. Please run the Ultimate Repair SQL.", 
                    code: 'MISSING_PROFILE' 
                };
            } catch (e: any) {
                if (e.message === 'RLS_RECURSION_ERROR') {
                    return { user: null, error: "Database Security Loop. Run Repair SQL.", code: 'RECURSION_ERROR' };
                }
                return { user: null, error: e.message };
            }
        }
        return { user: null, error: "Session creation failed." };
    } catch (err: any) {
        return { user: null, error: err.message || "Critical Auth Error." };
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshProfile, updatePassword }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import { Volunteer, Role } from '../../types';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { Power, Download, UserPlus, UserCheck, Copy, ShieldCheck, Loader2, UserCircle, Zap, ShieldAlert } from 'lucide-react';

type VolunteerWithEnrollments = Volunteer & { enrollments: number };

const ManageVolunteers: React.FC = () => {
  const { user } = useAuth();
  const [volunteers, setVolunteers] = useState<VolunteerWithEnrollments[]>([]);
  const [newVol, setNewVol] = useState({ name: '', mobile: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { addNotification } = useNotification();

  const fetchVolunteers = useCallback(async () => {
    if (!user?.organisationId) return;
    setLoading(true);

    try {
        const { data: profileData, error: profileError } = await supabase
          .from('profiles')
          .select('*, members(id)')
          .eq('role', Role.Volunteer)
          .eq('organisation_id', user.organisationId);

        if (profileError) {
          addNotification("Registry sync failed. Check RLS policies.", 'error');
        } else {
          setVolunteers(profileData.map((v: any) => ({
              id: v.id,
              name: v.name,
              email: v.email,
              mobile: v.mobile,
              role: Role.Volunteer,
              organisationId: v.organisation_id,
              organisationName: user.organisationName,
              status: v.status || 'Active',
              enrollments: v.members?.length || 0
          })) || []);
        }
    } catch (e) {
        console.error("Fetch Error:", e);
    } finally {
        setLoading(false);
    }
  }, [user, addNotification]);

  useEffect(() => {
    fetchVolunteers();
  }, [fetchVolunteers]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewVol(prev => ({ ...prev, [name]: value }));
  };

  const handleAddVolunteer = async () => {
    const email = newVol.email.trim().toLowerCase();
    const password = newVol.password;
    const name = newVol.name.trim();
    const mobile = newVol.mobile.trim();

    if (!user?.organisationId) {
        addNotification("Session missing Organisation context.", 'error');
        return;
    }
    if (!email || !password || !name || !mobile) {
        addNotification("Identity parameters incomplete.", 'error');
        return;
    }

    setIsSubmitting(true);

    try {
        // 1. Create Auth Identity
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email: email,
          password: password,
          options: {
            data: {
              name: name,
              mobile: mobile,
              role: 'Volunteer', 
              organisation_id: user.organisationId
            }
          }
        });

        if (authError) throw authError;

        // 2. Immediate Profile Injection (Atomic Sync)
        if (authData.user) {
            const { error: upsertError } = await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: name,
                email: email,
                role: 'Volunteer',
                organisation_id: user.organisationId,
                mobile: mobile,
                status: 'Active'
            });
            if (upsertError) throw upsertError;
        }

        addNotification('Field agent authorized and deployed.', 'success');
        setNewVol({ name: '', mobile: '', email: '', password: '' });
        fetchVolunteers(); 
    } catch (err: any) {
        console.error("Authorization fault:", err);
        addNotification(err.message || "Failed to establish agent identity.", 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const copyVolunteerCreds = (v: VolunteerWithEnrollments) => {
      const text = `Agent: ${v.name}\nIdentity: ${v.email}\nSecurity: [Predefined]`;
      navigator.clipboard.writeText(text);
      addNotification("Identity parameters copied.", "success");
  };

  const handleToggleStatus = async (vol: VolunteerWithEnrollments) => {
    const newStatus = vol.status === 'Active' ? 'Deactivated' : 'Active';
    const { error } = await supabase
        .from('profiles')
        .update({ status: newStatus })
        .eq('id', vol.id);

    if (error) {
        addNotification("Override failed.", 'error');
    } else {
        addNotification(`Agent state set to: ${newStatus}`, 'success');
        fetchVolunteers();
    }
  };

  return (
    <DashboardLayout title="Field Force Command">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        {/* Authorization Panel */}
        <div className="lg:col-span-1">
          <Card title="Authorize New Agent" className="relative overflow-hidden border-blue-900/30">
