  ShieldCheck, 
  AlertCircle, 
  AlertTriangle, 
  Copy, 
  Loader2, 
  Zap, 
  Terminal, 
  Database, 
  ExternalLink,
  ShieldAlert,
  ServerCrash
} from 'lucide-react';
