const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showFixPrompt, setShowFixPrompt] = useState(false);

  const { login, user: currentUser } = useAuth();
  const { addNotification } = useNotification();
  const navigate = useNavigate();

  useEffect(() => {
    if (currentUser) {
        if (currentUser.role === Role.MasterAdmin) navigate('/admin');
        else if (currentUser.role === Role.Organisation) navigate('/organisation');
        else if (currentUser.role === Role.Volunteer) navigate('/volunteer');
    }
  }, [currentUser, navigate]);

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setError('');
    setShowFixPrompt(false);
    setIsSubmitting(true);

    try {
      const result = await login(email.trim(), password);
      if (!result.user) {
          setError(result.error || 'Identity verification failed.');
          if (result.code === 'RECURSION_ERROR' || result.error?.toLowerCase().includes('recursion')) {
              setShowFixPrompt(true);
          }
      }
    } catch (err: any) {
      setError(err.message || 'System uplink failure.');
      setShowFixPrompt(true);
    } finally {
      setIsSubmitting(false);
    }
  };

  const metadataSqlFix = `-- 🚀 JWT METADATA BYPASS (RECURSION FIX)
-- 1. Grant MasterAdmin role to your Auth User metadata
UPDATE auth.users 
SET raw_app_metadata_content = jsonb_set(
  COALESCE(raw_app_metadata_content, '{}'::jsonb),
  '{role}',
  '"MasterAdmin"'
)
WHERE email = 'Masteradmin@ssk.com';

-- 2. Apply recursion-free policies using JWT claims
DROP POLICY IF EXISTS "Admins have full access" ON public.profiles;
DROP POLICY IF EXISTS "Users can view own profile" ON public.profiles;

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Self View" ON public.profiles FOR SELECT USING (auth.uid() = id);
CREATE POLICY "Admin Power" ON public.profiles FOR ALL 
USING ( (auth.jwt() -> 'app_metadata' ->> 'role') = 'MasterAdmin' );`;

  return (
    <div className="min-h-screen bg-black flex flex-col">
        <Header />
        <div className="flex-grow flex flex-col items-center justify-center p-6">
            <div className="w-full max-w-lg space-y-6">
                <Card className="border-orange-900/30 bg-black/80 backdrop-blur-xl relative overflow-hidden shadow-[0_0_50px_-12px_rgba(255,100,0,0.3)]">
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-orange-500 to-transparent"></div>

                    <div className="flex justify-center mb-8">
                      <div className="p-5 bg-orange-500/10 rounded-[2rem] border border-orange-500/20">
                        {isSubmitting ? <Loader2 className="text-orange-500 animate-spin" size={48} /> : <ShieldCheck className="text-orange-500" size={48} />}
                      </div>
                    </div>

                    <h1 className="font-cinzel text-4xl text-white text-center mb-2 uppercase tracking-tighter">System Access</h1>
                    <p className="text-gray-600 text-center text-[10px] tracking-[0.5em] uppercase mb-12 font-black">Identity Terminal</p>

                    <form onSubmit={handleLogin} className="space-y-6">
                        <Input 
                            label="SYSTEM EMAIL"
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="admin@ssk.com"
                            className="bg-black/40 border-gray-800 text-sm font-mono"
                            required
                        />
                        <Input 
                            label="SECURITY KEY"
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="••••••••"
                            className="bg-black/40 border-gray-800 text-sm font-mono"
                            required
                        />

                        {error && (
                            <div className="p-4 rounded-xl border bg-red-950/20 border-red-500/30">
                                <div className="flex items-center gap-2 font-black mb-1 text-[10px] uppercase text-red-400">
                                    <AlertTriangle size={14} />
                                    <span>Access Denied</span>
                                </div>
                                <p className="text-gray-300 text-xs leading-relaxed">{error}</p>
                            </div>
                        )}

                        <Button type="submit" disabled={isSubmitting} className="w-full py-5 text-[11px] tracking-[0.3em] font-black uppercase shadow-xl shadow-orange-950/20">
                            {isSubmitting ? 'CONNECTING...' : 'INITIATE UPLINK'}
                        </Button>
                    </form>

                    <div className="mt-10 pt-8 border-t border-gray-800/50">
                        <button 
                            onClick={() => { setEmail('Masteradmin@ssk.com'); setPassword('Ssk1919@'); }}
                            className="w-full flex items-center justify-between p-4 rounded-2xl bg-orange-500/5 border border-orange-500/10 hover:bg-orange-500/10 transition-all text-left group"
                        >
                            <div>
                                <span className="text-[10px] font-black uppercase tracking-widest text-orange-500 block mb-1">Master Admin Keys</span>
                                <span className="text-xs text-gray-500 font-mono">Masteradmin@ssk.com</span>
                            </div>
                            <Terminal size={18} className="text-gray-700 group-hover:text-orange-500 transition-colors" />
                        </button>
                    </div>
                </Card>

                {showFixPrompt && (
                    <Card className="bg-orange-950/20 border-orange-500/40 p-8 shadow-2xl animate-in fade-in slide-in-from-bottom-4 relative overflow-hidden">
                        <div className="absolute top-0 right-0 p-8 opacity-5">
                            <ServerCrash size={120} />
                        </div>
                        <div className="flex items-start gap-4 mb-6 relative z-10">
                            <div className="p-3 bg-orange-500/20 rounded-2xl text-orange-500 border border-orange-500/20">
                                <Zap size={24} className="animate-pulse" />
                            </div>
                            <div>
                                <h3 className="text-orange-400 font-cinzel text-xl">Fix Recursion</h3>
                                <p className="text-xs text-gray-500 uppercase tracking-widest font-black">Fastest Bypass Method</p>
                            </div>
                        </div>
                        <p className="text-sm text-gray-400 mb-6 leading-relaxed relative z-10">
                            The "Access Denied" error is caused by a recursive RLS policy. Use the **JWT Metadata** method to bypass the loop instantly.
                        </p>

                        <div className="space-y-4 relative z-10">
                            <div className="bg-black/60 p-4 rounded-xl font-mono text-[9px] text-orange-500/70 border border-white/5 overflow-x-auto max-h-32 mb-4">
                                <pre>{metadataSqlFix}</pre>
                            </div>
                            <Button 
                                variant="secondary"
                                onClick={() => { navigator.clipboard.writeText(metadataSqlFix); addNotification("Metadata fix copied.", "success"); }}
                                className="w-full py-3 text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2"
                            >
                                <Copy size={14} /> Copy Metadata Fix
                            </Button>
                            <a 
                                href="https://supabase.com/dashboard" 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center justify-center gap-2 w-full text-orange-500 text-[10px] font-black uppercase tracking-widest hover:underline"
                            >
                                Open SQL Editor <ExternalLink size={12} />
                            </a>
                        </div>
                    </Card>
                )}
            </div>
        </div>
    </div>
  );
};

export default LoginPage;

import React, { createContext, useState, useContext, ReactNode, useEffect, useCallback } from 'react';
import { User, Role } from '../types';
import { supabase } from '../supabase/client';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<{ user: User | null; error?: string; code?: string }>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  updatePassword: (newPassword: string) => Promise<{ success: boolean; error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const mapStringToRole = (roleStr: any): Role => {
    if (!roleStr) return Role.Volunteer;
    const normalized = String(roleStr).toLowerCase().trim();
    if (normalized === 'masteradmin' || normalized === 'superadmin' || normalized === 'master_admin') {
        return Role.MasterAdmin;
    }
    if (
        normalized === 'organisation' || 
        normalized === 'organization' || 
        normalized === 'admin' || 
        normalized === 'org' ||
        normalized === 'organisation_admin' ||
        normalized === 'org_admin'
    ) {
        return Role.Organisation;
    }
    return Role.Volunteer;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Fix: Explicitly typed fetchProfile return type to Promise<User | null> to resolve setUser type errors.
  const fetchProfile = useCallback(async (userId: string, authUser?: any): Promise<User | null> => {
    try {
      // Step 1: Try to get role from Auth Metadata (Fastest, Bypass RLS issues)
      const metadataRole = authUser?.app_metadata?.role || authUser?.user_metadata?.role;

      const { data: profile, error } = await supabase
          .from('profiles')
          .select(`*, organisations (name)`)
          .eq('id', userId)
          .maybeSingle();

      if (error) {
          const msg = error.message.toLowerCase();
          if (msg.includes('recursion') || msg.includes('infinite loop')) {
              // If recursion happens, we fallback strictly to Auth Metadata
              if (metadataRole && authUser) {
                  return {
                      id: authUser.id,
                      name: authUser.user_metadata?.name || 'Authorized User',
                      email: authUser.email || '',
                      role: mapStringToRole(metadataRole),
                      status: 'Active'
                  };
              }
              throw new Error('RLS_RECURSION_ERROR');
          }
          return null;
      }

      if (profile) {
          return {
              id: profile.id,
              name: profile.name,
              email: profile.email,
              role: mapStringToRole(profile.role || metadataRole),
              organisationId: profile.organisation_id,
              organisationName: profile.organisations?.name || undefined,
              mobile: profile.mobile,
              status: (profile.status as 'Active' | 'Deactivated') || 'Active'
          };
      } else if (authUser) {
          // Fallback if profile row doesn't exist yet but user is authenticated
          return {
              id: authUser.id,
              name: authUser.user_metadata?.name || 'Authorized User',
              email: authUser.email || '',
              role: mapStringToRole(metadataRole),
              status: 'Active'
          };
      }
    } catch (e: any) {
      if (e.message === 'RLS_RECURSION_ERROR') throw e;
      console.error("Profile sync fault:", e);
    }
    return null;
  }, []);

  const login = async (email: string, password: string): Promise<{ user: User | null; error?: string; code?: string }> => {
    try {
        const { data, error: authError } = await supabase.auth.signInWithPassword({ 
            email: email.trim().toLowerCase(), 
            password 
        });

        if (authError) return { user: null, error: authError.message };

        if (data.user) {
            try {
                const profile = await fetchProfile(data.user.id, data.user);
                if (profile) {
                    setUser(profile);
                    return { user: profile };
                }
                return { user: null, error: "Identity verified but profile node is unreachable.", code: 'SYNC_ERROR' };
            } catch (e: any) {
                if (e.message === 'RLS_RECURSION_ERROR') {
                    return { user: null, error: "Database Security Loop Detected. Access Denied by RLS.", code: 'RECURSION_ERROR' };
                }
                return { user: null, error: e.message };
            }
        }
        return { user: null, error: "Handshake failed." };
    } catch (err: any) {
        return { user: null, error: err.message };
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  const refreshProfile = useCallback(async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
          const updatedUser = await fetchProfile(session.user.id, session.user);
          setUser(updatedUser);
      }
  }, [fetchProfile]);

  const updatePassword = async (newPassword: string) => {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      if (error) return { success: false, error: error.message };
      return { success: true };
  }

  useEffect(() => {
    const init = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
            try {
                const mapped = await fetchProfile(session.user.id, session.user);
                setUser(mapped);
            } catch (e) {
                console.error("Auth init error:", e);
            }
        }
        setLoading(false);
    };
    init();
  }, [fetchProfile]);

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshProfile, updatePassword }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be wrapped in AuthProvider');
  return context;
};

import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { Organisation, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { ShieldCheck, UserPlus, Building2, Loader2, Settings, ShieldAlert, Zap, Copy, Info, AlertTriangle } from 'lucide-react';

const ManageOrganisations: React.FC = () => {
  const [organisations, setOrganisations] = useState<Organisation[]>([]);
  const [newOrg, setNewOrg] = useState({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { addNotification } = useNotification();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrg, setEditingOrg] = useState<Organisation | null>(null);

  const fetchOrganisations = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase.from('organisations').select('*').order('name');
    if (error) {
      if (error.message.includes('recursion')) {
          addNotification('Security Loop detected. Run Repair SQL.', 'error');
      } else {
          addNotification('Failed to sync with master registry.', 'error');
      }
    } else {
      setOrganisations(data || []);
    }
    setLoading(false);
  }, [addNotification]);

  useEffect(() => {
    fetchOrganisations();
  }, [fetchOrganisations]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewOrg(prev => ({ ...prev, [name]: value }));
  };

  const handleAddOrganisation = async () => {
    const email = newOrg.email.trim().toLowerCase();
    const password = newOrg.password;
    const name = newOrg.name.trim();
    const mobile = newOrg.mobile.trim();
    const secretaryName = newOrg.secretaryName.trim();

    if (!email || !password || !name || !mobile || !secretaryName) {
        addNotification("All identity parameters are mandatory.", 'error');
        return;
    }

    setIsSubmitting(true);
    let createdOrgId: string | null = null;

    try {
        // 1. Create Organization Record
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ name, mobile, secretary_name: secretaryName, status: 'Active' })
          .select().single();

        if (orgError) {
            console.error("Database Org Error:", orgError);
            throw new Error(`Org Creation Failed: ${orgError.message}`);
        }

        createdOrgId = orgData.id;

        // 2. Create Auth Account
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              name: secretaryName,
              role: 'Organisation',
              organisation_id: createdOrgId,
              mobile
            }
          }
        });

        if (authError) {
          // If auth fails, try to cleanup the org record we just made
          if (createdOrgId) await supabase.from('organisations').delete().eq('id', createdOrgId);

          // Specifically handle the "Database error saving new user" message
          if (authError.message.includes("Database error saving new user")) {
              throw new Error("Trigger Failure: The database couldn't link the profile. Check the SQL Trigger for 'handle_new_user'.");
          }
          throw authError;
        }

        // 3. Force Sync Profile (Sync Guard)
        if (authData.user) {
            const { error: profileError } = await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: secretaryName,
                email,
                role: 'Organisation',
                organisation_id: createdOrgId,
                mobile,
                status: 'Active'
            });

            if (profileError) {
                console.warn("Manual profile sync issue:", profileError.message);
            }
        }

        addNotification('Organization authorized successfully.', 'success');
        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
    } catch (err: any) {
        console.error("Critical Auth Sync Error:", err);
        const errorMessage = typeof err === 'object' ? (err.message || JSON.stringify(err)) : String(err);
        addNotification(errorMessage, 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleEditClick = (org: Organisation) => {
    setEditingOrg({ ...org });
    setIsModalOpen(true);
  };

  const handleUpdateOrganisation = async () => {
    if (!editingOrg) return;
    const { error } = await supabase.from('organisations').update({
        name: editingOrg.name, 
        mobile: editingOrg.mobile,
        secretary_name: editingOrg.secretary_name, 
        status: editingOrg.status
    }).eq('id', editingOrg.id);

    if (error) {
        addNotification(`Sync failed: ${error.message}`, 'error');
    } else {
        addNotification(`Organization parameters updated.`, 'success');
        fetchOrganisations();
        setIsModalOpen(false);
    }
  };

  return (
    <DashboardLayout title="Entity Administration">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        <div className="lg:col-span-1">
          <Card title="Authorize New Entity">
            <div className="space-y-6">
              <Input label="Organisation Name" name="name" value={newOrg.name} onChange={handleInputChange} placeholder="Ex: SSK Bangalore" />
              <Input label="Primary Mobile" name="mobile" value={newOrg.mobile} onChange={handleInputChange} placeholder="91XXXXXXXX" />
              <Input label="Secretary Name" name="secretaryName" value={newOrg.secretaryName} onChange={handleInputChange} />
              <Input label="Access Email" name="email" type="email" value={newOrg.email} onChange={handleInputChange} placeholder="admin@entity.com" />
              <Input label="Security Key" name="password" type="password" value={newOrg.password} onChange={handleInputChange} placeholder="Min 6 characters" />
              <Button type="button" onClick={handleAddOrganisation} disabled={isSubmitting} className="w-full py-5 flex items-center justify-center gap-3 text-[11px] font-black uppercase tracking-widest shadow-xl">
                {isSubmitting ? <Loader2 className="animate-spin" size={18} /> : <UserPlus size={18} />}
                {isSubmitting ? 'AUTHORIZING...' : 'Establish Entity'}
              </Button>
            </div>
          </Card>
        </div>

        <div className="lg:col-span-2">
          <Card title="Active Entity Registry">
            {loading ? (
                <div className="p-40 flex justify-center"><Loader2 className="animate-spin text-orange-500" size={48} /></div>
            ) : (
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="border-b border-gray-800">
                            <tr>
                                <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Entity Identity</th>
                                <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black text-right">Verification</th>
                                <th className="p-6"></th>
                            </tr>
                        </thead>
                        <tbody>
                            {organisations.map(org => (
                            <tr key={org.id} className="group border-b border-gray-900/50 hover:bg-white/[0.02] transition-all">
                                <td className="p-6">
                                    <div className="flex flex-col">
                                        <span className="font-bold text-white text-lg group-hover:text-orange-500 transition-colors">{org.name}</span>
                                        <span className="text-[11px] text-gray-600 uppercase font-mono tracking-tighter">{org.secretary_name} • {org.mobile}</span>
                                    </div>
                                </td>
                                <td className="p-6 text-right">
                                    <span className={`px-4 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-full border ${ org.status === 'Active' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20' }`}>
                                        {org.status}
                                    </span>
                                </td>
                                <td className="p-6 text-right">
                                    <Button size="sm" variant="secondary" onClick={() => handleEditClick(org)} className="opacity-0 group-hover:opacity-100 transition-opacity">Edit</Button>
                                </td>
                            </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
          </Card>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Modify Entity Parameters">
          {editingOrg && (
            <div className="space-y-6">
                <Input label="Organisation Name" name="name" value={editingOrg.name} onChange={(e) => setEditingOrg({...editingOrg, name: e.target.value})} />
                <Input label="Registry Mobile" name="mobile" value={editingOrg.mobile} onChange={(e) => setEditingOrg({...editingOrg, mobile: e.target.value})} />
                <Input label="Secretary Name" name="secretary_name" value={editingOrg.secretary_name} onChange={(e) => setEditingOrg({...editingOrg, secretary_name: e.target.value})} />
                <Select label="Access Status" name="status" value={editingOrg.status} onChange={(e) => setEditingOrg({...editingOrg, status: e.target.value as any})}>
                    <option value="Active">Active / Operational</option>
                    <option value="Deactivated">Locked / Deactivated</option>
                </Select>
                <div className="flex justify-end gap-4 pt-6">
                    <Button type="button" variant="secondary" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                    <Button type="button" onClick={handleUpdateOrganisation}>Commit Changes</Button>
                </div>
            </div>
          )}
      </Modal>
    </DashboardLayout>
  );
};

export default ManageOrganisations;

import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import { Volunteer, Role } from '../../types';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { Power, Download, UserPlus, UserCheck, Copy, ShieldCheck, Loader2, UserCircle, Zap, ShieldAlert } from 'lucide-react';

type VolunteerWithEnrollments = Volunteer & { enrollments: number };

const ManageVolunteers: React.FC = () => {
  const { user } = useAuth();
  const [volunteers, setVolunteers] = useState<VolunteerWithEnrollments[]>([]);
  const [newVol, setNewVol] = useState({ name: '', mobile: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { addNotification } = useNotification();

  const fetchVolunteers = useCallback(async () => {
    if (!user?.organisationId) return;
    setLoading(true);

    try {
        const { data: profileData, error: profileError } = await supabase
          .from('profiles')
          .select('*, members(id)')
          .eq('role', Role.Volunteer)
          .eq('organisation_id', user.organisationId);

        if (profileError) {
          addNotification("Registry sync failed. Check RLS policies.", 'error');
        } else {
          setVolunteers(profileData.map((v: any) => ({
              id: v.id,
              name: v.name,
              email: v.email,
              mobile: v.mobile,
              role: Role.Volunteer,
              organisationId: v.organisation_id,
              organisationName: user.organisationName,
              status: v.status || 'Active',
              enrollments: v.members?.length || 0
          })) || []);
        }
    } catch (e) {
        console.error("Fetch Error:", e);
    } finally {
        setLoading(false);
    }
  }, [user, addNotification]);

  useEffect(() => {
    fetchVolunteers();
  }, [fetchVolunteers]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewVol(prev => ({ ...prev, [name]: value }));
  };

  const handleAddVolunteer = async () => {
    const email = newVol.email.trim().toLowerCase();
    const password = newVol.password;
    const name = newVol.name.trim();
    const mobile = newVol.mobile.trim();

    if (!user?.organisationId) {
        addNotification("Session missing Organisation context.", 'error');
        return;
    }
    if (!email || !password || !name || !mobile) {
        addNotification("Identity parameters incomplete.", 'error');
        return;
    }

    setIsSubmitting(true);

    try {
        // 1. Create Auth Identity
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email: email,
          password: password,
          options: {
            data: {
              name: name,
              mobile: mobile,
              role: 'Volunteer', 
              organisation_id: user.organisationId
            }
          }
        });

        if (authError) {
            if (authError.message.includes("Database error saving new user")) {
                throw new Error("Trigger Failure: Database failed to create profile. Ensure 'profiles' table columns match metadata.");
            }
            throw authError;
        }

        // 2. Immediate Profile Injection (Atomic Sync)
        if (authData.user) {
            const { error: upsertError } = await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: name,
                email: email,
                role: 'Volunteer',
                organisation_id: user.organisationId,
                mobile: mobile,
                status: 'Active'
            });
            if (upsertError) {
                console.warn("Manual profile upsert warning:", upsertError.message);
            }
        }

        addNotification('Field agent authorized and deployed.', 'success');
        setNewVol({ name: '', mobile: '', email: '', password: '' });
        fetchVolunteers(); 
    } catch (err: any) {
        console.error("Authorization fault:", err);
        const errorMessage = typeof err === 'object' ? (err.message || JSON.stringify(err)) : String(err);
        addNotification(errorMessage, 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const copyVolunteerCreds = (v: VolunteerWithEnrollments) => {
      const text = `Agent: ${v.name}\nIdentity: ${v.email}\nSecurity: [Predefined]`;
      navigator.clipboard.writeText(text);
      addNotification("Identity parameters copied.", "success");
  };

  const handleToggleStatus = async (vol: VolunteerWithEnrollments) => {
    const newStatus = vol.status === 'Active' ? 'Deactivated' : 'Active';
    const { error } = await supabase
        .from('profiles')
        .update({ status: newStatus })
        .eq('id', vol.id);

    if (error) {
        addNotification("Override failed.", 'error');
    } else {
        addNotification(`Agent state set to: ${newStatus}`, 'success');
        fetchVolunteers();
    }
  };

  return (
    <DashboardLayout title="Field Force Command">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        {/* Authorization Panel */}
        <div className="lg:col-span-1">
          <Card title="Authorize New Agent" className="relative overflow-hidden border-blue-900/30">
            <div className="absolute top-0 right-0 p-4 opacity-10">
              <Zap size={60} />
            </div>
            <div className="space-y-6 relative z-10">
              <div className="flex items-center gap-4 p-5 bg-blue-500/5 border border-blue-500/10 rounded-2xl mb-4">
                 <ShieldCheck className="text-blue-500" size={24} />
                 <span className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400/80 leading-tight">Identity Tier: Field Operator</span>
              </div>

              <Input label="OPERATOR FULL NAME" name="name" value={newVol.name} onChange={handleInputChange} placeholder="Ex: Anil Kumar" className="bg-black/50 border-gray-800 font-mono text-sm" />
              <Input label="REGISTRY MOBILE" name="mobile" type="tel" value={newVol.mobile} onChange={handleInputChange} placeholder="98XXXXXXXX" className="bg-black/50 border-gray-800 font-mono text-sm" />
              <Input label="ACCESS EMAIL" name="email" type="email" value={newVol.email} onChange={handleInputChange} placeholder="agent@ssk.com" className="bg-black/50 border-gray-800 font-mono text-sm" />
              <Input label="SECURITY KEY" name="password" type="password" value={newVol.password} onChange={handleInputChange} placeholder="••••••••" className="bg-black/50 border-gray-800 font-mono text-sm" />

              <Button 
                type="button" 
                onClick={handleAddVolunteer} 
                disabled={isSubmitting} 
                className="w-full py-5 flex items-center justify-center gap-3 text-[11px] font-black tracking-[0.4em] uppercase mt-4 shadow-2xl shadow-blue-950/20"
              >
                {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <UserPlus size={20} />}
                {isSubmitting ? 'DEPLOYING...' : 'Authorize Operator'}
              </Button>
            </div>
          </Card>
        </div>

        {/* Force Registry */}
        <div className="lg:col-span-2">
          <Card className="bg-[#050505] border-white/5">
            <div className="flex justify-between items-center mb-12">
                <div className="flex items-center gap-5">
                    <div className="p-4 bg-orange-500/10 rounded-3xl text-orange-500 border border-orange-500/10">
                        <UserCircle size={28} />
                    </div>
                    <div>
                      <h3 className="font-cinzel text-3xl text-white tracking-tight">Active Force Registry</h3>
                      <p className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-600">Verified Personnel Records</p>
                    </div>
                </div>
                <button 
                  onClick={fetchVolunteers} 
                  className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:border-orange-500/40 text-gray-500 hover:text-white transition-all shadow-xl"
                  title="Force Sync"
                >
                    <Download size={20} />
                </button>
            </div>

            {loading ? (
                <div className="p-40 flex flex-col items-center justify-center gap-8">
                    <div className="w-16 h-16 border-4 border-orange-500/10 border-t-orange-500 rounded-full animate-spin"></div>
                    <span className="text-[11px] font-black uppercase tracking-[0.5em] text-gray-700">Accessing Cloud Registry...</span>
                </div>
            ) : (
            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left">
                <thead className="border-b border-gray-800">
                  <tr>
                    <th className="p-6 text-[10px] uppercase tracking-[0.4em] text-gray-500 font-black">Operator Identity</th>
                    <th className="p-6 text-[10px] uppercase tracking-[0.4em] text-gray-500 font-black text-center">Enrollment Matrix</th>
                    <th className="p-6 text-[10px] uppercase tracking-[0.4em] text-gray-500 font-black text-right">Overrides</th>
                  </tr>
                </thead>
                <tbody>
                  {volunteers.map(vol => (
                    <tr key={vol.id} className="group border-b border-gray-900/50 hover:bg-white/[0.015] transition-all duration-500">
                      <td className="p-6">
                        <div className="flex flex-col gap-2">
                            <span className="font-bold text-white text-lg group-hover:text-blue-400 transition-colors">{vol.name}</span>
                            <div className="flex items-center gap-4 text-[10px] text-gray-500 font-mono uppercase tracking-tighter">
                                <span className="text-gray-600">{vol.email}</span>
                                <span className="h-1 w-1 rounded-full bg-gray-800"></span>
                                <span className={`font-black tracking-[0.2em] ${vol.status === 'Active' ? 'text-green-500/60' : 'text-red-500/60'}`}>
                                  {vol.status === 'Active' ? 'OPERATIONAL' : 'DEACTIVATED'}
                                </span>
                            </div>
                        </div>
                      </td>
                      <td className="p-6 text-center">
                        <div className="inline-flex items-center gap-4 px-6 py-3 bg-white/[0.03] border border-white/5 rounded-[1.5rem] group-hover:border-orange-500/20 transition-all duration-500">
                            <UserCheck size={18} className="text-orange-500" />
                            <span className="font-black text-xl text-white tracking-tighter">{vol.enrollments}</span>
