          // If it's a "saving new user" error, the trigger crashed the transaction
          const isTriggerFault = errMsg.includes("database error") || 
                                 errMsg.includes("trigger") || 
                                 errMsg.includes("saving new user");

          if (isTriggerFault) {
            setShowRepairTool(true);
            setDiagnosticInfo("Fatal Trigger Crash: The background sync function is blocking user creation.");

            // Cleanup the org record since the user couldn't be created
            if (createdOrgId) await supabase.from('organisations').delete().eq('id', createdOrgId);

            throw new Error("Trigger Failure: Database crashed during user creation. Run the repair script.");
          } else {
            // Rollback for standard errors
            if (createdOrgId) await supabase.from('organisations').delete().eq('id', createdOrgId);
            throw authError;
          }
        }

        // Step 4: Post-Auth Verification & Manual Heal
        // Even if auth succeeds, the profile might have failed (if we used the 'Invincible' trigger)
        if (authData?.user?.id) {
            const { data: profileCheck } = await supabase.from('profiles').select('id').eq('id', authData.user.id).maybeSingle();

            if (!profileCheck) {
                addNotification("Auth successful but profile sync skipped. Healing...", "info");
                const { error: healError } = await supabase.from('profiles').upsert({
                    id: authData.user.id,
                    name: secretaryName,
                    email,
                    role: 'Organisation',
                    organisation_id: createdOrgId,
                    mobile,
                    status: 'Active'
                });

                if (healError) {
                    addNotification("System integrity warning: Profile heal failed.", "error");
                    setDiagnosticInfo(`Manual Sync Failed: ${healError.message}. System requires SQL Repair.`);
                    setShowRepairTool(true);
                }
            }
        }

        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
        addNotification('Entity successfully established.', 'success');
    } catch (err: any) {
        addNotification(err.message || "System handshake failed.", 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleEditClick = (org: Organisation) => {
    setEditingOrg({ ...org });
    setIsModalOpen(true);
  };

