                    </div>
                    <div>
                        <h4 className="text-red-400 font-bold text-sm uppercase tracking-tight">System Fault Detected</h4>
                        <p className="text-[9px] text-gray-500 uppercase tracking-widest font-black">Postgres Integrity Protocol</p>
                    </div>
                </div>

                <div className="bg-black/60 p-5 rounded-2xl border border-red-500/10 mb-6">
                    <div className="flex items-center gap-2 text-red-400 mb-2">
                        <Terminal size={14} />
