                    </div>
                    <p className="text-[11px] text-gray-400 leading-relaxed font-mono">
                        {diagnosticInfo || "CRITICAL: The user creation trigger is unstable. This prevents new signups from completing. Deployment of the Invincible Fix is mandatory."}
                    </p>
                </div>

                <div className="space-y-4">
                    <div className="flex items-center gap-2 mb-1">
                        <Wrench size={14} className="text-orange-500" />
                        <span className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Emergency Override</span>
