                    const { error: upsertError } = await supabase.from('profiles').upsert({
                        id: authData.user.id,
                        name,
                        email,
                        role: 'Volunteer',
                        organisation_id: user.organisationId,
                        mobile,
                        status: 'Active'
                    });

                    if (upsertError) {
                        throw new Error("Trigger crashed and manual sync failed. SQL Repair required.");
