        } 

        // Manual Handshake Fallback: If Auth succeeds but RLS/Trigger is slow
        if (authData?.user?.id) {
            const { error: healError } = await supabase.from('profiles').upsert({
                id: authData.user.id,
                name,
                email,
                role: 'Volunteer',
                organisation_id: user.organisationId,
                mobile,
                status: 'Active'
            });

            if (healError) {
                console.warn("Manual sync heal failed. This is likely an RLS Policy issue.", healError);
                setShowRepairTool(true);
                setDiagnosticInfo(`Access Policy Violation: ${healError.message}. Your account does not have permission to insert into the profiles table for this volunteer.`);
            } else {
                addNotification('Volunteer operator successfully deployed.', 'success');
                setNewVol({ name: '', mobile: '', email: '', password: '' });
                fetchVolunteers(); 
            }
        }
    } catch (err: any) {
        addNotification(err.message || "Uplink failed.", 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const copyVolunteerCreds = (v: VolunteerWithEnrollments) => {
