      COALESCE(new.raw_user_meta_data->>'name', 'User Node'), 
      new.email, 
      COALESCE(new.raw_user_meta_data->>'role', 'Volunteer'), 
      final_org_id, 
      new.raw_user_meta_data->>'mobile', 
      'Active'
    )
    ON CONFLICT (id) DO UPDATE SET 
      role = EXCLUDED.role, 
      organisation_id = EXCLUDED.organisation_id, 
      name = EXCLUDED.name, 
      mobile = EXCLUDED.mobile, 
      status = EXCLUDED.status;
  EXCEPTION WHEN OTHERS THEN
    -- If sync fails, the Auth system still succeeds. 
    -- We log it to the Postgres log for debugging.
    RAISE WARNING 'Sync failed for user %, but Auth signup allowed to proceed.', new.id;
  END;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 3. RESET TRIGGER
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- 4. RESET RLS POLICIES (THE CRITICAL FIX FOR ORG ADMINS)
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "MasterAdmin Full Access" ON public.profiles;
DROP POLICY IF EXISTS "Org Admins Manage Own Volunteers" ON public.profiles;
DROP POLICY IF EXISTS "Users View Own Profile" ON public.profiles;

-- Policy: Master Admin can do anything
CREATE POLICY "MasterAdmin Full Access" ON public.profiles FOR ALL 
TO authenticated
USING ( (auth.jwt() -> 'app_metadata' ->> 'role') = 'MasterAdmin' )
WITH CHECK ( (auth.jwt() -> 'app_metadata' ->> 'role') = 'MasterAdmin' );

-- Policy: Organisation Admins can manage their own volunteers
CREATE POLICY "Org Admins Manage Own Volunteers" ON public.profiles FOR ALL
TO authenticated
USING (
  organisation_id = (auth.jwt() -> 'user_metadata' ->> 'organisation_id')::uuid
  OR 
  organisation_id = (auth.jwt() -> 'app_metadata' ->> 'organisation_id')::uuid
)
WITH CHECK (
  organisation_id = (auth.jwt() -> 'user_metadata' ->> 'organisation_id')::uuid
  OR 
  organisation_id = (auth.jwt() -> 'app_metadata' ->> 'organisation_id')::uuid
);

-- Policy: Everyone can view their own profile
CREATE POLICY "Users View Own Profile" ON public.profiles FOR SELECT
TO authenticated
USING ( auth.uid() = id );

-- 5. FORCE PERMISSIONS
GRANT ALL ON public.profiles TO service_role;
GRANT ALL ON public.profiles TO postgres;
GRANT SELECT ON public.profiles TO authenticated, anon;`;

  const handleAddOrganisation = async () => {
    const email = newOrg.email.trim().toLowerCase();
    const password = newOrg.password;
    const name = newOrg.name.trim();
    const mobile = newOrg.mobile.trim();
    const secretaryName = newOrg.secretaryName.trim();

    if (!email || !password || !name || !mobile || !secretaryName) {
        addNotification("Authorization parameters missing.", 'error');
        return;
    }

    setIsSubmitting(true);
    setShowRepairTool(false);
    setDiagnosticInfo(null);
    let createdOrgId: string | null = null;

    try {
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ name, mobile, secretary_name: secretaryName, status: 'Active' })
          .select().single();

        if (orgError) throw new Error(`Registration Blocked: ${orgError.message}`);
        createdOrgId = orgData.id;

        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              name: secretaryName,
              role: 'Organisation',
              organisation_id: createdOrgId,
              mobile
            }
          }
        });

        if (authError) {
          const errMsg = authError.message.toLowerCase();
          const isTriggerFault = errMsg.includes("database error") || errMsg.includes("trigger") || errMsg.includes("saving new user");

          if (isTriggerFault) {
            setShowRepairTool(true);
            setDiagnosticInfo("Fatal Sync Collision: A background function crashed. This blocks user creation until the repair script is run.");
            if (createdOrgId) await supabase.from('organisations').delete().eq('id', createdOrgId);
            throw new Error(`Trigger Failure: ${authError.message}. Run the repair script.`);
          } else {
            if (createdOrgId) await supabase.from('organisations').delete().eq('id', createdOrgId);
            throw authError;
          }
        }

        if (authData?.user?.id) {
            const { data: profileCheck } = await supabase.from('profiles').select('id').eq('id', authData.user.id).maybeSingle();
            if (!profileCheck) {
                const { error: healError } = await supabase.from('profiles').upsert({
                    id: authData.user.id,
                    name: secretaryName,
                    email,
                    role: 'Organisation',
                    organisation_id: createdOrgId,
                    mobile,
                    status: 'Active'
                });
                if (healError) {
                   setShowRepairTool(true);
                   const healMsg = typeof healError.message === 'string' ? healError.message : JSON.stringify(healError);
                   setDiagnosticInfo(`Manual sync failed: ${healMsg}`);
                }
            }
        }

        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
        addNotification('Entity successfully authorized.', 'success');
    } catch (err: any) {
        const errMsg = err?.message || (typeof err === 'string' ? err : 'System handshake failed.');
        addNotification(errMsg, 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

