    organisation_id uuid REFERENCES public.organisations(id),
    submission_date timestamp with time zone DEFAULT now(),
    status text DEFAULT 'Pending'
);

-- 2. ENABLE RLS
ALTER TABLE public.members ENABLE ROW LEVEL SECURITY;

-- 3. RESET POLICIES
DROP POLICY IF EXISTS "Enable select for duplicates" ON public.members;
DROP POLICY IF EXISTS "Volunteers insert own" ON public.members;
DROP POLICY IF EXISTS "Orgs view own members" ON public.members;
DROP POLICY IF EXISTS "MasterAdmin view all" ON public.members;

