import React, { useState, useMemo, useEffect } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import { useAuth } from '../../context/AuthContext';
import { Member, MemberStatus } from '../../types';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { User, Building2, AlertTriangle, RefreshCw } from 'lucide-react';

const VolunteerDashboard: React.FC = () => {
    const { user, refreshProfile } = useAuth();
    const navigate = useNavigate();
    const [mySubmissions, setMySubmissions] = useState<Member[]>([]);
    const [loading, setLoading] = useState(true);
    const { addNotification } = useNotification();

    const getErrorMessage = (err: any): string => {
        if (!err) return "Unknown Error";
        if (typeof err === 'string') return err;
        const msg = err.message || err.error_description || err.details;
        if (typeof msg === 'string') return msg;
        try {
            const str = JSON.stringify(err);
            if (str !== '{}') return str;
        } catch {}
        return String(err);
    };

    useEffect(() => {
        const fetchSubmissions = async () => {
            if (!user?.id) return;
            setLoading(true);

            if (!user.organisationId) {
                console.warn("Profile sync missing. Attempting emergency refresh.");
                await refreshProfile();
            }

            const { data, error } = await supabase
                .from('members')
                .select('*')
                .eq('volunteer_id', user.id);

            if (error) {
                const errMsg = getErrorMessage(error);
                console.error("Submission Registry Error:", error);
                addNotification(`Sync Error: ${errMsg}`, 'error');
            } else if (data) {
                setMySubmissions(data);
            }
            setLoading(false);
        };
        fetchSubmissions();
    }, [user, addNotification, refreshProfile]);

    const [filters, setFilters] = useState({
        startDate: '',
        endDate: '',
        phone: '',
        area: '', 
    });

    const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
    };

    const filteredSubmissions = useMemo(() => {
        return mySubmissions.filter(member => {
            const submissionDate = new Date(member.submission_date);
            const startDate = filters.startDate ? new Date(filters.startDate) : null;
            const endDate = filters.endDate ? new Date(filters.endDate) : null;
            if (endDate) {
                endDate.setHours(23, 59, 59, 999);
            }
            if (startDate && submissionDate < startDate) return false;
            if (endDate && submissionDate > endDate) return false;

            if (filters.phone && !member.mobile.includes(filters.phone)) {
                return false;
            }

            if (filters.area && !member.pincode.includes(filters.area)) {
                return false;
            }

            return true;
        });
    }, [mySubmissions, filters]);

    if (!user?.organisationId && !loading) {
        return (
            <DashboardLayout title="Identity Sync Required">
                <Card className="border-red-500/30 bg-red-950/10 p-12 text-center max-w-2xl mx-auto mt-20">
                    <AlertTriangle className="text-red-500 mx-auto mb-6" size={64} />
                    <h2 className="text-2xl font-cinzel text-white mb-4">Identity Out of Sync</h2>
                    <p className="text-gray-400 mb-8 leading-relaxed">
                        Your account has been verified, but your field profile is not yet linked to an organization. 
                        This usually happens if the background sync trigger encountered a database conflict.
                    </p>
                    <div className="flex flex-col gap-4">
                        <Button onClick={() => window.location.reload()} className="flex items-center justify-center gap-2">
                            <RefreshCw size={18} /> Re-establish Handshake
                        </Button>
                        <p className="text-[10px] text-gray-600 font-black uppercase tracking-widest">
                            Contact Master Admin if this persists
                        </p>
                    </div>
                </Card>
            </DashboardLayout>
        );
    }

    return (
        <DashboardLayout title="Field Operations Hub">
            <div className="space-y-6">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 p-8 bg-blue-900/10 border border-blue-900/20 rounded-3xl backdrop-blur-sm">
                    <div className="flex gap-6 items-center">
                         <div className="p-4 bg-blue-500/10 rounded-2xl border border-blue-500/20 text-blue-400 shadow-xl shadow-blue-950/40">
                            <User size={32} />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-[0.4em] text-blue-400/60 mb-1">Authenticated Field Force</p>
                            <h2 className="font-cinzel text-3xl text-white tracking-tight">{user?.name}</h2>
                        </div>
                    </div>
                    <div className="flex gap-6 items-center md:border-l border-white/5 md:pl-10">
                         <div className="p-4 bg-white/5 rounded-2xl border border-white/10 text-gray-500">
                            <Building2 size={32} />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-500 mb-1">Operational Sector</p>
                            <h2 className="font-cinzel text-xl text-white opacity-80">{user?.organisationName || 'Registry Pending'}</h2>
                        </div>
                    </div>
                    <Button onClick={() => navigate('/volunteer/new-member')} className="w-full md:w-auto mt-2 md:mt-0 py-4 px-10 rounded-2xl shadow-2xl">
                        Enroll New Member
                    </Button>
                </div>

                <Card className="mb-6 border-white/5 bg-gray-900/40">
                    <div className="flex flex-wrap gap-6 items-end p-2">
                        <div className="flex-1 min-w-[200px]">
                            <Input label="Registry Start" type="date" name="startDate" value={filters.startDate} onChange={handleFilterChange} />
                        </div>
                        <div className="flex-1 min-w-[200px]">
                            <Input label="Registry End" type="date" name="endDate" value={filters.endDate} onChange={handleFilterChange} />
                        </div>
                        <div className="flex-1 min-w-[200px]">
                            <Input label="Search Mobile" type="text" name="phone" placeholder="91XXXXXXXX" value={filters.phone} onChange={handleFilterChange} />
                        </div>
                        <div className="flex-1 min-w-[200px]">
                            <Input label="Area Pincode" type="text" name="area" placeholder="560XXX" value={filters.area} onChange={handleFilterChange} />
                        </div>
                    </div>
                </Card>

                <Card title="My Field Enrollments">
                    <div className="overflow-x-auto">
                      <table className="w-full text-left">
                        <thead className="border-b border-gray-800">
                          <tr>
                            <th className="p-4 text-[10px] uppercase tracking-widest text-gray-500 font-black">Member Identity</th>
                            <th className="p-4 text-[10px] uppercase tracking-widest text-gray-500 font-black">Mobile</th>
                            <th className="p-4 text-[10px] uppercase tracking-widest text-gray-500 font-black text-center">Date</th>
                            <th className="p-4 text-[10px] uppercase tracking-widest text-gray-500 font-black text-center">Status</th>
                            <th className="p-4 text-right"></th>
                          </tr>
                        </thead>
                        <tbody>
                          {loading ? (
                              <tr><td colSpan={5} className="text-center p-20 animate-pulse text-[10px] uppercase tracking-[0.3em] text-gray-600 font-black">Scanning Master Registry...</td></tr>
                          ) : (
                            <>
                            {filteredSubmissions.map(member => (
                              <tr key={member.id} className="group border-b border-gray-900/50 hover:bg-white/[0.02] transition-colors">
                                <td className="p-4">
                                    <div className="flex flex-col">
                                        <span className="font-bold text-white group-hover:text-orange-500 transition-colors">{member.name} {member.surname}</span>
                                        <span className="text-[10px] text-gray-600 uppercase tracking-wider">{member.pincode}</span>
                                    </div>
                                </td>
                                <td className="p-4 font-mono text-gray-400">{member.mobile}</td>
                                <td className="p-4 text-center text-xs text-gray-500">{member.submission_date}</td>
                                <td className="p-4 text-center">
                                  <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                                      member.status === MemberStatus.Accepted ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20'
                                  }`}>
                                    {member.status}
                                  </span>
                                </td>
                                <td className="p-4 text-right">
                                  {member.status === MemberStatus.Pending && (
                                      <Button variant="secondary" size="sm" onClick={() => addNotification(`Edit node for ${member.name} is not implemented.`, 'info')} className="text-[10px] px-4 opacity-0 group-hover:opacity-100 transition-opacity">
                                          Update
                                      </Button>
                                  )}
                                </td>
                              </tr>
                            ))}
                            {filteredSubmissions.length === 0 && (
                                <tr>
                                    <td colSpan={5} className="text-center p-20 text-gray-700 font-black uppercase tracking-widest text-[10px]">
                                        No active records detected in current window.
                                    </td>
                                </tr>
                            )}
                            </>
                          )}
                        </tbody>
                      </table>
                    </div>
                </Card>
            </div>
        </DashboardLayout>
    );
};

export default VolunteerDashboard;

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import Button from '../../components/ui/Button';
import { Gender, Occupation, SupportNeed } from '../../types';
import { supabase } from '../../supabase/client';
import { useAuth } from '../../context/AuthContext';
import { useNotification } from '../../context/NotificationContext';
import { UploadCloud, Camera, ShieldAlert, Copy, ExternalLink, RefreshCw, Database, AlertTriangle, Zap, CheckCircle2, Loader2 } from 'lucide-react';

const initialFormData = {
  aadhaar: '',
  mobile: '',
  name: '',
  surname: '',
  fatherName: '',
  dob: '',
  gender: Gender.Male,
  emergencyContact: '',
  pincode: '',
  address: '',
  memberImage: null as File | null,
  occupation: Occupation.Job,
  supportNeed: SupportNeed.Education,
};

const NewMemberForm: React.FC = () => {
  const { user } = useAuth();
  const { addNotification } = useNotification();
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState(initialFormData);
  const [aadhaarError, setAadhaarError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [showRepairTool, setShowRepairTool] = useState(false);
  const [diagnosticInfo, setDiagnosticInfo] = useState<string | null>(null);

  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const getErrorMessage = (err: any): string => {
      if (!err) return "Unknown Error";
      if (typeof err === 'string') return err;
      const msg = err.message || err.error_description || err.details;
      if (typeof msg === 'string') return msg;
      try {
          const str = JSON.stringify(err);
          if (str !== '{}') return str;
      } catch {}
      return String(err);
  };

  useEffect(() => {
    return () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
        const file = e.target.files[0];
        setFormData(prev => ({ ...prev, memberImage: file }));
        if(imagePreview) URL.revokeObjectURL(imagePreview);
        setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = () => {
    if (imagePreview) URL.revokeObjectURL(imagePreview);
    setFormData(prev => ({ ...prev, memberImage: null }));
    setImagePreview(null);
    if(fileInputRef.current) fileInputRef.current.value = '';
  };

  const openCamera = async () => {
    try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        streamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;
        setIsCameraOpen(true);
    } catch (err) {
        console.error("Error accessing camera:", err);
        addNotification("Could not access camera. Please check browser permissions.", 'error');
    }
  };

  const closeCamera = () => {
    if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    setIsCameraOpen(false);
  };

  const handleCapture = () => {
    const canvas = document.createElement('canvas');
    if (videoRef.current) {
        canvas.width = videoRef.current.videoWidth;
        canvas.height = videoRef.current.videoHeight;
        const context = canvas.getContext('2d');
        if (context) {
            context.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
            canvas.toBlob((blob) => {
                if (blob) {
                    const file = new File([blob], "member-capture.jpg", { type: "image/jpeg" });
                    setFormData(prev => ({ ...prev, memberImage: file }));
                    if(imagePreview) URL.revokeObjectURL(imagePreview);
                    setImagePreview(URL.createObjectURL(file));
                    closeCamera();
                }
            }, 'image/jpeg');
        }
    }
  };

  const MEMBERS_TABLE_REPAIR_SQL = `-- 🔱 SSK "GOD-LEVEL" MEMBERS TABLE REPAIR 🔱
-- 1. ENSURE MEMBERS TABLE EXISTS WITH CORRECT SCHEMA
CREATE TABLE IF NOT EXISTS public.members (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    aadhaar text UNIQUE NOT NULL,
    mobile text,
    name text,
    surname text,
    father_name text,
    dob date,
    gender text,
    emergency_contact text,
    pincode text,
    address text,
    member_image_url text,
    occupation text,
    support_need text,
    volunteer_id uuid REFERENCES public.profiles(id),
    organisation_id uuid REFERENCES public.organisations(id),
    submission_date timestamp with time zone DEFAULT now(),
    status text DEFAULT 'Pending'
);

-- 2. ENABLE RLS
ALTER TABLE public.members ENABLE ROW LEVEL SECURITY;

-- 3. RESET POLICIES
DROP POLICY IF EXISTS "Enable select for duplicates" ON public.members;
DROP POLICY IF EXISTS "Volunteers insert own" ON public.members;
DROP POLICY IF EXISTS "Orgs view own members" ON public.members;
DROP POLICY IF EXISTS "MasterAdmin view all" ON public.members;

-- Policy: Everyone can check Aadhaar (needed for Step 1 duplicate check)
-- We only allow selecting the 'id' and 'aadhaar' column to preserve privacy
CREATE POLICY "Public Aadhaar Check" ON public.members FOR SELECT 
TO authenticated 
USING ( true );

-- Policy: Volunteers can insert members into their own organization
CREATE POLICY "Volunteers Insert" ON public.members FOR INSERT 
TO authenticated 
WITH CHECK (
    volunteer_id = auth.uid()
);

-- Policy: Org Admins and Volunteers can see members belonging to their organization
CREATE POLICY "Org Member Visibility" ON public.members FOR SELECT 
TO authenticated 
USING (
    organisation_id = (auth.jwt() -> 'user_metadata' ->> 'organisation_id')::uuid
    OR 
    organisation_id = (auth.jwt() -> 'app_metadata' ->> 'organisation_id')::uuid
    OR
    (auth.jwt() -> 'app_metadata' ->> 'role') = 'MasterAdmin'
);

-- 4. GRANT PERMISSIONS
GRANT ALL ON public.members TO authenticated;
GRANT ALL ON public.members TO service_role;
GRANT ALL ON public.members TO postgres;`;

  const handleStep1Next = async () => {
    setAadhaarError('');
    setShowRepairTool(false);

    if (!formData.aadhaar || !/^\d{12}$/.test(formData.aadhaar)) {
      setAadhaarError('Please enter a valid 12-digit Aadhaar number.');
      return;
    }

    setIsValidating(true);
    try {
        const { data, error } = await supabase
          .from('members')
          .select('id')
          .eq('aadhaar', formData.aadhaar)
          .maybeSingle();

        if (error) {
            const errMsg = getErrorMessage(error);
            console.error("Duplicate Check Fault:", error);

            if (errMsg.toLowerCase().includes("permission denied") || errMsg.toLowerCase().includes("not found")) {
                setShowRepairTool(true);
                setDiagnosticInfo(`Database Restriction: ${errMsg}. You lack permissions to check the 'members' registry.`);
            }

            setAadhaarError(`Registry Connection Fault: ${errMsg}`);
            return;
        }

        if (data) {
          setAadhaarError('This identity node (Aadhaar) is already registered in the master registry.');
        } else {
          setStep(2);
        }
    } catch (e: any) {
        const errMsg = getErrorMessage(e);
        setAadhaarError(`System Fault: ${errMsg}`);
    } finally {
        setIsValidating(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!user || !user.organisationId) {
          addNotification("Identity Context Lost. Re-login required.", 'error');
          return;
      }
      setIsSubmitting(true);

      try {
          let imageUrl = '';
          if (formData.memberImage) {
              const fileExt = formData.memberImage.name.split('.').pop();
              const fileName = `${uuidv4()}.${fileExt}`;
              const { data: uploadData, error: uploadError } = await supabase.storage
                .from('member-images')
                .upload(fileName, formData.memberImage);

              if(uploadError) {
                  throw new Error(`Cloud Storage Fault: ${uploadError.message}`);
              }
              const { data: publicUrlData } = supabase.storage.from('member-images').getPublicUrl(uploadData.path);
              imageUrl = publicUrlData.publicUrl;
          }

          const { error: insertError } = await supabase.from('members').insert({
              aadhaar: formData.aadhaar,
              mobile: formData.mobile,
              name: formData.name,
              surname: formData.surname,
              father_name: formData.fatherName,
              dob: formData.dob,
              gender: formData.gender,
              emergency_contact: formData.emergencyContact,
              pincode: formData.pincode,
              address: formData.address,
              member_image_url: imageUrl,
              occupation: formData.occupation,
              support_need: formData.supportNeed,
              volunteer_id: user.id,
              organisation_id: user.organisationId,
              status: 'Pending'
          });

          if (insertError) {
              throw insertError;
          } else {
              addNotification("Member successfully enrolled into the registry.", 'success');
              setFormData(initialFormData);
              handleRemoveImage();
              setStep(1);
          }
      } catch (err: any) {
          const errMsg = getErrorMessage(err);
          addNotification(errMsg, 'error');
      } finally {
          setIsSubmitting(false);
      }
  };

  const renderStep = () => {
    switch (step) {
      case 1:
        return (
          <div className="space-y-8">
            <div className="flex items-center gap-4 mb-2">
                <div className="p-3 bg-orange-500/10 rounded-2xl text-orange-500 border border-orange-500/10 shadow-lg">
                    <Database size={24} />
                </div>
                <div>
                    <h3 className="font-cinzel text-xl text-white">Registry Validation</h3>
                    <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest">Master Identity Sync</p>
                </div>
            </div>

            <Card className="bg-[#050505] border-white/5 relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
                  <ShieldAlert size={100} />
              </div>
              <div className="space-y-6 relative z-10">
                <Input 
                  label="12-DIGIT AADHAAR ID" 
                  name="aadhaar" 
                  value={formData.aadhaar} 
                  onChange={handleChange} 
                  placeholder="0000 0000 0000" 
                  className="bg-black/40 border-gray-800 text-lg font-mono tracking-[0.2em]"
                />

                <Input 
                    label="MOBILE CONTACT" 
                    name="mobile" 
                    type="tel"
                    value={formData.mobile} 
                    onChange={handleChange} 
                    placeholder="91XXXXXXXX" 
                    className="bg-black/40 border-gray-800"
                />

                {aadhaarError && (
                    <div className="p-4 rounded-2xl border border-red-500/20 bg-red-500/5 flex items-start gap-3 animate-in fade-in slide-in-from-top-2">
                        <AlertTriangle className="text-red-500 shrink-0 mt-0.5" size={16} />
                        <p className="text-xs text-red-200/80 leading-relaxed font-medium">{aadhaarError}</p>
                    </div>
                )}
              </div>

              <div className="mt-8 flex justify-end">
                <Button onClick={handleStep1Next} disabled={isValidating} className="py-4 px-12 text-[11px] font-black uppercase tracking-widest shadow-2xl flex items-center gap-3">
                  {isValidating ? <Loader2 className="animate-spin" size={16} /> : <Zap size={16} />}
                  {isValidating ? 'VALIDATING...' : 'Initialize Enrollment'}
                </Button>
              </div>
            </Card>

            {showRepairTool && (
                <Card className="border-red-500 border-2 bg-red-950/20 p-8 shadow-3xl animate-in fade-in slide-in-from-top-4 ring-4 ring-red-500/10">
                    <div className="flex items-start gap-4 mb-6">
                        <div className="p-3 bg-red-500 rounded-2xl text-white shadow-lg">
                            <ShieldAlert size={28} className="animate-pulse" />
                        </div>
                        <div>
                            <h4 className="text-red-400 font-bold text-lg uppercase tracking-tight leading-none mb-1">DATABASE FAULT</h4>
                            <p className="text-[10px] text-gray-400 uppercase tracking-widest font-black">RLS Policy Restriction</p>
                        </div>
                    </div>
                    <div className="space-y-6">
                        <div className="p-4 bg-black/60 rounded-xl border border-red-500/20">
                            <p className="text-[11px] text-red-200/80 leading-relaxed font-mono italic">
                            {diagnosticInfo || "Your organization account lacks permission to query the master registry. This blocks Aadhaar duplicate checks."}
                            </p>
                        </div>
                        <div className="space-y-3">
                            <Button 
                                variant="primary" 
                                size="sm" 
                                className="w-full text-[11px] font-black uppercase tracking-widest flex items-center justify-center gap-2 py-4 bg-red-600 hover:bg-red-500 text-white shadow-2xl"
                                onClick={() => { navigator.clipboard.writeText(MEMBERS_TABLE_REPAIR_SQL); addNotification("Registry fix copied.", "success"); }}
                            >
                                <Copy size={16} /> Copy Registry Repair Script
                            </Button>
                            <a 
                                href="https://baetdjjzfqupdzsoecph.supabase.co/dashboard/project/baetdjjzfqupdzsoecph/sql/new" 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center justify-center gap-2 w-full text-orange-500 text-[11px] font-black uppercase tracking-widest hover:underline py-3 bg-white/5 rounded-xl border border-white/5"
                            >
                                Open SQL Console <ExternalLink size={12} />
                            </a>
                        </div>
                        <div className="pt-4 border-t border-red-500/10">
                            <p className="text-[9px] text-gray-500 font-bold uppercase text-center leading-relaxed">
                                Instructions: Copy script -> Paste in Supabase SQL Editor -> Run -> Refresh Page
                            </p>
                        </div>
                    </div>
                </Card>
            )}
          </div>
        );
      case 2:
        return (
          <div className="space-y-8">
            <div className="flex items-center gap-4">
                <div className="p-3 bg-blue-500/10 rounded-2xl text-blue-500 border border-blue-500/10">
                    <UserCircle size={24} />
                </div>
                <div>
                    <h3 className="font-cinzel text-xl text-white">Identity Profile</h3>
                    <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest">Personal Identification Nodes</p>
                </div>
            </div>

            <Card className="bg-[#050505] border-white/5">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <Input label="GIVEN NAME" name="name" value={formData.name} onChange={handleChange} className="bg-black/40" />
                  <Input label="SURNAME / FAMILY NAME" name="surname" value={formData.surname} onChange={handleChange} className="bg-black/40" />
                  <Input label="FATHER / GUARDIAN NAME" name="fatherName" value={formData.fatherName} onChange={handleChange} className="bg-black/40" />
                  <Input label="DATE OF BIRTH" name="dob" type="date" value={formData.dob} onChange={handleChange} className="bg-black/40" />
                  <Select label="BIOLOGICAL GENDER" name="gender" value={formData.gender} onChange={handleChange} className="bg-black/40">
                    {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
                  </Select>
                  <Input label="EMERGENCY CONTACT" name="emergencyContact" value={formData.emergencyContact} onChange={handleChange} className="bg-black/40" />
                  <Input label="POSTAL PINCODE" name="pincode" value={formData.pincode} onChange={handleChange} className="bg-black/40" />
                   <div className="md:col-span-2">
                    <Input label="DETAILED POSTAL ADDRESS" name="address" value={formData.address} onChange={handleChange} placeholder="House No, Street, Landmark, City" className="bg-black/40" />
                   </div>
                  <div className="md:col-span-2">
                    <label className="block text-[10px] font-black uppercase tracking-widest text-gray-500 mb-4">IDENTITY CAPTURE (VISUAL)</label>
                    <div className="mt-1 flex items-center justify-center px-10 py-16 border-2 border-gray-800 border-dashed rounded-3xl bg-black/40 group hover:border-orange-500/30 transition-all">
                        {imagePreview ? (
                            <div className="text-center">
                                <img src={imagePreview} alt="Member Image Preview" className="mx-auto h-56 rounded-2xl shadow-2xl border border-white/10" />
                                <Button variant="secondary" size="sm" onClick={handleRemoveImage} className="mt-6 text-[10px] font-black uppercase">Purge Capture</Button>
                            </div>
                        ) : (
                            <div className="space-y-6 text-center">
                                <div className="flex flex-wrap gap-4 justify-center">
                                    <Button type="button" size="sm" onClick={() => fileInputRef.current?.click()} className="flex items-center gap-3 py-4 px-8 text-[10px] font-black uppercase">
                                        <UploadCloud size={16} /> Upload Identity
                                    </Button>
                                    <Button type="button" size="sm" variant="secondary" onClick={openCamera} className="flex items-center gap-3 py-4 px-8 text-[10px] font-black uppercase">
                                        <Camera size={16} /> Direct Capture
                                    </Button>
                                </div>
                                <input ref={fileInputRef} id="memberImage" name="memberImage" type="file" className="sr-only" onChange={handleFileChange} accept="image/*" />
                                <p className="text-[9px] text-gray-600 font-black uppercase tracking-widest">Digital imaging: PNG, JPG (MAX 10MB)</p>
                            </div>
                        )}
                    </div>
                  </div>
                </div>
                <div className="mt-12 flex justify-between border-t border-white/5 pt-8">
                    <Button variant="secondary" onClick={() => setStep(1)} className="py-4 px-10 text-[10px] font-black uppercase tracking-widest">Back</Button>
                    <Button onClick={() => setStep(3)} className="py-4 px-12 text-[10px] font-black uppercase tracking-widest shadow-2xl">Confirm Profile</Button>
                </div>
            </Card>
          </div>
        );
      case 3:
        return (
          <form onSubmit={handleSubmit} className="space-y-8">
            <div className="flex items-center gap-4">
                <div className="p-3 bg-green-500/10 rounded-2xl text-green-500 border border-green-500/10">
                    <CheckCircle2 size={24} />
                </div>
                <div>
                    <h3 className="font-cinzel text-xl text-white">Socio-Economic Purpose</h3>
                    <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest">Community Intelligence Data</p>
                </div>
            </div>

            <Card className="bg-[#050505] border-white/5">
                <div className="space-y-8 max-w-2xl">
                    <Select label="CURRENT OCCUPATION" name="occupation" value={formData.occupation} onChange={handleChange} className="bg-black/40">
                         {Object.values(Occupation).map(o => <option key={o} value={o}>{o}</option>)}
                    </Select>
                    <Select label="SUPPORT CATEGORY REQUESTED" name="supportNeed" value={formData.supportNeed} onChange={handleChange} className="bg-black/40">
                        {Object.values(SupportNeed).map(s => <option key={s} value={s}>{s}</option>)}
                    </Select>

                    <div className="p-6 bg-orange-500/5 border border-orange-500/10 rounded-2xl">
                        <div className="flex items-start gap-3">
                            <Zap className="text-orange-500 shrink-0 mt-1" size={18} />
                            <p className="text-xs text-gray-400 leading-relaxed">
                                By submitting this enrollment, you verify that all identity nodes captured are accurate and verified by the member. This node will be locked to your field agent ID.
                            </p>
                        </div>
                    </div>
                </div>
                <div className="mt-12 flex justify-between border-t border-white/5 pt-8">
                    <Button variant="secondary" type="button" onClick={() => setStep(2)} className="py-4 px-10 text-[10px] font-black uppercase tracking-widest">Back</Button>
                    <Button type="submit" disabled={isSubmitting} className="py-4 px-12 text-[10px] font-black uppercase tracking-widest shadow-2xl">
                        {isSubmitting ? 'TRANSMITTING...' : 'Commit Registry Entry'}
                    </Button>
                </div>
            </Card>
          </form>
        );
      default:
        return null;
    }
  };

  const UserCircle = ({ size }: { size: number }) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><path d="M16 16s-1.5-2-4-2-4 2-4 2"/><circle cx="12" cy="10" r="3"/></svg>;

  return (
    <DashboardLayout title="Member Enrollment Terminal">
      <div className="w-full max-w-5xl mx-auto space-y-12 pb-20">
          <div className="relative pt-10">
              <div className="flex justify-between items-center mb-6 relative z-10 px-2">
                  <div className={`flex flex-col items-center gap-2 group cursor-default transition-all duration-500 ${step >= 1 ? 'scale-110' : 'opacity-40'}`}>
                      <div className={`h-12 w-12 rounded-full border-2 flex items-center justify-center transition-all duration-500 ${step >= 1 ? 'bg-orange-500 border-orange-400 shadow-[0_0_20px_rgba(255,100,0,0.3)]' : 'bg-gray-900 border-gray-800'}`}>
                          <span className={`text-sm font-black ${step >= 1 ? 'text-white' : 'text-gray-600'}`}>01</span>
                      </div>
                      <span className={`text-[9px] font-black uppercase tracking-[0.2em] ${step >= 1 ? 'text-orange-500' : 'text-gray-600'}`}>Verify</span>
                  </div>
                  <div className={`flex flex-col items-center gap-2 group cursor-default transition-all duration-500 ${step >= 2 ? 'scale-110' : 'opacity-40'}`}>
                      <div className={`h-12 w-12 rounded-full border-2 flex items-center justify-center transition-all duration-500 ${step >= 2 ? 'bg-orange-500 border-orange-400 shadow-[0_0_20px_rgba(255,100,0,0.3)]' : 'bg-gray-900 border-gray-800'}`}>
                          <span className={`text-sm font-black ${step >= 2 ? 'text-white' : 'text-gray-600'}`}>02</span>
                      </div>
                      <span className={`text-[9px] font-black uppercase tracking-[0.2em] ${step >= 2 ? 'text-orange-500' : 'text-gray-600'}`}>Identity</span>
                  </div>
                  <div className={`flex flex-col items-center gap-2 group cursor-default transition-all duration-500 ${step >= 3 ? 'scale-110' : 'opacity-40'}`}>
                      <div className={`h-12 w-12 rounded-full border-2 flex items-center justify-center transition-all duration-500 ${step >= 3 ? 'bg-orange-500 border-orange-400 shadow-[0_0_20px_rgba(255,100,0,0.3)]' : 'bg-gray-900 border-gray-800'}`}>
                          <span className={`text-sm font-black ${step >= 3 ? 'text-white' : 'text-gray-600'}`}>03</span>
                      </div>
                      <span className={`text-[9px] font-black uppercase tracking-[0.2em] ${step >= 3 ? 'text-orange-500' : 'text-gray-600'}`}>Finalize</span>
                  </div>
              </div>
              <div className="absolute top-[4.5rem] left-0 w-full h-0.5 bg-gray-900 rounded-full overflow-hidden">
                  <div className="h-full bg-orange-600 transition-all duration-700 shadow-[0_0_10px_rgba(255,100,0,0.5)]" style={{ width: `${((step - 1) / 2) * 100}%` }}></div>
              </div>
          </div>

          <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
            {renderStep()}
          </div>
      </div>

      {isCameraOpen && (
          <div className="fixed inset-0 bg-black/95 flex items-center justify-center z-[100] p-6 backdrop-blur-md">
              <Card title="Direct Identity Capture" className="w-full max-w-3xl border-orange-500/20 bg-black shadow-[0_0_100px_rgba(255,100,0,0.1)]">
                  <div className="relative rounded-3xl overflow-hidden border border-white/10 bg-gray-900">
                    <video ref={videoRef} autoPlay playsInline className="w-full h-auto"></video>
                    <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none"></div>
                  </div>
                  <div className="flex justify-center space-x-6 pt-10">
                      <Button type="button" onClick={handleCapture} className="py-4 px-12 text-[10px] font-black uppercase tracking-widest shadow-2xl">Capture Identity</Button>
                      <Button type="button" variant="secondary" onClick={closeCamera} className="py-4 px-10 text-[10px] font-black uppercase tracking-widest">Abort</Button>
                  </div>
              </Card>
          </div>
      )}
    </DashboardLayout>
  );
};

export default NewMemberForm;

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import Button from '../../components/ui/Button';
import { Gender, Occupation, SupportNeed } from '../../types';
import { supabase } from '../../supabase/client';
import { useAuth } from '../../context/AuthContext';
import { useNotification } from '../../context/NotificationContext';
import { UploadCloud, Camera, ShieldAlert, Copy, ExternalLink, RefreshCw, Database, AlertTriangle, Zap, CheckCircle2, Loader2 } from 'lucide-react';

const initialFormData = {
  aadhaar: '',
  mobile: '',
  name: '',
  surname: '',
  fatherName: '',
  dob: '',
  gender: Gender.Male,
  emergencyContact: '',
  pincode: '',
  address: '',
  memberImage: null as File | null,
  occupation: Occupation.Job,
  supportNeed: SupportNeed.Education,
};

const NewMemberForm: React.FC = () => {
  const { user } = useAuth();
  const { addNotification } = useNotification();
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState(initialFormData);
  const [aadhaarError, setAadhaarError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [showRepairTool, setShowRepairTool] = useState(false);
  const [diagnosticInfo, setDiagnosticInfo] = useState<string | null>(null);

  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  // Hardened error extractor to kill [object Object] forever
  const getErrorMessage = (err: any): string => {
      if (!err) return "Unknown Error";
      if (typeof err === 'string') return err;

      // If it's a Supabase error object
      if (err.message && typeof err.message === 'string') return err.message;
      if (err.error_description && typeof err.error_description === 'string') return err.error_description;

      // Try deeper inspection
      if (err.details && typeof err.details === 'string') return err.details;
      if (err.hint && typeof err.hint === 'string') return err.hint;

      try {
          const str = JSON.stringify(err);
          if (str && str !== '{}') return str;
      } catch (e) {}

      return String(err);
  };

  useEffect(() => {
    return () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
        const file = e.target.files[0];
        setFormData(prev => ({ ...prev, memberImage: file }));
        if(imagePreview) URL.revokeObjectURL(imagePreview);
        setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = () => {
    if (imagePreview) URL.revokeObjectURL(imagePreview);
    setFormData(prev => ({ ...prev, memberImage: null }));
    setImagePreview(null);
    if(fileInputRef.current) fileInputRef.current.value = '';
  };

  const openCamera = async () => {
    try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        streamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;
        setIsCameraOpen(true);
    } catch (err) {
        console.error("Error accessing camera:", err);
        addNotification("Could not access camera. Please check browser permissions.", 'error');
    }
  };

  const closeCamera = () => {
    if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    setIsCameraOpen(false);
  };

  const handleCapture = () => {
    const canvas = document.createElement('canvas');
    if (videoRef.current) {
        canvas.width = videoRef.current.videoWidth;
        canvas.height = videoRef.current.videoHeight;
        const context = canvas.getContext('2d');
        if (context) {
            context.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
            canvas.toBlob((blob) => {
                if (blob) {
                    const file = new File([blob], "member-capture.jpg", { type: "image/jpeg" });
                    setFormData(prev => ({ ...prev, memberImage: file }));
                    if(imagePreview) URL.revokeObjectURL(imagePreview);
                    setImagePreview(URL.createObjectURL(file));
                    closeCamera();
                }
            }, 'image/jpeg');
        }
    }
  };

  const SQL_REPAIR_SCRIPT = `-- 🔱 SSK "GOD-LEVEL" MEMBERS TABLE REPAIR 🔱
-- Run this in your Supabase SQL Editor
ALTER TABLE public.members ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public Aadhaar Check" ON public.members;
CREATE POLICY "Public Aadhaar Check" ON public.members FOR SELECT TO authenticated USING ( true );
GRANT ALL ON public.members TO authenticated;`;

  const handleStep1Next = async () => {
    setAadhaarError('');
    setShowRepairTool(false);

    if (!formData.aadhaar || !/^\d{12}$/.test(formData.aadhaar)) {
      setAadhaarError('Please enter a valid 12-digit Aadhaar number.');
      return;
    }

    setIsValidating(true);
    try {
        const { data, error } = await supabase
          .from('members')
          .select('id')
          .eq('aadhaar', formData.aadhaar)
          .maybeSingle();

        if (error) {
            const errMsg = getErrorMessage(error);
            console.error("Duplicate Check Fault:", error);

            // Explicit check for permission/RLS errors
            if (errMsg.toLowerCase().includes("permission denied") || errMsg.toLowerCase().includes("not found") || errMsg.toLowerCase().includes("row-level security")) {
                setShowRepairTool(true);
                setDiagnosticInfo(`Database Restriction Detected: Your account is being blocked by Row-Level Security (RLS). You cannot check for duplicates until the repair script is run.`);
            }

            setAadhaarError(`Registry Connection Fault: ${errMsg}`);
            return;
        }

        if (data) {
          setAadhaarError('This identity node (Aadhaar) is already registered in the master registry.');
        } else {
          setStep(2);
        }
    } catch (e: any) {
        const errMsg = getErrorMessage(e);
        setAadhaarError(`System Connection Fault: ${errMsg}`);
    } finally {
        setIsValidating(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!user || !user.organisationId) {
