                await refreshProfile();
            }

            try {
                const { data, error } = await supabase
                    .from('members')
                    .select('*')
                    .eq('volunteer_id', user.id);

                if (error) {
                    const errMsg = getErrorMessage(error);
                    console.error("Submission Registry Error Details:", error);
                    addNotification(`Registry Sync Fault: ${errMsg}`, 'error');
                } else if (data) {
                    setMySubmissions(data);
                }
            } catch (err: any) {
                const errMsg = getErrorMessage(err);
                addNotification(`Critical System Error: ${errMsg}`, 'error');
