      setEditingOrg({ 
        ...org, 
        email: profile?.email || '',
        newPassword: ''
      });
      setShowEditPassword(false);
      setIsModalOpen(true);
    } catch (err) {
      console.error("Error fetching org email:", err);
      setEditingOrg({ ...org, email: '', newPassword: '' });
      setIsModalOpen(true);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateOrganisation = async () => {
    if (!editingOrg) return;
    setIsSubmitting(true);

    try {
      // 1. Update Organisations Table
      const { error: orgError } = await supabase.from('organisations').update({
          name: editingOrg.name, 
          mobile: editingOrg.mobile,
          secretary_name: editingOrg.secretary_name, 
          status: editingOrg.status
      }).eq('id', editingOrg.id);

      if (orgError) throw orgError;

      // 2. Update Profiles Table (Sync Name/Mobile/Email)
      const { error: profileError } = await supabase.from('profiles').update({
          name: editingOrg.secretary_name,
          mobile: editingOrg.mobile,
          email: editingOrg.email,
          status: editingOrg.status
      }).eq('organisation_id', editingOrg.id).eq('role', 'Organisation');

      if (profileError) {
          console.warn("Profile sync partially failed:", profileError);
      }

      // Note: Updating Email and Password in Supabase Auth requires Admin API (service_role).
      // Since we are using the public client, we provide the UI, but actual Auth credential 
      // updates for *other* users often require the Auth Admin dashboard or a backend function.
      if (editingOrg.newPassword) {
          addNotification("Auth password update requires Admin API privileges. Profile metadata synced.", "info");
      }

      addNotification(`Entity parameters synchronized.`, 'success');
      fetchOrganisations();
      setIsModalOpen(false);
    } catch (err: any) {
