    const { addNotification } = useNotification();

    // Selection State
    const [selectedOrgId, setSelectedOrgId] = useState<string>('');
    const [selectedVolunteerId, setSelectedVolunteerId] = useState<string>('');
    const [reportMode, setReportMode] = useState<ReportMode>('all');
    const [searchQuery, setSearchQuery] = useState('');
    const [dateRange, setDateRange] = useState({ start: '', end: '' });

    // Edit State
    const [editingMember, setEditingMember] = useState<Member | null>(null);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [isUpdating, setIsUpdating] = useState(false);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [membersRes, orgsRes, volsRes] = await Promise.all([
                supabase.from('members').select('*').order('submission_date', { ascending: false }),
                supabase.from('organisations').select('*').order('name'),
                supabase.from('profiles').select('*').eq('role', Role.Volunteer)
            ]);

            if (membersRes.data) setMembers(membersRes.data);
            if (orgsRes.data) setOrganisations(orgsRes.data);
            if (volsRes.data) setVolunteers(volsRes.data);
        } catch (err) {
            addNotification("Failed to fetch global registry data.", "error");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const filteredMembers = useMemo(() => {
        return members.filter(m => {
            const matchOrg = !selectedOrgId || m.organisation_id === selectedOrgId;
            const matchVol = !selectedVolunteerId || m.volunteer_id === selectedVolunteerId;
            const matchSearch = !searchQuery || 
                m.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                m.surname.toLowerCase().includes(searchQuery.toLowerCase()) ||
                m.mobile.includes(searchQuery) ||
                m.aadhaar.includes(searchQuery);

            const matchDate = (!dateRange.start || new Date(m.submission_date) >= new Date(dateRange.start)) &&
                              (!dateRange.end || new Date(m.submission_date) <= new Date(dateRange.end));

            return matchOrg && matchVol && matchSearch && matchDate;
        });
    }, [members, selectedOrgId, selectedVolunteerId, searchQuery, dateRange]);

    // Grouping for "Data Entry" mode
    const groupedByDate = useMemo(() => {
        const groups: Record<string, number> = {};
        filteredMembers.forEach(m => {
            const date = m.submission_date.split('T')[0];
            groups[date] = (groups[date] || 0) + 1;
        });
        return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
    }, [filteredMembers]);

    // Grouping for "Volunteer" mode
    const groupedByVolunteer = useMemo(() => {
        const groups: Record<string, number> = {};
        filteredMembers.forEach(m => {
            groups[m.volunteer_id] = (groups[m.volunteer_id] || 0) + 1;
        });
        return Object.entries(groups)
            .map(([id, count]) => {
                const vol = volunteers.find(v => v.id === id);
                return {
                    id,
                    count,
                    name: vol?.name || 'Unknown Agent',
                    org: organisations.find(o => o.id === vol?.organisationId)?.name || 'Unknown Org'
                };
            })
            .sort((a, b) => b.count - a.count);
    }, [filteredMembers, volunteers, organisations]);

    const activeVolunteers = useMemo(() => {
        if (!selectedOrgId) return volunteers;
        return volunteers.filter(v => v.organisationId === selectedOrgId);
    }, [selectedOrgId, volunteers]);

    const handleEditMember = (member: Member) => {
        setEditingMember({ ...member });
        setIsEditModalOpen(true);
    };

    const handleUpdateMember = async () => {
        if (!editingMember) return;
        setIsUpdating(true);
        try {
            const { error } = await supabase
                .from('members')
                .update({
                    name: editingMember.name,
                    surname: editingMember.surname,
                    mobile: editingMember.mobile,
                    father_name: editingMember.father_name,
                    dob: editingMember.dob,
                    gender: editingMember.gender,
                    pincode: editingMember.pincode,
                    address: editingMember.address,
                    occupation: editingMember.occupation,
                    support_need: editingMember.support_need
                })
                .eq('id', editingMember.id);

            if (error) throw error;

            addNotification("Member record successfully updated in the master registry.", "success");
            setIsEditModalOpen(false);
            fetchData();
        } catch (err: any) {
            addNotification(`Update failed: ${err.message}`, "error");
        } finally {
            setIsUpdating(false);
        }
    };

    const handleDownload = () => {
        const headers = ['Aadhaar', 'Name', 'Surname', 'Mobile', 'Org', 'Volunteer', 'Date', 'Occupation', 'Support'];
        const rows = filteredMembers.map(m => [
            m.aadhaar,
            m.name,
            m.surname,
            m.mobile,
            organisations.find(o => o.id === m.organisation_id)?.name || 'N/A',
            volunteers.find(v => v.id === m.volunteer_id)?.name || 'N/A',
            m.submission_date,
            m.occupation,
            m.support_need
        ]);

        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.setAttribute("href", url);
        link.setAttribute("download", `SSK_Master_Report_${new Date().toISOString().split('T')[0]}.csv`);
        link.click();
        addNotification("Full dataset exported successfully.", "success");
    };

    return (
        <DashboardLayout title="Master Registry Intelligence">
            <div className="space-y-8">
                {/* Global Stats Bar */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <Card className="bg-orange-500/5 border-orange-500/10 flex items-center justify-between p-6">
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-orange-500/60 mb-1">Total Members</p>
                            <p className="text-3xl font-black text-white">{members.length}</p>
                        </div>
                        <UserCheck className="text-orange-500/30" size={32} />
                    </Card>
                    <Card className="bg-blue-500/5 border-blue-500/10 flex items-center justify-between p-6">
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-blue-500/60 mb-1">Active Sectors</p>
                            <p className="text-3xl font-black text-white">{organisations.length}</p>
                        </div>
                        <Building2 className="text-blue-500/30" size={32} />
                    </Card>
                    <Card className="bg-purple-500/5 border-purple-500/10 flex items-center justify-between p-6">
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-purple-500/60 mb-1">Field Agents</p>
                            <p className="text-3xl font-black text-white">{volunteers.length}</p>
                        </div>
                        <Users className="text-purple-500/30" size={32} />
                    </Card>
                    <Card className="bg-green-500/5 border-green-500/10 flex items-center justify-between p-6">
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-green-500/60 mb-1">Target Filter</p>
                            <p className="text-3xl font-black text-white">{filteredMembers.length}</p>
                        </div>
                        <FileSpreadsheet className="text-green-500/30" size={32} />
                    </Card>
                </div>

                {/* Mode Selector */}
                <div className="flex flex-wrap gap-4 p-2 bg-gray-900/50 border border-white/5 rounded-3xl w-fit">
                    <button 
                        onClick={() => setReportMode('all')}
                        className={`px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all ${reportMode === 'all' ? 'bg-orange-600 text-white shadow-xl shadow-orange-900/20' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                        <LayoutGrid size={14} className="inline mr-2 -mt-0.5" /> All Data
                    </button>
                    <button 
                        onClick={() => setReportMode('entry')}
                        className={`px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all ${reportMode === 'entry' ? 'bg-orange-600 text-white shadow-xl shadow-orange-900/20' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                        <Clock size={14} className="inline mr-2 -mt-0.5" /> Data Entry
                    </button>
                    <button 
                        onClick={() => setReportMode('volunteer')}
                        className={`px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all ${reportMode === 'volunteer' ? 'bg-orange-600 text-white shadow-xl shadow-orange-900/20' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                        <Users size={14} className="inline mr-2 -mt-0.5" /> Data by Volunteer
                    </button>
                </div>

                <div className="grid grid-cols-1 xl:grid-cols-4 gap-8">
                    {/* Hierarchical Drill-down (Left Sidebar) */}
                    <div className="xl:col-span-1 space-y-6">
                        <Card className="bg-[#050505] border-white/5">
                            <div className="flex items-center justify-between mb-8">
                                <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-500">Organisation Node</h3>
                                <RefreshCw 
                                    size={14} 
                                    className={`text-gray-600 cursor-pointer hover:text-orange-500 transition-colors ${loading ? 'animate-spin' : ''}`}
                                    onClick={fetchData}
                                />
                            </div>
                            <div className="space-y-2 max-h-[50vh] overflow-y-auto custom-scrollbar pr-2">
                                <button 
                                    onClick={() => { setSelectedOrgId(''); setSelectedVolunteerId(''); }}
                                    className={`w-full text-left p-4 rounded-2xl border transition-all flex items-center justify-between group ${!selectedOrgId ? 'bg-orange-600/10 border-orange-500/30 text-orange-500' : 'bg-white/5 border-transparent text-gray-400 hover:bg-white/10'}`}
                                >
                                    <div className="flex items-center gap-3">
                                        <LayoutGrid size={16} />
                                        <span className="text-xs font-bold uppercase tracking-wider">Show All Nodes</span>
                                    </div>
                                    <ChevronRight size={14} className={!selectedOrgId ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'} />
                                </button>
                                {organisations.map(org => (
                                    <button 
                                        key={org.id}
                                        onClick={() => { setSelectedOrgId(org.id); setSelectedVolunteerId(''); }}
                                        className={`w-full text-left p-4 rounded-2xl border transition-all flex items-center justify-between group ${selectedOrgId === org.id ? 'bg-orange-600/10 border-orange-500/30 text-orange-500' : 'bg-white/5 border-transparent text-gray-400 hover:bg-white/10'}`}
                                    >
                                        <div className="flex items-center gap-3">
                                            <Building2 size={16} />
                                            <span className="text-xs font-bold uppercase tracking-wider truncate max-w-[150px]">{org.name}</span>
                                        </div>
                                        <ChevronRight size={14} className={selectedOrgId === org.id ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'} />
                                    </button>
                                ))}
                            </div>
                        </Card>

                        <Card className="bg-[#050505] border-white/5 animate-in slide-in-from-left-4">
                            <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-500 mb-6">Agent Drill-down</h3>
                            <Select 
                                value={selectedVolunteerId} 
                                onChange={(e) => setSelectedVolunteerId(e.target.value)}
                                className="bg-black/60 border-gray-800"
                            >
                                <option value="">All Field Operators</option>
                                {activeVolunteers.map(v => (
                                    <option key={v.id} value={v.id}>{v.name} ({organisations.find(o => o.id === v.organisationId)?.name})</option>
                                ))}
                            </Select>
                            <p className="mt-4 text-[9px] text-gray-600 font-bold uppercase text-center tracking-widest">
                                {selectedOrgId ? 'Filtering agents for selected node' : 'Scanning all field agents'}
                            </p>
                        </Card>
                    </div>

                    {/* Main Content Area */}
                    <div className="xl:col-span-3 space-y-6">
                        <Card title="Registry Master View">
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10 pb-10 border-b border-white/5">
                                <div className="md:col-span-1">
                                    <Input 
                                        label="UPLINK SEARCH" 
                                        placeholder="Name, Phone or Aadhaar..."
                                        value={searchQuery}
                                        onChange={(e) => setSearchQuery(e.target.value)}
                                        icon={<Search size={16} />}
                                        className="bg-black/60"
                                    />
                                </div>
                                <Input label="INIT DATE" type="date" value={dateRange.start} onChange={(e) => setDateRange(prev => ({ ...prev, start: e.target.value }))} className="bg-black/60" />
                                <Input label="END DATE" type="date" value={dateRange.end} onChange={(e) => setDateRange(prev => ({ ...prev, end: e.target.value }))} className="bg-black/60" />
                            </div>

                            <div className="flex items-center justify-between mb-10">
                                <div className="px-6 py-2 bg-white/5 border border-white/10 rounded-full">
                                    <span className="text-[10px] font-black text-orange-500 uppercase tracking-[0.3em]">Filtered: {filteredMembers.length} records</span>
                                </div>
                                <Button onClick={handleDownload} className="flex items-center gap-2 px-10 py-4 text-[10px] font-black tracking-[0.2em] uppercase shadow-2xl">
                                    <FileSpreadsheet size={16} /> DOWNLOAD CSV
                                </Button>
                            </div>

                            {/* Mode Conditional Rendering */}
                            {reportMode === 'entry' ? (
                                <div className="space-y-4">
                                    {groupedByDate.map(([date, count]) => (
                                        <div key={date} className="flex items-center justify-between p-8 bg-white/[0.02] border border-white/5 rounded-[2rem] hover:border-orange-500/30 hover:bg-orange-500/[0.02] transition-all group">
                                            <div className="flex items-center gap-6">
                                                <div className="p-4 bg-orange-500/10 rounded-2xl text-orange-500 group-hover:scale-110 transition-transform">
                                                    <Calendar size={24} />
                                                </div>
                                                <div>
                                                    <p className="text-2xl font-black text-white font-mono tracking-tighter">{date}</p>
                                                    <p className="text-[10px] text-gray-500 uppercase tracking-widest font-black">Registry Window</p>
                                                </div>
                                            </div>
                                            <div className="text-right">
                                                <p className="text-4xl font-black text-orange-500">{count}</p>
                                                <p className="text-[10px] text-gray-600 uppercase tracking-widest font-black">Submissions</p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) : reportMode === 'volunteer' ? (
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    {groupedByVolunteer.map((vol) => (
                                        <div key={vol.id} className="p-10 bg-white/[0.02] border border-white/5 rounded-[3rem] hover:border-blue-500/30 hover:bg-blue-500/[0.02] transition-all group relative overflow-hidden">
                                            <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
                                                <Users size={80} />
                                            </div>
                                            <div className="flex justify-between items-start mb-8 relative z-10">
                                                <div className="p-5 bg-blue-500/10 rounded-3xl text-blue-500 group-hover:scale-110 transition-transform">
                                                    <UserIcon size={32} />
                                                </div>
                                                <div className="px-6 py-3 bg-black/80 rounded-2xl border border-white/10 shadow-2xl">
                                                    <span className="text-3xl font-black text-white">{vol.count}</span>
                                                </div>
                                            </div>
                                            <div className="relative z-10">
                                                <h4 className="text-2xl font-cinzel text-white mb-2 tracking-tight group-hover:text-blue-400 transition-colors">{vol.name}</h4>
                                                <div className="flex items-center gap-2 text-gray-500">
                                                    <Building2 size={12} />
                                                    <span className="text-[10px] font-black uppercase tracking-widest">{vol.org}</span>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <div className="overflow-x-auto">
                                    <table className="w-full text-left">
                                        <thead className="border-b border-gray-800">
                                            <tr>
                                                <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Identity Node</th>
                                                <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Node / Agent</th>
                                                <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Date</th>
                                                <th className="p-6"></th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {filteredMembers.map(m => (
                                                <tr key={m.id} className="group border-b border-gray-900/50 hover:bg-white/[0.03] transition-all">
                                                    <td className="p-6">
                                                        <div className="flex flex-col gap-1">
                                                            <span className="font-bold text-lg text-white group-hover:text-orange-500 transition-colors">{m.name} {m.surname}</span>
                                                            <div className="flex items-center gap-3">
                                                                <span className="text-[11px] text-gray-500 font-mono">{m.mobile}</span>
                                                                <span className="h-1 w-1 rounded-full bg-gray-700"></span>
                                                                <span className="text-[11px] text-gray-700 font-mono">{m.aadhaar}</span>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className="p-6">
                                                        <div className="flex flex-col">
                                                            <span className="text-[10px] font-black uppercase text-gray-400 tracking-wider">
                                                                {organisations.find(o => o.id === m.organisation_id)?.name}
                                                            </span>
                                                            <span className="text-[10px] text-gray-600 font-bold uppercase tracking-widest">
                                                                {volunteers.find(v => v.id === m.volunteer_id)?.name}
                                                            </span>
                                                        </div>
                                                    </td>
                                                    <td className="p-6">
                                                        <span className="text-[11px] text-gray-600 font-black uppercase tracking-[0.2em]">{m.submission_date.split('T')[0]}</span>
                                                    </td>
                                                    <td className="p-6 text-right">
                                                        <button 
                                                            onClick={() => handleEditMember(m)}
                                                            className="p-3 bg-white/5 rounded-xl border border-white/10 text-gray-500 hover:text-white hover:border-orange-500/50 hover:bg-orange-500/10 transition-all opacity-0 group-hover:opacity-100"
                                                        >
                                                            <Edit3 size={18} />
                                                        </button>
                                                    </td>
                                                </tr>
                                            ))}
                                            {filteredMembers.length === 0 && (
                                                <tr>
                                                    <td colSpan={4} className="text-center p-40 text-gray-800 uppercase tracking-[0.5em] font-black text-[11px]">
                                                        NO INTELLIGENCE DETECTED IN SECTOR
                                                    </td>
                                                </tr>
                                            )}
                                        </tbody>
                                    </table>
                                </div>
                            )}
                        </Card>
                    </div>
                </div>
            </div>

            {/* Member Edit Modal */}
            <Modal 
                isOpen={isEditModalOpen} 
                onClose={() => setIsEditModalOpen(false)} 
                title="Modify Registry Entry"
            >
                {editingMember && (
                    <div className="space-y-6 max-h-[80vh] overflow-y-auto custom-scrollbar p-2">
                        <div className="flex items-center gap-4 mb-8 p-6 bg-orange-500/5 border border-orange-500/20 rounded-3xl">
                             <div className="p-3 bg-orange-500/10 rounded-2xl text-orange-500">
                                <Edit3 size={24} />
                             </div>
                             <div>
                                <p className="text-[10px] font-black uppercase tracking-widest text-orange-500/60">Node Override</p>
                                <p className="text-sm font-bold text-white">ID: {editingMember.aadhaar}</p>
                             </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <Input 
                                label="GIVEN NAME" 
                                value={editingMember.name} 
                                onChange={(e) => setEditingMember({...editingMember, name: e.target.value})} 
                            />
                            <Input 
                                label="SURNAME" 
                                value={editingMember.surname} 
                                onChange={(e) => setEditingMember({...editingMember, surname: e.target.value})} 
                            />
                            <Input 
                                label="FATHER / GUARDIAN" 
                                value={editingMember.father_name} 
                                onChange={(e) => setEditingMember({...editingMember, father_name: e.target.value})} 
                            />
                            <Input 
                                label="MOBILE CONTACT" 
                                value={editingMember.mobile} 
                                onChange={(e) => setEditingMember({...editingMember, mobile: e.target.value})} 
                            />
                            <Input 
                                label="DATE OF BIRTH" 
                                type="date"
                                value={editingMember.dob} 
                                onChange={(e) => setEditingMember({...editingMember, dob: e.target.value})} 
                            />
                            <Select 
                                label="GENDER" 
                                value={editingMember.gender} 
                                onChange={(e) => setEditingMember({...editingMember, gender: e.target.value as Gender})}
                            >
                                {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
                            </Select>
                            <Input 
                                label="POSTAL PINCODE" 
                                value={editingMember.pincode} 
                                onChange={(e) => setEditingMember({...editingMember, pincode: e.target.value})} 
                            />
                            <div className="md:col-span-2">
                                <Input 
                                    label="ADDRESS" 
                                    value={editingMember.address} 
                                    onChange={(e) => setEditingMember({...editingMember, address: e.target.value})} 
                                />
                            </div>
                            <Select 
                                label="OCCUPATION" 
                                value={editingMember.occupation} 
                                onChange={(e) => setEditingMember({...editingMember, occupation: e.target.value as Occupation})}
                            >
                                {Object.values(Occupation).map(o => <option key={o} value={o}>{o}</option>)}
                            </Select>
                            <Select 
                                label="SUPPORT NEED" 
                                value={editingMember.support_need} 
                                onChange={(e) => setEditingMember({...editingMember, support_need: e.target.value as SupportNeed})}
                            >
                                {Object.values(SupportNeed).map(s => <option key={s} value={s}>{s}</option>)}
                            </Select>
                        </div>

                        <div className="flex justify-end gap-4 pt-10 border-t border-white/5 mt-8 sticky bottom-0 bg-gray-900 pb-2">
                            <Button variant="secondary" onClick={() => setIsEditModalOpen(false)} className="px-8 py-4 text-[10px] font-black uppercase tracking-widest">Cancel</Button>
                            <Button 
                                onClick={handleUpdateMember} 
                                disabled={isUpdating}
                                className="px-10 py-4 text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-2xl"
                            >
                                {isUpdating ? <RefreshCw className="animate-spin" size={16} /> : <Save size={16} />}
                                {isUpdating ? 'Synchronizing...' : 'Commit Changes'}
                            </Button>
                        </div>
                    </div>
                )}
            </Modal>
        </DashboardLayout>
    );
};

