  // Password UI State
  const [showPassword, setShowPassword] = useState(false);
  const [showEditPassword, setShowEditPassword] = useState(false);
  const [showEditPasswordReveal, setShowEditPasswordReveal] = useState(false);

  const { addNotification } = useNotification();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrg, setEditingOrg] = useState<(Organisation & { email?: string, newPassword?: string }) | null>(null);

  const fetchOrganisations = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('organisations').select('*').order('name');
      if (error) {
        addNotification(`Registry sync failed: ${error.message}`, 'error');
      } else {
        setOrganisations(data || []);
      }
    } catch (err: any) {
      addNotification(`Registry sync failed: ${err?.message || 'Unknown sync error'}`, 'error');
    }
    setLoading(false);
  }, [addNotification]);

  useEffect(() => {
    fetchOrganisations();
  }, [fetchOrganisations]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewOrg(prev => ({ ...prev, [name]: value }));
  };

  const handleAddOrganisation = async () => {
    const email = newOrg.email.trim().toLowerCase();
    const password = newOrg.password;
    const name = newOrg.name.trim();
    const mobile = newOrg.mobile.trim();
    const secretaryName = newOrg.secretaryName.trim();

    if (!email || !password || !name || !mobile || !secretaryName) {
        addNotification("Authorization parameters missing.", 'error');
        return;
    }

    setIsSubmitting(true);
    setShowRepairTool(false);
    let createdOrgId: string | null = null;

    try {
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ name, mobile, secretary_name: secretaryName, status: 'Active' })
          .select().single();

        if (orgError) throw orgError;
        createdOrgId = orgData.id;

        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              name: secretaryName,
              role: 'Organisation',
              organisation_id: createdOrgId,
              mobile
            }
          }
        });

        if (authError) {
          if (createdOrgId) await supabase.from('organisations').delete().eq('id', createdOrgId);
          throw authError;
        }

        if (authData?.user?.id) {
            await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: secretaryName,
                email,
                role: 'Organisation',
                organisation_id: createdOrgId,
                mobile,
                status: 'Active'
            });
        }

        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
        addNotification('Entity successfully authorized.', 'success');
    } catch (err: any) {
        addNotification(err?.message || 'Handshake failed.', 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleEditClick = async (org: Organisation) => {
    setLoading(true);
    try {
      const { data: profile } = await supabase
        .from('profiles')
        .select('email')
        .eq('organisation_id', org.id)
        .eq('role', 'Organisation')
        .maybeSingle();

      setEditingOrg({ 
        ...org, 
        email: profile?.email || '',
        newPassword: ''
      });
      setShowEditPassword(false);
      setShowEditPasswordReveal(false);
      setIsModalOpen(true);
    } catch (err) {
      setEditingOrg({ ...org, email: '', newPassword: '' });
      setIsModalOpen(true);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateOrganisation = async () => {
    if (!editingOrg) return;
    setIsSubmitting(true);

    try {
      // 1. Update Organisations Table
      const { error: orgError } = await supabase.from('organisations').update({
          name: editingOrg.name, 
          mobile: editingOrg.mobile,
          secretary_name: editingOrg.secretary_name, 
          status: editingOrg.status
      }).eq('id', editingOrg.id);

      if (orgError) throw orgError;

      // 2. Update Profiles Table
      const { error: profileError } = await supabase.from('profiles').update({
          name: editingOrg.secretary_name,
          mobile: editingOrg.mobile,
          email: editingOrg.email,
          status: editingOrg.status
      }).eq('organisation_id', editingOrg.id).eq('role', 'Organisation');

      if (profileError) {
          console.warn("Profile sync error:", profileError);
      }

      if (editingOrg.newPassword) {
          addNotification("Auth update requires high-level privileges. Profile sync completed.", "info");
      } else {
          addNotification(`Entity parameters synchronized.`, 'success');
      }

      fetchOrganisations();
      setIsModalOpen(false);
    } catch (err: any) {
        addNotification(`Update failed: ${err.message}`, 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <DashboardLayout title="Entity Administration">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        <div className="lg:col-span-1 space-y-8">
          <Card title="Authorize New Entity" className="border-orange-500/10 relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                <ShieldCheck size={100} />
            </div>
            <div className="space-y-6 relative z-10">
              <Input label="Organisation Name" name="name" value={newOrg.name} onChange={handleInputChange} placeholder="Ex: SSK Bangalore" icon={<Building2 size={16} />} />
              <Input label="Primary Mobile" name="mobile" value={newOrg.mobile} onChange={handleInputChange} placeholder="91XXXXXXXX" icon={<Phone size={16} />} />
              <Input label="Secretary Name" name="secretaryName" value={newOrg.secretaryName} onChange={handleInputChange} icon={<User size={16} />} />
              <Input label="Access Email" name="email" type="email" value={newOrg.email} onChange={handleInputChange} placeholder="admin@entity.com" icon={<Mail size={16} />} />

              <div className="relative">
                <Input 
                  label="Security Key" 
                  name="password" 
                  type={showPassword ? "text" : "password"} 
                  value={newOrg.password} 
                  onChange={handleInputChange} 
                  placeholder="Min 6 characters" 
                  icon={<Lock size={16} />}
                />
                <button 
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-[34px] text-gray-500 hover:text-white transition-colors"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>

              <Button type="button" onClick={handleAddOrganisation} disabled={isSubmitting} className="w-full py-5 flex items-center justify-center gap-3 text-[11px] font-black uppercase tracking-widest shadow-xl">
                {isSubmitting ? <Loader2 className="animate-spin" size={18} /> : <UserPlus size={18} />}
                {isSubmitting ? 'ESTABLISHING...' : 'Establish Entity'}
              </Button>
            </div>
          </Card>

          {showRepairTool && (
            <Card className="border-red-500 border-2 bg-red-950/20 p-8 shadow-3xl animate-in fade-in slide-in-from-top-4 ring-4 ring-red-500/10">
                <div className="flex items-start gap-4 mb-6">
                    <div className="p-3 bg-red-500 rounded-2xl text-white shadow-lg">
                        <ShieldAlert size={28} className="animate-pulse" />
                    </div>
                    <div>
                        <h4 className="text-red-400 font-bold text-lg uppercase tracking-tight">LOGIC COLLISION</h4>
                        <p className="text-[10px] text-gray-400 uppercase tracking-widest font-black">Database Repair Required</p>
                    </div>
                </div>
                <Button 
                    className="w-full text-[11px] font-black uppercase tracking-widest flex items-center justify-center gap-2 py-4 bg-red-600 hover:bg-red-500 text-white shadow-2xl"
                    onClick={() => { navigator.clipboard.writeText(`-- FIX SCRIPT COPIED`); addNotification("Repair Script Copied.", "success"); }}
                >
                    <Copy size={16} /> Copy Fix Script
                </Button>
            </Card>
          )}
        </div>

        <div className="lg:col-span-2 space-y-6">
          <Card title="Active Entity Registry">
            <div className="flex justify-between items-center mb-10">
                <div className="flex items-center gap-4 text-gray-500">
                    <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
                        <Activity size={16} />
                    </div>
                    <span className="text-[10px] font-black uppercase tracking-widest">Master Registry Sync</span>
                </div>
                <button onClick={fetchOrganisations} className="p-3 bg-white/5 rounded-xl border border-white/5 hover:border-orange-500/40 text-gray-500 hover:text-white transition-all">
                    <RefreshCw size={16} className={loading ? 'animate-spin' : ''} />
                </button>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead className="border-b border-gray-800">
                        <tr>
                            <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Entity Identity</th>
                            <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black text-right">Verification</th>
                            <th className="p-6"></th>
                        </tr>
                    </thead>
                    <tbody>
                        {loading ? (
                             <tr><td colSpan={3} className="p-20 text-center animate-pulse uppercase tracking-[0.5em] text-[10px] text-gray-600 font-black">Synchronizing Registry...</td></tr>
                        ) : organisations.map(org => (
                        <tr key={org.id} className="group border-b border-gray-900/50 hover:bg-white/[0.02] transition-all">
                            <td className="p-6">
                                <div className="flex flex-col gap-1">
                                    <div className="flex items-center gap-3">
                                        <span className="font-bold text-white text-lg group-hover:text-orange-500 transition-colors">{org.name}</span>
                                        {org.status === 'Active' && <CheckCircle2 size={14} className="text-green-500/50" />}
                                    </div>
                                    <span className="text-[11px] text-gray-600 uppercase font-mono tracking-tighter">{org.secretary_name} • {org.mobile}</span>
                                </div>
                            </td>
                            <td className="p-6 text-right">
                                <span className={`px-4 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-full border ${ org.status === 'Active' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20' }`}>
                                    {org.status}
                                </span>
                            </td>
                            <td className="p-6 text-right">
                                <Button size="sm" variant="secondary" onClick={() => handleEditClick(org)} className="opacity-0 group-hover:opacity-100 transition-all scale-95 group-hover:scale-100">Modify Node</Button>
                            </td>
                        </tr>
                        ))}
                    </tbody>
                </table>
            </div>
          </Card>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Modify Entity Parameters">
          {editingOrg && (
            <div className="space-y-6 p-2 max-h-[80vh] overflow-y-auto custom-scrollbar">
                <div className="flex items-center gap-4 mb-6 p-5 bg-orange-500/5 border border-orange-500/10 rounded-2xl relative overflow-hidden">
                    <div className="p-3 bg-orange-500/10 rounded-xl text-orange-500">
                        <Settings size={20} />
                    </div>
                    <div className="relative z-10">
                        <p className="text-[10px] text-orange-500/60 font-black uppercase tracking-widest">Security Override</p>
                        <p className="text-sm font-bold text-white">Target: {editingOrg.name}</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="md:col-span-2">
                    <Input 
                      label="ORGANISATION NAME" 
                      name="name" 
                      value={editingOrg.name} 
                      onChange={(e) => setEditingOrg({...editingOrg, name: e.target.value})} 
                      icon={<Building2 size={16} />}
                    />
                  </div>

                  <Input 
                    label="SECRETARY NAME" 
                    name="secretary_name" 
                    value={editingOrg.secretary_name} 
                    onChange={(e) => setEditingOrg({...editingOrg, secretary_name: e.target.value})} 
                    icon={<User size={16} />}
                  />

                  <Input 
                    label="PRIMARY MOBILE" 
                    name="mobile" 
                    value={editingOrg.mobile} 
                    onChange={(e) => setEditingOrg({...editingOrg, mobile: e.target.value})} 
                    icon={<Phone size={16} />}
                  />

                  <div className="md:col-span-2">
                    <Input 
                      label="ACCESS EMAIL" 
                      name="email" 
                      type="email"
                      value={editingOrg.email || ''} 
                      onChange={(e) => setEditingOrg({...editingOrg, email: e.target.value})} 
                      icon={<Mail size={16} />}
                    />
                  </div>

                  <div className="md:col-span-2">
                    <div className="flex items-center justify-between mb-2">
                      <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Security Key Override</label>
                      <button 
                        type="button"
                        onClick={() => setShowEditPassword(!showEditPassword)}
                        className="text-[10px] font-black uppercase tracking-widest text-orange-500 hover:text-orange-400 transition-colors"
                      >
                        {showEditPassword ? "Cancel" : "Change Password"}
                      </button>
                    </div>
                    {showEditPassword && (
                      <div className="relative animate-in slide-in-from-top-2 fade-in">
                        <Input 
                          placeholder="New Security Key" 
                          type={showEditPasswordReveal ? "text" : "password"}
                          value={editingOrg.newPassword || ''}
                          onChange={(e) => setEditingOrg({...editingOrg, newPassword: e.target.value})}
                          icon={<Lock size={16} />}
                        />
                        <button 
                          type="button"
                          onClick={() => setShowEditPasswordReveal(!showEditPasswordReveal)}
                          className="absolute right-3 top-[10px] text-gray-500 hover:text-white transition-colors"
                        >
                          {showEditPasswordReveal ? <EyeOff size={18} /> : <Eye size={18} />}
                        </button>
                      </div>
                    )}
                  </div>

                  <div className="md:col-span-2">
                    <Select label="ACCESS STATUS" name="status" value={editingOrg.status} onChange={(e) => setEditingOrg({...editingOrg, status: e.target.value as any})}>
                        <option value="Active">Active / Operational</option>
                        <option value="Deactivated">Locked / Deactivated</option>
                    </Select>
                  </div>
                </div>

                <div className="flex justify-end gap-4 pt-10 sticky bottom-0 bg-gray-900 pb-2 border-t border-white/5 mt-6">
                    <Button type="button" variant="secondary" onClick={() => setIsModalOpen(false)} className="px-8 border-white/10 hover:bg-white/5 py-4 text-[10px] uppercase font-black tracking-widest">Cancel</Button>
                    <Button 
                      type="button" 
                      onClick={handleUpdateOrganisation} 
                      disabled={isSubmitting}
                      className="px-8 shadow-lg shadow-orange-950/20 py-4 text-[10px] uppercase font-black tracking-widest flex items-center gap-2"
                    >
                      {isSubmitting ? <Loader2 size={16} className="animate-spin" /> : <Zap size={16} />}
                      {isSubmitting ? "Syncing..." : "Commit Update"}
                    </Button>
                </div>
            </div>
          )}
      </Modal>
    </DashboardLayout>
  );
};

export default ManageOrganisations;

import React, { useState, useEffect, useMemo } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { supabase } from '../../supabase/client';
import { Member, Organisation, Role, User as VolunteerUser, Gender, Occupation, SupportNeed } from '../../types';
import { useNotification } from '../../context/NotificationContext';
import { 
  FileSpreadsheet, 
  Users, 
  Building2, 
  Calendar, 
  UserCheck, 
  ChevronRight,
  Search,
  LayoutGrid,
  RefreshCw,
  Clock,
  Edit3,
  Save,
  User as UserIcon,
  HardDrive
} from 'lucide-react';

type ReportMode = 'all' | 'entry' | 'volunteer';

const AdminReports: React.FC = () => {
    const [members, setMembers] = useState<Member[]>([]);
    const [organisations, setOrganisations] = useState<Organisation[]>([]);
    const [volunteers, setVolunteers] = useState<VolunteerUser[]>([]);
    const [loading, setLoading] = useState(true);
    const { addNotification } = useNotification();

    // Selection State
    const [selectedOrgId, setSelectedOrgId] = useState<string>('');
    const [selectedVolunteerId, setSelectedVolunteerId] = useState<string>('');
    const [reportMode, setReportMode] = useState<ReportMode>('all');
    const [searchQuery, setSearchQuery] = useState('');
    const [dateRange, setDateRange] = useState({ start: '', end: '' });

    // Edit State
    const [editingMember, setEditingMember] = useState<Member | null>(null);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [isUpdating, setIsUpdating] = useState(false);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [membersRes, orgsRes, volsRes] = await Promise.all([
                supabase.from('members').select('*').order('submission_date', { ascending: false }),
                supabase.from('organisations').select('*').order('name'),
                supabase.from('profiles').select('*').eq('role', Role.Volunteer)
            ]);

            if (membersRes.data) setMembers(membersRes.data);
            if (orgsRes.data) setOrganisations(orgsRes.data);
            if (volsRes.data) setVolunteers(volsRes.data);
        } catch (err) {
            addNotification("Master registry uplink failed.", "error");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    // Filter Logic
    const filteredMembers = useMemo(() => {
        return members.filter(m => {
            const matchOrg = !selectedOrgId || m.organisation_id === selectedOrgId;
            const matchVol = !selectedVolunteerId || m.volunteer_id === selectedVolunteerId;
            const matchSearch = !searchQuery || 
                m.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                m.surname.toLowerCase().includes(searchQuery.toLowerCase()) ||
                m.mobile.includes(searchQuery) ||
                m.aadhaar.includes(searchQuery);

            const matchDate = (!dateRange.start || new Date(m.submission_date) >= new Date(dateRange.start)) &&
                              (!dateRange.end || new Date(m.submission_date) <= new Date(dateRange.end));

            return matchOrg && matchVol && matchSearch && matchDate;
        });
    }, [members, selectedOrgId, selectedVolunteerId, searchQuery, dateRange]);

    // Summary Groups
    const groupedByDate = useMemo(() => {
        const groups: Record<string, number> = {};
        filteredMembers.forEach(m => {
            const date = m.submission_date.split('T')[0];
            groups[date] = (groups[date] || 0) + 1;
        });
        return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
    }, [filteredMembers]);

    const groupedByVolunteer = useMemo(() => {
        const groups: Record<string, number> = {};
        filteredMembers.forEach(m => {
            groups[m.volunteer_id] = (groups[m.volunteer_id] || 0) + 1;
        });
        return Object.entries(groups)
            .map(([id, count]) => {
                const vol = volunteers.find(v => v.id === id);
                return {
                    id,
                    count,
                    name: vol?.name || 'Deactivated Agent',
                    org: organisations.find(o => o.id === vol?.organisationId)?.name || 'Legacy Organisation'
                };
            })
            .sort((a, b) => b.count - a.count);
    }, [filteredMembers, volunteers, organisations]);

    const activeVolunteersInSelection = useMemo(() => {
        if (!selectedOrgId) return volunteers;
        return volunteers.filter(v => v.organisationId === selectedOrgId);
    }, [selectedOrgId, volunteers]);

    const handleEditMember = (member: Member) => {
        setEditingMember({ ...member });
        setIsEditModalOpen(true);
    };

    const handleUpdateMember = async () => {
        if (!editingMember) return;
        setIsUpdating(true);
        try {
            const { error } = await supabase
                .from('members')
                .update({
                    name: editingMember.name,
                    surname: editingMember.surname,
                    mobile: editingMember.mobile,
                    father_name: editingMember.father_name,
                    dob: editingMember.dob,
                    gender: editingMember.gender,
                    pincode: editingMember.pincode,
                    address: editingMember.address,
                    occupation: editingMember.occupation,
                    support_need: editingMember.support_need
                })
                .eq('id', editingMember.id);

            if (error) throw error;

            addNotification("Master record modified successfully.", "success");
            setIsEditModalOpen(false);
            fetchData();
        } catch (err: any) {
            addNotification(`Sync failed: ${err.message}`, "error");
        } finally {
            setIsUpdating(false);
        }
    };

    const handleDownload = () => {
        const headers = ['Aadhaar', 'Name', 'Surname', 'Mobile', 'Org Name', 'Entered By (Volunteer)', 'Date', 'Occupation', 'Support Need'];
        const rows = filteredMembers.map(m => [
            m.aadhaar,
            m.name,
            m.surname,
            m.mobile,
            organisations.find(o => o.id === m.organisation_id)?.name || 'N/A',
            volunteers.find(v => v.id === m.volunteer_id)?.name || 'Unknown Agent',
            m.submission_date,
            m.occupation,
            m.support_need
        ]);

        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.setAttribute("href", url);
        link.setAttribute("download", `SSK_MASTER_REPORT_${new Date().toISOString().split('T')[0]}.csv`);
        link.click();
        addNotification("CSV Transmission Complete.", "success");
    };

    return (
        <DashboardLayout title="Master Registry Intelligence">
            <div className="space-y-8">
                {/* Statistics Overview */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                    <Card className="bg-orange-500/5 border-orange-500/10 p-6 flex items-center justify-between">
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-orange-500/60 mb-1">Global Records</p>
                            <p className="text-3xl font-black text-white">{members.length}</p>
                        </div>
                        <HardDrive className="text-orange-500/20" size={32} />
                    </Card>
                    <Card className="bg-blue-500/5 border-blue-500/10 p-6 flex items-center justify-between">
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-blue-500/60 mb-1">Total Agents</p>
                            <p className="text-3xl font-black text-white">{volunteers.length}</p>
                        </div>
                        <Users className="text-blue-500/20" size={32} />
                    </Card>
                    <Card className="bg-purple-500/5 border-purple-500/10 p-6 flex items-center justify-between">
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-purple-500/60 mb-1">Reporting Sectors</p>
                            <p className="text-3xl font-black text-white">{organisations.length}</p>
                        </div>
                        <Building2 className="text-purple-500/20" size={32} />
                    </Card>
                    <Card className="bg-green-500/5 border-green-500/10 p-6 flex items-center justify-between">
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-green-500/60 mb-1">Filtered Matches</p>
                            <p className="text-3xl font-black text-white">{filteredMembers.length}</p>
                        </div>
                        <UserCheck className="text-green-500/20" size={32} />
                    </Card>
                </div>

                {/* View Mode Switching */}
                <div className="flex flex-wrap gap-4 p-2 bg-gray-950 border border-white/5 rounded-3xl w-fit">
                    <button 
                        onClick={() => setReportMode('all')}
                        className={`px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all flex items-center gap-2 ${reportMode === 'all' ? 'bg-orange-600 text-white shadow-xl' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                        <LayoutGrid size={14} /> All Data
                    </button>
                    <button 
                        onClick={() => setReportMode('entry')}
                        className={`px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all flex items-center gap-2 ${reportMode === 'entry' ? 'bg-orange-600 text-white shadow-xl' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                        <Clock size={14} /> Data Entry
                    </button>
                    <button 
                        onClick={() => setReportMode('volunteer')}
                        className={`px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all flex items-center gap-2 ${reportMode === 'volunteer' ? 'bg-orange-600 text-white shadow-xl' : 'text-gray-500 hover:text-gray-300'}`}
                    >
