        <DashboardLayout title="Intelligence Reports">
            <div className="space-y-8">
                {/* Master Filters Card */}
                <Card className="bg-gray-950 border-white/5 p-8 rounded-3xl">
                    <div className="flex items-center gap-3 mb-8">
                        <Filter className="text-orange-500" size={20} />
                        <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-400">Master Filter Terminal</h3>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                        <div>
                            <label className="block text-[10px] font-black text-gray-600 uppercase tracking-widest mb-2">Organisation Filter</label>
                            <Select 
                                value={selectedOrgId} 
                                onChange={(e) => { setSelectedOrgId(e.target.value); setSelectedVolunteerId(''); }}
                                className="bg-black border-gray-800"
                            >
                                <option value="">All Organisations</option>
                                {organisations.map(org => (
                                    <option key={org.id} value={org.id}>{org.name}</option>
                                ))}
                            </Select>
                        </div>

                        <div>
                            <label className="block text-[10px] font-black text-gray-600 uppercase tracking-widest mb-2">Volunteer Filter</label>
                            <Select 
                                value={selectedVolunteerId} 
                                onChange={(e) => setSelectedVolunteerId(e.target.value)}
                                className="bg-black border-gray-800"
                            >
                                <option value="">All Volunteers</option>
                                {availableVolunteers.map(v => (
                                    <option key={v.id} value={v.id}>{v.name}</option>
                                ))}
                            </Select>
                        </div>

                        <div className="lg:col-span-2">
                            <label className="block text-[10px] font-black text-gray-600 uppercase tracking-widest mb-2">Search Registry</label>
                            <Input 
                                placeholder="Search by Name, Mobile, or Aadhaar..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                icon={<Search size={16} />}
                                className="bg-black border-gray-800"
                            />
                        </div>
                    </div>
                </Card>

                {/* Data Grid Card */}
                <Card title="Global Member Registry">
                    <div className="flex justify-between items-center mb-10 border-b border-white/5 pb-6">
                        <div className="flex gap-10">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Active Records</span>
                                <span className="text-3xl font-black text-white">{filteredMembers.length}</span>
                            </div>
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Sector Filter</span>
                                <span className="text-xl font-bold text-orange-500 uppercase tracking-tight">
                                    {selectedOrgId ? organisations.find(o => o.id === selectedOrgId)?.name : 'All Entities'}
                                </span>
                            </div>
                        </div>
                        <div className="flex gap-4">
                            <button 
                                onClick={fetchData} 
                                className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:border-orange-500/40 text-gray-500 hover:text-white transition-all"
                            >
                                <RefreshCw size={18} className={loading ? 'animate-spin' : ''} />
                            </button>
                            <Button onClick={handleDownloadCSV} className="flex items-center gap-2 px-8 py-4 text-[10px] font-black tracking-widest uppercase shadow-2xl">
                                <FileSpreadsheet size={16} /> Export Master
                            </Button>
                        </div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="border-b border-gray-800">
                                <tr>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Member Identity</th>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Organisation</th>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Field Agent</th>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black text-right">Terminal Access</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-900/50">
                                {loading ? (
                                    <tr><td colSpan={4} className="p-20 text-center text-xs text-gray-600 font-black uppercase tracking-[0.5em] animate-pulse">Syncing Master Registry...</td></tr>
                                ) : filteredMembers.map(m => (
                                    <tr key={m.id} className="group hover:bg-white/[0.02] transition-all">
                                        <td className="p-6">
                                            <div className="flex flex-col gap-1">
                                                <div className="flex items-center gap-3">
                                                    <span className="font-bold text-white text-lg group-hover:text-orange-500 transition-colors">{m.name} {m.surname}</span>
                                                    {m.member_image_url && <ImageIcon size={14} className="text-blue-500/50" />}
