                        <div className="flex justify-end gap-4 pt-10 border-t border-white/5 mt-6 sticky bottom-0 bg-gray-900 pb-2 z-10">
                            <Button variant="secondary" onClick={() => setIsEditModalOpen(false)} className="px-8 py-4 text-[10px] font-black uppercase tracking-widest">Cancel</Button>
                            <Button 
                                onClick={handleUpdateMember} 
                                disabled={isUpdating}
