                            >
                                {isUpdating ? <RefreshCw className="animate-spin" size={16} /> : <Save size={16} />}
                                {isUpdating ? 'Synchronizing...' : 'Save Changes'}
                            </Button>
                        </div>
                    </div>
                )}
            </Modal>
        </DashboardLayout>
    );
};

