import React, { useState, useMemo, useEffect } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Modal from '../../components/ui/Modal';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../supabase/client';
import { Member, MemberStatus, Role, User as VolunteerUser, Gender, Occupation, SupportNeed } from '../../types';
import { useNotification } from '../../context/NotificationContext';
import { 
  FileSpreadsheet, 
  Filter, 
  Search, 
  Edit3, 
  CheckCircle2, 
  Clock, 
  User as UserIcon, 
  Image as ImageIcon, 
  ExternalLink,
  Save,
  RefreshCw,
  XCircle
} from 'lucide-react';

const OrganisationReports: React.FC = () => {
    const { user } = useAuth();
    const [myMembers, setMyMembers] = useState<Member[]>([]);
    const [myVolunteers, setMyVolunteers] = useState<VolunteerUser[]>([]);
    const [loading, setLoading] = useState(true);
    const { addNotification } = useNotification();

    // Modal & Edit State
    const [editingMember, setEditingMember] = useState<Member | null>(null);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [isUpdating, setIsUpdating] = useState(false);

    const fetchData = async () => {
        if (!user?.organisationId) return;
        setLoading(true);
        try {
            const [membersRes, volsRes] = await Promise.all([
                supabase.from('members').select('*').eq('organisation_id', user.organisationId).order('submission_date', { ascending: false }),
                supabase.from('profiles').select('*').eq('role', Role.Volunteer).eq('organisation_id', user.organisationId)
            ]);
            if (membersRes.data) setMyMembers(membersRes.data);
            if (volsRes.data) setMyVolunteers(volsRes.data);
        } catch (error) {
            addNotification("Failed to synchronize organization records.", "error");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, [user]);

    const [filters, setFilters] = useState({
        startDate: '',
        endDate: '',
        volunteerId: '',
        search: '',
        status: ''
    });

    const filteredMembers = useMemo(() => {
        return myMembers.filter(member => {
            const submissionDate = new Date(member.submission_date);
            const startDate = filters.startDate ? new Date(filters.startDate) : null;
            const endDate = filters.endDate ? new Date(filters.endDate) : null;

            if (endDate) endDate.setHours(23, 59, 59, 999);

            if (startDate && submissionDate < startDate) return false;
            if (endDate && submissionDate > endDate) return false;
            if (filters.volunteerId && member.volunteer_id !== filters.volunteerId) return false;
            if (filters.status && member.status !== filters.status) return false;

            if (filters.search) {
                const term = filters.search.toLowerCase();
                return member.name.toLowerCase().includes(term) || 
                       member.surname.toLowerCase().includes(term) || 
                       member.mobile.includes(term) ||
                       member.aadhaar.includes(term);
            }

            return true;
        });
    }, [myMembers, filters]);

    const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
    };

    const handleVerify = async (member: Member) => {
        const newStatus = member.status === MemberStatus.Accepted ? MemberStatus.Pending : MemberStatus.Accepted;
        try {
            const { error } = await supabase
                .from('members')
                .update({ status: newStatus })
                .eq('id', member.id);

            if (error) throw error;
            addNotification(`Member ${newStatus === MemberStatus.Accepted ? 'Verified' : 'Moved to Pending'}.`, "success");
            fetchData();
        } catch (err: any) {
            addNotification(`Verification failed: ${err.message}`, "error");
        }
    };

    const handleEditClick = (member: Member) => {
        setEditingMember({ ...member });
        setIsEditModalOpen(true);
    };

    const handleUpdateMember = async () => {
        if (!editingMember) return;
        setIsUpdating(true);
        try {
            const { error } = await supabase
                .from('members')
                .update({
                    name: editingMember.name,
                    surname: editingMember.surname,
                    mobile: editingMember.mobile,
                    father_name: editingMember.father_name,
                    dob: editingMember.dob,
                    gender: editingMember.gender,
                    pincode: editingMember.pincode,
                    address: editingMember.address,
                    occupation: editingMember.occupation,
                    support_need: editingMember.support_need,
                    status: editingMember.status
                })
                .eq('id', editingMember.id);

            if (error) throw error;
            addNotification("Member profile synchronized successfully.", "success");
            setIsEditModalOpen(false);
            fetchData();
        } catch (err: any) {
            addNotification(`Sync failed: ${err.message}`, "error");
        } finally {
            setIsUpdating(false);
        }
    };

    const handleDownload = () => {
        const headers = ['Aadhaar', 'Name', 'Surname', 'Mobile', 'Volunteer', 'Date', 'Status'];
        const rows = filteredMembers.map(m => [
            m.aadhaar, m.name, m.surname, m.mobile,
            myVolunteers.find(v => v.id === m.volunteer_id)?.name || 'N/A',
            m.submission_date, m.status
        ]);
        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = `SSK_Report_${user?.organisationName}_${new Date().toISOString().split('T')[0]}.csv`;
        link.click();
    };

    return (
        <DashboardLayout title="Member Verification & Reports">
            <div className="space-y-8">
                {/* Filter Section */}
                <Card className="bg-gray-950 border-white/5">
                    <div className="flex items-center gap-2 mb-8 text-orange-500">
                        <Filter size={18} />
                        <h3 className="text-[10px] font-black uppercase tracking-[0.3em]">Query Intelligence</h3>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6">
                        <Input label="Search Registry" name="search" value={filters.search} onChange={handleFilterChange} placeholder="Name, Phone or ID..." icon={<Search size={14}/>} />
                        <Select label="Verification Status" name="status" value={filters.status} onChange={handleFilterChange}>
                            <option value="">All Records</option>
                            <option value={MemberStatus.Pending}>Pending Approval</option>
                            <option value={MemberStatus.Accepted}>Verified / Accepted</option>
                        </Select>
                        <Select label="Field Agent" name="volunteerId" value={filters.volunteerId} onChange={handleFilterChange}>
                            <option value="">All Operators</option>
                            {myVolunteers.map(vol => <option key={vol.id} value={vol.id}>{vol.name}</option>)}
                        </Select>
                        <Input label="From Date" type="date" name="startDate" value={filters.startDate} onChange={handleFilterChange} />
                        <Input label="To Date" type="date" name="endDate" value={filters.endDate} onChange={handleFilterChange} />
                    </div>

                    <div className="mt-10 pt-6 border-t border-white/5 flex justify-between items-center">
                        <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Active results: {filteredMembers.length} records</span>
                        <Button onClick={handleDownload} className="flex items-center gap-2 px-10 py-4 text-[10px] font-black uppercase tracking-widest shadow-2xl">
                            <FileSpreadsheet size={16} /> Export Dataset
                        </Button>
                    </div>
                </Card>

                {/* Member Table */}
                <Card title="Registry Master Table">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="border-b border-gray-800">
                                <tr>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Member Identity</th>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Field Agent</th>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black text-center">Status</th>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-900/50">
                                {loading ? (
                                    <tr><td colSpan={4} className="p-20 text-center animate-pulse text-[10px] uppercase tracking-[0.5em] text-gray-600 font-black">Scanning Node Registry...</td></tr>
                                ) : filteredMembers.map(member => (
                                    <tr key={member.id} className="group hover:bg-white/[0.02] transition-all">
                                        <td className="p-6">
                                            <div className="flex flex-col gap-1">
                                                <div className="flex items-center gap-3">
                                                    <span className="font-bold text-white text-lg group-hover:text-orange-500 transition-colors">{member.name} {member.surname}</span>
                                                    {member.member_image_url && <ImageIcon size={14} className="text-blue-500/50" />}
                                                </div>
                                                <div className="flex items-center gap-3 text-[11px] text-gray-600 font-mono">
                                                    <span>{member.mobile}</span>
                                                    <span className="h-1 w-1 rounded-full bg-gray-800"></span>
                                                    <span>{member.aadhaar.slice(-4).padStart(12, '•')}</span>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-6">
                                            <div className="flex flex-col">
                                                <span className="text-xs font-bold text-gray-400">{myVolunteers.find(v => v.id === member.volunteer_id)?.name || 'System Agent'}</span>
                                                <span className="text-[10px] text-gray-600 uppercase tracking-widest font-black mt-0.5">Enrollment Agent</span>
                                            </div>
                                        </td>
                                        <td className="p-6 text-center">
                                            <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-full border ${
                                                member.status === MemberStatus.Accepted 
                                                    ? 'bg-green-500/10 text-green-400 border-green-500/20' 
                                                    : 'bg-orange-500/10 text-orange-400 border-orange-500/20 animate-pulse'
                                            }`}>
                                                {member.status === MemberStatus.Accepted ? <CheckCircle2 size={12} /> : <Clock size={12} />}
                                                <span className="text-[10px] font-black uppercase tracking-widest">{member.status}</span>
                                            </div>
                                        </td>
                                        <td className="p-6 text-right">
                                            <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button 
                                                    onClick={() => handleVerify(member)}
                                                    className={`p-3 rounded-xl border transition-all ${
                                                        member.status === MemberStatus.Accepted 
                                                            ? 'bg-red-500/5 border-red-500/20 text-red-400 hover:bg-red-500/10' 
                                                            : 'bg-green-500/5 border-green-500/20 text-green-400 hover:bg-green-500/10'
                                                    }`}
                                                    title={member.status === MemberStatus.Accepted ? "Revoke Verification" : "Verify Member"}
                                                >
                                                    {member.status === MemberStatus.Accepted ? <XCircle size={18} /> : <CheckCircle2 size={18} />}
                                                </button>
                                                <button 
                                                    onClick={() => handleEditClick(member)}
                                                    className="p-3 bg-white/5 border border-white/10 rounded-xl text-gray-500 hover:text-white hover:border-orange-500/50 transition-all"
                                                    title="Modify Record"
                                                >
                                                    <Edit3 size={18} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                                {filteredMembers.length === 0 && !loading && (
                                    <tr><td colSpan={4} className="p-40 text-center text-[11px] text-gray-700 uppercase tracking-[0.5em] font-black">No intelligence detected in current window.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </Card>
            </div>

            {/* Edit Modal */}
            <Modal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} title="Registry Override Terminal">
                {editingMember && (
                    <div className="space-y-6 max-h-[85vh] overflow-y-auto custom-scrollbar p-2">
                        {/* Member Identity Preview */}
                        <div className="flex items-start gap-8 p-8 bg-orange-500/5 border border-orange-500/10 rounded-[2.5rem] relative overflow-hidden group/id">
                            <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none group-hover/id:opacity-10 transition-opacity">
                                <UserIcon size={120} strokeWidth={1} />
                            </div>
                            {editingMember.member_image_url ? (
                                <div className="relative h-40 w-40 rounded-[2rem] overflow-hidden border-2 border-white/10 shrink-0 shadow-2xl">
                                    <img src={editingMember.member_image_url} alt="Capture" className="w-full h-full object-cover" />
                                    <a href={editingMember.member_image_url} target="_blank" rel="noreferrer" className="absolute inset-0 bg-black/60 opacity-0 hover:opacity-100 flex items-center justify-center transition-opacity text-white">
                                        <ExternalLink size={24} />
                                    </a>
                                </div>
                            ) : (
                                <div className="h-40 w-40 rounded-[2rem] bg-gray-900 border-2 border-white/5 flex items-center justify-center text-gray-700 shrink-0">
                                    <ImageIcon size={48} />
                                </div>
                            )}
                            <div className="flex-1 space-y-4 relative z-10 pt-2">
                                <div>
                                    <p className="text-[10px] font-black text-orange-500 uppercase tracking-[0.4em] mb-1">Identity Node</p>
                                    <h4 className="text-3xl font-cinzel text-white leading-none">{editingMember.name} {editingMember.surname}</h4>
                                </div>
                                <div className="flex gap-4">
                                    <div className="px-5 py-2 bg-black/40 rounded-2xl border border-white/5">
                                        <span className="text-[10px] font-mono text-gray-400 uppercase tracking-widest">{editingMember.aadhaar}</span>
                                    </div>
                                    <div className="px-5 py-2 bg-black/40 rounded-2xl border border-white/5">
                                        <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Added By: {myVolunteers.find(v => v.id === editingMember.volunteer_id)?.name || 'System'}</span>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Editable Form */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <Input label="GIVEN NAME" value={editingMember.name} onChange={(e) => setEditingMember({...editingMember, name: e.target.value})} />
                            <Input label="SURNAME" value={editingMember.surname} onChange={(e) => setEditingMember({...editingMember, surname: e.target.value})} />
                            <Input label="FATHER NAME" value={editingMember.father_name} onChange={(e) => setEditingMember({...editingMember, father_name: e.target.value})} />
                            <Input label="MOBILE" value={editingMember.mobile} onChange={(e) => setEditingMember({...editingMember, mobile: e.target.value})} />
                            <Input label="DOB" type="date" value={editingMember.dob} onChange={(e) => setEditingMember({...editingMember, dob: e.target.value})} />
                            <Select label="GENDER" value={editingMember.gender} onChange={(e) => setEditingMember({...editingMember, gender: e.target.value as Gender})}>
                                {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
                            </Select>
                            <Input label="PINCODE" value={editingMember.pincode} onChange={(e) => setEditingMember({...editingMember, pincode: e.target.value})} />
                            <Select label="VERIFICATION STATUS" value={editingMember.status} onChange={(e) => setEditingMember({...editingMember, status: e.target.value as MemberStatus})}>
                                <option value={MemberStatus.Pending}>Pending Approval</option>
                                <option value={MemberStatus.Accepted}>Verified / Accepted</option>
                            </Select>
                            <div className="md:col-span-2">
                                <Input label="FULL ADDRESS" value={editingMember.address} onChange={(e) => setEditingMember({...editingMember, address: e.target.value})} />
                            </div>
                            <Select label="OCCUPATION" value={editingMember.occupation} onChange={(e) => setEditingMember({...editingMember, occupation: e.target.value as Occupation})}>
                                {Object.values(Occupation).map(o => <option key={o} value={o}>{o}</option>)}
                            </Select>
                            <Select label="SUPPORT NEED" value={editingMember.support_need} onChange={(e) => setEditingMember({...editingMember, support_need: e.target.value as SupportNeed})}>
                                {Object.values(SupportNeed).map(s => <option key={s} value={s}>{s}</option>)}
                            </Select>
                        </div>

                        {/* Modal Actions */}
                        <div className="flex justify-end gap-4 pt-10 border-t border-white/5 mt-8 sticky bottom-0 bg-gray-900 pb-2 z-10">
                            <Button variant="secondary" onClick={() => setIsEditModalOpen(false)} className="px-8 py-4 text-[10px] font-black uppercase tracking-widest">Abort</Button>
                            <Button 
                                onClick={handleUpdateMember} 
                                disabled={isUpdating}
                                className="px-12 py-4 text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-2xl"
                            >
                                {isUpdating ? <RefreshCw className="animate-spin" size={16} /> : <Save size={16} />}
                                {isUpdating ? 'SYNCHRONIZING...' : 'Commit Override'}
                            </Button>
                        </div>
                    </div>
                )}
            </Modal>
        </DashboardLayout>
    );
};

export default OrganisationReports;

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import Button from '../../components/ui/Button';
import { Gender, Occupation, SupportNeed, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useAuth } from '../../context/AuthContext';
import { useNotification } from '../../context/NotificationContext';
import { UploadCloud, Camera, ShieldAlert, Copy, ExternalLink, RefreshCw, Database, AlertTriangle, Zap, CheckCircle2, Loader2, User as UserIcon } from 'lucide-react';

const initialFormData = {
  aadhaar: '',
  mobile: '',
  name: '',
  surname: '',
  fatherName: '',
  dob: '',
  gender: Gender.Male,
  emergencyContact: '',
  pincode: '',
  address: '',
  memberImage: null as File | null,
  occupation: Occupation.Job,
  supportNeed: SupportNeed.Education,
};

const NewMemberForm: React.FC = () => {
  const { user } = useAuth();
  const { addNotification } = useNotification();
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState(initialFormData);
  const [aadhaarError, setAadhaarError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [showRepairTool, setShowRepairTool] = useState(false);
  const [diagnosticInfo, setDiagnosticInfo] = useState<string | null>(null);

  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const getErrorMessage = (err: any): string => {
      if (!err) return "Unknown System Error";
      if (typeof err === 'string') return err;
      const commonProps = ['message', 'error_description', 'details', 'hint', 'msg', 'error'];
      for (const prop of commonProps) {
          if (err[prop] && typeof err[prop] === 'string') return err[prop];
      }
      return "Database security policy failure";
  };

  useEffect(() => {
    return () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
        const file = e.target.files[0];
        setFormData(prev => ({ ...prev, memberImage: file }));
        if(imagePreview) URL.revokeObjectURL(imagePreview);
        setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = () => {
    if (imagePreview) URL.revokeObjectURL(imagePreview);
    setFormData(prev => ({ ...prev, memberImage: null }));
    setImagePreview(null);
    if(fileInputRef.current) fileInputRef.current.value = '';
  };

  const openCamera = async () => {
    try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });
        streamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;
        setIsCameraOpen(true);
    } catch (err) {
        addNotification("Camera access denied.", 'error');
    }
  };

  const closeCamera = () => {
    if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    setIsCameraOpen(false);
  };

  const handleCapture = () => {
    const canvas = document.createElement('canvas');
    if (videoRef.current) {
        canvas.width = videoRef.current.videoWidth;
        canvas.height = videoRef.current.videoHeight;
        const context = canvas.getContext('2d');
        if (context) {
            context.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
            canvas.toBlob((blob) => {
                if (blob) {
                    const file = new File([blob], "capture.jpg", { type: "image/jpeg" });
                    setFormData(prev => ({ ...prev, memberImage: file }));
                    if(imagePreview) URL.revokeObjectURL(imagePreview);
                    setImagePreview(URL.createObjectURL(file));
                    closeCamera();
                }
            }, 'image/jpeg');
        }
    }
  };

  const handleStep1Next = async () => {
    setAadhaarError('');
    if (!formData.aadhaar || !/^\d{12}$/.test(formData.aadhaar)) {
      setAadhaarError('Valid 12-digit Aadhaar required.');
      return;
    }
    setIsValidating(true);
    try {
        const { data, error } = await supabase.from('members').select('id').eq('aadhaar', formData.aadhaar).maybeSingle();
        if (error) throw error;
        if (data) setAadhaarError('Aadhaar already registered.');
        else setStep(2);
    } catch (e: any) {
        setAadhaarError(`Registry Fault: ${getErrorMessage(e)}`);
    } finally {
        setIsValidating(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!user?.organisationId) return;
      setIsSubmitting(true);
      try {
          let imageUrl = '';
          if (formData.memberImage) {
              const fileName = `${uuidv4()}.jpg`;
              const { data: uploadData, error: uploadError } = await supabase.storage.from('member-images').upload(fileName, formData.memberImage);
              if(uploadError) throw uploadError;
              imageUrl = supabase.storage.from('member-images').getPublicUrl(uploadData.path).data.publicUrl;
          }
          const { error } = await supabase.from('members').insert({
              aadhaar: formData.aadhaar,
              mobile: formData.mobile,
              name: formData.name,
              surname: formData.surname,
              father_name: formData.fatherName,
              dob: formData.dob,
              gender: formData.gender,
              emergency_contact: formData.emergencyContact,
              pincode: formData.pincode,
              address: formData.address,
              member_image_url: imageUrl,
              occupation: formData.occupation,
              support_need: formData.supportNeed,
              volunteer_id: user.id,
              organisation_id: user.organisationId,
              status: 'Pending'
          });
          if (error) throw error;
          addNotification("Enrollment Complete.", 'success');
          setFormData(initialFormData);
          setImagePreview(null);
          setStep(1);
      } catch (err: any) {
          addNotification(`Error: ${getErrorMessage(err)}`, 'error');
      } finally {
          setIsSubmitting(false);
      }
  };

  return (
    <DashboardLayout title="Member Enrollment Terminal">
      <div className="w-full max-w-5xl mx-auto space-y-8 pb-20">
          {/* Operator Identity Banner */}
          <div className="bg-orange-600/10 border border-orange-500/20 rounded-3xl p-6 flex items-center justify-between">
              <div className="flex items-center gap-4">
                  <div className="p-3 bg-orange-600/20 rounded-2xl text-orange-500">
                      <UserIcon size={24} />
                  </div>
                  <div>
                      <p className="text-[10px] font-black uppercase tracking-[0.3em] text-orange-500/60 leading-none mb-1">Authenticated Operator</p>
                      <h4 className="text-xl font-bold text-white uppercase tracking-tight">{user?.name}</h4>
                  </div>
              </div>
              <div className="text-right hidden md:block">
                  <p className="text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1">Entity sector</p>
                  <p className="text-xs font-bold text-gray-400 uppercase">{user?.organisationName}</p>
              </div>
          </div>

          <div className="relative pt-6">
              <div className="flex justify-between items-center mb-6 relative z-10 px-2">
                  {[1, 2, 3].map(s => (
                      <div key={s} className={`flex flex-col items-center gap-2 transition-all duration-500 ${step >= s ? 'scale-110' : 'opacity-40'}`}>
                          <div className={`h-12 w-12 rounded-full border-2 flex items-center justify-center transition-all ${step >= s ? 'bg-orange-500 border-orange-400' : 'bg-gray-900 border-gray-800'}`}>
                              <span className="text-sm font-black text-white">{s}</span>
                          </div>
                      </div>
                  ))}
              </div>
              <div className="absolute top-[3.2rem] left-0 w-full h-0.5 bg-gray-900 rounded-full overflow-hidden">
                  <div className="h-full bg-orange-600 transition-all duration-700 shadow-[0_0_10px_rgba(255,100,0,0.5)]" style={{ width: `${((step - 1) / 2) * 100}%` }}></div>
              </div>
          </div>

          <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
            {step === 1 && (
                <div className="space-y-8">
                    <Card title="Registry Validation" className="bg-[#050505]">
                        <div className="space-y-6">
                            <Input label="AADHAAR ID" name="aadhaar" value={formData.aadhaar} onChange={handleChange} maxLength={12} className="text-lg font-mono tracking-[0.2em]" />
                            <Input label="MOBILE" name="mobile" type="tel" value={formData.mobile} onChange={handleChange} maxLength={10} />
                            {aadhaarError && <p className="text-xs text-red-400 font-bold uppercase tracking-widest">{aadhaarError}</p>}
                        </div>
                        <div className="mt-8 flex justify-end">
                            <Button onClick={handleStep1Next} disabled={isValidating} className="py-4 px-12 text-[10px] font-black uppercase tracking-widest">
                                {isValidating ? 'Validating...' : 'Next Step'}
                            </Button>
                        </div>
                    </Card>
                </div>
            )}
            {step === 2 && (
                <Card title="Identity Profile" className="bg-[#050505]">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <Input label="GIVEN NAME" name="name" value={formData.name} onChange={handleChange} />
                        <Input label="SURNAME" name="surname" value={formData.surname} onChange={handleChange} />
                        <Input label="FATHER NAME" name="fatherName" value={formData.fatherName} onChange={handleChange} />
