                            name="search" 
                            value={filters.search} 
                            onChange={handleFilterChange} 
                            placeholder="Name or Phone..."
                        />
                        <Select label="Status Filter" name="status" value={filters.status} onChange={handleFilterChange}>
                            <option value="">All Status</option>
                            <option value={MemberStatus.Pending}>Pending Verification</option>
                            <option value={MemberStatus.Accepted}>Verified / Accepted</option>
                        </Select>
                        <Select label="Enrollment Agent" name="agentId" value={filters.agentId} onChange={handleFilterChange}>
                            <option value="">All Agents</option>
                            {allOrgProfiles.map(p => <option key={p.id} value={p.id}>{p.name} ({p.role})</option>)}
                        </Select>
                        <div className="flex items-end">
                            <Button onClick={fetchData} variant="secondary" className="w-full flex items-center justify-center gap-2 py-3 uppercase text-[10px] font-black tracking-widest">
                                <RefreshCw size={14} className={loading ? 'animate-spin' : ''} /> Sync Dataset
                            </Button>
                        </div>
                    </div>
                </Card>

                <Card title="Sector Node Registry">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="border-b border-gray-800">
                                <tr>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Member Identity</th>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black text-center">Enrollment Agent</th>
                                    <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black text-center">Status</th>
                                    <th className="p-6 text-right"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-900/50">
                                {loading ? (
                                    <tr><td colSpan={4} className="p-24 text-center text-[10px] font-black uppercase tracking-[0.4em] text-gray-600 animate-pulse">Scanning Sector Nodes...</td></tr>
                                ) : filteredMembers.map(member => (
                                    <tr key={member.id} className="group hover:bg-white/[0.02] transition-all">
                                        <td className="p-6">
                                            <div className="flex flex-col gap-1">
                                                <div className="flex items-center gap-2">
                                                    <span className="font-bold text-white text-lg group-hover:text-orange-500 transition-colors">{member.name} {member.surname}</span>
                                                    {member.member_image_url && <FileText size={14} className="text-blue-500/50" />}
                                                </div>
                                                <div className="flex items-center gap-2 text-[11px] text-gray-600 font-mono">
                                                    <span>{member.mobile}</span>
                                                    <span className="h-1 w-1 rounded-full bg-gray-800"></span>
                                                    <span>{member.aadhaar.slice(-4).padStart(12, '•')}</span>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-6 text-center">
                                            <div className="inline-flex flex-col items-center">
                                                <div className="px-4 py-1.5 bg-blue-500/10 border border-blue-500/10 rounded-xl flex items-center gap-2">
                                                    <UserIcon size={12} className="text-blue-500" />
                                                    <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest">
                                                        {allOrgProfiles.find(p => p.id === member.volunteer_id)?.name || 'Agent '+member.volunteer_id.slice(0,5)}
                                                    </span>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-6 text-center">
                                            <span className={`px-4 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-full border ${member.status === MemberStatus.Accepted ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-orange-500/10 text-orange-400 border-orange-500/20'}`}>
                                                {member.status}
                                            </span>
                                        </td>
                                        <td className="p-6 text-right">
                                            <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-all">
                                                <button 
                                                    onClick={() => handleVerify(member)} 
                                                    className="p-3 bg-white/5 rounded-xl border border-white/5 hover:border-green-500/40 text-gray-500 hover:text-green-400 transition-all"
                                                    title="Verify Member"
                                                >
                                                    <CheckCircle2 size={18} />
                                                </button>
                                                <button 
                                                    onClick={() => handleEditClick(member)} 
                                                    className="p-3 bg-white/5 rounded-xl border border-white/5 hover:border-orange-500/40 text-gray-500 hover:text-orange-500 transition-all"
                                                    title="Override Record"
                                                >
                                                    <Edit3 size={18} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </Card>
            </div>

            <Modal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} title="Sector Override Terminal">
                {editingMember && (
                    <div className="space-y-6 max-h-[85vh] overflow-y-auto custom-scrollbar p-2">
                        <div className="p-8 bg-blue-500/5 border border-blue-500/10 rounded-[2rem] flex items-center gap-8 relative overflow-hidden group/modal-head">
                            {editingMember.member_image_url ? (
                                <div className="relative h-32 w-32 rounded-2xl overflow-hidden border border-white/10 shrink-0">
                                    <img src={editingMember.member_image_url} className="h-full w-full object-cover" alt="Aadhaar Scan" />
                                    <a href={editingMember.member_image_url} target="_blank" rel="noreferrer" className="absolute inset-0 bg-black/60 opacity-0 hover:opacity-100 flex items-center justify-center transition-opacity text-white">
                                        <ExternalLink size={20} />
                                    </a>
                                </div>
                            ) : (
                                <div className="h-32 w-32 rounded-2xl bg-gray-900 border border-white/5 flex items-center justify-center text-gray-700 shrink-0">
                                    <FileText size={32} />
                                </div>
                            )}
                            <div>
                                <p className="text-[10px] font-black text-blue-500 uppercase tracking-[0.4em] mb-1">Aadhaar Scan Record</p>
                                <p className="text-3xl font-cinzel text-white leading-tight uppercase mb-2">{editingMember.name} {editingMember.surname}</p>
                                <div className="flex items-center gap-2">
                                    <UserIcon size={12} className="text-gray-600" />
                                    <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">
                                        Source Agent: {allOrgProfiles.find(v => v.id === editingMember.volunteer_id)?.name || 'System'}
                                    </span>
                                </div>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <Input label="GIVEN NAME" value={editingMember.name} onChange={(e) => setEditingMember({...editingMember, name: e.target.value})} />
                            <Input label="SURNAME" value={editingMember.surname} onChange={(e) => setEditingMember({...editingMember, surname: e.target.value})} />
                            <Input label="MOBILE" value={editingMember.mobile} onChange={(e) => setEditingMember({...editingMember, mobile: e.target.value})} />
                            <Input label="AADHAAR" value={editingMember.aadhaar} onChange={(e) => setEditingMember({...editingMember, aadhaar: e.target.value})} maxLength={12} />
                            <Select label="SECTOR STATUS" value={editingMember.status} onChange={(e) => setEditingMember({...editingMember, status: e.target.value as MemberStatus})}>
                                <option value={MemberStatus.Pending}>Pending Verification</option>
                                <option value={MemberStatus.Accepted}>Accepted / Verified</option>
                            </Select>
                        </div>

                        <div className="flex justify-end gap-4 pt-10 border-t border-white/5 mt-8 sticky bottom-0 bg-gray-900 pb-2 z-10">
                            <Button variant="secondary" onClick={() => setIsEditModalOpen(false)} className="px-8 py-4 text-[10px] font-black uppercase tracking-widest">Abort</Button>
                            <Button 
                                onClick={handleUpdateMember} 
                                disabled={isUpdating}
                                className="px-12 py-4 text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-2xl"
                            >
                                {isUpdating ? <RefreshCw className="animate-spin" size={16} /> : <Save size={16} />}
                                {isUpdating ? 'SYNCHRONIZING...' : 'Commit Changes'}
                            </Button>
                        </div>
                    </div>
                )}
            </Modal>
        </DashboardLayout>
    );
};

export default OrganisationReports;

import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import { Volunteer, Role } from '../../types';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { Power, Download, UserPlus, UserCheck, Copy, ShieldCheck, Loader2, UserCircle, Zap, ShieldAlert, RefreshCw, ExternalLink, Activity, Database } from 'lucide-react';

type VolunteerWithEnrollments = Volunteer & { enrollments: number };

const ManageVolunteers: React.FC = () => {
  const { user } = useAuth();
  const [volunteers, setVolunteers] = useState<VolunteerWithEnrollments[]>([]);
  const [newVol, setNewVol] = useState({ name: '', mobile: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showRepairTool, setShowRepairTool] = useState(false);
  const [diagnosticInfo, setDiagnosticInfo] = useState<string | null>(null);

  const { addNotification } = useNotification();

  const fetchVolunteers = useCallback(async () => {
    if (!user?.organisationId) return;
    setLoading(true);

    try {
        const { data: profileData, error: profileError } = await supabase
          .from('profiles')
          .select('*, members(id)')
          .eq('role', Role.Volunteer)
          .eq('organisation_id', user.organisationId);

        if (profileError) {
          const errorMsg = profileError.message || (typeof profileError === 'string' ? profileError : JSON.stringify(profileError));
          console.error("Registry Sync Fault:", profileError);
          setDiagnosticInfo(`Database Access Denied: ${errorMsg}`);
          setShowRepairTool(true);
          addNotification(`Registry sync failed: ${errorMsg}`, 'error');
        } else {
          setVolunteers(profileData.map((v: any) => ({
              id: v.id,
              name: v.name,
              email: v.email,
              mobile: v.mobile,
              role: Role.Volunteer,
              organisationId: v.organisation_id,
              organisationName: user.organisationName,
              status: v.status || 'Active',
              enrollments: v.members?.length || 0
          })) || []);
          setShowRepairTool(false);
        }
    } catch (e: any) {
        const errorMsg = e?.message || (typeof e === 'string' ? e : 'Unknown Protocol Fault');
        addNotification(`Protocol Error: ${errorMsg}`, 'error');
    } finally {
        setLoading(false);
    }
  }, [user, addNotification]);

  useEffect(() => {
    fetchVolunteers();
  }, [fetchVolunteers]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewVol(prev => ({ ...prev, [name]: value }));
  };

  const GOD_LEVEL_REPAIR_SQL = `-- 🔱 SSK "GOD-LEVEL" INTEGRITY & RLS REPAIR 🔱
-- 1. HARDEN PROFILE SCHEMA
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS name text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS email text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS mobile text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS role text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS status text DEFAULT 'Active';
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS organisation_id uuid;

-- 2. CRASH-PROOF SYNC TRIGGER
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger AS $$
DECLARE
  raw_org_id text;
  final_org_id uuid;
BEGIN
  BEGIN 
    raw_org_id := new.raw_user_meta_data->>'organisation_id';
    IF raw_org_id IS NOT NULL AND raw_org_id <> '' AND raw_org_id <> 'null' THEN
      BEGIN final_org_id := raw_org_id::uuid; EXCEPTION WHEN OTHERS THEN final_org_id := NULL; END;
    END IF;

    INSERT INTO public.profiles (id, name, email, role, organisation_id, mobile, status)
    VALUES (
      new.id, 
      COALESCE(new.raw_user_meta_data->>'name', 'User Node'), 
      new.email, 
      COALESCE(new.raw_user_meta_data->>'role', 'Volunteer'), 
      final_org_id, 
      new.raw_user_meta_data->>'mobile', 
      'Active'
    )
    ON CONFLICT (id) DO UPDATE SET 
      role = EXCLUDED.role, 
      organisation_id = EXCLUDED.organisation_id, 
      name = EXCLUDED.name, 
      mobile = EXCLUDED.mobile, 
      status = EXCLUDED.status;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Sync failed for user %, but Auth allowed to proceed.', new.id;
  END;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- 3. RESET RLS POLICIES (THE CRITICAL FIX FOR ORG ADMINS)
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Enable all for admins" ON public.profiles;
DROP POLICY IF EXISTS "Org Admins Manage Own Volunteers" ON public.profiles;
DROP POLICY IF EXISTS "Users view own" ON public.profiles;
DROP POLICY IF EXISTS "MasterAdmin Full Access" ON public.profiles;
DROP POLICY IF EXISTS "Users View Own Profile" ON public.profiles;

-- Policy: Master Admin can do anything
CREATE POLICY "MasterAdmin Full Access" ON public.profiles FOR ALL 
TO authenticated
USING ( (auth.jwt() -> 'app_metadata' ->> 'role') = 'MasterAdmin' )
WITH CHECK ( (auth.jwt() -> 'app_metadata' ->> 'role') = 'MasterAdmin' );

-- Policy: Organisation Admins can manage their own volunteers
CREATE POLICY "Org Admins Manage Own Volunteers" ON public.profiles FOR ALL
TO authenticated
USING (
  organisation_id = (auth.jwt() -> 'user_metadata' ->> 'organisation_id')::uuid
  OR 
  organisation_id = (auth.jwt() -> 'app_metadata' ->> 'organisation_id')::uuid
)
WITH CHECK (
  organisation_id = (auth.jwt() -> 'user_metadata' ->> 'organisation_id')::uuid
  OR 
  organisation_id = (auth.jwt() -> 'app_metadata' ->> 'organisation_id')::uuid
);

-- Policy: Everyone can view their own profile
CREATE POLICY "Users View Own Profile" ON public.profiles FOR SELECT
TO authenticated
USING ( auth.uid() = id );

-- 4. GRANT PERMISSIONS
GRANT ALL ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
GRANT ALL ON public.profiles TO postgres;`;

  const handleAddVolunteer = async () => {
    const email = newVol.email.trim().toLowerCase();
    const password = newVol.password;
    const name = newVol.name.trim();
    const mobile = newVol.mobile.trim();

    if (!user?.organisationId) {
        addNotification("Session missing context. Re-login required.", 'error');
        return;
    }
    if (!email || !password || !name || !mobile) {
        addNotification("All identity parameters are mandatory.", 'error');
        return;
    }

    setIsSubmitting(true);
    setDiagnosticInfo(null);

    try {
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              name,
              mobile,
              role: 'Volunteer', 
              organisation_id: user.organisationId
            }
          }
        });

        if (authError) {
            const errMsg = authError.message.toLowerCase();
            const isTriggerFault = errMsg.includes("database error") || errMsg.includes("trigger") || errMsg.includes("saving new user");

            if (isTriggerFault) {
                setShowRepairTool(true);
                setDiagnosticInfo(`Trigger Collision: ${authError.message}. The database trigger 'handle_new_user' is blocking the Auth operation.`);
                throw new Error("Trigger Fault: Background sync crashed.");
            } else {
                throw authError;
            }
        } 

        if (authData?.user?.id) {
            const { error: healError } = await supabase.from('profiles').upsert({
                id: authData.user.id,
                name,
                email,
                role: 'Volunteer',
                organisation_id: user.organisationId,
                mobile,
                status: 'Active'
            });

            if (healError) {
                console.warn("Manual sync heal failed. This is likely an RLS Policy issue.", healError);
                setShowRepairTool(true);
                const healMsg = healError.message || JSON.stringify(healError);
                setDiagnosticInfo(`Access Policy Violation: ${healMsg}. Your account does not have permission to insert into the profiles table.`);
            } else {
                addNotification('Volunteer operator successfully deployed.', 'success');
                setNewVol({ name: '', mobile: '', email: '', password: '' });
                fetchVolunteers(); 
            }
        }
    } catch (err: any) {
        const errorMsg = err?.message || (typeof err === 'string' ? err : 'System handshake failed.');
        addNotification(errorMsg, 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const copyVolunteerCreds = (v: VolunteerWithEnrollments) => {
