import React, { createContext, useState, useContext, ReactNode, useEffect, useCallback } from 'react';
import { User, Role } from '../types';
import { supabase } from '../supabase/client';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<{ user: User | null; error?: string; code?: string }>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  updatePassword: (newPassword: string) => Promise<{ success: boolean; error?: string }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Fix: Update mapStringToRole to correctly handle and return Organisation and Volunteer roles
export const mapStringToRole = (roleStr: any): Role | string => {
    if (!roleStr) return 'Guest';
    const normalized = String(roleStr).toLowerCase().trim();
    if (normalized === 'masteradmin' || normalized === 'superadmin' || normalized === 'master_admin') {
        return Role.MasterAdmin;
    }
    if (normalized === 'organisation' || normalized === 'org' || normalized === 'organisationadmin') {
        return Role.Organisation;
    }
    if (normalized === 'volunteer') {
        return Role.Volunteer;
    }
    // Return the string as is for data categorization, but App.tsx will block access
    return roleStr;
};

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchProfile = useCallback(async (userId: string, authUser?: any): Promise<User | null> => {
    try {
      const metadataRole = authUser?.app_metadata?.role || authUser?.user_metadata?.role;
      const metadataOrgId = authUser?.app_metadata?.organisation_id || authUser?.user_metadata?.organisation_id;

      const { data: profile, error } = await supabase
          .from('profiles')
          .select(`*, organisations (name)`)
          .eq('id', userId)
          .maybeSingle();

      if (error) {
          if (authUser) {
              return {
                  id: authUser.id,
                  name: authUser.user_metadata?.name || 'Authorized User',
                  email: authUser.email || '',
                  role: mapStringToRole(metadataRole),
                  organisationId: metadataOrgId,
                  status: 'Active'
              };
          }
          return null;
      }

      if (profile) {
          const role = mapStringToRole(profile.role || metadataRole);

          // Fix: Allow roles other than MasterAdmin to authenticate successfully
          return {
              id: profile.id,
              name: profile.name,
              email: profile.email,
              role: role,
              organisationId: profile.organisation_id || metadataOrgId,
              organisationName: profile.organisations?.name || undefined,
              mobile: profile.mobile,
              status: (profile.status as 'Active' | 'Deactivated') || 'Active'
          };
      } else if (authUser) {
          const role = mapStringToRole(metadataRole);
          return {
              id: authUser.id,
              name: authUser.user_metadata?.name || 'Authorized User',
              email: authUser.email || '',
              role: role,
              organisationId: metadataOrgId,
              status: 'Active'
          };
      }
    } catch (e: any) {
      console.error("Critical Profile sync fault:", e);
    }
    return null;
  }, []);

  const login = async (email: string, password: string): Promise<{ user: User | null; error?: string; code?: string }> => {
    try {
        const { data, error: authError } = await supabase.auth.signInWithPassword({ 
            email: email.trim().toLowerCase(), 
            password 
        });

        if (authError) return { user: null, error: authError.message };

        if (data.user) {
            const profile = await fetchProfile(data.user.id, data.user);
            if (profile) {
                setUser(profile);
                return { user: profile };
            }
            return { user: null, error: "Access Denied: Account not authorized for registry access.", code: 'UNAUTHORIZED' };
        }
        return { user: null, error: "Authentication Handshake Failed." };
    } catch (err: any) {
        return { user: null, error: err.message };
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  const refreshProfile = useCallback(async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
          const updatedUser = await fetchProfile(session.user.id, session.user);
          setUser(updatedUser);
      }
  }, [fetchProfile]);

  const updatePassword = async (newPassword: string) => {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      if (error) return { success: false, error: error.message };
      return { success: true };
  }

  useEffect(() => {
    const init = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
            try {
                const mapped = await fetchProfile(session.user.id, session.user);
                setUser(mapped);
            } catch (e) {
                console.error("Auth init error:", e);
            }
        }
        setLoading(false);
    };
    init();
  }, [fetchProfile]);

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshProfile, updatePassword }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be wrapped in AuthProvider');
  return context;
};

import React from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import { NotificationProvider } from './context/NotificationContext';
import { Role } from './types';

import LandingPage from './pages/LandingPage';
import LoginPage from './pages/LoginPage';
import AdminDashboard from './pages/admin/AdminDashboard';
import ManageOrganisations from './pages/admin/ManageOrganisations';
import AdminReports from './pages/admin/AdminReports';

// Fix: Add missing imports for Role-specific pages
import OrganisationDashboard from './pages/organisation/OrganisationDashboard';
import ManageVolunteers from './pages/organisation/ManageVolunteers';
import OrganisationReports from './pages/organisation/OrganisationReports';
import VolunteerDashboard from './pages/volunteer/VolunteerDashboard';
import NewMemberForm from './pages/volunteer/NewMemberForm';

const App: React.FC = () => {
  return (
    <AuthProvider>
      <NotificationProvider>
        <HashRouter>
          <Routes>
            <Route path="/" element={<LandingPage />} />
            <Route path="/login" element={<LoginPage />} />

            {/* Master Admin Routes */}
            <Route path="/admin" element={<ProtectedRoute requiredRole={Role.MasterAdmin}><AdminDashboard /></ProtectedRoute>} />
            <Route path="/admin/organisations" element={<ProtectedRoute requiredRole={Role.MasterAdmin}><ManageOrganisations /></ProtectedRoute>} />
            <Route path="/admin/reports" element={<ProtectedRoute requiredRole={Role.MasterAdmin}><AdminReports /></ProtectedRoute>} />

            {/* Organisation Routes */}
            <Route path="/organisation" element={<ProtectedRoute requiredRole={Role.Organisation}><OrganisationDashboard /></ProtectedRoute>} />
            <Route path="/organisation/volunteers" element={<ProtectedRoute requiredRole={Role.Organisation}><ManageVolunteers /></ProtectedRoute>} />
            <Route path="/organisation/reports" element={<ProtectedRoute requiredRole={Role.Organisation}><OrganisationReports /></ProtectedRoute>} />

            {/* Volunteer Routes */}
            <Route path="/volunteer" element={<ProtectedRoute requiredRole={Role.Volunteer}><VolunteerDashboard /></ProtectedRoute>} />
            <Route path="/volunteer/new-member" element={<ProtectedRoute requiredRole={Role.Volunteer}><NewMemberForm /></ProtectedRoute>} />

            <Route path="*" element={<Navigate to="/" />} />
          </Routes>
        </HashRouter>
      </NotificationProvider>
    </AuthProvider>
  );
};

interface ProtectedRouteProps {
  children: React.ReactElement;
  requiredRole: Role;
}

const ProtectedRoute: React.FC<ProtectedRouteProps> = ({ children, requiredRole }) => {
  const { user } = useAuth();
  if (!user || user.role !== requiredRole) {
    return <Navigate to="/login" />;
  }
  return children;
};

export default App;

