import React, { useState, useEffect, useMemo } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { supabase } from '../../supabase/client';
import { Member, Organisation, Role, User as VolunteerUser, Gender, Occupation, SupportNeed, MemberStatus } from '../../types';
import { useNotification } from '../../context/NotificationContext';
import { 
  FileSpreadsheet, 
  Search,
  RefreshCw,
  Edit3,
  Save,
  User as UserIcon,
  Image as ImageIcon,
  ExternalLink,
  Filter,
  Trash2,
  AlertTriangle,
  Calendar,
  Building2,
  Fingerprint,
  FileText,
  Activity,
  Eye,
  UserCircle,
  ShieldCheck,
  Phone,
  BadgeCheck
} from 'lucide-react';

type MemberWithAgent = Member & {
    agent_profile?: { 
        name: string, 
        mobile: string,
        organisations?: { name: string }
    }
};

const AdminReports: React.FC = () => {
    const [members, setMembers] = useState<MemberWithAgent[]>([]);
    const [organisations, setOrganisations] = useState<Organisation[]>([]);
    const [allProfiles, setAllProfiles] = useState<VolunteerUser[]>([]);
    const [loading, setLoading] = useState(true);
    const { addNotification } = useNotification();

    const [selectedOrgId, setSelectedOrgId] = useState<string>('');
    const [selectedVolunteerId, setSelectedVolunteerId] = useState<string>('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [searchQuery, setSearchQuery] = useState('');

    const [editingMember, setEditingMember] = useState<MemberWithAgent | null>(null);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [isDeleting, setIsDeleting] = useState(false);
    const [memberToDelete, setMemberToDelete] = useState<string | null>(null);
    const [isUpdating, setIsUpdating] = useState(false);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [membersRes, orgsRes, profilesRes] = await Promise.all([
                supabase
                    .from('members')
                    .select(`
                        *,
                        agent_profile:profiles!volunteer_id(
                            name, 
                            mobile,
                            organisations (name)
                        )
                    `)
                    .order('submission_date', { ascending: false }),
                supabase.from('organisations').select('*').order('name'),
                supabase.from('profiles').select('*')
            ]);

            if (membersRes.data) setMembers(membersRes.data as MemberWithAgent[]);
            if (orgsRes.data) setOrganisations(orgsRes.data);

            if (profilesRes.data) {
                const mappedProfiles: VolunteerUser[] = profilesRes.data.map(p => ({
                    id: p.id,
                    name: p.name,
                    email: p.email,
                    role: p.role as Role,
                    organisationId: p.organisation_id,
                    mobile: p.mobile,
                    status: p.status
                }));
                setAllProfiles(mappedProfiles);
            }
        } catch (err) {
            addNotification("Master registry uplink failed.", "error");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const filteredMembers = useMemo(() => {
        return members.filter(m => {
            const matchOrg = !selectedOrgId || m.organisation_id === selectedOrgId;
            const matchVol = !selectedVolunteerId || m.volunteer_id === selectedVolunteerId;
            const matchSearch = !searchQuery || 
                m.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                m.surname.toLowerCase().includes(searchQuery.toLowerCase()) ||
                m.mobile.includes(searchQuery);
            return matchOrg && matchVol && matchSearch;
        });
    }, [members, selectedOrgId, selectedVolunteerId, searchQuery]);

    const handleEditMember = (member: MemberWithAgent) => {
        setEditingMember({ ...member });
        setIsEditModalOpen(true);
    };

    const handleDeleteMember = async () => {
        if (!memberToDelete) return;
        setIsDeleting(true);
        try {
            const { error } = await supabase.from('members').delete().eq('id', memberToDelete);
            if (error) throw error;
            addNotification("Record purged.", "success");
            setMemberToDelete(null);
            fetchData();
        } catch (err: any) {
            addNotification(`Action failed.`, "error");
        } finally {
            setIsDeleting(false);
        }
    };

    const handleUpdateMember = async () => {
        if (!editingMember) return;
        setIsUpdating(true);
        try {
            const { error } = await supabase.from('members').update({
                name: editingMember.name,
                surname: editingMember.surname,
                status: editingMember.status,
            }).eq('id', editingMember.id);
            if (error) throw error;
            addNotification("Data synchronized.", "success");
            setIsEditModalOpen(false);
            fetchData();
        } catch (err: any) {
            addNotification(`Update failed.`, "error");
        } finally {
            setIsUpdating(false);
        }
    };

    return (
        <DashboardLayout title="Master Registry Terminal">
            <div className="space-y-8">
                <Card className="bg-gray-950 border-white/5 p-8 rounded-[2rem] shadow-2xl relative overflow-hidden">
                    <div className="flex items-center gap-2 mb-8 text-orange-500 relative z-10">
                        <Activity size={18} />
                        <h3 className="text-[10px] font-black uppercase tracking-[0.4em]">Multi-Vector Registry Search</h3>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8 relative z-10">
                        <Select label="Filter by Sector" value={selectedOrgId} onChange={(e) => setSelectedOrgId(e.target.value)}>
                            <option value="">All Organizations</option>
                            {organisations.map(org => <option key={org.id} value={org.id}>{org.name}</option>)}
                        </Select>
                        <Input 
                            placeholder="Search by Name/Mobile..." 
                            value={searchQuery} 
                            onChange={(e) => setSearchQuery(e.target.value)} 
                            icon={<Search size={16} />}
                        />
                        <div className="flex gap-4 items-end">
                            <Button onClick={fetchData} variant="secondary" className="flex-1 py-4 text-[10px] font-black uppercase tracking-widest gap-2">
                                <RefreshCw size={14} className={loading ? 'animate-spin' : ''} /> Sync
                            </Button>
                        </div>
                    </div>
                </Card>

                <Card title="Global Enrolled Members">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="border-b border-gray-800">
                                <tr className="text-gray-500 uppercase tracking-widest text-[10px] font-black">
                                    <th className="p-6">Member Identity</th>
                                    <th className="p-6 text-blue-500">Personnel Attribution</th>
                                    <th className="p-6 text-center">Verification</th>
                                    <th className="p-6"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-900/50">
                                {loading ? (
                                    <tr><td colSpan={4} className="p-24 text-center text-[11px] animate-pulse font-black uppercase tracking-[0.4em] text-gray-600">Loading Node Data...</td></tr>
                                ) : filteredMembers.map(m => (
                                    <tr key={m.id} className="group hover:bg-white/[0.02] transition-all">
                                        <td className="p-6">
                                            <div className="flex flex-col">
                                                <span className="font-bold text-white text-lg">{m.name} {m.surname}</span>
                                                <span className="text-[11px] text-gray-600 font-mono">{m.mobile}</span>
                                            </div>
                                        </td>
                                        <td className="p-6">
                                            <div className="flex items-center gap-4">
                                                <div className="h-10 w-10 rounded-xl bg-orange-500/10 border border-orange-500/20 flex items-center justify-center text-orange-500">
                                                    <UserCircle size={20} />
                                                </div>
                                                <div className="flex flex-col">
                                                    <span className="text-[11px] font-black text-white uppercase tracking-widest">
                                                        {m.agent_profile?.name || 'Unknown Agent'}
                                                    </span>
                                                    <div className="flex items-center gap-2 mt-0.5">
                                                        <Building2 size={10} className="text-orange-500/80" />
                                                        <span className="text-[9px] text-orange-500/80 font-black uppercase tracking-widest">
                                                            {m.agent_profile?.organisations?.name || 'Independent'}
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-6 text-center">
                                            <span className={`px-4 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-full border ${m.status === MemberStatus.Accepted ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-orange-500/10 text-orange-400 border-orange-500/20'}`}>
                                                {m.status}
                                            </span>
                                        </td>
                                        <td className="p-6 text-right">
                                            <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-all">
                                                <button onClick={() => handleEditMember(m)} className="p-3 text-gray-400 hover:text-white">
                                                    <Edit3 size={18} />
                                                </button>
                                                <button onClick={() => setMemberToDelete(m.id)} className="p-3 text-red-500/60 hover:text-red-500">
                                                    <Trash2 size={18} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </Card>
            </div>

            <Modal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} title="Modify Member Identity">
                {editingMember && (
                    <div className="space-y-6">
                        <Input label="Name" value={editingMember.name} onChange={(e) => setEditingMember({...editingMember, name: e.target.value})} />
                        <Input label="Surname" value={editingMember.surname} onChange={(e) => setEditingMember({...editingMember, surname: e.target.value})} />
                        <Select label="Status" value={editingMember.status} onChange={(e) => setEditingMember({...editingMember, status: e.target.value as MemberStatus})}>
                            <option value={MemberStatus.Pending}>Pending</option>
                            <option value={MemberStatus.Accepted}>Accepted</option>
                        </Select>
                        <div className="flex justify-end gap-4 pt-6">
                            <Button variant="secondary" onClick={() => setIsEditModalOpen(false)}>Cancel</Button>
                            <Button onClick={handleUpdateMember} disabled={isUpdating}>{isUpdating ? 'Saving...' : 'Save Changes'}</Button>
                        </div>
                    </div>
                )}
            </Modal>
        </DashboardLayout>
    );
};

export default AdminReports;

import React, { useState, useMemo, useEffect } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Modal from '../../components/ui/Modal';
import { 
  Shield, 
  Users, 
  UserCheck, 
  RefreshCw, 
  User as UserIcon, 
  ExternalLink, 
  Search, 
  Building2, 
  Activity, 
  TrendingUp,
  Phone,
  Database,
  Network,
  BadgeCheck
} from 'lucide-react';
import { Organisation, Volunteer, Member, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';

interface OrgStats extends Organisation {
    volunteerCount: number;
    memberCount: number;
}

type VolunteerWithOrg = Volunteer & {
    organisation_name?: string;
};

const AdminDashboard: React.FC = () => {
    const { addNotification } = useNotification();
    const [searchTerm, setSearchTerm] = useState('');
    const [organisations, setOrganisations] = useState<Organisation[]>([]);
    const [members, setMembers] = useState<Member[]>([]);
    const [volunteersWithOrg, setVolunteersWithOrg] = useState<VolunteerWithOrg[]>([]);
    const [loading, setLoading] = useState(true);
    const [isVolunteersModalOpen, setIsVolunteersModalOpen] = useState(false);

    const fetchData = async () => {
        setLoading(true);
        try {
            // 1. Fetch Core Data Tables
            const [orgsRes, membersRes, profilesRes] = await Promise.all([
                supabase.from('organisations').select('*').order('name'),
                supabase.from('members').select('*'),
                supabase.from('profiles').select('*, organisations(name)').eq('role', 'Volunteer')
            ]);

            if (orgsRes.error) throw orgsRes.error;
            if (membersRes.error) throw membersRes.error;
            if (profilesRes.error) throw profilesRes.error;

            setOrganisations(orgsRes.data || []);
            setMembers(membersRes.data || []);

            // 2. Map Volunteers with their Enrollment Counts and Org names
            if (profilesRes.data) {
                const enrollmentMap = (membersRes.data || []).reduce((acc, m) => {
                    if (m.volunteer_id) acc[m.volunteer_id] = (acc[m.volunteer_id] || 0) + 1;
                    return acc;
                }, {} as Record<string, number>);

                const mapped: VolunteerWithOrg[] = profilesRes.data.map((p: any) => ({
                    id: p.id,
                    name: p.name || 'Agent ' + p.id.slice(0, 4),
                    email: p.email,
                    role: Role.Volunteer,
                    organisationId: p.organisation_id,
                    organisation_name: p.organisations?.name || 'Unassigned Sector',
                    mobile: p.mobile || 'N/A',
                    status: p.status,
                    enrollments: enrollmentMap[p.id] || 0
                }));

                setVolunteersWithOrg(mapped.sort((a, b) => b.enrollments - a.enrollments));
            }
        } catch (err: any) {
            console.error("Critical Admin Sync Fault:", err);
            addNotification(`Registry Offline: ${err.message}`, "error");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const filteredVolunteers = useMemo(() => {
        if (!searchTerm) return volunteersWithOrg;
        const term = searchTerm.toLowerCase();
        return volunteersWithOrg.filter(vol => 
            vol.name.toLowerCase().includes(term) || 
            vol.mobile?.includes(term) ||
            vol.organisation_name?.toLowerCase().includes(term)
        );
    }, [searchTerm, volunteersWithOrg]);

    const orgStats = useMemo<OrgStats[]>(() => {
        return organisations.map(org => {
            const orgVolunteers = volunteersWithOrg.filter(p => p.organisationId === org.id);
            const orgMembers = members.filter(m => m.organisation_id === org.id);
            return {
                ...org,
                volunteerCount: orgVolunteers.length,
                memberCount: orgMembers.length
            };
        }).sort((a, b) => b.memberCount - a.memberCount);
    }, [organisations, volunteersWithOrg, members]);

    return (
        <DashboardLayout title="Master Admin Dashboard">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                <Card className="p-8 border-l-4 border-orange-600 bg-[#080808] hover:bg-[#0a0a0a] transition-all group relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none group-hover:rotate-12 transition-transform">
                        <Building2 size={80} />
                    </div>
                    <div className="flex justify-between items-center mb-4">
                      <Shield className="text-orange-600 group-hover:scale-110 transition-transform" size={32} strokeWidth={1.5} />
                      <span className="text-[9px] font-black text-orange-600/50 uppercase tracking-[0.2em]">Sectors</span>
                    </div>
                    <div>
                        <p className="text-gray-500 text-[10px] uppercase tracking-widest font-bold mb-1">Active Organisations</p>
                        <p className="text-5xl font-black text-white">{loading ? '...' : organisations.length}</p>
                    </div>
                </Card>

                <button 
                    onClick={() => setIsVolunteersModalOpen(true)}
                    className="text-left w-full block group relative overflow-hidden rounded-lg outline-none focus:ring-2 focus:ring-blue-500/50 transition-all"
                >
                    <Card className="p-8 border-l-4 border-blue-600 bg-[#080808] group-hover:bg-[#0a0a0a] transition-all h-full relative">
                        <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none group-hover:-rotate-12 transition-transform">
                            <Users size={80} />
                        </div>
                        <div className="flex justify-between items-center mb-4">
                            <Users className="text-blue-600 group-hover:scale-110 transition-transform" size={32} strokeWidth={1.5} />
                            <span className="text-[9px] font-black text-blue-600/50 uppercase tracking-[0.2em]">Personnel</span>
                        </div>
                        <div>
                            <p className="text-gray-500 text-[10px] uppercase tracking-widest font-bold mb-1">Global Volunteers</p>
                            <p className="text-5xl font-black text-white">{loading ? '...' : volunteersWithOrg.length}</p>
                            <p className="text-[9px] font-black text-blue-500 uppercase tracking-widest mt-4 opacity-60 group-hover:opacity-100 transition-opacity">View All Personnel →</p>
                        </div>
                    </Card>
                </button>

                <Card className="p-8 border-l-4 border-green-600 bg-[#080808] hover:bg-[#0a0a0a] transition-all group relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none group-hover:scale-125 transition-transform">
                        <Database size={80} />
                    </div>
                    <div className="flex justify-between items-center mb-4">
                      <UserCheck className="text-green-600 group-hover:scale-110 transition-transform" size={32} strokeWidth={1.5} />
                      <span className="text-[9px] font-black text-green-600/50 uppercase tracking-[0.2em]">Database</span>
                    </div>
                    <div>
                        <p className="text-gray-500 text-[10px] uppercase tracking-widest font-bold mb-1">Enrolled Members</p>
                        <p className="text-5xl font-black text-white">{loading ? '...' : members.length}</p>
                    </div>
                </Card>
            </div>

            <div className="mt-12">
                <Card title="Sector Performance Matrix" className="bg-[#050505] border-white/5">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left text-sm">
                            <thead className="border-b border-gray-800">
                                <tr className="text-gray-500 uppercase tracking-wider text-[10px] font-black">
                                    <th className="p-5">Entity Node</th>
                                    <th className="p-5 text-center">Personnel (Volunteers)</th>
                                    <th className="p-5 text-center">Enrollments (Members)</th>
                                    <th className="p-5 text-right">Operational Status</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-900/50">
                                {orgStats.map(org => (
                                    <tr key={org.id} className="group hover:bg-white/[0.02] transition-colors">
                                        <td className="p-5">
                                            <div className="flex items-center gap-4">
                                                <div className="p-3 bg-orange-500/10 rounded-xl text-orange-500 border border-orange-500/10 group-hover:scale-105 transition-transform">
                                                    <Building2 size={20} />
                                                </div>
                                                <span className="font-bold text-white text-base group-hover:text-orange-500 transition-colors">{org.name}</span>
                                            </div>
                                        </td>
                                        <td className="p-5 text-center">
                                            <span className="font-mono text-xl text-blue-400 font-black">{org.volunteerCount}</span>
                                        </td>
                                        <td className="p-5 text-center">
                                            <span className="font-mono text-xl text-green-400 font-black">{org.memberCount}</span>
                                        </td>
                                        <td className="p-5 text-right">
                                            <div className="flex items-center justify-end gap-3">
                                                <span className={`h-2 w-2 rounded-full ${org.status === 'Active' ? 'bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]' : 'bg-red-500'} animate-pulse`}></span>
                                                <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">{org.status}</span>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                                {orgStats.length === 0 && (
                                    <tr>
                                        <td colSpan={4} className="p-20 text-center text-[10px] text-gray-700 uppercase tracking-[0.5em] font-black">Scanning for active nodes...</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </Card>
            </div>

            <Modal 
                isOpen={isVolunteersModalOpen} 
                onClose={() => setIsVolunteersModalOpen(false)} 
                title="Global Personnel Registry"
            >
                <div className="space-y-6 max-h-[75vh] overflow-y-auto pr-2 custom-scrollbar">
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" size={16} />
                        <input 
                            type="text"
                            placeholder="Filter by Name, Mobile, or Sector..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full bg-black/40 border border-gray-800 rounded-xl py-3 pl-10 pr-4 text-white text-xs font-mono focus:outline-none focus:border-orange-500 transition-all"
                        />
                    </div>

