                                    </a>
                                </div>
                            ) : (
                                <div className="h-40 w-full md:w-56 rounded-[2rem] bg-gray-950 border-2 border-white/5 flex flex-col items-center justify-center text-gray-800 shrink-0 gap-3">
                                    <FileText size={32} strokeWidth={1} />
