/**
 * GOOGLE SHEETS SYNCHRONIZATION SERVICE
 * This service pushes real-time data to a Google Apps Script Web App bridge.
 */

// Replace this URL with your deployed Google Apps Script Web App URL
const WEB_APP_URL = "YOUR_GOOGLE_APPS_SCRIPT_URL_HERE";

export enum SheetType {
  MEMBERS = 'Member Databases',
  VOLUNTEERS = 'Volunteer Databases',
  ORGANISATIONS = 'Organisation Databases'
}

export const syncToSheets = async (type: SheetType, data: any) => {
  // If no URL is provided, we log to console (Dev Mode)
  if (WEB_APP_URL === "YOUR_GOOGLE_APPS_SCRIPT_URL_HERE") {
    console.debug(`[Sheets Sync Simulation] Type: ${type}`, data);
    return;
  }

  try {
    const response = await fetch(WEB_APP_URL, {
      method: 'POST',
      mode: 'no-cors', // CORS handling for GAS
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        sheetName: type,
        data: data,
        timestamp: new Date().toISOString()
      }),
    });
    return response;
  } catch (error) {
    console.error('Sheets Sync Error:', error);
  }
};

import React, { useState, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import Button from '../../components/ui/Button';
import { Gender, Occupation, SupportNeed } from '../../types';
import { supabase } from '../../supabase/client';
import { useAuth } from '../../context/AuthContext';
import { useNotification } from '../../context/NotificationContext';
import { syncToSheets, SheetType } from '../../services/googleSheets';
import { ShieldAlert, RefreshCw, User as UserIcon, CheckCircle2, FileText, Fingerprint, UploadCloud, ShieldCheck, Search, Info } from 'lucide-react';

const initialFormData = {
  aadhaar: '',
  mobile: '',
  name: '',
  surname: '',
  fatherName: '',
  dob: '',
  gender: Gender.Male,
  emergencyContact: '',
  pincode: '',
  address: '',
  memberImage: null as File | null,
  occupation: Occupation.Job,
  supportNeed: SupportNeed.Education,
};

const NewMemberForm: React.FC = () => {
  const { user } = useAuth();
  const { addNotification } = useNotification();
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState(initialFormData);
  const [validationError, setValidationError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const getErrorMessage = (err: any): string => {
      if (!err) return "Unknown System Error";
      if (typeof err === 'string') return err;
      const commonProps = ['message', 'error_description', 'details', 'hint', 'msg', 'error'];
      for (const prop of commonProps) {
          if (err[prop] && typeof err[prop] === 'string') return err[prop];
      }
      return "Database security policy failure";
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    if ((name === 'aadhaar' || name === 'mobile' || name === 'emergencyContact' || name === 'pincode') && value !== '' && !/^\d+$/.test(value)) return;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
        const file = e.target.files[0];
        setFormData(prev => ({ ...prev, memberImage: file }));
        if(imagePreview) URL.revokeObjectURL(imagePreview);
        setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = () => {
    if (imagePreview) URL.revokeObjectURL(imagePreview);
    setFormData(prev => ({ ...prev, memberImage: null }));
    setImagePreview(null);
    if(fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleStep1Next = async () => {
    setValidationError('');
    if (!formData.aadhaar || !formData.mobile) {
        setValidationError('Aadhaar and Mobile Number are both mandatory.');
        return;
    }
    if (!/^\d{12}$/.test(formData.aadhaar)) {
      setValidationError('Aadhaar ID must be exactly 12 numeric digits.');
      return;
    }
    if (!/^\d{10}$/.test(formData.mobile)) {
        setValidationError('Mobile Number must be exactly 10 numeric digits.');
        return;
    }

    setIsValidating(true);
    try {
        const { data, error } = await supabase.from('members').select('id').eq('aadhaar', formData.aadhaar).maybeSingle();
        if (error) throw error;
        if (data) {
            setValidationError('Identification Conflict: This Aadhaar ID is already registered.');
        } else {
            setStep(2);
            window.scrollTo(0, 0);
        }
    } catch (e: any) {
        setValidationError(`Registry Fault: ${getErrorMessage(e)}`);
    } finally {
        setIsValidating(false);
    }
  };

  const handleStep2Next = () => {
      setValidationError('');
      if (!formData.name || !formData.surname || !formData.fatherName || !formData.dob || !formData.emergencyContact || !formData.pincode || !formData.address) {
          setValidationError('Action Required: All profile fields must be completed.');
          return;
      }
      if (!/^\d{10}$/.test(formData.emergencyContact)) {
          setValidationError('Validation Error: Emergency contact must be a valid 10-digit number.');
          return;
      }
      if (!/^\d{6}$/.test(formData.pincode)) {
          setValidationError('Validation Error: Pincode must be exactly 6 numeric digits.');
          return;
      }
      if (!formData.memberImage) {
          setValidationError('Critical Requirement: Aadhaar Card document scan is missing.');
          return;
      }
      setStep(3);
      window.scrollTo(0, 0);
  };

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!user?.organisationId) return;

      setIsSubmitting(true);
      try {
          let imageUrl = '';
          if (formData.memberImage) {
              const fileName = `aadhaar_${uuidv4()}.jpg`;
              const { data: uploadData, error: uploadError } = await supabase.storage.from('member-images').upload(fileName, formData.memberImage);
              if(uploadError) throw uploadError;
              imageUrl = supabase.storage.from('member-images').getPublicUrl(uploadData.path).data.publicUrl;
          }

          const memberPayload = {
              aadhaar: formData.aadhaar,
              mobile: formData.mobile,
              name: formData.name,
              surname: formData.surname,
              father_name: formData.fatherName,
              dob: formData.dob,
              gender: formData.gender,
              emergency_contact: formData.emergencyContact,
              pincode: formData.pincode,
              address: formData.address,
              member_image_url: imageUrl,
              occupation: formData.occupation,
              support_need: formData.supportNeed,
              volunteer_id: user.id,
              organisation_id: user.organisationId,
              status: 'Pending'
          };

          const { error } = await supabase.from('members').insert(memberPayload);

          if (error) throw error;

          // Push to Google Sheets Ledger
          await syncToSheets(SheetType.MEMBERS, {
            ...memberPayload,
            volunteer_name: user.name,
            organisation_name: user.organisationName,
            submission_date: new Date().toLocaleDateString()
          });

          addNotification("Success: Member identity synchronized with global registry.", 'success');
          setFormData(initialFormData);
          setImagePreview(null);
          setStep(1);
          window.scrollTo(0, 0);
      } catch (err: any) {
          addNotification(`Registry Fault: ${getErrorMessage(err)}`, 'error');
      } finally {
          setIsSubmitting(false);
      }
  };

  return (
    <DashboardLayout title="Identity Enrollment Terminal">
      <div className="w-full max-w-4xl mx-auto space-y-6 md:space-y-8 pb-20">

          {/* Operator Context Banner */}
          <div className="bg-orange-600/5 border border-white/5 rounded-2xl p-4 flex flex-col sm:flex-row items-center justify-between gap-4">
              <div className="flex items-center gap-4">
                  <div className="p-3 bg-orange-600/10 rounded-xl text-orange-500">
                      <Fingerprint size={24} />
                  </div>
                  <div>
                      <p className="text-[9px] font-black uppercase tracking-[0.3em] text-gray-500 leading-none mb-1">Operator Profile</p>
                      <h4 className="text-sm md:text-base font-bold text-white uppercase tracking-tight">{user?.name}</h4>
                  </div>
              </div>
              <div className="text-center sm:text-right bg-black/40 px-4 py-2 rounded-xl border border-white/5">
                  <p className="text-[9px] font-black uppercase tracking-widest text-gray-600 mb-0.5">Sector Unit</p>
                  <p className="text-[10px] font-black text-orange-500 uppercase tracking-widest">{user?.organisationName}</p>
              </div>
          </div>

          {/* Sled-style Progress Bar */}
          <div className="relative pt-4 px-2">
              <div className="flex justify-between items-center mb-6 relative z-10">
                  {[1, 2, 3].map(s => (
                      <div key={s} className="flex flex-col items-center gap-2">
                          <div className={`h-10 w-10 rounded-full border flex items-center justify-center transition-all duration-500 ${step >= s ? 'bg-orange-600 border-orange-400 shadow-[0_0_20px_rgba(234,88,12,0.3)]' : 'bg-gray-950 border-gray-800 opacity-40'}`}>
                              <span className="text-xs font-black text-white">{s}</span>
                          </div>
                      </div>
                  ))}
              </div>
              <div className="absolute top-[2.2rem] left-0 w-full h-0.5 bg-gray-900 rounded-full overflow-hidden">
                  <div className="h-full bg-orange-600 transition-all duration-700" style={{ width: `${((step - 1) / 2) * 100}%` }}></div>
              </div>
          </div>

          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            {step === 1 && (
                <div className="max-w-xl mx-auto py-4">
                    <div className="relative">
                        <div className="absolute -inset-0.5 bg-gradient-to-r from-orange-600 to-orange-400 rounded-2xl blur-[2px] opacity-10"></div>

                        <Card className="relative bg-black border-white/10 border p-0 rounded-2xl overflow-hidden shadow-2xl">
                            <div className="p-6 md:p-8 space-y-8">
                                <div className="flex items-center gap-4 mb-2">
                                    <div className="p-3 bg-orange-500/10 rounded-xl text-orange-500">
                                        <ShieldCheck size={20} />
                                    </div>
                                    <div>
                                        <h3 className="text-lg font-cinzel text-white uppercase tracking-wider">Registry Validation</h3>
                                        <p className="text-[9px] font-black text-gray-500 uppercase tracking-widest mt-1">Tier 1 Verification</p>
                                    </div>
                                </div>

                                <div className="space-y-6">
                                    <Input 
                                        label="AADHAAR ID (12 DIGITS) *" 
                                        name="aadhaar" 
                                        value={formData.aadhaar} 
                                        onChange={handleChange} 
                                        maxLength={12} 
                                        placeholder="Enter 12-digit Aadhaar ID"
                                        description="Unique Biometric Identifier (As printed on card)"
                                        className="text-base font-mono tracking-[0.2em] bg-gray-950 border-white/5" 
                                        required
                                    />

                                    <Input 
                                        label="MOBILE NUMBER (10 DIGITS) *" 
                                        name="mobile" 
                                        type="tel" 
                                        value={formData.mobile} 
                                        onChange={handleChange} 
                                        maxLength={10} 
                                        placeholder="Enter 10-digit mobile number"
                                        description="Primary connection for system alerts"
                                        className="text-base font-mono tracking-[0.1em] bg-gray-950 border-white/5"
                                        required
                                    />

                                    {validationError && (
                                        <div className="flex items-start gap-3 p-4 bg-red-600/10 border border-red-500/20 rounded-xl animate-in shake duration-300">
                                            <ShieldAlert size={18} className="text-red-500 shrink-0 mt-0.5" />
                                            <p className="text-[11px] text-red-400 font-bold uppercase tracking-wider leading-relaxed">
                                                {validationError}
                                            </p>
                                        </div>
                                    )}
                                </div>

                                <div className="pt-4">
                                    <Button 
                                        onClick={handleStep1Next} 
                                        disabled={isValidating} 
                                        className="w-full py-4 text-[10px] font-black uppercase tracking-[0.4em] flex items-center justify-center gap-3 bg-orange-600 hover:bg-orange-500 transition-all rounded-xl shadow-lg shadow-orange-950/20"
                                    >
                                        {isValidating ? <RefreshCw className="animate-spin" size={16} /> : (
                                            <>
                                                <Search size={16} />
                                                Authorize Enrollment
                                            </>
                                        )}
                                    </Button>
                                    <p className="text-[8px] text-gray-700 text-center font-black uppercase tracking-[0.2em] mt-6">
                                        Data integrity is monitored by central authority
                                    </p>
                                </div>
                            </div>
                        </Card>
                    </div>
                </div>
            )}

            {step === 2 && (
                <Card title="Member Profile Enrollment" className="bg-[#050505] border-white/10 rounded-2xl p-6 md:p-10 shadow-2xl relative">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <Input label="GIVEN NAME *" name="name" value={formData.name} onChange={handleChange} placeholder="First and Middle" required />
                        <Input label="SURNAME *" name="surname" value={formData.surname} onChange={handleChange} placeholder="Family Name" required />
                        <Input label="FATHER / GUARDIAN NAME *" name="fatherName" value={formData.fatherName} onChange={handleChange} required />
                        <Input label="DATE OF BIRTH *" name="dob" type="date" value={formData.dob} onChange={handleChange} required />

                        <Select label="BIOLOGICAL GENDER *" name="gender" value={formData.gender} onChange={handleChange}>
                            {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
                        </Select>

                        <Input label="EMERGENCY CONTACT *" name="emergencyContact" value={formData.emergencyContact} onChange={handleChange} maxLength={10} placeholder="Emergency Ph No" required />
                        <Input label="POSTAL PINCODE *" name="pincode" value={formData.pincode} onChange={handleChange} maxLength={6} placeholder="6-digit Pincode" required />

                        <div className="md:col-span-2">
                            <Input label="FULL RESIDENTIAL ADDRESS *" name="address" value={formData.address} onChange={handleChange} placeholder="Complete Address Node" required />
                        </div>

                        <div className="md:col-span-2 pt-4">
                            <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-white mb-4">AADHAAR CARD DOCUMENT SCAN *</label>
                            <div className="flex flex-col items-center justify-center p-6 md:p-10 border-2 border-gray-900 border-dashed rounded-2xl bg-black/60 hover:border-orange-500/20 transition-all group">
                                {imagePreview ? (
                                    <div className="text-center">
                                        <div className="relative inline-block">
                                            <img src={imagePreview} className="mx-auto h-48 rounded-xl shadow-2xl border border-white/10" />
                                            <button 
                                                onClick={handleRemoveImage}
                                                className="absolute -top-3 -right-3 h-8 w-8 bg-red-600 text-white rounded-full flex items-center justify-center shadow-xl hover:bg-red-500 transition-all"
                                            >
                                                <XCircle size={18} />
                                            </button>
                                        </div>
                                        <p className="mt-4 text-[10px] font-black text-green-500 uppercase tracking-widest">Document Linked</p>
                                    </div>
                                ) : (
                                    <div className="flex flex-col items-center gap-6 w-full">
                                        <div className="p-4 bg-gray-900 rounded-xl text-gray-700 group-hover:text-orange-500 transition-colors">
                                            <FileText size={40} />
                                        </div>
                                        <div className="flex flex-col sm:flex-row gap-4 w-full sm:w-auto">
                                            <Button variant="secondary" onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-2 text-[10px] py-3 px-6 w-full sm:w-auto">
                                                <UploadCloud size={14} /> Upload Aadhaar Scan
                                            </Button>
                                            <input ref={fileInputRef} type="file" className="sr-only" onChange={handleFileChange} accept="image/*" />
                                        </div>
                                        <p className="text-[9px] text-gray-500 uppercase tracking-widest text-center">Supported formats: JPG, PNG, WEBP</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>

                    {validationError && (
                        <div className="mt-8 flex items-center gap-3 p-4 bg-red-600/10 border border-red-500/20 rounded-xl">
                            <ShieldAlert size={20} className="text-red-500 shrink-0" />
                            <p className="text-[11px] text-red-400 font-bold uppercase tracking-widest">{validationError}</p>
                        </div>
                    )}

                    <div className="mt-12 flex flex-col sm:flex-row justify-between gap-4">
                        <Button variant="secondary" onClick={() => { setStep(1); window.scrollTo(0, 0); }} className="w-full sm:w-auto py-3 px-8 text-[10px] uppercase font-black">Back</Button>
                        <Button onClick={handleStep2Next} className="w-full sm:w-auto py-3 px-10 text-[10px] uppercase font-black">Continue</Button>
                    </div>
                </Card>
            )}

            {step === 3 && (
                <Card title="Review Enrollment" className="bg-[#050505] border-white/10 rounded-2xl p-6 md:p-10">
                    <div className="space-y-10">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <Select label="PRIMARY OCCUPATION *" name="occupation" value={formData.occupation} onChange={handleChange}>
                                {Object.values(Occupation).map(o => <option key={o} value={o}>{o}</option>)}
                            </Select>
                            <Select label="SUPPORT NEED *" name="supportNeed" value={formData.supportNeed} onChange={handleChange}>
                                {Object.values(SupportNeed).map(s => <option key={s} value={s}>{s}</option>)}
                            </Select>
                        </div>

                        <div className="p-6 bg-orange-600/5 border border-orange-500/10 rounded-2xl flex flex-col md:flex-row items-start gap-6">
                            <div className="p-3 bg-orange-500/10 rounded-xl text-orange-500 shrink-0">
                                <ShieldCheck size={28} />
                            </div>
                            <div className="space-y-2">
                                <h4 className="text-sm font-bold text-white uppercase tracking-tight">Operator Certification</h4>
                                <p className="text-[10px] text-gray-500 leading-relaxed uppercase tracking-wider font-bold">
                                    I, {user?.name}, certify that the biometric ID (Aadhaar: {formData.aadhaar}) has been physically verified. I confirm that all entered data points match original documentation.
                                </p>
                            </div>
                        </div>
                    </div>

                    <div className="mt-12 flex flex-col sm:flex-row justify-between gap-4">
                        <Button variant="secondary" onClick={() => { setStep(2); window.scrollTo(0, 0); }} className="w-full sm:w-auto py-3 px-8 text-[10px] uppercase font-black">Edit Details</Button>
                        <Button onClick={handleSubmit} disabled={isSubmitting} className="w-full sm:w-auto py-4 px-12 text-[10px] font-black uppercase tracking-[0.3em] bg-orange-600 hover:bg-orange-500 rounded-xl">
                            {isSubmitting ? 'Syncing...' : 'Finalize Enrollment'}
                        </Button>
                    </div>
                </Card>
            )}
          </div>
      </div>
    </DashboardLayout>
  );
};

const XCircle = ({ size }: { size: number }) => (
    <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>
);

export default NewMemberForm;

import React, { useState, useEffect, useCallback } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { Organisation, Role } from '../../types';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { syncToSheets, SheetType } from '../../services/googleSheets';
import { 
  ShieldCheck, 
  UserPlus, 
  Building2, 
  Loader2, 
  ShieldAlert, 
  Copy, 
  ExternalLink, 
  RefreshCw,
  CheckCircle2,
  Settings,
  Zap,
  Activity,
  Eye,
  EyeOff,
  Mail,
  Lock,
  Phone,
  User,
  Trash2,
  AlertTriangle
} from 'lucide-react';

const ManageOrganisations: React.FC = () => {
  const [organisations, setOrganisations] = useState<Organisation[]>([]);
  const [newOrg, setNewOrg] = useState({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [orgToDelete, setOrgToDelete] = useState<Organisation | null>(null);

  // UI States
  const [showPassword, setShowPassword] = useState(false);
  const [showEditPassword, setShowEditPassword] = useState(false);
  const [showEditPasswordReveal, setShowEditPasswordReveal] = useState(false);

  const { addNotification } = useNotification();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrg, setEditingOrg] = useState<(Organisation & { email?: string, newPassword?: string }) | null>(null);

  const fetchOrganisations = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('organisations').select('*').order('name');
      if (error) {
        addNotification(`Registry error: ${error.message}`, 'error');
      } else {
        setOrganisations(data || []);
      }
    } catch (err: any) {
      addNotification(`Sync failed: ${err?.message || 'Unknown network error'}`, 'error');
    }
    setLoading(false);
  }, [addNotification]);

  useEffect(() => {
    fetchOrganisations();
  }, [fetchOrganisations]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewOrg(prev => ({ ...prev, [name]: value }));
  };

  const handleAddOrganisation = async () => {
    const email = newOrg.email.trim().toLowerCase();
    const password = newOrg.password;
    const name = newOrg.name.trim();
    const mobile = newOrg.mobile.trim();
    const secretaryName = newOrg.secretaryName.trim();

    if (!email || !password || !name || !mobile || !secretaryName) {
        addNotification("Incomplete credentials provided.", 'error');
        return;
    }

    setIsSubmitting(true);
    let createdOrgId: string | null = null;

    try {
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ name, mobile, secretary_name: secretaryName, status: 'Active' })
          .select().single();

        if (orgError) throw orgError;
        createdOrgId = orgData.id;

        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              name: secretaryName,
              role: 'Organisation',
              organisation_id: createdOrgId,
              mobile
            }
          }
        });

        if (authError) {
          if (createdOrgId) await supabase.from('organisations').delete().eq('id', createdOrgId);
          throw authError;
        }

        if (authData?.user?.id) {
            await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: secretaryName,
                email,
                role: 'Organisation',
                organisation_id: createdOrgId,
                mobile,
                status: 'Active'
            });
        }

        // Push to Google Sheets Ledger
        await syncToSheets(SheetType.ORGANISATIONS, {
          name,
          secretary_name: secretaryName,
          mobile,
          email,
          status: 'Active',
          registration_date: new Date().toLocaleDateString()
        });

        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
        addNotification('Sector authorised successfully.', 'success');
    } catch (err: any) {
        addNotification(err?.message || 'Handshake failed.', 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleEditClick = async (org: Organisation) => {
    setLoading(true);
    try {
      const { data: profile } = await supabase
        .from('profiles')
        .select('email')
        .eq('organisation_id', org.id)
        .eq('role', 'Organisation')
        .maybeSingle();

      setEditingOrg({ 
        ...org, 
        email: profile?.email || '',
        newPassword: ''
      });
      setShowEditPassword(false);
      setShowEditPasswordReveal(false);
      setIsModalOpen(true);
    } catch (err) {
      setEditingOrg({ ...org, email: '', newPassword: '' });
      setIsModalOpen(true);
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteOrganisation = async () => {
    if (!orgToDelete) return;
    setIsDeleting(true);
    try {
      const { error } = await supabase
        .from('organisations')
        .delete()
        .eq('id', orgToDelete.id);

      if (error) throw error;

      await supabase.from('profiles').delete().eq('organisation_id', orgToDelete.id);

      addNotification(`${orgToDelete.name} node purged from registry.`, 'success');
      setOrgToDelete(null);
      fetchOrganisations();
    } catch (err: any) {
      addNotification(`Purge failed: ${err.message}`, 'error');
    } finally {
      setIsDeleting(false);
    }
  };

  const handleUpdateOrganisation = async () => {
    if (!editingOrg) return;
    setIsSubmitting(true);

    try {
      const { error: orgError } = await supabase.from('organisations').update({
          name: editingOrg.name, 
          mobile: editingOrg.mobile,
          secretary_name: editingOrg.secretary_name, 
          status: editingOrg.status
      }).eq('id', editingOrg.id);

      if (orgError) throw orgError;

      const { error: profileError } = await supabase.from('profiles').update({
          name: editingOrg.secretary_name,
          mobile: editingOrg.mobile,
          email: editingOrg.email,
          status: editingOrg.status
      }).eq('organisation_id', editingOrg.id).eq('role', 'Organisation');

      if (editingOrg.newPassword) {
          addNotification("Auth key rotation requires high-level privileges. Metadata synced.", "info");
      } else {
          addNotification(`Sector parameters updated.`, 'success');
      }

      fetchOrganisations();
      setIsModalOpen(false);
    } catch (err: any) {
        addNotification(`Update failed: ${err.message}`, 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <DashboardLayout title="Sector Management">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        <div className="lg:col-span-1 space-y-8">
          <Card title="Authorise New Sector" className="border-orange-500/10 relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                <ShieldCheck size={100} />
            </div>
            <div className="space-y-6 relative z-10">
              <Input label="Organisation Name" name="name" value={newOrg.name} onChange={handleInputChange} placeholder="Ex: SSK Bangalore" icon={<Building2 size={16} />} />
              <Input label="Primary Mobile" name="mobile" value={newOrg.mobile} onChange={handleInputChange} placeholder="91XXXXXXXX" icon={<Phone size={16} />} />
              <Input label="Secretary Name" name="secretaryName" value={newOrg.secretaryName} onChange={handleInputChange} icon={<User size={16} />} />
              <Input label="Access Email" name="email" type="email" value={newOrg.email} onChange={handleInputChange} placeholder="admin@node.com" icon={<Mail size={16} />} />

              <div className="relative">
                <Input 
                  label="Access Key" 
                  name="password" 
                  type={showPassword ? "text" : "password"} 
                  value={newOrg.password} 
                  onChange={handleInputChange} 
                  placeholder="Min 6 characters" 
                  icon={<Lock size={16} />}
                />
                <button 
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-[34px] text-gray-500 hover:text-white transition-colors"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>

              <Button type="button" onClick={handleAddOrganisation} disabled={isSubmitting} className="w-full py-5 flex items-center justify-center gap-3 text-[11px] font-black uppercase tracking-widest shadow-xl">
                {isSubmitting ? <Loader2 className="animate-spin" size={18} /> : <UserPlus size={18} />}
                {isSubmitting ? 'ESTABLISHING...' : 'Deploy Sector'}
              </Button>
            </div>
          </Card>
        </div>

        <div className="lg:col-span-2 space-y-6">
          <Card title="Operational Sector Registry">
            <div className="flex justify-between items-center mb-10">
                <div className="flex items-center gap-4 text-gray-500">
                    <div className="p-2 bg-orange-500/10 rounded-lg text-orange-500">
                        <Activity size={16} />
                    </div>
                    <span className="text-[10px] font-black uppercase tracking-widest">Master Node Synchronisation</span>
                </div>
                <button onClick={fetchOrganisations} className="p-3 bg-white/5 rounded-xl border border-white/5 hover:border-orange-500/40 text-gray-500 hover:text-white transition-all">
                    <RefreshCw size={16} className={loading ? 'animate-spin' : ''} />
                </button>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead className="border-b border-gray-800">
                        <tr>
                            <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black">Organisation Identity</th>
                            <th className="p-6 text-[10px] uppercase tracking-widest text-gray-500 font-black text-right">Verification</th>
                            <th className="p-6"></th>
                        </tr>
                    </thead>
                    <tbody>
                        {loading ? (
                             <tr><td colSpan={3} className="p-20 text-center animate-pulse uppercase tracking-[0.5em] text-[10px] text-gray-600 font-black">Syncing Network...</td></tr>
                        ) : organisations.map(org => (
                        <tr key={org.id} className="group border-b border-gray-900/50 hover:bg-white/[0.02] transition-all">
                            <td className="p-6">
                                <div className="flex flex-col gap-1">
                                    <div className="flex items-center gap-3">
                                        <span className="font-bold text-white text-lg group-hover:text-orange-500 transition-colors">{org.name}</span>
                                        {org.status === 'Active' && <CheckCircle2 size={14} className="text-green-500/50" />}
                                    </div>
                                    <span className="text-[11px] text-gray-600 uppercase font-mono tracking-tighter">{org.secretary_name} • {org.mobile}</span>
                                </div>
                            </td>
                            <td className="p-6 text-right">
                                <span className={`px-4 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-full border ${ org.status === 'Active' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20' }`}>
                                    {org.status}
                                </span>
                            </td>
                            <td className="p-6 text-right">
                                <div className="flex items-center justify-end gap-3 opacity-0 group-hover:opacity-100 transition-all">
                                    <Button size="sm" variant="secondary" onClick={() => handleEditClick(org)} className="scale-95 hover:scale-100">Modify Node</Button>
                                    <button 
                                        onClick={() => setOrgToDelete(org)}
                                        className="p-2 text-red-500/40 hover:text-red-500 hover:bg-red-500/10 rounded-lg transition-all"
                                        title="Purge Sector"
                                    >
                                        <Trash2 size={18} />
                                    </button>
                                </div>
                            </td>
                        </tr>
                        ))}
                    </tbody>
                </table>
            </div>
          </Card>
        </div>
      </div>

      {/* Edit Modal */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Modify Sector Parameters">
          {editingOrg && (
            <div className="space-y-6 p-2 max-h-[80vh] overflow-y-auto custom-scrollbar">
                <div className="flex items-center gap-4 mb-6 p-5 bg-orange-500/5 border border-orange-500/10 rounded-2xl relative overflow-hidden">
                    <div className="p-3 bg-orange-500/10 rounded-xl text-orange-500">
                        <Settings size={20} />
                    </div>
                    <div className="relative z-10">
                        <p className="text-[10px] text-orange-500/60 font-black uppercase tracking-widest leading-none mb-1">Administrative Override</p>
                        <p className="text-sm font-bold text-white">Target Node: {editingOrg.name}</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="md:col-span-2">
                    <Input 
                      label="ORGANISATION NAME" 
                      name="name" 
                      value={editingOrg.name} 
                      onChange={(e) => setEditingOrg({...editingOrg, name: e.target.value})} 
                      icon={<Building2 size={16} />}
                    />
                  </div>

                  <Input 
                    label="SECRETARY NAME" 
                    name="secretary_name" 
                    value={editingOrg.secretary_name} 
                    onChange={(e) => setEditingOrg({...editingOrg, secretary_name: e.target.value})} 
                    icon={<User size={16} />}
                  />

                  <Input 
                    label="CONTACT MOBILE" 
                    name="mobile" 
                    value={editingOrg.mobile} 
                    onChange={(e) => setEditingOrg({...editingOrg, mobile: e.target.value})} 
                    icon={<Phone size={16} />}
                  />

                  <div className="md:col-span-2">
                    <Input 
                      label="OPERATIONAL EMAIL" 
                      name="email" 
                      type="email"
                      value={editingOrg.email || ''} 
                      onChange={(e) => setEditingOrg({...editingOrg, email: e.target.value})} 
                      icon={<Mail size={16} />}
                    />
                  </div>

                  <div className="md:col-span-2">
                    <div className="flex items-center justify-between mb-2">
                      <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Access Key Override</label>
                      <button 
                        type="button"
                        onClick={() => setShowEditPassword(!showEditPassword)}
                        className="text-[10px] font-black uppercase tracking-widest text-orange-500 hover:text-orange-400 transition-colors"
                      >
                        {showEditPassword ? "Cancel" : "Modify Key"}
                      </button>
                    </div>
                    {showEditPassword && (
                      <div className="relative animate-in slide-in-from-top-2 fade-in">
                        <Input 
                          placeholder="New Security Key" 
                          type={showEditPasswordReveal ? "text" : "password"}
                          value={editingOrg.newPassword || ''}
                          onChange={(e) => setEditingOrg({...editingOrg, newPassword: e.target.value})}
                          icon={<Lock size={16} />}
                        />
                        <button 
                          type="button" 
                          onClick={() => setShowEditPasswordReveal(!showEditPasswordReveal)}
                          className="absolute right-3 top-[10px] text-gray-500 hover:text-white transition-colors"
                        >
                          {showEditPasswordReveal ? <EyeOff size={18} /> : <Eye size={18} />}
                        </button>
                      </div>
                    )}
                  </div>

                  <div className="md:col-span-2">
                    <Select label="OPERATIONAL STATUS" name="status" value={editingOrg.status} onChange={(e) => setEditingOrg({...editingOrg, status: e.target.value as any})}>
                        <option value="Active">Active / Online</option>
                        <option value="Deactivated">Deactivated / Locked</option>
                    </Select>
                  </div>
                </div>

                <div className="flex justify-end gap-4 pt-10 sticky bottom-0 bg-gray-900 pb-2 border-t border-white/5 mt-6 z-10">
                    <Button type="button" variant="secondary" onClick={() => setIsModalOpen(false)} className="px-8 border-white/10 hover:bg-white/5 py-4 text-[10px] uppercase font-black tracking-widest">Cancel</Button>
                    <Button 
                      type="button" 
                      onClick={handleUpdateOrganisation} 
                      disabled={isSubmitting}
                      className="px-8 shadow-lg shadow-orange-950/20 py-4 text-[10px] uppercase font-black tracking-widest flex items-center gap-2"
                    >
                      {isSubmitting ? <Loader2 size={16} className="animate-spin" /> : <Zap size={16} />}
                      {isSubmitting ? "Syncing..." : "Apply Changes"}
                    </Button>
                </div>
            </div>
          )}
      </Modal>

      {/* Delete Confirmation Modal */}
      <Modal isOpen={!!orgToDelete} onClose={() => setOrgToDelete(null)} title="Security Protocol: Node Purge">
        <div className="p-6 text-center space-y-8">
            <div className="p-6 bg-red-500/10 rounded-full w-24 h-24 mx-auto flex items-center justify-center text-red-500 border border-red-500/20 shadow-[0_0_30px_rgba(239,68,68,0.2)]">
                <AlertTriangle size={48} />
            </div>
            <div>
                <h4 className="text-2xl font-cinzel text-white mb-3">Irreversible Purge</h4>
                <p className="text-sm text-gray-500 leading-relaxed uppercase tracking-widest font-black">
                    You are about to purge <span className="text-red-500">"{orgToDelete?.name}"</span>. 
                    This will disconnect all associated personnel and data nodes.
                </p>
            </div>
            <div className="flex gap-4">
                <Button variant="secondary" onClick={() => setOrgToDelete(null)} className="flex-1 py-4 text-[10px] font-black uppercase tracking-widest">Abort</Button>
                <Button 
                    onClick={handleDeleteOrganisation} 
                    disabled={isDeleting}
                    className="flex-1 bg-red-600 hover:bg-red-700 py-4 text-[10px] font-black uppercase tracking-widest shadow-xl shadow-red-950/20"
                >
                    {isDeleting ? 'PURGING...' : 'Confirm Purge'}
                </Button>
            </div>
        </div>
      </Modal>
    </DashboardLayout>
  );
};

