import { supabase } from '../supabase/client';
import { Member, Organisation, Role } from '../types';
import { Users, RefreshCw, Globe, Activity } from 'lucide-react';

const LandingPage: React.FC = () => {
  const [members, setMembers] = useState<Member[]>([]);
