      {/* Live Analytics Dashboard */}
      <main className="container mx-auto px-4 md:px-6 py-12 md:py-24 space-y-24 md:space-y-32">
        <section id="analytics">
          <div className="flex flex-col items-center mb-12 md:mb-16">
