import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { syncToSheets, SheetType } from '../../services/googleSheets';
import { 
  Power, 
  Download, 
  UserPlus, 
  UserCheck, 
  Copy, 
  ShieldCheck, 
  Loader2, 
  UserCircle, 
  Zap, 
  RefreshCw, 
  Activity,
  FileSpreadsheet,
  ShieldAlert
} from 'lucide-react';

type VolunteerWithEnrollments = Volunteer & { enrollments: number };

const ManageVolunteers: React.FC = () => {
  const { user } = useAuth();
  const [volunteers, setVolunteers] = useState<VolunteerWithEnrollments[]>([]);
  const [newVol, setNewVol] = useState({ name: '', mobile: '', email: '', password: '' });
  const [loading, setLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { addNotification } = useNotification();

  const fetchVolunteers = useCallback(async () => {
    if (!user?.organisationId) return;
    setLoading(true);

    try {
        const { data: profileData, error: profileError } = await supabase
          .from('profiles')
          .select('*, members(id)')
          .eq('role', 'Volunteer')
          .eq('organisation_id', user.organisationId);

        if (profileError) throw profileError;

        setVolunteers(profileData.map((v: any) => ({
            id: v.id,
            name: v.name,
            email: v.email,
            mobile: v.mobile,
            role: Role.Volunteer,
            organisationId: v.organisation_id,
            organisationName: user.organisationName,
            status: v.status || 'Active',
            enrollments: v.members?.length || 0
        })) || []);
    } catch (e: any) {
        addNotification(`Uplink Error: ${e.message}`, 'error');
    } finally {
        setLoading(false);
    }
  }, [user, addNotification]);

  useEffect(() => {
    fetchVolunteers();
  }, [fetchVolunteers]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewVol(prev => ({ ...prev, [name]: value }));
  };

  const handleExport = () => {
    const headers = ['Agent Name', 'Email', 'Mobile', 'Enrollments', 'Status'];
    const rows = volunteers.map(v => [
        v.name,
        v.email,
        v.mobile,
        v.enrollments,
        v.status
    ]);
    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `Agent_Registry_${user?.organisationName || 'Sector'}.csv`;
    link.click();
  };

  const handleAddVolunteer = async () => {
    const email = newVol.email.trim().toLowerCase();
    const password = newVol.password;
    const name = newVol.name.trim();
    const mobile = newVol.mobile.trim();

    if (!user?.organisationId) return;
    if (!email || !password || !name || !mobile) {
        addNotification("Incomplete identity data.", 'error');
        return;
    }

    setIsSubmitting(true);
    try {
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              name,
              mobile,
              role: 'Volunteer', 
              organisation_id: user.organisationId
            }
          }
        });

        if (authError) throw authError;

        if (authData?.user?.id) {
            const { error: profileError } = await supabase.from('profiles').upsert({
                id: authData.user.id,
                name,
                email,
                role: 'Volunteer',
                organisation_id: user.organisationId,
                mobile,
                status: 'Active'
            });

            if (profileError) throw profileError;

            await syncToSheets(SheetType.VOLUNTEERS, {
              name,
              email,
              mobile,
              organisation_name: user.organisationName,
              status: 'Active',
              authorized_date: new Date().toLocaleDateString()
            });

            addNotification('Agent authorized successfully.', 'success');
            setNewVol({ name: '', mobile: '', email: '', password: '' });
            fetchVolunteers(); 
        }
    } catch (err: any) {
        addNotification(err.message, 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <DashboardLayout title="Agent Authorization Hub">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        <div className="lg:col-span-1 space-y-8">
          <Card title="Authorize New Agent" className="relative overflow-hidden border-blue-900/30 bg-[#020202]/80">
            <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
              <Zap size={100} />
            </div>
            <div className="space-y-6 relative z-10">
              <div className="flex items-center gap-4 p-5 bg-blue-500/5 border border-blue-500/10 rounded-2xl mb-4">
                 <ShieldCheck className="text-blue-500" size={24} />
                 <div className="flex flex-col">
                    <span className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400/80 leading-tight">Identity Tier</span>
                    <span className="text-xs font-bold text-white uppercase">Field Operator</span>
                 </div>
              </div>

              <Input label="FULL NAME" name="name" value={newVol.name} onChange={handleInputChange} placeholder="Ex: Rahul S" />
              <Input label="MOBILE IDENTITY" name="mobile" type="tel" value={newVol.mobile} onChange={handleInputChange} placeholder="91XXXXXXXX" />
              <Input label="ACCESS EMAIL" name="email" type="email" value={newVol.email} onChange={handleInputChange} placeholder="agent@ssk.com" />
              <Input label="SECURITY KEY" name="password" type="password" value={newVol.password} onChange={handleInputChange} placeholder="Min 6 characters" />

              <Button 
                type="button" 
                onClick={handleAddVolunteer} 
                disabled={isSubmitting} 
                className="w-full py-5 flex items-center justify-center gap-3 text-[11px] font-black uppercase tracking-[0.4em]"
              >
                {isSubmitting ? <Loader2 className="animate-spin" size={20} /> : <UserPlus size={20} />}
                {isSubmitting ? 'AUTHORIZING...' : 'Authorize Agent'}
              </Button>
            </div>
          </Card>
        </div>

        <div className="lg:col-span-2">
          <Card className="bg-[#050505] border-white/5 h-full">
            <div className="flex justify-between items-center mb-12">
                <div className="flex items-center gap-5">
                    <div className="p-4 bg-orange-500/10 rounded-3xl text-orange-500 border border-orange-500/10">
                        <UserCircle size={28} />
                    </div>
                    <div>
                      <h3 className="font-cinzel text-3xl text-white tracking-tight">Active Agent Registry</h3>
                      <div className="flex items-center gap-2 mt-1">
                          <Activity size={12} className="text-green-500 animate-pulse" />
                          <span className="text-[9px] text-gray-600 font-black uppercase tracking-widest">Network Node Active</span>
                      </div>
                    </div>
                </div>
                <div className="flex gap-4">
                    <button 
                      onClick={handleExport}
                      className="p-4 bg-blue-600 hover:bg-blue-700 rounded-2xl text-white transition-all shadow-xl flex items-center gap-2 text-[10px] font-black uppercase tracking-widest"
                    >
                        <FileSpreadsheet size={20} />
                        <span className="hidden sm:inline">Export CSV</span>
                    </button>
                    <button 
                      onClick={fetchVolunteers} 
                      className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:border-orange-500/40 text-gray-500 hover:text-white transition-all shadow-xl"
                    >
                        <RefreshCw size={20} className={loading ? 'animate-spin' : ''} />
                    </button>
                </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="border-b border-gray-800">
                  <tr>
                    <th className="p-6 text-[10px] uppercase tracking-[0.4em] text-gray-500 font-black">Personnel Node</th>
                    <th className="p-6 text-[10px] uppercase tracking-[0.4em] text-gray-500 font-black text-center">Enrollments</th>
                    <th className="p-6 text-[10px] uppercase tracking-[0.4em] text-gray-500 font-black text-right">Node Action</th>
                  </tr>
                </thead>
                <tbody>
                  {volunteers.map(vol => (
                    <tr key={vol.id} className="group border-b border-gray-900/50 hover:bg-white/[0.015] transition-all">
                      <td className="p-6">
                        <div className="flex flex-col gap-2">
                            <span className="font-bold text-white text-lg group-hover:text-orange-500 transition-colors">{vol.name}</span>
                            <div className="flex items-center gap-3">
                                <span className="text-[10px] text-gray-600 font-mono tracking-tight">{vol.email}</span>
                                <span className="h-1 w-1 rounded-full bg-gray-700"></span>
                                <span className="text-[10px] text-gray-600 font-mono tracking-tight">{vol.mobile}</span>
                            </div>
                        </div>
                      </td>
                      <td className="p-6 text-center">
                        <div className="inline-flex items-center gap-4 px-6 py-3 bg-white/[0.03] border border-white/5 rounded-[1.5rem]">
                            <UserCheck size={18} className="text-orange-500" />
                            <span className="font-black text-xl text-white tracking-tighter">{vol.enrollments}</span>
                        </div>
                      </td>
                      <td className="p-6 text-right">
                        <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-all translate-x-4 group-hover:translate-x-0 duration-500">
                            <button onClick={() => copyVolunteerCreds(vol)} className="p-4 bg-gray-950 border border-white/5 text-gray-600 hover:text-orange-500 rounded-2xl transition-all">
                                <Copy size={18} />
                            </button>
                            <button 
                                onClick={() => handleToggleStatus(vol)}
                                className={`p-4 rounded-2xl border transition-all ${vol.status === 'Active' ? 'text-red-400 border-red-500/10 bg-red-500/5' : 'text-green-400 border-green-500/10 bg-green-500/5'}`}
                            >
                                <Power size={18} />
                            </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Card>
        </div>
      </div>
    </DashboardLayout>
  );
};

export default ManageVolunteers;

import React, { useState, useMemo, useEffect } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import { useAuth } from '../../context/AuthContext';
import { Member, MemberStatus } from '../../types';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../../supabase/client';
import { useNotification } from '../../context/NotificationContext';
import { User, RefreshCw, Clock, Filter, Search, MapPin, Phone, Building2, UserCircle, Activity } from 'lucide-react';

type MemberWithAttribution = Member & {
    agent?: {
        name: string;
        organisations?: {
            name: string;
        }
    }
};

const VolunteerDashboard: React.FC = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [mySubmissions, setMySubmissions] = useState<MemberWithAttribution[]>([]);
    const [loading, setLoading] = useState(true);
    const { addNotification } = useNotification();

    const fetchSubmissions = async () => {
        if (!user?.id) return;
        setLoading(true);
        try {
            const { data, error } = await supabase
                .from('members')
                .select(`
                    *,
                    agent:profiles!volunteer_id (
                        name,
                        organisations (name)
                    )
                `)
                .eq('volunteer_id', user.id)
                .order('submission_date', { ascending: false });

            if (error) throw error;
            if (data) setMySubmissions(data as MemberWithAttribution[]);
        } catch (err: any) {
            addNotification(`Sync Fault: ${err.message}`, 'error');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchSubmissions();
    }, [user, addNotification]);

    const [filters, setFilters] = useState({
        startDate: '',
        endDate: '',
        phone: '',
        area: '', 
    });

    const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
    };

    const filteredSubmissions = useMemo(() => {
        return mySubmissions.filter(member => {
            const submissionDate = new Date(member.submission_date);
            const start = filters.startDate ? new Date(filters.startDate) : null;
            const end = filters.endDate ? new Date(filters.endDate) : null;
            if (end) end.setHours(23, 59, 59, 999);

            if (start && submissionDate < start) return false;
            if (end && submissionDate > end) return false;
            if (filters.phone && !member.mobile.includes(filters.phone)) return false;
            if (filters.area && !member.pincode.includes(filters.area)) return false;
            return true;
        });
    }, [mySubmissions, filters]);

    return (
        <DashboardLayout title="Agent Command Hub">
            <div className="space-y-10">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-10 p-10 bg-blue-900/10 border border-blue-900/20 rounded-[3rem] shadow-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-10 opacity-[0.03] group-hover:rotate-12 transition-transform duration-700 pointer-events-none">
                        <User size={150} />
                    </div>
                    <div className="flex gap-8 items-center relative z-10">
                         <div className="p-6 bg-blue-500/10 rounded-3xl text-blue-400 border border-blue-400/20 shadow-xl group-hover:scale-105 transition-transform">
                            <User size={40} strokeWidth={1.5} />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-blue-400/60 mb-2">Authenticated Field Agent</p>
                            <h2 className="font-cinzel text-4xl text-white tracking-tighter leading-none">{user?.name}</h2>
                        </div>
                    </div>
                    <div className="flex gap-4 w-full md:w-auto relative z-10">
                        <button onClick={fetchSubmissions} className="p-5 bg-white/5 rounded-2xl border border-white/5 hover:border-blue-500/40 transition-all text-gray-500 hover:text-white shadow-lg">
                            <RefreshCw size={24} className={loading ? 'animate-spin' : ''} />
                        </button>
                        <Button onClick={() => navigate('/volunteer/new-member')} className="flex-1 md:flex-none py-5 px-12 text-[10px] font-black uppercase tracking-widest shadow-[0_20px_40px_-10px_rgba(59,130,246,0.3)] bg-blue-600 hover:bg-blue-500">
                            Enroll New Member
                        </Button>
                    </div>
                </div>

                <Card className="border-white/5 bg-gray-900/20 backdrop-blur-md p-8 rounded-[2rem]">
                    <div className="flex items-center gap-2 mb-6 text-gray-500">
                        <Filter size={14} />
                        <span className="text-[10px] font-black uppercase tracking-widest">Registry Query</span>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                        <Input label="ENROLLMENT START" type="date" name="startDate" value={filters.startDate} onChange={handleFilterChange} />
                        <Input label="ENROLLMENT END" type="date" name="endDate" value={filters.endDate} onChange={handleFilterChange} />
                        <Input label="MEMBER CONTACT" name="phone" placeholder="91XXXXXXXX" value={filters.phone} onChange={handleFilterChange} icon={<Phone size={14} />} />
                        <Input label="SECTOR PINCODE" name="area" placeholder="560XXX" value={filters.area} onChange={handleFilterChange} icon={<MapPin size={14} />} />
                    </div>
                </Card>

                <Card title="Agent Field Activity Registry" className="bg-[#050505] border-white/5 rounded-[2.5rem]">
                    <div className="overflow-x-auto">
                      <table className="w-full text-left">
                        <thead className="border-b border-white/5">
                          <tr>
                            <th className="p-6 text-[10px] uppercase tracking-widest text-gray-600 font-black">Member Node</th>
                            <th className="p-6 text-[10px] uppercase tracking-widest text-blue-500 font-black">Agent Attribution</th>
                            <th className="p-6 text-[10px] uppercase tracking-widest text-gray-600 font-black text-center">Status</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-white/[0.02]">
                          {loading ? (
                              <tr><td colSpan={3} className="text-center p-32 animate-pulse text-[10px] uppercase tracking-[0.4em] text-gray-700 font-black">Syncing Network...</td></tr>
                          ) : (
                            <>
                            {filteredSubmissions.map(member => (
                              <tr key={member.id} className="group hover:bg-white/[0.01] transition-all duration-300">
                                <td className="p-6">
                                    <div className="flex flex-col gap-1">
                                        <div className="flex items-center gap-3">
                                            <span className="font-bold text-white text-lg group-hover:text-blue-400 transition-colors">{member.name} {member.surname}</span>
                                        </div>
                                        <div className="flex items-center gap-2 text-[10px] text-gray-600 font-mono tracking-tighter">
                                          <Phone size={10} /> {member.mobile}
                                        </div>
                                    </div>
                                </td>
                                <td className="p-6">
                                    <div className="flex items-center gap-4">
                                        <div className="h-10 w-10 rounded-xl bg-blue-500/10 border border-blue-500/20 flex items-center justify-center text-blue-500 shadow-inner">
                                            <UserCircle size={20} />
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[11px] font-black text-white uppercase tracking-widest">
                                                {member.agent?.name || user?.name}
                                            </span>
                                            <div className="flex items-center gap-2 mt-0.5">
                                                <Building2 size={10} className="text-orange-500" />
                                                <span className="text-[9px] font-black text-orange-500/80 uppercase tracking-widest">
                                                    {member.agent?.organisations?.name || user?.organisationName || 'Independent'}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                </td>
                                <td className="p-6 text-center">
                                  <div className="flex flex-col items-center gap-2">
                                    <span className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border shadow-sm ${
                                        member.status === MemberStatus.Accepted ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20'
                                    }`}>
                                      {member.status}
                                    </span>
                                    <span className="text-[9px] font-mono text-gray-600 uppercase tracking-tighter">{member.submission_date.split('T')[0]}</span>
                                  </div>
                                </td>
                              </tr>
                            ))}
                            </>
                          )}
                        </tbody>
                      </table>
                    </div>
                </Card>
            </div>
        </DashboardLayout>
    );
};

export default VolunteerDashboard;

