    if (!email || !password || !name || !mobile || !secretaryName) {
        addNotification("Incomplete credentials provided.", 'error');
        return;
    }

    setIsSubmitting(true);
    let createdOrgId: string | null = null;

    try {
        const { data: orgData, error: orgError } = await supabase
          .from('organisations')
          .insert({ name, mobile, secretary_name: secretaryName, status: 'Active' })
          .select().single();

        if (orgError) throw orgError;
        createdOrgId = orgData.id;

        // CRITICAL: Use a separate client that DOES NOT persist session 
        // to prevent the current Admin from being logged out.
        const authClient = createClient(supabaseUrl, supabaseAnonKey, {
            auth: {
                persistSession: false,
                autoRefreshToken: false,
                detectSessionInUrl: false
            }
        });

        const { data: authData, error: authError } = await authClient.auth.signUp({
          email,
          password,
          options: {
            data: {
              name: secretaryName,
              role: 'Organisation',
              organisation_id: createdOrgId,
              mobile
            }
          }
        });

        if (authError) {
          if (createdOrgId) await supabase.from('organisations').delete().eq('id', createdOrgId);
          throw authError;
        }

        if (authData?.user?.id) {
            await supabase.from('profiles').upsert({
                id: authData.user.id,
                name: secretaryName,
                email,
                role: 'Organisation',
                organisation_id: createdOrgId,
                mobile,
                status: 'Active'
            });
        }

        // Push to Google Sheets Ledger
        await syncToSheets(SheetType.ORGANISATIONS, {
          name,
          secretary_name: secretaryName,
          mobile,
          email,
          status: 'Active',
          registration_date: new Date().toLocaleDateString()
        });

        setNewOrg({ name: '', mobile: '', secretaryName: '', email: '', password: '' });
        fetchOrganisations();
        addNotification('Sector authorised successfully.', 'success');
    } catch (err: any) {
        addNotification(err?.message || 'Handshake failed.', 'error');
    } finally {
        setIsSubmitting(false);
    }
  };

