import React, { useState, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import Button from '../../components/ui/Button';
import { Gender, Occupation, SupportNeed } from '../../types';
import { supabase } from '../../supabase/client';
import { useAuth } from '../../context/AuthContext';
import { useNotification } from '../../context/NotificationContext';
import { syncToSheets, SheetType } from '../../services/googleSheets';
import { ShieldAlert, RefreshCw, Fingerprint, ShieldCheck, Search, XCircle, ImageIcon } from 'lucide-react';

const initialFormData = {
  aadhaar: '',
  mobile: '',
  name: '',
  surname: '',
  fatherName: '',
  dob: '',
  gender: Gender.Male,
  emergencyContact: '',
  pincode: '',
  address: '',
  aadhaarFront: null as File | null,
  aadhaarBack: null as File | null,
  occupation: Occupation.Job,
  supportNeed: SupportNeed.Education,
};

const NewMemberForm: React.FC = () => {
  const { user } = useAuth();
  const { addNotification } = useNotification();
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState(initialFormData);
  const [validationError, setValidationError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [frontPreview, setFrontPreview] = useState<string | null>(null);
  const [backPreview, setBackPreview] = useState<string | null>(null);

  const frontInputRef = useRef<HTMLInputElement>(null);
  const backInputRef = useRef<HTMLInputElement>(null);

  const formatInput = (text: string) => {
      return text.trim().toLowerCase().split(' ').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    if ((name === 'aadhaar' || name === 'mobile' || name === 'emergencyContact' || name === 'pincode') && value !== '' && !/^\d+$/.test(value)) return;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, side: 'front' | 'back') => {
    if (e.target.files && e.target.files[0]) {
        const file = e.target.files[0];
        if (side === 'front') {
            setFormData(prev => ({ ...prev, aadhaarFront: file }));
            if(frontPreview) URL.revokeObjectURL(frontPreview);
            setFrontPreview(URL.createObjectURL(file));
        } else {
            setFormData(prev => ({ ...prev, aadhaarBack: file }));
            if(backPreview) URL.revokeObjectURL(backPreview);
            setBackPreview(URL.createObjectURL(file));
        }
    }
  };

  const handleRemoveImage = (side: 'front' | 'back') => {
    if (side === 'front') {
        if (frontPreview) URL.revokeObjectURL(frontPreview);
        setFormData(prev => ({ ...prev, aadhaarFront: null }));
        setFrontPreview(null);
    } else {
        if (backPreview) URL.revokeObjectURL(backPreview);
        setFormData(prev => ({ ...prev, aadhaarBack: null }));
        setBackPreview(null);
    }
  };

  const handleStep1Next = async () => {
    setValidationError('');
    if (!formData.aadhaar || !formData.mobile) {
        setValidationError('Action Required: Identity Number and Primary Mobile are mandatory.');
        return;
    }
    if (!/^\d{12}$/.test(formData.aadhaar)) {
      setValidationError('UID must be exactly 12 numeric digits.');
      return;
    }
    if (!/^\d{10}$/.test(formData.mobile)) {
        setValidationError('Mobile must be exactly 10 numeric digits.');
        return;
    }

    setIsValidating(true);
    try {
        const { data, error } = await supabase.from('members').select('id').eq('aadhaar', formData.aadhaar).maybeSingle();
        if (error) throw error;
        if (data) {
            setValidationError('Identification Conflict: This record already exists.');
        } else {
            setStep(2);
            window.scrollTo(0, 0);
        }
    } catch (e: any) {
        setValidationError(`Registry Fault: Access Denied`);
    } finally {
        setIsValidating(false);
    }
  };

  const handleStep2Next = () => {
      setValidationError('');
      if (!formData.name || !formData.surname || !formData.fatherName || !formData.dob || !formData.gender || !formData.emergencyContact || !formData.pincode || !formData.address) {
          setValidationError('Action Required: All fields are mandatory.');
          return;
      }

      if (!/^\d{10}$/.test(formData.emergencyContact)) {
          setValidationError('Emergency Contact must be 10 digits.');
          return;
      }

      if (formData.mobile === formData.emergencyContact) {
          setValidationError('Conflict: Mobile and Emergency Contact cannot be identical.');
          return;
      }

      if (!/^\d{6}$/.test(formData.pincode)) {
          setValidationError('Pincode must be exactly 6 digits.');
          return;
      }

      if (!formData.aadhaarFront || !formData.aadhaarBack) {
          setValidationError('Identity Scans are mandatory.');
          return;
      }

      setStep(3);
      window.scrollTo(0, 0);
  };

  const uploadFile = async (file: File, prefix: string) => {
      const fileName = `${prefix}_${uuidv4()}.jpg`;
      const { data, error } = await supabase.storage.from('member-images').upload(fileName, file);
      if (error) throw error;
      return supabase.storage.from('member-images').getPublicUrl(data.path).data.publicUrl;
  };

  const handleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!user?.organisationId) return;

      setIsSubmitting(true);
      try {
          const [frontUrl, backUrl] = await Promise.all([
              uploadFile(formData.aadhaarFront!, 'front'),
              uploadFile(formData.aadhaarBack!, 'back')
          ]);

          const memberPayload = {
              aadhaar: formData.aadhaar,
              mobile: formData.mobile,
              name: formatInput(formData.name),
              surname: formatInput(formData.surname),
              father_name: formatInput(formData.fatherName),
              dob: formData.dob,
              gender: formData.gender,
              emergency_contact: formData.emergencyContact,
              pincode: formData.pincode,
              address: formData.address.trim(),
              aadhaar_front_url: frontUrl,
              aadhaar_back_url: backUrl,
              occupation: formData.occupation,
              support_need: formData.supportNeed,
              volunteer_id: user.id,
              organisation_id: user.organisationId,
              status: 'Pending'
          };

          const { error } = await supabase.from('members').insert(memberPayload);
          if (error) throw error;

          await syncToSheets(SheetType.MEMBERS, {
            ...memberPayload,
            volunteer_name: user.name,
            organisation_name: user.organisationName,
            submission_date: new Date().toLocaleDateString()
          });

          addNotification("Identity record synchronized.", 'success');
          setFormData(initialFormData);
          setFrontPreview(null);
          setBackPreview(null);
          setStep(1);
          window.scrollTo(0, 0);
      } catch (err: any) {
          addNotification(`Registry Fault.`, 'error');
      } finally {
          setIsSubmitting(false);
      }
  };

  return (
    <DashboardLayout title="Identity Enrollment Hub">
      <div className="w-full max-w-4xl mx-auto space-y-8 md:space-y-12 pb-20">

          <div className="bg-[#0a0c14] border border-white/5 rounded-3xl p-6 flex flex-col sm:flex-row items-center justify-between gap-6 shadow-2xl">
              <div className="flex items-center gap-6">
                  <div className="p-4 bg-orange-600/10 rounded-2xl text-orange-500 border border-orange-500/20 shadow-inner">
                      <Fingerprint size={32} strokeWidth={1.5} />
                  </div>
                  <div>
                      <p className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-500 mb-2">Authenticated Operator</p>
                      <h4 className="text-lg md:text-xl font-bold text-white uppercase font-cinzel">{user?.name}</h4>
                  </div>
              </div>
              <div className="text-center sm:text-right px-6 py-3 bg-black/60 rounded-2xl border border-white/5">
                  <p className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-600 mb-1">Organization</p>
                  <p className="text-[11px] font-black text-orange-500 uppercase tracking-[0.2em]">{user?.organisationName}</p>
              </div>
          </div>

          <div className="relative pt-6 px-4">
              <div className="flex justify-between items-center mb-10 relative z-10">
                  {[1, 2, 3].map(s => (
                      <div key={s} className="flex flex-col items-center gap-3">
                          <div className={`h-12 w-12 rounded-full border-2 flex items-center justify-center transition-all duration-700 ${step >= s ? 'bg-orange-600 border-orange-400' : 'bg-[#0a0c14] border-gray-800 opacity-40'}`}>
                              <span className="text-sm font-black text-white">{s}</span>
                          </div>
                      </div>
                  ))}
              </div>
              <div className="absolute top-[2.75rem] left-0 w-full h-0.5 bg-gray-900 rounded-full overflow-hidden">
                  <div className="h-full bg-orange-600 transition-all duration-1000" style={{ width: `${((step - 1) / 2) * 100}%` }}></div>
              </div>
          </div>

          <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
            {step === 1 && (
                <div className="max-w-xl mx-auto py-4">
                    <Card className="relative bg-[#0a0c14] border-white/10 border p-0 rounded-[2.5rem] overflow-hidden shadow-[0_0_80px_rgba(0,0,0,0.5)]">
                        <div className="p-8 md:p-12 space-y-10">
                            <div className="flex items-center gap-6 mb-4">
                                <div className="p-4 bg-orange-500/10 rounded-2xl text-orange-500">
                                    <ShieldCheck size={28} />
                                </div>
                                <div>
                                    <h3 className="text-xl font-cinzel text-white uppercase tracking-wider">Validation Step</h3>
                                    <p className="text-[10px] font-black text-gray-500 uppercase tracking-[0.3em] mt-2">Registry Clearance</p>
                                </div>
                            </div>
                            <div className="space-y-8">
                                <Input label="IDENTIFICATION (12 DIGITS) *" name="aadhaar" value={formData.aadhaar} onChange={handleChange} maxLength={12} placeholder="Aadhaar Number" required />
                                <Input label="MOBILE NUMBER *" name="mobile" type="tel" value={formData.mobile} onChange={handleChange} maxLength={10} placeholder="Primary Mobile" required />
                                {validationError && (
                                    <div className="p-5 bg-red-600/10 border border-red-500/20 rounded-2xl">
                                        <p className="text-xs text-red-400 font-bold uppercase tracking-wider leading-relaxed">{validationError}</p>
                                    </div>
                                )}
                            </div>
                            <div className="pt-6">
                                <Button onClick={handleStep1Next} disabled={isValidating} className="w-full py-5 text-[11px] font-black uppercase tracking-[0.4em] flex items-center justify-center gap-4">
                                    {isValidating ? <RefreshCw className="animate-spin" size={20} /> : <Search size={20} />}
                                    {isValidating ? 'VALIDATING...' : 'AUTHORIZE ACCESS'}
                                </Button>
                            </div>
                        </div>
                    </Card>
                </div>
            )}

            {step === 2 && (
                <Card title="Citizen Identity File" className="bg-[#0a0c14] border-white/10 rounded-[2.5rem] p-8 md:p-14 shadow-2xl relative">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                        <Input label="GIVEN NAME *" name="name" value={formData.name} onChange={handleChange} placeholder="First Name" required />
                        <Input label="SURNAME *" name="surname" value={formData.surname} onChange={handleChange} placeholder="Last Name" required />
                        <Input label="FATHER / GUARDIAN NAME *" name="fatherName" value={formData.fatherName} onChange={handleChange} description="Maintained separately from primary identity name." required />
                        <Input label="DATE OF BIRTH *" name="dob" type="date" value={formData.dob} onChange={handleChange} required />
                        <Select label="BIOLOGICAL GENDER *" name="gender" value={formData.gender} onChange={handleChange}>
                            {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
                        </Select>
                        <Input label="EMERGENCY CONTACT *" name="emergencyContact" value={formData.emergencyContact} onChange={handleChange} maxLength={10} required />
                        <Input label="PINCODE *" name="pincode" value={formData.pincode} onChange={handleChange} maxLength={6} required />
                        <div className="md:col-span-2">
                            <Input label="FULL ADDRESS *" name="address" value={formData.address} onChange={handleChange} placeholder="Residential address" required />
                        </div>

                        <div className="md:col-span-2 pt-10 grid grid-cols-1 md:grid-cols-2 gap-10 border-t border-white/5">
                            <div className="space-y-4">
                                <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-gray-500">ID FRONT SIDE *</label>
                                <div className="relative border-2 border-gray-800 border-dashed rounded-[2rem] bg-black/60 aspect-video flex flex-col items-center justify-center overflow-hidden">
                                    {frontPreview ? (
                                        <>
                                            <img src={frontPreview} className="w-full h-full object-cover" />
                                            <button onClick={() => handleRemoveImage('front')} className="absolute top-4 right-4 p-2 bg-red-600 text-white rounded-xl"><XCircle size={20} /></button>
                                        </>
                                    ) : (
                                        <button onClick={() => frontInputRef.current?.click()} className="flex flex-col items-center gap-4 text-gray-700">
                                            <ImageIcon size={48} strokeWidth={1} />
                                            <span className="text-[10px] font-black uppercase tracking-[0.3em]">UPLOAD FRONT</span>
                                        </button>
                                    )}
                                    <input ref={frontInputRef} type="file" className="sr-only" onChange={(e) => handleFileChange(e, 'front')} accept="image/*" />
                                </div>
                            </div>

                            <div className="space-y-4">
                                <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-gray-500">ID BACK SIDE *</label>
                                <div className="relative border-2 border-gray-800 border-dashed rounded-[2rem] bg-black/60 aspect-video flex flex-col items-center justify-center overflow-hidden">
                                    {backPreview ? (
                                        <>
                                            <img src={backPreview} className="w-full h-full object-cover" />
                                            <button onClick={() => handleRemoveImage('back')} className="absolute top-4 right-4 p-2 bg-red-600 text-white rounded-xl"><XCircle size={20} /></button>
                                        </>
                                    ) : (
                                        <button onClick={() => backInputRef.current?.click()} className="flex flex-col items-center gap-4 text-gray-700">
                                            <ImageIcon size={48} strokeWidth={1} />
                                            <span className="text-[10px] font-black uppercase tracking-[0.3em]">UPLOAD BACK</span>
                                        </button>
                                    )}
                                    <input ref={backInputRef} type="file" className="sr-only" onChange={(e) => handleFileChange(e, 'back')} accept="image/*" />
                                </div>
                            </div>
                        </div>
                    </div>

                    {validationError && (
                        <div className="mt-10 flex items-center gap-4 p-5 bg-red-600/10 border border-red-500/20 rounded-2xl">
                            <ShieldAlert size={24} className="text-red-500 shrink-0" />
                            <p className="text-xs text-red-400 font-bold uppercase tracking-widest">{validationError}</p>
                        </div>
                    )}

                    <div className="mt-16 flex flex-col sm:flex-row justify-between gap-6">
                        <Button variant="secondary" onClick={() => { setStep(1); window.scrollTo(0, 0); }} className="w-full sm:w-auto py-4 px-10">Back</Button>
                        <Button onClick={handleStep2Next} className="w-full sm:w-auto py-4 px-12">Review Registry</Button>
                    </div>
                </Card>
            )}

            {step === 3 && (
                <Card title="Review Node" className="bg-[#0a0c14] border-white/10 rounded-[2.5rem] p-8 md:p-14 shadow-2xl">
                    <div className="space-y-12">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                            <Select label="PRIMARY VOCATION *" name="occupation" value={formData.occupation} onChange={handleChange}>
                                {Object.values(Occupation).map(o => <option key={o} value={o}>{o}</option>)}
                            </Select>
                            <Select label="SUPPORT REQUIREMENT *" name="supportNeed" value={formData.supportNeed} onChange={handleChange}>
                                {Object.values(SupportNeed).map(s => <option key={s} value={s}>{s}</option>)}
                            </Select>
                        </div>
                        <div className="p-8 bg-orange-600/5 border border-orange-500/10 rounded-[2rem] flex flex-col md:flex-row items-start gap-8">
                            <div className="p-4 bg-orange-500/10 rounded-2xl text-orange-500 shrink-0">
                                <ShieldCheck size={36} strokeWidth={1.5} />
                            </div>
                            <div className="space-y-3">
                                <h4 className="text-base font-bold text-white uppercase tracking-tight">Identity Certification</h4>
                                <p className="text-[11px] text-gray-500 leading-relaxed uppercase tracking-[0.2em] font-bold">
                                    I certify that I have physically verified the Given Name and Surname of this citizen against legal documentation. Father/Guardian name is recorded separately for registry accuracy.
                                </p>
                            </div>
                        </div>
                    </div>
                    {validationError && (
                        <div className="mt-10 flex items-center gap-4 p-5 bg-red-600/10 border border-red-500/20 rounded-2xl">
                            <ShieldAlert size={24} className="text-red-500 shrink-0" />
                            <p className="text-xs text-red-400 font-bold uppercase tracking-widest">{validationError}</p>
                        </div>
                    )}
                    <div className="mt-16 flex flex-col sm:flex-row justify-between gap-6">
                        <Button variant="secondary" onClick={() => { setStep(2); window.scrollTo(0, 0); }} className="w-full sm:w-auto py-4 px-10">Modify Profile</Button>
                        <Button onClick={handleSubmit} disabled={isSubmitting} className="w-full sm:w-auto py-5 px-16 text-[12px] font-black uppercase tracking-[0.4em]">
                            {isSubmitting ? 'SYNCHRONIZING...' : 'FINALIZE REGISTRATION'}
                        </Button>
                    </div>
                </Card>
            )}
          </div>
      </div>
    </DashboardLayout>
  );
};

export default NewMemberForm;

import React, { useState, useEffect, useMemo } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import Modal from '../../components/ui/Modal';
import { supabase } from '../../supabase/client';
import { Member, Organisation, Role, User as VolunteerUser, Gender, Occupation, SupportNeed, MemberStatus } from '../../types';
import { useNotification } from '../../context/NotificationContext';
import { 
  FileSpreadsheet, 
  Search,
  RefreshCw,
  Edit3,
  Save,
  User as UserIcon,
  ExternalLink,
  Trash2,
  Calendar,
  Building2,
  Fingerprint,
  Activity,
  UserCircle,
  Phone,
  BadgeCheck,
  MapPin,
  Loader2,
  Copy,
  AlertTriangle
} from 'lucide-react';

type MemberWithAgent = Member & {
    agent_profile?: { 
        name: string, 
        mobile: string,
        organisations?: { name: string }
    }
};

const AdminReports: React.FC = () => {
    const [members, setMembers] = useState<MemberWithAgent[]>([]);
    const [organisations, setOrganisations] = useState<Organisation[]>([]);
    const [loading, setLoading] = useState(true);
    const { addNotification } = useNotification();

    const [selectedOrgId, setSelectedOrgId] = useState<string>('');
    const [selectedVolunteerId, setSelectedVolunteerId] = useState<string>('');
    const [searchQuery, setSearchQuery] = useState('');

    const [editingMember, setEditingMember] = useState<MemberWithAgent | null>(null);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [memberToDelete, setMemberToDelete] = useState<MemberWithAgent | null>(null);
    const [isUpdating, setIsUpdating] = useState(false);
    const [isDeleting, setIsDeleting] = useState(false);

    const formatDisplayName = (first: string, last: string) => {
        const f = (first || '').trim().toLowerCase();
        const l = (last || '').trim().toLowerCase();
        return `${f} ${l}`.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    };

    const fetchData = async () => {
        setLoading(true);
        try {
            const [membersRes, orgsRes] = await Promise.all([
                supabase
                    .from('members')
                    .select(`
                        *,
                        agent_profile:profiles!volunteer_id(
                            name, 
                            mobile,
                            organisations (name)
                        )
                    `)
                    .order('submission_date', { ascending: false }),
                supabase.from('organisations').select('*').order('name')
            ]);

            if (membersRes.data) setMembers(membersRes.data as MemberWithAgent[]);
            if (orgsRes.data) setOrganisations(orgsRes.data);
        } catch (err) {
            addNotification("Master registry uplink failed.", "error");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const filteredMembers = useMemo(() => {
        return members.filter(m => {
            const matchOrg = !selectedOrgId || m.organisation_id === selectedOrgId;
            const matchVol = !selectedVolunteerId || m.volunteer_id === selectedVolunteerId;
            const matchSearch = !searchQuery || 
                m.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                m.surname.toLowerCase().includes(searchQuery.toLowerCase()) ||
                m.mobile.includes(searchQuery) ||
                m.aadhaar.includes(searchQuery);
            return matchOrg && matchVol && matchSearch;
        });
    }, [members, selectedOrgId, selectedVolunteerId, searchQuery]);

    const handleVerifyStatus = async (member: MemberWithAgent) => {
        const newStatus = member.status === MemberStatus.Accepted ? MemberStatus.Pending : MemberStatus.Accepted;
        try {
            const { error } = await supabase.from('members').update({ status: newStatus }).eq('id', member.id);
            if (error) throw error;
            addNotification(`Verification status updated.`, "success");
            fetchData();
        } catch (err) {
            addNotification("Verification update failed.", "error");
        }
    };

    const handleCopyDetails = (member: MemberWithAgent) => {
        const text = `Name: ${formatDisplayName(member.name, member.surname)}\nMobile: ${member.mobile}\nAadhaar: ${member.aadhaar}`;
        navigator.clipboard.writeText(text);
        addNotification("Identity details copied to clipboard.", "info");
    };

    const handleEditMember = (member: MemberWithAgent) => {
        setEditingMember({ ...member });
        setIsEditModalOpen(true);
    };

    const handleDeleteMember = async () => {
        if (!memberToDelete) return;
        setIsDeleting(true);
        try {
            const { error } = await supabase.from('members').delete().eq('id', memberToDelete.id);
            if (error) throw error;
            addNotification("Identity record purged successfully.", "success");
            setMemberToDelete(null);
            fetchData();
        } catch (err: any) {
            addNotification(`Purge operation failed.`, "error");
        } finally {
            setIsDeleting(false);
        }
    };

    const handleUpdateMember = async () => {
        if (!editingMember) return;
        setIsUpdating(true);
        try {
            const { error } = await supabase.from('members').update({
                name: editingMember.name.trim(),
                surname: editingMember.surname.trim(),
                father_name: editingMember.father_name.trim(),
                mobile: editingMember.mobile.trim(),
                emergency_contact: editingMember.emergency_contact.trim(),
                dob: editingMember.dob,
                gender: editingMember.gender,
                pincode: editingMember.pincode,
                address: editingMember.address,
                occupation: editingMember.occupation,
                support_need: editingMember.support_need,
                status: editingMember.status,
            }).eq('id', editingMember.id);

            if (error) throw error;
            addNotification("Identity synchronized.", "success");
            setIsEditModalOpen(false);
            fetchData();
        } catch (err: any) {
            addNotification(`Update failed.`, "error");
        } finally {
            setIsUpdating(false);
        }
    };

    const handleExport = () => {
        const headers = ['Aadhaar', 'Display Name', 'Father Name', 'Mobile', 'DOB', 'Gender', 'Address', 'Pincode', 'Occupation', 'Support Need', 'Volunteer', 'Organization', 'Status'];
        const rows = filteredMembers.map(m => [
            m.aadhaar, 
            formatDisplayName(m.name, m.surname), 
            m.father_name, 
            m.mobile, 
            m.dob, 
            m.gender,
            m.address,
            m.pincode,
            m.occupation,
            m.support_need,
            m.agent_profile?.name || 'N/A',
            m.agent_profile?.organisations?.name || 'N/A',
            m.status
        ]);
        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = `Registry_Export_${new Date().toISOString().split('T')[0]}.csv`;
        link.click();
    };

    return (
        <DashboardLayout title="Master Registry Terminal">
            <div className="space-y-8">
                <Card className="bg-gray-950 border-white/5 p-8 rounded-[2rem] shadow-2xl relative overflow-hidden">
                    <div className="flex items-center gap-2 mb-8 text-orange-500 relative z-10">
                        <Activity size={18} />
                        <h3 className="text-[10px] font-black uppercase tracking-[0.4em]">Multi-Vector Intelligence</h3>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 relative z-10">
                        <Select label="Filter by Organization" value={selectedOrgId} onChange={(e) => setSelectedOrgId(e.target.value)} className="bg-black/60 border-gray-700">
                            <option value="">All Organizations</option>
                            {organisations.map(org => <option key={org.id} value={org.id}>{org.name}</option>)}
                        </Select>
                        <Input 
                            label="Universal Search"
                            placeholder="Name, Mobile, Aadhaar..." 
                            value={searchQuery} 
                            onChange={(e) => setSearchQuery(e.target.value)} 
                            icon={<Search size={16} />}
                            className="bg-black/60 border-gray-700"
                        />
                        <div className="md:col-span-2 flex gap-4 items-end">
                            <Button onClick={fetchData} variant="secondary" className="flex-1 py-4 text-[10px] font-black uppercase tracking-widest gap-2">
                                <RefreshCw size={14} className={loading ? 'animate-spin' : ''} /> Sync Node
                            </Button>
                            <Button onClick={handleExport} className="flex-1 py-4 text-[10px] font-black uppercase tracking-widest gap-2 bg-blue-600 hover:bg-blue-700">
                                <FileSpreadsheet size={16} /> Export CSV
                            </Button>
                        </div>
                    </div>
                </Card>

                <Card title="Global Identity Registry">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="border-b border-gray-800">
                                <tr className="text-gray-400 uppercase tracking-widest text-[10px] font-black">
                                    <th className="p-6">Member Identity</th>
                                    <th className="p-6 text-blue-500">Personnel Attribution</th>
                                    <th className="p-6 text-center">Verification</th>
                                    <th className="p-6">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-900/50">
                                {loading ? (
                                    <tr><td colSpan={4} className="p-24 text-center text-[11px] animate-pulse font-black uppercase tracking-[0.4em] text-gray-500">Syncing...</td></tr>
                                ) : filteredMembers.map(m => (
                                    <tr key={m.id} className="group hover:bg-white/[0.02] transition-all">
                                        <td className="p-6">
                                            <div className="flex flex-col overflow-hidden">
                                                <span className="font-bold text-white text-lg group-hover:text-orange-500 transition-colors truncate">
                                                    {formatDisplayName(m.name, m.surname)}
                                                </span>
                                                <div className="flex items-center gap-3 mt-1 text-[11px] text-gray-400 font-mono tracking-tighter">
                                                    <span>{m.mobile}</span>
                                                    <span className="h-1 w-1 rounded-full bg-gray-700"></span>
                                                    <span>{m.aadhaar.slice(-4).padStart(12, '•')}</span>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-6">
                                            <div className="flex items-center gap-4">
                                                <div className="h-10 w-10 rounded-xl bg-orange-500/10 border border-orange-500/20 flex items-center justify-center text-orange-500 shrink-0">
                                                    <UserCircle size={20} />
                                                </div>
                                                <div className="flex flex-col overflow-hidden">
                                                    <span className="text-[11px] font-black text-white uppercase tracking-widest truncate">
                                                        {m.agent_profile?.name || 'Unknown'}
                                                    </span>
                                                    <div className="flex items-center gap-2 mt-0.5">
                                                        <Building2 size={10} className="text-orange-500/80" />
                                                        <span className="text-[9px] text-orange-500/80 font-black uppercase tracking-widest truncate">
                                                            {m.agent_profile?.organisations?.name || 'Independent'}
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-6 text-center">
