                                <div className="h-1 w-1 rounded-full bg-orange-500"></div>
                                Mix uppercase, lowercase, and symbols.
                            </li>
                            <li className="text-[10px] text-gray-500 flex items-center gap-2">
                                <div className="h-1 w-1 rounded-full bg-orange-500"></div>
                                Avoid using agent's mobile or birth year.
                            </li>
                        </ul>
                    </div>
