                                <Eye size={16} />
                            </button>
                            <button onClick={() => handleResetPasswordClick(vol)} className="p-3 bg-white/5 border border-white/10 text-gray-500 hover:text-orange-400 rounded-xl transition-all" title="Reset Access Key">
                                <KeyRound size={16} />
