      .channel('public-registry-monitor')
      .on(
        'postgres_changes',
        'public',
        'members',
        () => fetchData()
      )
      .on(
        'postgres_changes',
        'public',
        'profiles',
        () => fetchData()
      )
      .on(
        'postgres_changes',
        'public',
        'organisations',
        () => fetchData()
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [fetchData]);

  const volunteers = useMemo(() => {
    if (!volsData.length) return [];

