/* Base Tailwind directives are handled by the CDN script in index.html */

/* Custom scrollbar for a premium dark UI feel */
.custom-scrollbar::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.custom-scrollbar::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.2);
  border-radius: 10px;
}

.custom-scrollbar::-webkit-scrollbar-thumb {
  background: rgba(255, 100, 0, 0.2);
  border-radius: 10px;
}

.custom-scrollbar::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 100, 0, 0.4);
}

/* Glassmorphism utility */
.glass-panel {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.05);
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideInSpring {
  0% { transform: translateX(120%) scale(0.9); opacity: 0; }
  70% { transform: translateX(-5%) scale(1.02); opacity: 1; }
  100% { transform: translateX(0) scale(1); opacity: 1; }
}

@keyframes notificationPulse {
  0% { box-shadow: 0 0 0 0 rgba(234, 88, 12, 0.4); }
  70% { box-shadow: 0 0 0 15px rgba(234, 88, 12, 0); }
  100% { box-shadow: 0 0 0 0 rgba(234, 88, 12, 0); }
}

@keyframes successSplash {
  0% { transform: scale(0.8) translateY(20px); opacity: 0; filter: blur(10px); }
  50% { transform: scale(1.05) translateY(-5px); opacity: 1; filter: blur(0); }
  100% { transform: scale(1) translateY(0); opacity: 1; filter: blur(0); }
}

@keyframes celebrateOuter {
  0% { transform: scale(0); opacity: 0; }
  10% { transform: scale(1.2); opacity: 0.5; }
  100% { transform: scale(1.5); opacity: 0; }
}

.animate-in {
  animation: fadeIn 0.5s ease-out forwards;
}

.animate-notification {
  animation: slideInSpring 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.animate-pulse-success {
  animation: notificationPulse 2s infinite;
}

.animate-splash {
  animation: successSplash 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.animate-celebrate {
  animation: celebrateOuter 1.5s ease-out forwards;
}

input[type="date"]::-webkit-calendar-picker-indicator {
  filter: invert(1);
  cursor: pointer;
}

import React, { useEffect } from 'react';
import { CheckCircle, XCircle, Info, X } from 'lucide-react';

export interface NotificationProps {
  id: string;
  message: string;
  type: 'success' | 'error' | 'info';
  onDismiss: (id: string) => void;
}

const icons = {
  success: <CheckCircle className="text-green-400" size={20} />,
  error: <XCircle className="text-red-400" size={20} />,
  info: <Info className="text-blue-400" size={20} />,
};

const colors = {
    success: 'bg-green-500',
    error: 'bg-red-500',
    info: 'bg-blue-500'
};

const borderColors = {
    success: 'border-green-500/30',
    error: 'border-red-500/30',
    info: 'border-blue-500/30'
};

const Notification: React.FC<NotificationProps> = ({ id, message, type, onDismiss }) => {

  useEffect(() => {
    const timer = setTimeout(() => {
      onDismiss(id);
    }, 6000); // Extended time slightly for motion appreciation

    return () => clearTimeout(timer);
  }, [id, onDismiss]);

  return (
    <div className={`group animate-notification ${type === 'success' ? 'animate-pulse-success' : ''} bg-[#0a0a0a]/95 backdrop-blur-xl border ${borderColors[type]} rounded-2xl shadow-2xl p-5 flex items-start space-x-4 relative overflow-hidden`}>
        <div className={`absolute left-0 top-0 bottom-0 w-1.5 ${colors[type]} shadow-[0_0_15px_rgba(0,0,0,0.5)]`}></div>
        <div className="flex-shrink-0 pt-0.5">{icons[type]}</div>
        <div className="flex-1 min-w-0">
            <h4 className={`text-[9px] font-black uppercase tracking-[0.3em] mb-1 ${type === 'success' ? 'text-green-500' : type === 'error' ? 'text-red-500' : 'text-blue-500'}`}>
                {type === 'success' ? 'System Cleared' : type === 'error' ? 'Handshake Error' : 'Uplink Message'}
            </h4>
            <p className="text-sm font-bold text-white leading-relaxed">{message}</p>
        </div>
        <button 
            onClick={() => onDismiss(id)} 
            className="text-gray-600 hover:text-white transition-colors bg-white/5 p-1 rounded-lg"
        >
            <X size={14} />
        </button>
    </div>
  );
};

export default Notification;

