import React, { createContext, useState, useContext, ReactNode, useCallback } from 'react';
import Notification, { NotificationProps } from '../components/ui/Notification';
import { v4 as uuidv4 } from 'uuid';

export type NotificationType = 'success' | 'error' | 'info' | 'registry-success';

interface ExtendedNotificationProps extends Omit<NotificationProps, 'onDismiss'> {
    imageUrl?: string;
    title?: string;
}

interface NotificationContextType {
  addNotification: (message: string, type: NotificationType, imageUrl?: string, title?: string) => void;
}

const NotificationContext = createContext<NotificationContextType | undefined>(undefined);

export const NotificationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [notifications, setNotifications] = useState<ExtendedNotificationProps[]>([]);

  const addNotification = useCallback((message: string, type: NotificationType, imageUrl?: string, title?: string) => {
    const id = uuidv4();
    setNotifications(prev => [...prev, { id, message, type, imageUrl, title }]);
  }, []);

  const dismissNotification = useCallback((id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  }, []);

  return (
    <NotificationContext.Provider value={{ addNotification }}>
      {children}
      <div className="fixed top-5 right-5 z-[100] space-y-3 w-full max-w-sm pointer-events-none">
        {notifications.map((notification) => (
          <div key={notification.id} className="pointer-events-auto">
            <Notification {...notification} onDismiss={dismissNotification} />
          </div>
        ))}
      </div>
    </NotificationContext.Provider>
  );
};

export const useNotification = (): NotificationContextType => {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotification must be used within a NotificationProvider');
  }
  return context;
};

import React, { useEffect } from 'react';
import { CheckCircle, XCircle, Info, X, Building2 } from 'lucide-react';

export interface NotificationProps {
  id: string;
  message: string;
  type: 'success' | 'error' | 'info' | 'registry-success';
  imageUrl?: string;
  title?: string;
  onDismiss: (id: string) => void;
}

const icons = {
  success: <CheckCircle className="text-green-400" size={20} />,
  error: <XCircle className="text-red-400" size={20} />,
  info: <Info className="text-blue-400" size={20} />,
  'registry-success': <CheckCircle className="text-orange-500" size={20} />
};

const colors = {
    success: 'bg-green-500',
    error: 'bg-red-500',
    info: 'bg-blue-500',
    'registry-success': 'bg-orange-500'
};

const borderColors = {
    success: 'border-green-500/30',
    error: 'border-red-500/30',
    info: 'border-blue-500/30',
    'registry-success': 'border-orange-500/40'
};

const Notification: React.FC<NotificationProps> = ({ id, message, type, imageUrl, title, onDismiss }) => {

  useEffect(() => {
    // Standard notifications dismiss at 6s. Registry success follows the 5.5s animation lifecycle.
    const duration = type === 'registry-success' ? 5500 : 6000;
    const timer = setTimeout(() => {
      onDismiss(id);
    }, duration);

    return () => clearTimeout(timer);
  }, [id, type, onDismiss]);

  const isRegistryType = type === 'registry-success';

  return (
    <div className={`
        group relative overflow-hidden flex items-start space-x-4 p-5 rounded-2xl shadow-2xl backdrop-blur-xl border
        ${isRegistryType ? 'animate-registry-success' : 'animate-notification'}
        ${type === 'success' ? 'animate-pulse-success' : ''} 
        ${isRegistryType ? 'bg-[#050505]/95' : 'bg-[#0a0a0a]/95'} 
        ${borderColors[type]} 
    `}>
        <div className={`absolute left-0 top-0 bottom-0 w-1 ${colors[type]} shadow-[0_0_15px_rgba(0,0,0,0.5)]`}></div>

        {isRegistryType && imageUrl ? (
            <div className="flex-shrink-0">
                <div className="h-12 w-12 rounded-xl overflow-hidden border border-white/10 shadow-lg bg-black">
                    <img 
                        src={imageUrl} 
                        alt="Org" 
                        className="h-full w-full logo-contain"
                    />
                </div>
            </div>
        ) : isRegistryType ? (
            <div className="flex-shrink-0">
                <div className="h-12 w-12 rounded-xl border border-orange-500/20 bg-orange-500/5 flex items-center justify-center text-orange-500">
                    <Building2 size={24} />
                </div>
            </div>
        ) : (
            <div className="flex-shrink-0 pt-0.5">{icons[type]}</div>
        )}

        <div className="flex-1 min-w-0">
            <h4 className={`text-[9px] font-black uppercase tracking-[0.3em] mb-1 ${isRegistryType ? 'text-orange-500' : type === 'success' ? 'text-green-500' : type === 'error' ? 'text-red-500' : 'text-blue-500'}`}>
                {title || (type === 'success' ? 'System Cleared' : type === 'error' ? 'Handshake Error' : 'Uplink Message')}
            </h4>
            <p className={`text-sm leading-relaxed ${isRegistryType ? 'text-white font-black' : 'text-white font-bold'}`}>
                {message}
            </p>
            {isRegistryType && (
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">
                    New organization added to the registry
                </p>
            )}
        </div>

        {!isRegistryType && (
            <button 
                onClick={() => onDismiss(id)} 
                className="text-gray-600 hover:text-white transition-colors bg-white/5 p-1 rounded-lg"
            >
                <X size={14} />
            </button>
        )}
    </div>
  );
};

export default Notification;

