import React, { useEffect, useState, useCallback } from 'react';
import { supabase } from '../../supabase/client';
import { Organisation } from '../../types';
import { Building2, Zap, Globe } from 'lucide-react';

const ScrollingStrip: React.FC = () => {
  const [orgs, setOrgs] = useState<Organisation[]>([]);
  const [newOrgIds, setNewOrgIds] = useState<Set<string>>(new Set());

  const fetchInitialOrgs = useCallback(async () => {
    const { data } = await supabase
      .from('organisations')
      .select('*')
      .order('name', { ascending: true });
    if (data) setOrgs(data);
  }, []);

  useEffect(() => {
    fetchInitialOrgs();

    // Subscribe to real-time additions to the registry
    const channel = supabase
      .channel('live-registry-ticker')
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'organisations' },
        (payload) => {
          const newOrg = payload.new as Organisation;
          // Prepend new org to the start of the strip list
          setOrgs(prev => [newOrg, ...prev]);

          // Mark as "new" for the glow highlight phase
          setNewOrgIds(prev => {
            const next = new Set(prev);
            next.add(newOrg.id);
            return next;
          });

          // Transition from "Glow" to "Blended" after 45 seconds (approx 1 pass)
          setTimeout(() => {
            setNewOrgIds(prev => {
              const next = new Set(prev);
              next.delete(newOrg.id);
              return next;
            });
          }, 45000);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [fetchInitialOrgs]);

  if (orgs.length === 0) return null;

  // Seamless duplication for infinite loop
  const displayOrgs = [...orgs, ...orgs];

  return (
    <div className="w-full bg-[#050505] border-t border-b border-white/5 overflow-hidden relative h-16 flex items-center group shadow-[0_10px_30px_rgba(0,0,0,0.5)]">
      {/* Indicator Sidebar */}
      <div className="absolute left-0 top-0 bottom-0 z-20 bg-[#050505]/90 backdrop-blur-md px-6 flex items-center gap-3 border-r border-orange-500/20 shadow-[15px_0_30px_rgba(0,0,0,0.9)]">
        <div className="relative">
            <Globe size={16} className="text-orange-500 animate-[spin_10s_linear_infinite]" />
            <div className="absolute inset-0 bg-orange-500 blur-lg opacity-20"></div>
        </div>
        <span className="text-[10px] font-black uppercase tracking-[0.4em] text-white">Registry Live</span>
      </div>

      <div className="animate-marquee ml-44 flex items-center">
        {displayOrgs.map((org, idx) => (
          <div 
            key={`${org.id}-${idx}`}
            className={`
                flex items-center gap-4 px-10 h-16 border-r border-white/5 transition-all duration-1000
                ${newOrgIds.has(org.id) ? 'new-node-glow' : 'hover:bg-white/[0.02]'}
            `}
          >
            <div className={`
                h-10 w-10 rounded-xl overflow-hidden border bg-black/60 flex-shrink-0 flex items-center justify-center transition-all duration-500
                ${newOrgIds.has(org.id) ? 'border-orange-500/50 scale-110 shadow-lg shadow-orange-500/10' : 'border-white/10'}
            `}>
              {org.profile_photo_url ? (
                <img src={org.profile_photo_url} alt={org.name} className="h-full w-full object-contain p-1" />
              ) : (
                <Building2 size={20} className={newOrgIds.has(org.id) ? 'text-orange-500' : 'text-gray-700'} />
              )}
            </div>

            <div className="flex flex-col">
              <span className={`text-[13px] font-black uppercase tracking-wider whitespace-nowrap transition-colors duration-500 ${newOrgIds.has(org.id) ? 'text-white' : 'text-gray-400 group-hover:text-white'}`}>
                {org.name}
              </span>
              {newOrgIds.has(org.id) && (
                <div className="flex items-center gap-1.5 mt-0.5">
                    <span className="h-1.5 w-1.5 rounded-full bg-orange-500 animate-pulse"></span>
                    <span className="text-[8px] font-black text-orange-500 uppercase tracking-widest">
                        New Establishment
                    </span>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Edge Gradient */}
      <div className="absolute right-0 top-0 bottom-0 w-40 bg-gradient-to-l from-[#050505] to-transparent z-10 pointer-events-none"></div>
    </div>
  );
};

export default ScrollingStrip;

