import React, { useEffect, useState, useCallback } from 'react';
import { supabase } from '../../supabase/client';
import { Organisation } from '../../types';
import { Building2, Globe } from 'lucide-react';

const ScrollingStrip: React.FC = () => {
  const [orgs, setOrgs] = useState<Organisation[]>([]);
  const [newOrgIds, setNewOrgIds] = useState<Set<string>>(new Set());

  const fetchInitialOrgs = useCallback(async () => {
    const { data } = await supabase
      .from('organisations')
      .select('*')
      .order('name', { ascending: true });
    if (data) setOrgs(data);
  }, []);

  useEffect(() => {
    fetchInitialOrgs();

    const channel = supabase
      .channel('live-registry-ticker')
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'organisations' },
        (payload) => {
          const newOrg = payload.new as Organisation;
          setOrgs(prev => [newOrg, ...prev]);
          setNewOrgIds(prev => {
            const next = new Set(prev);
            next.add(newOrg.id);
            return next;
          });

          setTimeout(() => {
            setNewOrgIds(prev => {
              const next = new Set(prev);
              next.delete(newOrg.id);
              return next;
            });
          }, 45000);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [fetchInitialOrgs]);

  if (orgs.length === 0) return null;

  const displayOrgs = [...orgs, ...orgs];

  return (
    <div className="w-full bg-[#050505] border-b border-white/5 overflow-hidden relative h-16 flex items-center group shadow-[0_4px_20px_rgba(0,0,0,0.5)]">
      {/* Fixed Width Sidebar Label - Aligned to 12rem (w-48) */}
      <div className="absolute left-0 top-0 bottom-0 z-20 bg-[#050505] w-48 flex items-center gap-3 px-6 border-r border-orange-500/20 shadow-[10px_0_30px_rgba(0,0,0,0.9)]">
        <div className="relative flex-shrink-0">
            <Globe size={16} className="text-orange-500 animate-[spin_10s_linear_infinite]" />
            <div className="absolute inset-0 bg-orange-500 blur-lg opacity-20"></div>
        </div>
        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-white whitespace-nowrap">Registry Live</span>
      </div>

      {/* Marquee Container with matching margin-left */}
      <div className="animate-marquee ml-48 flex items-center">
        {displayOrgs.map((org, idx) => (
          <div 
            key={`${org.id}-${idx}`}
            className={`
                flex items-center gap-4 px-10 h-16 border-r border-white/5 transition-all duration-1000
                ${newOrgIds.has(org.id) ? 'new-node-glow' : 'hover:bg-white/[0.02]'}
            `}
          >
            <div className={`
                h-10 w-10 rounded-xl overflow-hidden border bg-black/60 flex-shrink-0 flex items-center justify-center transition-all duration-500
                ${newOrgIds.has(org.id) ? 'border-orange-500/50 scale-110 shadow-lg shadow-orange-500/10' : 'border-white/10'}
            `}>
              {org.profile_photo_url ? (
                <img src={org.profile_photo_url} alt={org.name} className="h-full w-full object-contain p-1" />
              ) : (
                <Building2 size={20} className={newOrgIds.has(org.id) ? 'text-orange-500' : 'text-gray-700'} />
              )}
            </div>

            <div className="flex flex-col">
              <span className={`text-[13px] font-black uppercase tracking-wider whitespace-nowrap transition-colors duration-500 ${newOrgIds.has(org.id) ? 'text-white' : 'text-gray-400 group-hover:text-white'}`}>
                {org.name}
              </span>
              {newOrgIds.has(org.id) && (
                <div className="flex items-center gap-1.5 mt-0.5">
                    <span className="h-1.5 w-1.5 rounded-full bg-orange-500 animate-pulse"></span>
                    <span className="text-[8px] font-black text-orange-500 uppercase tracking-widest">
                        New Establishment
                    </span>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      <div className="absolute right-0 top-0 bottom-0 w-40 bg-gradient-to-l from-[#050505] to-transparent z-10 pointer-events-none"></div>
    </div>
  );
};

export default ScrollingStrip;

import React, { useEffect, useState, useCallback } from 'react';
import { supabase } from '../../supabase/client';
import { UserCircle, Zap } from 'lucide-react';

interface VolunteerNode {
    id: string;
    name: string;
    profile_photo_url?: string;
    organisation_name?: string;
}

const VolunteerScrollingStrip: React.FC = () => {
  const [vols, setVols] = useState<VolunteerNode[]>([]);
  const [newVolIds, setNewVolIds] = useState<Set<string>>(new Set());

  const fetchInitialVols = useCallback(async () => {
    const { data } = await supabase
      .from('profiles')
      .select(`
        id, 
        name, 
        profile_photo_url,
        organisations (name)
      `)
      .eq('role', 'Volunteer')
      .order('name', { ascending: true });

    if (data) {
        const mapped = data.map((v: any) => ({
            id: v.id,
            name: v.name,
            profile_photo_url: v.profile_photo_url,
            organisation_name: v.organisations?.name
        }));
        setVols(mapped);
    }
  }, []);

  useEffect(() => {
    fetchInitialVols();

    const channel = supabase
      .channel('live-volunteer-ticker')
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'profiles', filter: `role=eq.Volunteer` },
        async (payload) => {
          const { data } = await supabase
            .from('profiles')
            .select('id, name, profile_photo_url, organisations(name)')
            .eq('id', payload.new.id)
            .single();

          if (data) {
              const newVol = {
                  id: data.id,
                  name: data.name,
                  profile_photo_url: data.profile_photo_url,
                  organisation_name: (data as any).organisations?.name
              };

              setVols(prev => [newVol, ...prev]);
              setNewVolIds(prev => {
                const next = new Set(prev);
                next.add(newVol.id);
                return next;
              });

              setTimeout(() => {
                setNewVolIds(prev => {
                  const next = new Set(prev);
                  next.delete(newVol.id);
                  return next;
                });
              }, 45000);
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [fetchInitialVols]);

  if (vols.length === 0) return null;

  const displayVols = [...vols, ...vols];

  return (
    <div className="w-full bg-[#050505] border-b border-white/5 overflow-hidden relative h-16 flex items-center group shadow-[0_10px_30px_rgba(0,0,0,0.5)]">
      {/* Fixed Width Sidebar Label - Aligned to 12rem (w-48) to match Registry strip */}
      <div className="absolute left-0 top-0 bottom-0 z-20 bg-[#050505] w-48 flex items-center gap-3 px-6 border-r border-blue-500/20 shadow-[10px_0_30px_rgba(0,0,0,0.9)]">
        <div className="relative flex-shrink-0">
            <Zap size={16} className="text-blue-500 animate-pulse" />
            <div className="absolute inset-0 bg-blue-500 blur-lg opacity-20"></div>
        </div>
        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-white whitespace-nowrap">Personnel Live</span>
      </div>

      {/* Marquee Container with matching margin-left */}
      <div className="animate-marquee ml-48 flex items-center">
        {displayVols.map((vol, idx) => (
          <div 
            key={`${vol.id}-${idx}`}
            className={`
                flex items-center gap-4 px-10 h-16 border-r border-white/5 transition-all duration-1000
                ${newVolIds.has(vol.id) ? 'bg-blue-500/10 border-l border-blue-500/50 border-r border-blue-500/50' : 'hover:bg-white/[0.02]'}
            `}
          >
            <div className={`
                h-10 w-10 rounded-xl overflow-hidden border bg-black/60 flex-shrink-0 flex items-center justify-center transition-all duration-500
                ${newVolIds.has(vol.id) ? 'border-blue-500/50 scale-110 shadow-lg shadow-blue-500/10' : 'border-white/10'}
            `}>
              {vol.profile_photo_url ? (
                <img src={vol.profile_photo_url} alt={vol.name} className="h-full w-full object-cover" />
              ) : (
                <UserCircle size={20} className={newVolIds.has(vol.id) ? 'text-blue-500' : 'text-gray-700'} />
              )}
            </div>

            <div className="flex flex-col">
              <span className={`text-[13px] font-black uppercase tracking-wider whitespace-nowrap transition-colors duration-500 ${newVolIds.has(vol.id) ? 'text-white' : 'text-gray-400 group-hover:text-white'}`}>
                {vol.name}
              </span>
              <div className="flex items-center gap-1.5 mt-0.5">
                  {newVolIds.has(vol.id) ? (
                    <>
                        <span className="h-1.5 w-1.5 rounded-full bg-blue-500 animate-pulse"></span>
                        <span className="text-[8px] font-black text-blue-500 uppercase tracking-widest">
                            Authorized Agent
                        </span>
                    </>
                  ) : (
                    <span className="text-[8px] font-black text-gray-600 uppercase tracking-widest truncate max-w-[120px]">
                        {vol.organisation_name || 'Independent'}
                    </span>
                  )}
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="absolute right-0 top-0 bottom-0 w-40 bg-gradient-to-l from-[#050505] to-transparent z-10 pointer-events-none"></div>
    </div>
  );
};

export default VolunteerScrollingStrip;

/* Base Tailwind directives are handled by the CDN script in index.html */

/* Custom scrollbar for a premium dark UI feel */
.custom-scrollbar::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.custom-scrollbar::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.1);
  border-radius: 10px;
}

.custom-scrollbar::-webkit-scrollbar-thumb {
  background: rgba(255, 100, 0, 0.15);
  border-radius: 10px;
}

.custom-scrollbar::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 100, 0, 0.3);
}

/* Glassmorphism utility with more depth */
.glass-panel {
  background: rgba(255, 255, 255, 0.02);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.8);
}

.glass-card {
  background: linear-gradient(135deg, rgba(255,255,255,0.03) 0%, rgba(255,255,255,0) 100%);
  border: 1px solid rgba(255, 255, 255, 0.05);
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.glass-card:hover {
  border-color: rgba(255, 100, 0, 0.2);
  background: rgba(255, 255, 255, 0.04);
  transform: translateY(-2px);
}

/* Animations */
@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes glow-pulse-registry {
  0% { box-shadow: inset 0 0 10px rgba(234, 88, 12, 0.05); border-color: rgba(234, 88, 12, 0.1); }
  50% { box-shadow: inset 0 0 40px rgba(234, 88, 12, 0.3); border-color: rgba(234, 88, 12, 0.5); }
  100% { box-shadow: inset 0 0 10px rgba(234, 88, 12, 0.05); border-color: rgba(234, 88, 12, 0.1); }
}

@keyframes fadeInScale {
  from { opacity: 0; transform: translateY(20px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.animate-marquee {
  display: flex;
  width: max-content;
  animation: marquee 60s linear infinite;
}

.animate-marquee:hover {
  animation-play-state: paused;
}

.new-node-glow {
  animation: glow-pulse-registry 3s infinite ease-in-out;
  background: rgba(234, 88, 12, 0.05) !important;
}

.animate-in {
  animation: fadeInScale 0.7s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Typographic Alignment Helpers */
.tracking-tight-custom {
  letter-spacing: -0.02em;
}

.tracking-wide-custom {
  letter-spacing: 0.15em;
}

input[type="date"]::-webkit-calendar-picker-indicator {
  filter: invert(1) brightness(0.8);
  cursor: pointer;
}

import React from 'react';

interface CardProps {
