import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import Button from '../ui/Button';
import { Role } from '../../types';

const Header: React.FC<{ isLandingPage?: boolean }> = ({ isLandingPage = false }) => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleAuthAction = () => {
    if (user) {
      logout();
      navigate('/');
    } else {
      navigate('/login');
    }
  };

  const getDashboardPath = () => {
      if (!user) return "/";
      if (user.role === Role.MasterAdmin) return "/admin";
      if (user.role === Role.Organisation) return "/organisation";
      if (user.role === Role.Volunteer) return "/volunteer";
      return "/";
  }

  return (
    <header className={`w-full z-50 border-b border-white/5 bg-black/80 backdrop-blur-xl ${isLandingPage ? 'fixed' : 'sticky'} top-0`}>
      <div className="container mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="flex items-center gap-3 group">
          <div className="h-8 w-8 bg-orange-600 rounded-lg flex items-center justify-center text-white font-black text-xs transition-transform group-hover:scale-110">
            S
          </div>
          <span className="text-xl md:text-2xl font-bold text-white font-cinzel tracking-tighter">
            SSK<span className="text-orange-500">PEOPLE</span>
          </span>
        </Link>

        <div className="flex items-center space-x-8">
          {user && (
            <Link to={getDashboardPath()} className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-400 hover:text-white transition-all hidden sm:block">
              Network Portal
            </Link>
          )}
          <div className="h-6 w-px bg-white/10 hidden sm:block"></div>
          <Button 
            onClick={handleAuthAction} 
            size="sm" 
            className="px-6 py-2.5 text-[10px] font-black uppercase tracking-[0.2em] rounded-full"
          >
            {user ? 'Terminate Session' : 'Access System'}
          </Button>
        </div>
      </div>
    </header>
  );
};

export default Header;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import Header from '../components/layout/Header';
import Footer from '../components/layout/Footer';
import Card from '../components/ui/Card';
import ScrollingStrip from '../components/ui/ScrollingStrip';
import VolunteerScrollingStrip from '../components/ui/VolunteerScrollingStrip';
import GenderChart from '../components/charts/GenderChart';
import OccupationChart from '../components/charts/OccupationChart';
import SupportChart from '../components/charts/SupportChart';
import Leaderboard from '../components/Leaderboard';
import Rewards from '../components/Rewards';
import { supabase } from '../supabase/client';
import { Member, Organisation, Role } from '../types';
import { Users, RefreshCw, Globe, Activity, ShieldCheck, Database, Award } from 'lucide-react';

const LandingPage: React.FC = () => {
  const [members, setMembers] = useState<Member[]>([]);
  const [organisations, setOrganisations] = useState<Organisation[]>([]);
  const [volsData, setVolsData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [lastSync, setLastSync] = useState<Date>(new Date());

  const fetchData = useCallback(async () => {
    try {
      const [mRes, oRes, pRes] = await Promise.all([
        supabase.from('members').select('*'),
        supabase.from('organisations').select('*'),
        supabase.from('profiles').select('*')
      ]);

      if (mRes.data) setMembers(mRes.data);
      if (oRes.data) setOrganisations(oRes.data);

      if (pRes.data) {
        const filteredVols = pRes.data.filter(p => {
          if (!p.role) return false;
          const roleStr = String(p.role).toLowerCase();
          return roleStr === 'volunteer';
        });
        setVolsData(filteredVols);
      }

      setLastSync(new Date());
    } catch (err) {
      console.error("Master Sync Failure:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();

    const channel = supabase
      .channel('public-registry-monitor')
      .on('postgres_changes', 'public', 'members', () => fetchData())
      .on('postgres_changes', 'public', 'profiles', () => fetchData())
      .on('postgres_changes', 'public', 'organisations', () => fetchData())
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [fetchData]);

  const volunteers = useMemo(() => {
    if (!volsData.length) return [];
    const enrollmentMap = members.reduce((acc, m) => {
      if (m.volunteer_id) acc[m.volunteer_id] = (acc[m.volunteer_id] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    return volsData.map(v => ({
      id: v.id,
      name: v.name || 'Anonymous Agent',
      email: v.email,
      role: Role.Volunteer,
      organisationId: v.organisation_id,
      mobile: v.mobile,
      enrollments: enrollmentMap[v.id] || 0,
    }));
  }, [volsData, members]);

  const totalMembers = members.length;

  return (
    <div className="bg-black text-white min-h-screen selection:bg-orange-500/30 overflow-x-hidden">
      <Header isLandingPage />

      {/* Hero Section - Refined for Trust */}
      <section className="relative pt-40 md:pt-56 pb-24 px-6">
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full max-w-7xl h-full opacity-20 pointer-events-none overflow-hidden">
           <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[800px] h-[800px] bg-orange-600/20 blur-[120px] rounded-full -mt-96"></div>
        </div>

        <div className="max-w-6xl mx-auto text-center relative z-10">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-full mb-10 backdrop-blur-md">
            <ShieldCheck size={14} className="text-orange-500" />
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-300">Verified Community Registry</span>
          </div>

          <h1 className="text-3xl sm:text-4xl md:text-6xl lg:text-7xl font-cinzel font-bold uppercase tracking-tight leading-[1.1] mb-12">
            <span className="text-white block">THE SOMAVAMSHA</span>
            <span className="text-white/60 block mb-2">SAHASRARJUNA</span>
            <span className="text-orange-600 block drop-shadow-[0_0_30px_rgba(234,88,12,0.3)]">KSHATRIYA (SSK)</span>
          </h1>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-12 text-gray-400 text-sm md:text-base leading-relaxed text-left max-w-5xl mx-auto font-light border-t border-white/5 pt-12">
            <p>
              The Somavamsha Sahasrarjuna Kshatriya (SSK) community belongs to the Somavamsha or Chandravamsha (Lunar Dynasty), one of the three main Kshatriya lineages in India. Descended from Soma (the Moon), they are known as warriors of the Moon Dynasty, carrying a legacy of strength and spiritual wisdom.
            </p>
            <p>
              The name Sahasrarjuna refers to the great emperor Kartavirya Arjuna, who was blessed with a thousand hands for his devotion and strength. Today, we unite under this banner to manage our global identity and support our members through digital transparency.
            </p>
          </div>

          <div className="mt-20 flex justify-center">
            <div className="relative group max-w-lg w-full">
              <div className="absolute -inset-4 bg-orange-600/10 rounded-[3rem] blur-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-1000"></div>
              <div className="relative rounded-[2.5rem] overflow-hidden border border-white/10 shadow-2xl bg-[#050505]">
                <img 
                  src="https://i.pinimg.com/736x/68/ac/f6/68acf6f32a216959c497c7a232b35551.jpg" 
                  alt="Sahasrarjuna Illustration" 
                  className="w-full h-auto grayscale opacity-80 group-hover:grayscale-0 group-hover:opacity-100 transition-all duration-1000"
                />
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Registry Dual Ticker - High End Component Placement */}
