                  <Users className="text-orange-500/40 group-hover:text-orange-500 transition-all duration-500 mb-8" size={56} strokeWidth={1} />
                  <p className="text-[10px] font-black uppercase tracking-[0.5em] text-gray-500 mb-4 text-center">Verified Members</p>
                  <p className="text-7xl md:text-8xl font-black text-white tracking-tighter leading-none font-cinzel transition-all group-hover:scale-105">
                    {totalMembers}
                  </p>
                </Card>

                <Card title="Gender Profile" icon={<Activity size={20}/>}>
                  <GenderChart members={members} />
                </Card>

                <Card title="Professional Distribution" icon={<Award size={20}/>}>
                  <OccupationChart members={members} />
                </Card>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                  <Card title="Support Requirement Matrix" className="lg:col-span-3" icon={<Database size={20}/>}>
                    <SupportChart members={members} />
                  </Card>

                  <Card title="Global Network" className="flex flex-col justify-center items-center text-center p-12">
                      <div className="w-full space-y-12">
                          <div className="group">
                              <p className="text-5xl font-black text-orange-500 mb-2 font-cinzel group-hover:scale-110 transition-transform">{volunteers.length}</p>
                              <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Active Personnel</p>
                          </div>
                          <div className="h-px w-full bg-white/5"></div>
                          <div className="group">
                              <p className="text-5xl font-black text-orange-500 mb-2 font-cinzel group-hover:scale-110 transition-transform">{organisations.length}</p>
                              <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Strategic Nodes</p>
                          </div>
                      </div>
                  </Card>
              </div>
