/* Base Tailwind directives are handled by the CDN script in index.html */

/* Custom scrollbar for a premium dark UI feel */
.custom-scrollbar::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.custom-scrollbar::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.02);
  border-radius: 10px;
}

.custom-scrollbar::-webkit-scrollbar-thumb {
  background: rgba(255, 100, 0, 0.1);
  border-radius: 10px;
  border: 2px solid transparent;
  background-clip: content-box;
}

.custom-scrollbar::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 100, 0, 0.3);
  background-clip: content-box;
}

/* Glassmorphism & Depth */
.glass-panel {
  background: rgba(5, 5, 5, 0.7);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.glass-card {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.03) 0%, rgba(255, 255, 255, 0) 100%);
  border: 1px solid rgba(255, 255, 255, 0.05);
  box-shadow: 0 10px 40px -10px rgba(0, 0, 0, 0.5);
  transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.glass-card:hover {
  background: rgba(255, 255, 255, 0.04);
  border-color: rgba(255, 100, 0, 0.2);
  transform: translateY(-4px);
  box-shadow: 0 20px 60px -10px rgba(255, 100, 0, 0.1);
}

/* Dynamic Glows */
.registry-node-glow {
  animation: glow-pulse-registry 3s infinite ease-in-out;
}

@keyframes glow-pulse-registry {
  0%, 100% { box-shadow: inset 0 0 15px rgba(234, 88, 12, 0.05); border-color: rgba(234, 88, 12, 0.1); }
  50% { box-shadow: inset 0 0 35px rgba(234, 88, 12, 0.25); border-color: rgba(234, 88, 12, 0.5); }
}

.personnel-node-glow {
  animation: glow-pulse-personnel 3s infinite ease-in-out;
}

@keyframes glow-pulse-personnel {
  0%, 100% { box-shadow: inset 0 0 15px rgba(59, 130, 246, 0.05); border-color: rgba(59, 130, 246, 0.1); }
  50% { box-shadow: inset 0 0 35px rgba(59, 130, 246, 0.25); border-color: rgba(59, 130, 246, 0.5); }
}

/* Marquee & Motion */
@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

.animate-marquee {
  display: flex;
  width: max-content;
  animation: marquee 80s linear infinite;
}

.animate-marquee:hover {
  animation-play-state: paused;
}

@keyframes fadeInScale {
  from { opacity: 0; transform: translateY(20px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.animate-in {
  animation: fadeInScale 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

