          </div>

          <h1 className="text-5xl sm:text-6xl md:text-8xl lg:text-9xl font-cinzel font-bold uppercase tracking-tight leading-[0.9] mb-20">
            <span className="text-white/40 block mb-2">THE SOMAVAMSHA</span>
            <span className="text-white block">SAHASRARJUNA</span>
            <span className="text-orange-600 block drop-shadow-[0_0_60px_rgba(234,102,12,0.5)] mt-4">KSHATRIYA</span>
          </h1>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-16 text-gray-400 text-sm md:text-lg leading-relaxed text-left max-w-6xl mx-auto font-light border-t border-white/5 pt-20">
