            SSK <span className="text-[#FF6600]">PEOPLE</span>
          </span>
        </Link>

        <div className="flex items-center space-x-6">
          {user ? (
            <>
              <Link to={getDashboardPath()} className="text-xs font-bold uppercase tracking-widest text-gray-400 hover:text-white transition-all hidden sm:block">
