import React from 'react';
import { PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Gender, Member } from '../../types';

interface GenderChartProps {
    members: Member[];
}

const GenderChart: React.FC<GenderChartProps> = ({ members }) => {
    const genderCounts = Object.values(Gender).reduce((acc, g) => {
        acc[g] = 0;
        return acc;
    }, {} as Record<string, number>);

    members.forEach(member => {
        const g = member.gender;
        if (g && genderCounts[g] !== undefined) genderCounts[g]++;
    });

    const data = Object.entries(genderCounts).map(([name, value]) => ({ name, value }));

    // Exact Colors from Screenshot: Orange (Male), Blue (Female), Yellow (Other)
    const COLORS = ['#FF6600', '#0095FF', '#FFCC00'];

    return (
        <div style={{ width: '100%', height: 260 }}>
            <ResponsiveContainer>
                <PieChart>
                    <Pie
                        data={data}
                        cx="50%"
                        cy="50%"
                        innerRadius={70}
                        outerRadius={100}
                        paddingAngle={2}
                        dataKey="value"
                        stroke="none"
                    >
                        {data.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                        ))}
                    </Pie>
                    <Tooltip 
                        contentStyle={{ backgroundColor: '#000', border: '1px solid #333', color: '#fff' }}
                    />
                    <Legend 
                      verticalAlign="bottom" 
                      align="center" 
                      iconType="rect"
                      formatter={(value) => <span className="text-[12px] font-bold text-gray-400 uppercase tracking-widest">{value}</span>}
                    />
                </PieChart>
            </ResponsiveContainer>
        </div>
    );
};

