              </div>
            </div>
          </div>
        </section>

        {/* Hall of Fame */}
        <section className="mt-40">
           <Rewards members={members} volunteers={volunteers} organisations={organisations} />
        </section>

        <section className="mt-40">
           <Leaderboard members={members} organisations={organisations} volunteers={volunteers} />
        </section>

        {/* Join Registry CTA */}
        <section className="text-center pt-32 pb-24 px-4">
          <div className="max-w-5xl mx-auto py-20 px-6 md:px-10 bg-[#000000] border border-white/5 rounded-[1.5rem] md:rounded-[3rem] shadow-2xl relative overflow-hidden group">
            <div className="relative z-10">
              <h2 className="text-3xl md:text-6xl font-cinzel text-white uppercase tracking-[0.15em] mb-10">
                JOIN THE REGISTRY
              </h2>
              <p className="text-white font-normal text-lg md:text-2xl mb-16 max-w-2xl mx-auto">
