import React from 'react';
import { Trophy, Shield } from 'lucide-react';
import { Volunteer, Organisation, Member } from '../types';

interface LeaderboardProps {
    volunteers: Volunteer[];
    organisations: Organisation[];
    members: Member[];
}

const Leaderboard: React.FC<LeaderboardProps> = ({ volunteers, organisations, members }) => {
  const topVolunteers = [...volunteers]
    .sort((a, b) => b.enrollments - a.enrollments)
    .slice(0, 5);

  const orgEnrollments = members.reduce((acc, member) => {
    acc[member.organisation_id] = (acc[member.organisation_id] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const topOrganisations = [...organisations]
    .map(org => ({ ...org, enrollments: orgEnrollments[org.id] || 0 }))
    .sort((a, b) => b.enrollments - a.enrollments)
    .slice(0, 5);

  return (
    <div className="space-y-12">
      <div className="text-center">
        <h2 className="text-3xl md:text-5xl font-cinzel uppercase tracking-[0.2em]">
          <span className="text-white">LEADING</span> <span className="text-[#FF6600]">CONTRIBUTORS</span>
        </h2>
      </div>

      <div className="grid md:grid-cols-2 gap-8 max-w-7xl mx-auto">
        {/* Top Volunteers Card */}
        <div className="bg-[#0f172a] border border-white/5 rounded-xl p-8 shadow-2xl">
          <h3 className="text-[#FF6600] text-xs font-black uppercase tracking-[0.3em] mb-8">
            TOP VOLUNTEERS
          </h3>
          <div className="space-y-3">
            {topVolunteers.map((volunteer) => (
              <div 
                key={volunteer.id} 
                className="flex items-center justify-between p-4 bg-[#1e293b] rounded-lg group hover:bg-[#2d3748] transition-colors"
              >
                <div className="flex items-center gap-4">
                  <div className="text-orange-400">
                    <Trophy size={20} strokeWidth={2.5} />
                  </div>
                  <span className="font-bold text-white text-sm md:text-base">
                    {volunteer.name}
                  </span>
                </div>
                <span className="text-lg font-black text-[#FF6600] font-mono">
                  {volunteer.enrollments}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Top Organisations Card */}
        <div className="bg-[#0f172a] border border-white/5 rounded-xl p-8 shadow-2xl">
          <h3 className="text-[#FF6600] text-xs font-black uppercase tracking-[0.3em] mb-8">
            TOP ORGANISATIONS
          </h3>
          <div className="space-y-3">
            {topOrganisations.map((org) => (
              <div 
                key={org.id} 
                className="flex items-center justify-between p-4 bg-[#1e293b] rounded-lg group hover:bg-[#2d3748] transition-colors"
              >
                <div className="flex items-center gap-4">
                  <div className="text-orange-400">
                    <Shield size={20} strokeWidth={2.5} />
                  </div>
                  <span className="font-bold text-white text-sm md:text-base">
                    {org.name}
                  </span>
                </div>
                <span className="text-lg font-black text-[#FF6600] font-mono">
                  {org.enrollments}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

