                        </div>
                        <button onClick={handleLogout} className="w-full p-4 bg-red-600/10 text-red-500 border border-red-600/20 rounded-xl font-black uppercase tracking-widest text-[10px]">
                            Terminate Session
                        </button>
                    </div>
                </div>
              </>
            )}
        </div>
    );
};

export default DashboardLayout;

