                                    <div className="aspect-[1.58/1] rounded-2xl overflow-hidden border border-white/10 bg-black/60 relative group/img shadow-xl">
                                        <img src={editingMember.aadhaar_front_url} className="w-full h-full object-cover transition-transform duration-700 group-hover/img:scale-110" />
                                        <a href={editingMember.aadhaar_front_url} target="_blank" className="absolute inset-0 bg-black/70 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-all duration-300">
