                        {/* High-Density Form Grid */}
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                            <Input label="Given Name" value={editingMember.name} onChange={(e) => setEditingMember({...editingMember, name: e.target.value})} icon={<UserIcon size={12} />} className="text-sm" />
                            <Input label="Surname" value={editingMember.surname} onChange={(e) => setEditingMember({...editingMember, surname: e.target.value})} icon={<UserIcon size={12} />} className="text-sm" />
                            <Input label="Father / Guardian" value={editingMember.father_name} onChange={(e) => setEditingMember({...editingMember, father_name: e.target.value})} icon={<UserCircle size={12} />} className="text-sm" description="Full Name remains Name + Surname" />

                            <Input label="Primary Mobile" value={editingMember.mobile} onChange={(e) => setEditingMember({...editingMember, mobile: e.target.value})} icon={<Phone size={12} />} className="text-sm" />
                            <Input label="Emergency Contact" value={editingMember.emergency_contact} onChange={(e) => setEditingMember({...editingMember, emergency_contact: e.target.value})} icon={<Phone size={12} />} className="text-sm" />
                            <Input label="Date of Birth" type="date" value={editingMember.dob} onChange={(e) => setEditingMember({...editingMember, dob: e.target.value})} icon={<Calendar size={12} />} className="text-sm" />

                            <Select label="Gender" value={editingMember.gender} onChange={(e) => setEditingMember({...editingMember, gender: e.target.value as Gender})}>
                                {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
                            </Select>
                            <Input label="Pincode" value={editingMember.pincode} onChange={(e) => setEditingMember({...editingMember, pincode: e.target.value})} icon={<MapPin size={12} />} className="text-sm" />
                            <Select label="Registry Status" value={editingMember.status} onChange={(e) => setEditingMember({...editingMember, status: e.target.value as MemberStatus})}>
                                <option value={MemberStatus.Pending}>Pending</option>
                                <option value={MemberStatus.Accepted}>Accepted</option>
                            </Select>

                            <div className="sm:col-span-2 lg:col-span-3">
                                <Input label="Residential Address" value={editingMember.address} onChange={(e) => setEditingMember({...editingMember, address: e.target.value})} icon={<MapPin size={12} />} className="text-sm" />
                            </div>
                        </div>

                        <div className="flex flex-wrap justify-between items-center gap-4 pt-6 border-t border-white/5">
                            <div className="flex gap-2">
                                <Button variant="secondary" onClick={() => handleCopyDetails(editingMember)} className="px-4 py-3 text-[9px] font-black uppercase tracking-widest gap-2 bg-white/5">
                                    <Copy size={14} /> Copy Details
                                </Button>
                                <Button variant="secondary" onClick={() => setIsEditModalOpen(false)} className="px-6 py-3 text-[9px] font-black uppercase tracking-widest">Abort</Button>
                            </div>

                            <Button onClick={handleUpdateMember} disabled={isUpdating} className="px-10 py-4 text-[10px] font-black uppercase tracking-[0.3em] bg-orange-600 hover:bg-orange-500 shadow-xl flex items-center gap-2">
                                {isUpdating ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                                {isUpdating ? 'Syncing...' : 'Save Record'}
                            </Button>
                        </div>
                    </div>
                )}
            </Modal>

            <Modal isOpen={!!memberToDelete} onClose={() => setMemberToDelete(null)} title="Registry Security: Purge Record">
                <div className="p-6 text-center space-y-8">
                    <div className="p-6 bg-red-500/10 rounded-full w-20 h-20 mx-auto flex items-center justify-center text-red-500 border border-red-500/20 shadow-inner">
                        <AlertTriangle size={36} strokeWidth={1.5} />
                    </div>
                    <div className="space-y-2">
                        <h4 className="text-xl font-cinzel text-white tracking-widest">Irreversible Purge</h4>
                        <p className="text-[10px] text-gray-500 leading-relaxed uppercase tracking-[0.2em] font-black max-w-[280px] mx-auto">
                            Erase <span className="text-red-500">"{memberToDelete ? formatDisplayName(memberToDelete.name, memberToDelete.surname) : ''}"</span> from the global registry?
                        </p>
                    </div>
                    <div className="flex gap-4">
                        <Button variant="secondary" onClick={() => setMemberToDelete(null)} className="flex-1 text-[10px] font-black tracking-widest uppercase py-4">Abort</Button>
                        <Button onClick={handleDeleteMember} disabled={isDeleting} className="flex-1 bg-red-600 hover:bg-red-700 text-[10px] font-black tracking-widest uppercase py-4">
                            {isDeleting ? 'PURGING...' : 'Execute'}
                        </Button>
                    </div>
                </div>
            </Modal>
        </DashboardLayout>
    );
};

