/* Base Tailwind directives are handled by the CDN script in index.html */

:root {
  color-scheme: dark;
}

body {
  background-color: #000000;
  color: #ffffff;
  font-family: 'Jost', sans-serif;
  margin: 0;
  padding: 0;
}

.font-cinzel {
  font-family: 'Cinzel', serif;
}

/* Ensure native selectors are dark */
select {
  background-color: #050505;
  color: white;
}

/* Exact Chart Card Styling from Screenshot */
.analytics-card {
  background: #050505;
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  position: relative;
  overflow: hidden;
}

.chart-title {
  font-family: 'Cinzel', serif;
  color: #FF6600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 1.1rem;
  font-weight: 500;
}

/* Stat card watermark */
.globe-watermark {
  position: absolute;
  top: 10%;
  right: 5%;
  opacity: 0.05;
  pointer-events: none;
}

.activity-icon-container {
  height: 80px;
  width: 80px;
  background: rgba(255, 102, 0, 0.05);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

@keyframes pulse-soft {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.1); opacity: 0.7; }
}

.animate-pulse-soft {
  animation: pulse-soft 2.5s infinite ease-in-out;
}

/* Marquee Animation */
@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

