import React from 'react';
import { Organisation } from '../../types';
import { Building2, Activity, Globe } from 'lucide-react';

interface OrgMarqueeProps {
  organisations: Organisation[];
}

const OrgMarquee: React.FC<OrgMarqueeProps> = ({ organisations }) => {
  if (organisations.length === 0) return null;

  // Newest to Oldest sorting
  const sortedOrgs = [...organisations].reverse();

  // Duplicate list thrice to ensure no gaps even on ultra-wide screens
  const displayOrgs = [...sortedOrgs, ...sortedOrgs, ...sortedOrgs];

  return (
    <div className="w-full bg-black/20 border-y border-white/[0.03] py-8 overflow-hidden group relative">
      {/* Premium Edge Fades */}
      <div className="absolute inset-y-0 left-0 w-32 md:w-64 bg-gradient-to-r from-black via-black/80 to-transparent z-20 pointer-events-none"></div>
      <div className="absolute inset-y-0 right-0 w-32 md:w-64 bg-gradient-to-l from-black via-black/80 to-transparent z-20 pointer-events-none"></div>

      {/* Floating Background Accent */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-1/2 bg-orange-600/5 blur-[120px] pointer-events-none"></div>

      <div className="flex animate-marquee-slow group-hover:[animation-play-state:paused] whitespace-nowrap">
        {displayOrgs.map((org, idx) => (
          <div 
            key={`${org.id}-${idx}`}
            className="flex items-center gap-6 px-10 py-5 mx-5 bg-white/[0.02] backdrop-blur-2xl border border-white/[0.05] hover:border-orange-500/40 rounded-[2rem] transition-all duration-700 shadow-[0_20px_50px_rgba(0,0,0,0.5)] hover:shadow-[0_20px_60px_-10px_rgba(234,88,12,0.15)] hover:scale-[1.02] group/item cursor-default"
          >
            {/* Logo Container with Soft Neumorphism */}
            <div className="relative">
              <div className="h-16 w-16 rounded-2xl overflow-hidden border border-white/10 bg-black/60 flex-shrink-0 flex items-center justify-center p-2 transition-transform duration-500 group-hover/item:scale-110 shadow-inner">
                {org.profile_photo_url ? (
                  <img 
                    src={org.profile_photo_url} 
                    alt={org.name} 
                    className="h-full w-full object-contain filter drop-shadow-lg"
                    loading="lazy"
                  />
                ) : (
                  <Building2 size={32} className="text-orange-500/30" />
                )}
              </div>
              {/* Glow Pulse for Newest Items */}
              {idx < sortedOrgs.length && idx < 5 && (
                <div className="absolute -top-1 -right-1 h-3 w-3 bg-orange-500 rounded-full blur-[2px] animate-pulse"></div>
              )}
            </div>

            <div className="flex flex-col">
              <div className="flex items-center gap-3">
                <span className="text-sm md:text-lg font-bold text-white tracking-tight leading-none group-hover/item:text-orange-500 transition-colors">
                  {org.name}
                </span>
                <div className="h-1 w-1 rounded-full bg-white/20"></div>
                <div className="flex items-center gap-1.5 opacity-60">
                  <Activity size={10} className="text-orange-500" />
                  <span className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-400">Node Active</span>
                </div>
              </div>
              <div className="flex items-center gap-2 mt-2">
                <div className="px-2.5 py-1 bg-white/[0.03] border border-white/[0.05] rounded-full flex items-center gap-2">
                  <Globe size={10} className="text-gray-600" />
                  <span className="text-[9px] font-black text-gray-500 uppercase tracking-[0.3em]">
                    Registry Authorized
                  </span>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

