      <div className="flex animate-marquee-slow group-hover:[animation-play-state:paused] whitespace-nowrap">
        {displayOrgs.map((org, idx) => (
          <div 
            key={`${org.id}-${idx}`}
            className="flex-shrink-0 w-1/2 md:w-1/4 px-6 md:px-10 group/card"
          >
            <div className="flex flex-col items-center transition-transform duration-500 group-hover/card:-translate-y-1">

              {/* Uniform Image Section (Top) - Strictly borderless */}
              <div className="relative w-full aspect-square mb-4 md:mb-6 overflow-hidden rounded-[1.5rem] md:rounded-[2.5rem] bg-zinc-900/50 shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
