  const { organisations, volunteers } = useMemo(() => {
    // 1. De-duplicate Organisations by Mobile (Primary Key for Identity)
    const orgMap = new Map();
    (orgsDataRaw || []).forEach(o => {
      const mobile = o.mobile?.trim();
      const key = mobile || o.id;
      if (!orgMap.has(key)) orgMap.set(key, o);
    });
    const uniqueOrgs = Array.from(orgMap.values());
    const orgMobiles = new Set(uniqueOrgs.map(o => o.mobile?.trim()).filter(Boolean));

    // 2. Prepare Volunteer Enrollment Map
    const enrollmentMap = members.reduce((acc, m) => {
      if (m.volunteer_id) acc[m.volunteer_id] = (acc[m.volunteer_id] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    // 3. De-duplicate Volunteers and filter out those who are already shown in Orgs
    const volMap = new Map();
    (volsDataRaw || []).forEach(v => {
      const mobile = v.mobile?.trim();
      // Skip if already in Orgs to prevent redundant display
      if (mobile && orgMobiles.has(mobile)) return;

