                            <input type="file" ref={editFileInputRef} className="hidden" accept="image/*" onChange={(e) => {
                                if (e.target.files?.[0]) {
                                    setEditProfilePhoto(e.target.files[0]);
                                    setEditPreviewUrl(URL.createObjectURL(e.target.files[0]));
                                }
