import React, { useState, useMemo, useEffect } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Modal from '../../components/ui/Modal';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../supabase/client';
import { Member, MemberStatus, Role, User as VolunteerUser, Gender, Occupation, SupportNeed, MaritalStatus, Qualification } from '../../types';
import { useNotification } from '../../context/NotificationContext';
import { 
  FileSpreadsheet, 
  Search, 
  User as UserIcon, 
  ExternalLink,
  Edit3,
  Save,
  Calendar,
  Fingerprint,
  MapPin,
  Activity,
  Phone,
  UserCircle,
  BadgeCheck,
  Loader2,
  Eye,
  Image as ImageIcon,
  CheckCircle,
  Clock,
  Copy
} from 'lucide-react';

type MemberWithAgent = Member & {
    agent_profile?: { name: string, mobile: string, profile_photo_url?: string }
};

const OrganisationReports: React.FC = () => {
    const { user } = useAuth();
    const [myMembers, setMyMembers] = useState<MemberWithAgent[]>([]);
    const [allOrgProfiles, setAllOrgProfiles] = useState<VolunteerUser[]>([]);
    const [loading, setLoading] = useState(true);
    const { addNotification } = useNotification();

    const [editingMember, setEditingMember] = useState<MemberWithAgent | null>(null);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [isUpdating, setIsUpdating] = useState(false);

    const [filters, setFilters] = useState({ 
        startDate: '', 
        endDate: '', 
        agentId: '', 
        search: '', 
        status: '' 
    });

    const formatDisplayName = (first: string, last: string) => {
        const f = (first || '').trim().toLowerCase();
        const l = (last || '').trim().toLowerCase();
        return `${f} ${l}`.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    };

    const fetchData = async () => {
        if (!user?.organisationId) return;
        setLoading(true);
        try {
            const [membersRes, profilesRes] = await Promise.all([
                supabase
                    .from('members')
                    .select('*, agent_profile:profiles!volunteer_id(name, mobile, profile_photo_url)')
                    .eq('organisation_id', user.organisationId)
                    .order('submission_date', { ascending: false }),
                supabase
                    .from('profiles')
                    .select('*')
                    .eq('organisation_id', user.organisationId)
            ]);

            if (membersRes.data) setMyMembers(membersRes.data as MemberWithAgent[]);
            if (profilesRes.data) {
                const mappedProfiles: VolunteerUser[] = profilesRes.data.map(p => ({
                    id: p.id,
                    name: p.name,
                    email: p.email,
                    role: p.role as Role,
                    organisationId: p.organisation_id,
                    mobile: p.mobile,
                    status: p.status
                }));
                setAllOrgProfiles(mappedProfiles);
            }
        } catch (error) {
            addNotification("Sync failed.", "error");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, [user]);

    const filteredMembers = useMemo(() => {
        return myMembers.filter(member => {
            if (filters.agentId && member.volunteer_id !== filters.agentId) return false;
            if (filters.status && member.status !== filters.status) return false;
            const subDate = new Date(member.submission_date);
            const start = filters.startDate ? new Date(filters.startDate) : null;
            const end = filters.endDate ? new Date(filters.endDate) : null;
            if (end) end.setHours(23, 59, 59, 999);
            if (start && subDate < start) return false;
            if (end && subDate > end) return false;
            if (filters.search) {
                const term = filters.search.toLowerCase();
                return member.name.toLowerCase().includes(term) || member.surname.toLowerCase().includes(term) || member.mobile.includes(term) || member.aadhaar.includes(term);
            }
            return true;
        });
    }, [myMembers, filters]);

    const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
    };

    const handleEditMember = (member: MemberWithAgent) => {
        setEditingMember({ ...member });
        setIsEditModalOpen(true);
    };

    const handleCopyDetails = (member: MemberWithAgent) => {
        const text = `Name: ${formatDisplayName(member.name, member.surname)}\nMobile: ${member.mobile}\nAadhaar: ${member.aadhaar}`;
        navigator.clipboard.writeText(text);
        addNotification("Identity details copied to clipboard.", "info");
    };

    const handleUpdateMember = async () => {
        if (!editingMember || editingMember.status === MemberStatus.Accepted) return;
        setIsUpdating(true);
        try {
            const { error } = await supabase.from('members').update({
                name: editingMember.name.trim(),
                surname: editingMember.surname.trim(),
                father_name: editingMember.father_name.trim(),
                mobile: editingMember.mobile.trim(),
                emergency_contact: editingMember.emergency_contact.trim(),
                dob: editingMember.dob,
                gender: editingMember.gender,
                marital_status: editingMember.marital_status,
                qualification: editingMember.qualification,
                pincode: editingMember.pincode,
                address: editingMember.address,
                occupation: editingMember.occupation,
                support_need: editingMember.support_need,
            }).eq('id', editingMember.id);

            if (error) throw error;
            addNotification("Member synchronized.", "success");
            setIsEditModalOpen(false);
            fetchData();
        } catch (err: any) {
            addNotification(`Sync failed.`, "error");
        } finally {
            setIsUpdating(false);
        }
    };

    const handleExport = () => {
        const headers = ['Aadhaar', 'Identity Name', 'Father Name', 'Mobile', 'DOB', 'Pincode', 'Address', 'Volunteer', 'Date', 'Status'];
        const rows = filteredMembers.map(m => [
            m.aadhaar, 
            formatDisplayName(m.name, m.surname), 
            m.father_name, 
            m.mobile, 
            m.dob, 
            m.pincode, 
            m.address,
            m.agent_profile?.name || 'N/A',
            m.submission_date.split('T')[0], 
            m.status
        ]);
        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = `Registry_Export_${new Date().toISOString().split('T')[0]}.csv`;
        link.click();
    };

    const isVerified = editingMember?.status === MemberStatus.Accepted;

    return (
        <DashboardLayout title="Our Members’ Data Registry">
            <div className="space-y-8">
                <Card className="bg-gray-950 border-white/5 p-5 sm:p-8 rounded-[2rem] shadow-2xl relative overflow-hidden">
                    <div className="flex items-center gap-2 mb-6 sm:mb-8 text-blue-500 relative z-10">
                        <Activity size={18} />
                        <h3 className="text-[10px] font-black uppercase tracking-[0.4em]">Registry Query Node</h3>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-8 relative z-10">
                        <Select label="VOLUNTEER" name="agentId" value={filters.agentId} onChange={handleFilterChange}>
                            <option value="">All Volunteers</option>
                            {allOrgProfiles.filter(p => p.role === Role.Volunteer).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                        </Select>
                        <Select label="VERIFICATION" name="status" value={filters.status} onChange={handleFilterChange}>
                            <option value="">All States</option>
                            <option value={MemberStatus.Pending}>Pending</option>
                            <option value={MemberStatus.Accepted}>Accepted</option>
                        </Select>
                        <Input type="date" label="START" name="startDate" value={filters.startDate} onChange={handleFilterChange} />
                        <Input type="date" label="END" name="endDate" value={filters.endDate} onChange={handleFilterChange} />
                    </div>
                    <div className="mt-8 sm:mt-10 pt-6 sm:pt-8 border-t border-white/5 flex flex-col md:flex-row justify-between items-center gap-6 relative z-10">
                        <Input placeholder="Search Identity..." name="search" value={filters.search} onChange={handleFilterChange} icon={<Search size={16} />} className="flex-1" />
                        <Button onClick={handleExport} className="w-full md:w-auto bg-blue-600 hover:bg-blue-700 px-10"><FileSpreadsheet size={16} className="mr-2" /> Export CSV</Button>
                    </div>
                </Card>

                <Card title="Our Members’ Data Registry">
                    <div className="overflow-x-auto custom-scrollbar">
                        <table className="w-full text-left">
                            <thead className="border-b border-gray-800">
                                <tr className="text-gray-500 text-[10px] uppercase font-black tracking-widest">
                                    <th className="p-4 sm:p-6">Identity Node</th>
                                    <th className="p-4 sm:p-6 hidden sm:table-cell">Volunteer</th>
                                    <th className="p-4 sm:p-6 text-center">Status</th>
                                    <th className="p-4 sm:p-6 text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    <tr><td colSpan={4} className="p-24 text-center text-[11px] animate-pulse font-black uppercase tracking-[0.4em] text-gray-500">Syncing...</td></tr>
                                ) : filteredMembers.map(member => (
                                    <tr key={member.id} className="group border-b border-gray-900/50 hover:bg-white/[0.02] transition-all">
                                        <td className="p-4 sm:p-6">
                                            <div className="flex flex-col">
                                                <span className="font-bold text-white text-sm sm:text-lg group-hover:text-blue-400 transition-colors truncate">
                                                    {formatDisplayName(member.name, member.surname)}
                                                </span>
                                                <div className="flex items-center gap-2 sm:gap-3 mt-1 text-[10px] sm:text-[11px] text-gray-400 font-mono tracking-tighter">
                                                    <span>{member.mobile}</span>
                                                    <span className="h-1 w-1 rounded-full bg-gray-700"></span>
                                                    <span>{member.aadhaar.slice(-4).padStart(12, '•')}</span>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-4 sm:p-6 hidden sm:table-cell">
                                            <div className="flex items-center gap-3">
                                                <div className="h-8 w-8 flex-shrink-0 rounded-lg overflow-hidden border border-white/10 group-hover:border-blue-500/50 transition-all shadow-lg bg-black/40">
                                                  {member.agent_profile?.profile_photo_url ? (
                                                    <img 
                                                      src={member.agent_profile.profile_photo_url} 
                                                      className="h-full w-full object-cover" 
                                                      alt="Volunteer profile" 
                                                    />
                                                  ) : (
                                                    <div className="h-full w-full flex items-center justify-center text-blue-500/30">
                                                        <UserCircle size={16} />
                                                    </div>
                                                  )}
                                                </div>
                                                <span className="text-[10px] font-black text-white uppercase tracking-widest">{member.agent_profile?.name || 'Volunteer'}</span>
                                            </div>
                                        </td>
                                        <td className="p-4 sm:p-6 text-center">
                                            <span className={`px-3 py-1 text-[8px] sm:text-[10px] font-black uppercase rounded-full border ${member.status === MemberStatus.Accepted ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-orange-500/10 text-orange-400 border-orange-500/20'}`}>
                                                {member.status}
                                            </span>
                                        </td>
                                        <td className="p-4 sm:p-6 text-right">
                                            <div className="flex justify-end gap-2">
                                                <button onClick={() => handleEditMember(member)} className="p-2 sm:p-2.5 bg-white/5 rounded-xl border border-white/10 hover:border-blue-500/50 text-gray-500 hover:text-white transition-all" title={member.status === MemberStatus.Accepted ? "View Member" : "Edit Member"}>
                                                    {member.status === MemberStatus.Accepted ? <Eye size={18} /> : <Edit3 size={18} />}
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </Card>
            </div>

            <Modal 
              isOpen={isEditModalOpen} 
              onClose={() => setIsEditModalOpen(false)} 
              title={isVerified ? "Review Identity File" : "Operational Override"} 
              maxWidth="4xl"
              footer={editingMember && (
                <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
                    <div className="flex gap-2 sm:gap-3 w-full sm:w-auto">
                        <Button 
                          variant="secondary" 
                          onClick={() => handleCopyDetails(editingMember)} 
                          className="flex-1 sm:flex-none px-4 py-3.5 text-[9px] font-black uppercase tracking-widest gap-2 bg-white/5 border border-white/5 active:scale-95 transition-all"
                        >
                            <Copy size={16} /> <span>Copy Details</span>
                        </Button>
                        <Button 
                          variant="secondary" 
                          onClick={() => setIsEditModalOpen(false)} 
                          className="flex-1 sm:flex-none px-6 sm:px-10 py-3.5 text-[9px] font-black uppercase tracking-widest active:scale-95 transition-all"
                        >
                            {isVerified ? "Close" : "Cancel"}
                        </Button>
                    </div>
                    {!isVerified && (
                        <Button 
                          onClick={handleUpdateMember} 
                          disabled={isUpdating} 
                          className="w-full sm:w-auto px-10 sm:px-14 py-4 text-[10px] font-black uppercase tracking-[0.4em] bg-blue-600 hover:bg-blue-500 shadow-[0_15px_30px_-10px_rgba(59,130,246,0.4)] flex items-center justify-center gap-2 active:scale-95 transition-all"
                        >
                            {isUpdating ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
                            {isUpdating ? 'SYNCING...' : 'SAVE RECORD'}
                        </Button>
                    )}
                </div>
              )}
            >
                {editingMember && (
                    <div className="space-y-6 sm:space-y-8">
                        <div className={`p-4 sm:p-6 border rounded-[1.5rem] sm:rounded-[2rem] relative overflow-hidden group transition-all duration-500 ${isVerified ? 'bg-green-500/5 border-green-500/10' : 'bg-blue-500/5 border-blue-500/10'}`}>
                            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-8 items-center relative z-10">
                                <div className="lg:col-span-5 space-y-3">
                                    <div className="flex items-center gap-2">
                                        <ImageIcon className={isVerified ? "text-green-500/60" : "text-blue-500/60"} size={12} />
                                        <p className={`text-[9px] font-black uppercase tracking-widest ${isVerified ? "text-green-500/60" : "text-blue-500/60"}`}>Identification Scan</p>
                                    </div>
                                    <div className="rounded-[1rem] sm:rounded-[1.25rem] overflow-hidden border border-white/10 bg-black/40 relative group/img shadow-xl aspect-[1.58/1]">
                                        <img src={editingMember.aadhaar_front_url} className="w-full h-full object-cover transition-transform duration-700 group-hover/img:scale-105" alt="Aadhaar Front" />
                                        <a href={editingMember.aadhaar_front_url} target="_blank" rel="noopener noreferrer" className="absolute inset-0 bg-black/70 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-opacity backdrop-blur-sm">
                                            <ExternalLink className="text-white" size={24} />
                                        </a>
                                    </div>
                                </div>

                                <div className="lg:col-span-7 flex flex-col justify-center space-y-4 lg:space-y-5">
                                    <div className="space-y-4">
                                        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/5 pb-3">
                                            <div className="space-y-1">
                                                <p className={`text-[9px] font-black uppercase tracking-[0.4em] ${isVerified ? "text-green-500" : "text-blue-500"}`}>Target Identity</p>
                                                <h4 className="text-lg sm:text-2xl font-cinzel text-white leading-none font-bold uppercase break-words pr-2">
                                                    {formatDisplayName(editingMember.name, editingMember.surname)}
                                                </h4>
                                            </div>
                                            <div className="flex-shrink-0">
                                                <div className={`px-3 py-1 rounded-full border text-[8px] font-black uppercase tracking-widest whitespace-nowrap ${editingMember.status === MemberStatus.Accepted ? 'bg-green-500/10 border-green-500/20 text-green-400' : 'bg-orange-500/10 border-orange-500/20 text-orange-400'}`}>
                                                    {editingMember.status} Record
                                                </div>
                                            </div>
                                        </div>
                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                            <div className="px-3 py-2 sm:px-4 sm:py-3 bg-black/40 rounded-xl border border-white/5 flex items-center gap-4 transition-all hover:bg-black/60">
                                                <Fingerprint size={16} className={isVerified ? "text-green-500/50" : "text-blue-500/50"} />
                                                <div className="flex flex-col min-w-0">
                                                    <span className="text-[7px] font-black uppercase tracking-widest text-gray-600 leading-none mb-1">Citizen ID</span>
                                                    <span className="text-xs sm:text-sm font-mono text-white tracking-widest truncate">{editingMember.aadhaar}</span>
                                                </div>
                                            </div>
                                            <div className="px-3 py-2 sm:px-4 sm:py-3 bg-black/40 rounded-xl border border-white/5 flex items-center gap-4 transition-all hover:bg-black/60">
                                                <BadgeCheck size={16} className={isVerified ? "text-green-500/50" : "text-blue-500/50"} />
                                                <div className="flex flex-col min-w-0">
                                                    <span className="text-[7px] font-black uppercase tracking-widest text-gray-600 leading-none mb-1">Verification</span>
                                                    <span className="text-[10px] sm:text-xs font-bold text-white uppercase tracking-tighter truncate">Tier-1 Citizen</span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                    {isVerified && (
                                        <div className="p-2 sm:p-3 bg-green-500/10 border border-green-500/20 rounded-xl flex items-center gap-3">
                                            <CheckCircle size={14} className="text-green-500 shrink-0" />
                                            <p className="text-[9px] font-black text-green-400 uppercase tracking-widest">Verified: Locked</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-5 pb-8">
                            <Input label="Full Name" disabled={isVerified} value={editingMember.name} onChange={(e) => setEditingMember({...editingMember, name: e.target.value})} icon={<UserIcon size={12} />} className="py-2.5 text-xs font-bold" />
                            <Input label="Gharano" disabled={isVerified} value={editingMember.surname} onChange={(e) => setEditingMember({...editingMember, surname: e.target.value})} icon={<UserIcon size={12} />} className="py-2.5 text-xs font-bold" />
                            <Input label="Father Name" disabled={isVerified} value={editingMember.father_name} onChange={(e) => setEditingMember({...editingMember, father_name: e.target.value})} icon={<UserCircle size={12} />} className="py-2.5 text-xs font-bold" />
                            <Input label="Mobile" disabled={isVerified} value={editingMember.mobile} onChange={(e) => setEditingMember({...editingMember, mobile: e.target.value})} icon={<Phone size={12} />} className="py-2.5 text-xs font-bold" />
                            <Input label="DOB" disabled={isVerified} type="date" value={editingMember.dob} onChange={(e) => setEditingMember({...editingMember, dob: e.target.value})} icon={<Calendar size={12} />} className="py-2.5 text-xs font-bold" />
                            <Select label="Gender" disabled={isVerified} value={editingMember.gender} onChange={(e) => setEditingMember({...editingMember, gender: e.target.value as Gender})} className="py-2.5 text-xs font-bold">
                                {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
                            </Select>
                            <Select label="Marital Status" disabled={isVerified} value={editingMember.marital_status} onChange={(e) => setEditingMember({...editingMember, marital_status: e.target.value as MaritalStatus})} className="py-2.5 text-xs font-bold">
                                {Object.values(MaritalStatus).map(m => <option key={m} value={m}>{m}</option>)}
                            </Select>
                            <Select label="Qualification" disabled={isVerified} value={editingMember.qualification} onChange={(e) => setEditingMember({...editingMember, qualification: e.target.value as Qualification})} className="py-2.5 text-xs font-bold">
                                {Object.values(Qualification).map(q => <option key={q} value={q}>{q}</option>)}
                            </Select>
                            <Input label="Pincode" disabled={isVerified} value={editingMember.pincode} onChange={(e) => setEditingMember({...editingMember, pincode: e.target.value})} icon={<MapPin size={12} />} className="py-2.5 text-xs font-bold" />
                            <div className="sm:col-span-2">
                                <Input label="Full Residence" disabled={isVerified} value={editingMember.address} onChange={(e) => setEditingMember({...editingMember, address: e.target.value})} icon={<MapPin size={12} />} className="py-2.5 text-xs font-bold" />
                            </div>
                            <Select label="What do you do?" disabled={isVerified} value={editingMember.occupation} onChange={(e) => setEditingMember({...editingMember, occupation: e.target.value as Occupation})} className="py-2.5 text-xs font-bold">
                                {Object.values(Occupation).map(o => <option key={o} value={o}>{o}</option>)}
                            </Select>
                            <Select label="What do you want?" disabled={isVerified} value={editingMember.support_need} onChange={(e) => setEditingMember({...editingMember, support_need: e.target.value as SupportNeed})} className="py-2.5 text-xs font-bold">
                                {Object.values(SupportNeed).map(s => <option key={s} value={s}>{s}</option>)}
                            </Select>
                        </div>
                    </div>
                )}
            </Modal>
        </DashboardLayout>
    );
};

export default OrganisationReports;

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import DashboardLayout from '../../components/layout/DashboardLayout';
import Card from '../../components/ui/Card';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import Button from '../../components/ui/Button';
import { Gender, Occupation, SupportNeed, MaritalStatus, Qualification } from '../../types';
import { supabase } from '../../supabase/client';
import { useAuth } from '../../context/AuthContext';
import { useNotification } from '../../context/NotificationContext';
import { syncToSheets, SheetType } from '../../services/googleSheets';
import { ShieldAlert, RefreshCw, Fingerprint, ShieldCheck, Search, XCircle, ImageIcon, Image as ImageIcon2, Info } from 'lucide-react';

const initialFormData = {
  aadhaar: '',
  mobile: '',
  name: '',
  surname: '',
  fatherName: '',
  dob: '',
  gender: Gender.Male,
  maritalStatus: MaritalStatus.Single,
  qualification: Qualification.Secondary,
  emergencyContact: '',
  pincode: '',
  address: '',
  aadhaarPhoto: null as File | null,
  occupation: Occupation.Employee,
  supportNeed: SupportNeed.Education,
};

const NewMemberForm: React.FC = () => {
  const { user } = useAuth();
  const { addNotification } = useNotification();
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState(initialFormData);
  const [validationError, setValidationError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isValidating, setIsValidating] = useState(false);

  const [preview, setPreview] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Diagnostic: Check if organization link is broken (ID exists but Name doesn't return from join)
  const isLinkBroken = user?.organisationId && !user?.organisationName;

  const formatInput = (text: string) => {
    return text.trim().toLowerCase().split(' ').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    if ((name === 'aadhaar' || name === 'mobile' || name === 'emergencyContact' || name === 'pincode') && value !== '' && !/^\d+$/.test(value)) return;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setFormData(prev => ({ ...prev, aadhaarPhoto: file }));
      if (preview) URL.revokeObjectURL(preview);
      setPreview(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = () => {
    if (preview) URL.revokeObjectURL(preview);
    setFormData(prev => ({ ...prev, aadhaarPhoto: null }));
    setPreview(null);
  };

  const handleStep1Next = async () => {
    setValidationError('');

    // Safety check for organization linkage
    if (!user?.organisationId || isLinkBroken) {
      setValidationError(`Linkage Fault: Your account is linked to an ID (${user?.organisationId?.slice(0,8)}) that does not exist in the master registry or has been purged.`);
      return;
    }

    if (!formData.aadhaar || !formData.mobile) {
      setValidationError('Action Required: Identity Number and Primary Mobile are mandatory.');
      return;
    }
    if (!/^\d{12}$/.test(formData.aadhaar)) {
      setValidationError('UID must be exactly 12 numeric digits.');
      return;
    }
    if (!/^\d{10}$/.test(formData.mobile)) {
      setValidationError('Mobile must be exactly 10 numeric digits.');
      return;
    }

    setIsValidating(true);
    try {
      const { data, error } = await supabase.from('members').select('id').eq('aadhaar', formData.aadhaar).maybeSingle();

      if (error) {
        setValidationError(`Uplink Error: ${error.message}`);
        return;
      }

      if (data) {
        setValidationError('Identification Conflict: This record already exists in the Global Registry.');
      } else {
        setStep(2);
        window.scrollTo(0, 0);
      }
    } catch (e: any) {
      setValidationError(`System Fault: ${e.message || 'Access Denied'}`);
    } finally {
      setIsValidating(false);
    }
  };

  const handleStep2Next = () => {
    setValidationError('');
    if (!formData.name || !formData.surname || !formData.fatherName || !formData.dob || !formData.gender || !formData.emergencyContact || !formData.pincode || !formData.address) {
      setValidationError('Action Required: All text fields are mandatory.');
      return;
    }

    if (!/^\d{10}$/.test(formData.emergencyContact)) {
      setValidationError('Emergency Contact must be 10 digits.');
      return;
    }

    if (formData.mobile === formData.emergencyContact) {
      setValidationError('Conflict: Mobile and Emergency Contact cannot be identical.');
      return;
    }

    if (!/^\d{6}$/.test(formData.pincode)) {
      setValidationError('Pincode must be exactly 6 digits.');
      return;
    }

    if (!formData.aadhaarPhoto) {
      setValidationError('Identity Scan is mandatory.');
      return;
    }

    setStep(3);
    window.scrollTo(0, 0);
  };

  const uploadFile = async (file: File) => {
    const fileName = `aadhaar_${uuidv4()}.jpg`;
    const { data, error } = await supabase.storage.from('member-images').upload(fileName, file);
    if (error) throw new Error(`Storage Error: ${error.message}`);
    return supabase.storage.from('member-images').getPublicUrl(data.path).data.publicUrl;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!user?.organisationId || isLinkBroken || !user?.id) {
      addNotification("Registry Fault: Organization Linkage Missing or Invalid. Please contact Admin.", "error");
      return;
    }

    setIsSubmitting(true);
    try {
      const photoUrl = await uploadFile(formData.aadhaarPhoto!);

      const memberPayload = {
        aadhaar: formData.aadhaar,
        mobile: formData.mobile,
        name: formatInput(formData.name),
        surname: formatInput(formData.surname),
        father_name: formatInput(formData.fatherName),
        dob: formData.dob,
        gender: formData.gender,
        marital_status: formData.maritalStatus,
        qualification: formData.qualification,
        emergency_contact: formData.emergencyContact,
        pincode: formData.pincode,
        address: formData.address.trim(),
        aadhaar_front_url: photoUrl,
        aadhaar_back_url: photoUrl, 
        occupation: formData.occupation,
        support_need: formData.supportNeed,
        volunteer_id: user.id,
        organisation_id: user.organisationId,
        submission_date: new Date().toISOString(),
        status: 'Pending'
      };

      const { error: dbError } = await supabase.from('members').insert(memberPayload);

      if (dbError) {
        if (dbError.code === '23503') {
          const msg = `Critical Linkage Fault: Organization ID (${user.organisationId}) is invalid or has been purged from the master registry. Please contact support.`;
          setValidationError(msg);
          throw new Error(msg);
        }
        throw new Error(`Database Synchronization Error: ${dbError.message}`);
      }

      syncToSheets(SheetType.MEMBERS, {
        ...memberPayload,
        volunteer_name: user.name,
        organisation_name: user.organisationName,
        submission_date: new Date().toLocaleDateString()
      }).catch(err => console.error("Sheet Sync Failed:", err));

      addNotification("Identity record synchronized successfully.", 'success');
      setFormData(initialFormData);
      setPreview(null);
      setStep(1);
      window.scrollTo(0, 0);
    } catch (err: any) {
      console.error("Submission Fault:", err);
      addNotification(err.message || "Registry Fault: Synchronization Interrupted.", 'error');
      setValidationError(err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <DashboardLayout title="Identity Enrollment Hub">
      <div className="w-full max-w-4xl mx-auto space-y-8 md:space-y-12 pb-20">
        <div className="bg-[#0a0c14] border border-white/5 rounded-3xl p-6 flex flex-col sm:flex-row items-center justify-between gap-6 shadow-2xl">
          <div className="flex items-center gap-6">
            <div className="p-4 bg-orange-600/10 rounded-2xl text-orange-500 border border-orange-500/20 shadow-inner">
              <Fingerprint size={32} strokeWidth={1.5} />
            </div>
            <div>
              <p className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-500 mb-2">Authenticated Operator</p>
              <h4 className="text-lg md:text-xl font-bold text-white uppercase font-cinzel">{user?.name}</h4>
            </div>
          </div>
          <div className="text-center sm:text-right px-6 py-3 bg-black/60 rounded-2xl border border-white/5 flex flex-col gap-1 items-center sm:items-end">
            <p className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-600 mb-1">Organization Node</p>
            <p className={`text-[11px] font-black uppercase tracking-[0.2em] ${isLinkBroken ? 'text-red-500 animate-pulse' : 'text-orange-500'}`}>
              {user?.organisationName || 'LINKAGE FAULT'}
            </p>
            <div className="flex items-center gap-1.5 opacity-40">
              <Info size={10} className="text-gray-500" />
              <span className="text-[8px] font-mono text-gray-600 uppercase tracking-tighter">ID: {user?.organisationId?.slice(0, 8) || 'NONE'}...</span>
            </div>
          </div>
        </div>

        {(isLinkBroken || !user?.organisationId) && (
          <div className="p-6 bg-red-600/10 border border-red-500/20 rounded-3xl flex items-start gap-4 text-red-400">
            <ShieldAlert size={24} className="shrink-0 mt-1" />
            <div className="space-y-1">
              <p className="text-xs font-black uppercase tracking-widest">Critical System Error: Broken Registry Link</p>
              <p className="text-[10px] text-gray-400 leading-relaxed font-bold uppercase tracking-wider">
                The organization ID associated with your profile ({user?.organisationId}) does not exist in the master registry. <br />
                Enrollment is locked. Please contact the Master Admin to re-link your account.
              </p>
            </div>
          </div>
        )}

        <div className="relative pt-6 px-4">
          <div className="flex justify-between items-center mb-10 relative z-10">
            {[1, 2, 3].map(s => (
              <div key={s} className="flex flex-col items-center gap-3">
                <div className={`h-12 w-12 rounded-full border-2 flex items-center justify-center transition-all duration-700 ${step >= s ? 'bg-orange-600 border-orange-400' : 'bg-[#0a0c14] border-gray-800 opacity-40'}`}>
                  <span className="text-sm font-black text-white">{s}</span>
                </div>
              </div>
            ))}
          </div>
          <div className="absolute top-[2.75rem] left-0 w-full h-0.5 bg-gray-900 rounded-full overflow-hidden">
            <div className="h-full bg-orange-600 transition-all duration-1000" style={{ width: `${((step - 1) / 2) * 100}%` }}></div>
          </div>
        </div>

        <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
          {step === 1 && (
            <div className="max-w-xl mx-auto py-4">
              <Card className="relative bg-[#0a0c14] border-white/10 border p-0 rounded-[2.5rem] overflow-hidden shadow-[0_0_80px_rgba(0,0,0,0.5)]">
                <div className="p-8 md:p-12 space-y-10">
                  <div className="flex items-center gap-6 mb-4">
                    <div className="p-4 bg-orange-500/10 rounded-2xl text-orange-500">
                      <ShieldCheck size={28} />
                    </div>
                    <div>
                      <h3 className="text-xl font-cinzel text-white uppercase tracking-wider">Validation Step</h3>
                      <p className="text-[10px] font-black text-gray-500 uppercase tracking-[0.3em] mt-2">Registry Clearance</p>
                    </div>
                  </div>
                  <div className="space-y-8">
                    <Input label="IDENTIFICATION (12 DIGITS) *" name="aadhaar" value={formData.aadhaar} onChange={handleChange} maxLength={12} placeholder="Aadhaar Number" required />
                    <Input label="MOBILE NUMBER *" name="mobile" type="tel" value={formData.mobile} onChange={handleChange} maxLength={10} placeholder="Primary Mobile" required />
                    {validationError && (
                      <div className="p-5 bg-red-600/10 border border-red-500/20 rounded-2xl flex items-start gap-3">
                        <ShieldAlert size={16} className="text-red-500 shrink-0 mt-0.5" />
                        <p className="text-xs text-red-400 font-bold uppercase tracking-wider leading-relaxed">{validationError}</p>
                      </div>
                    )}
                  </div>
                  <div className="pt-6">
                    <Button onClick={handleStep1Next} disabled={isValidating || !user?.organisationId || isLinkBroken} className="w-full py-5 text-[11px] font-black uppercase tracking-[0.4em] flex items-center justify-center gap-4">
                      {isValidating ? <RefreshCw className="animate-spin" size={20} /> : <Search size={20} />}
                      {isValidating ? 'VALIDATING...' : 'AUTHORIZE ACCESS'}
                    </Button>
                  </div>
                </div>
              </Card>
            </div>
          )}

          {step === 2 && (
            <Card title="Citizen Identity File" className="bg-[#0a0c14] border-white/10 rounded-[2.5rem] p-8 md:p-14 shadow-2xl relative">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10 mb-12">
                <Input label="Full Name *" name="name" value={formData.name} onChange={handleChange} placeholder="First Name" required />
                <Input label="Gharano *" name="surname" value={formData.surname} onChange={handleChange} placeholder="Last Name" required />
                <Input label="FATHER / GUARDIAN NAME *" name="fatherName" value={formData.fatherName} onChange={handleChange} description="Maintained separately from primary identity name." required />
                <Input label="DATE OF BIRTH *" name="dob" type="date" value={formData.dob} onChange={handleChange} required />
                <Select label="BIOLOGICAL GENDER *" name="gender" value={formData.gender} onChange={handleChange}>
                  {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
                </Select>
                <Select label="MARITAL STATUS *" name="maritalStatus" value={formData.maritalStatus} onChange={handleChange}>
                  {Object.values(MaritalStatus).map(m => <option key={m} value={m}>{m}</option>)}
                </Select>
                <Select label="QUALIFICATION *" name="qualification" value={formData.qualification} onChange={handleChange}>
                  {Object.values(Qualification).map(q => <option key={q} value={q}>{q}</option>)}
                </Select>
                <Input label="EMERGENCY CONTACT *" name="emergencyContact" value={formData.emergencyContact} onChange={handleChange} maxLength={10} required />
                <Input label="PINCODE *" name="pincode" value={formData.pincode} onChange={handleChange} maxLength={6} required />
                <div className="md:col-span-2">
                  <Input label="FULL ADDRESS *" name="address" value={formData.address} onChange={handleChange} placeholder="Residential address" required />
                </div>
              </div>

              <div className="pt-10 border-t border-white/5">
                <div className="flex items-center gap-3 mb-8">
                  <ImageIcon2 className="text-orange-500" size={20} />
                  <h3 className="font-cinzel text-xl text-white uppercase tracking-widest">Aadhaar Card Upload</h3>
                </div>

                <div className="max-w-lg mx-auto">
                  <div className="space-y-4">
                    <label className="block text-[10px] font-black uppercase tracking-[0.3em] text-gray-500">AADHAAR PHOTO (SINGLE SIDE) *</label>
                    <div className="relative border-2 border-gray-800 border-dashed rounded-[2.5rem] bg-black/60 aspect-video flex flex-col items-center justify-center overflow-hidden group/upload hover:border-orange-500/50 transition-all duration-500">
                      {preview ? (
                        <>
                          <img src={preview} className="w-full h-full object-cover" />
                          <button onClick={handleRemoveImage} className="absolute top-6 right-6 p-3 bg-red-600 text-white rounded-2xl shadow-xl hover:bg-red-700 transition-all scale-90 hover:scale-100"><XCircle size={24} /></button>
                        </>
                      ) : (
                        <button onClick={() => inputRef.current?.click()} className="flex flex-col items-center gap-4 text-gray-700 group-hover/upload:text-orange-500/70 transition-colors">
                          <ImageIcon size={64} strokeWidth={1} />
                          <span className="text-[11px] font-black uppercase tracking-[0.4em]">UPLOAD CARD PHOTO</span>
                        </button>
                      )}
                      <input ref={inputRef} type="file" className="sr-only" onChange={handleFileChange} accept="image/*" />
                    </div>
                  </div>
                </div>
              </div>

              {validationError && (
                <div className="mt-12 flex items-center gap-4 p-5 bg-red-600/10 border border-red-500/20 rounded-2xl flex items-start">
                  <ShieldAlert size={20} className="text-red-500 shrink-0 mt-0.5" />
                  <p className="text-xs text-red-400 font-bold uppercase tracking-widest leading-relaxed">{validationError}</p>
                </div>
              )}

              <div className="mt-16 flex flex-col sm:flex-row justify-between gap-6">
                <Button variant="secondary" onClick={() => { setStep(1); window.scrollTo(0, 0); }} className="w-full sm:w-auto py-4 px-10">Back</Button>
                <Button onClick={handleStep2Next} className="w-full sm:w-auto py-4 px-12">Review Registry</Button>
              </div>
            </Card>
          )}

          {step === 3 && (
            <Card title="Review Node" className="bg-[#0a0c14] border-white/10 rounded-[2.5rem] p-8 md:p-14 shadow-2xl">
              <div className="space-y-12">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <Select label="What do they do? *" name="occupation" value={formData.occupation} onChange={handleChange}>
                    {Object.values(Occupation).map(o => <option key={o} value={o}>{o}</option>)}
                  </Select>
                  <Select label="What do they want? *" name="supportNeed" value={formData.supportNeed} onChange={handleChange}>
                    {Object.values(SupportNeed).map(s => <option key={s} value={s}>{s}</option>)}
                  </Select>
                </div>
                <div className="p-8 bg-orange-600/5 border border-orange-500/10 rounded-[2rem] flex flex-col md:flex-row items-start gap-8">
                  <div className="p-4 bg-orange-500/10 rounded-2xl text-orange-500 shrink-0">
                    <ShieldCheck size={36} strokeWidth={1.5} />
                  </div>
                  <div className="space-y-3">
                    <h4 className="text-base font-bold text-white uppercase tracking-tight">Identity Certification</h4>
                    <p className="text-[11px] text-gray-500 leading-relaxed uppercase tracking-[0.2em] font-bold">
                      I certify that I have physically verified the Given Name and Surname of this citizen against legal documentation. Single-side Aadhaar verification is sufficient for this drive.
                    </p>
                  </div>
                </div>
              </div>
              {validationError && (
                <div className="mt-10 flex items-center gap-4 p-5 bg-red-600/10 border border-red-500/20 rounded-2xl flex items-start">
                  <ShieldAlert size={20} className="text-red-500 shrink-0 mt-0.5" />
                  <p className="text-xs text-red-400 font-bold uppercase tracking-widest leading-relaxed">{validationError}</p>
                </div>
              )}
              <div className="mt-16 flex flex-col sm:flex-row justify-between gap-6">
                <Button variant="secondary" onClick={() => { setStep(2); window.scrollTo(0, 0); }} className="w-full sm:w-auto py-4 px-10">Modify Profile</Button>
                <Button onClick={handleSubmit} disabled={isSubmitting} className="w-full sm:w-auto py-5 px-16 text-[12px] font-black uppercase tracking-[0.4em]">
                  {isSubmitting ? 'SYNCHRONIZING...' : 'FINALIZE REGISTRATION'}
                </Button>
              </div>
            </Card>
          )}
        </div>
      </div>
    </DashboardLayout>
  );
};

