                                                <span className="text-[10px] font-black text-white uppercase tracking-widest">{member.agent_profile?.name || 'Volunteer'}</span>
                                            </div>
                                        </td>
                                        <td className="p-4 sm:p-6 text-center">
                                            <span className={`px-3 py-1 text-[8px] sm:text-[10px] font-black uppercase rounded-full border ${member.status === MemberStatus.Accepted ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-orange-500/10 text-orange-400 border-orange-500/20'}`}>
